if GetLocale() ~= "frFR" then
    return
end

ns.DB:AddTexts("frFR", nil, function() return {
	["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} forme les mages dans {object:32362} de {zone:1455}. Prenez ensuite {area:2257} depuis {object:171524} pour {zone:1453}.",
	["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312} forme les mages dans {object:32362} de {zone:1455}. Prenez ensuite {area:2257} depuis {object:171524} pour {zone:1453}.",
	["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "Orbe étrange au sommet de {area:444} : clic droit sur l'orbe d'Althalaxx qu'elle donne",
	["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Retour auprès de {npc:3649} à {area:442} : il purifie la gemme.",
	["{spell:921} the {npc:6846} for the {item:7675}"] = "{spell:921} sur {npc:6846} pour {item:7675}",
	["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "Au niveau 10, {npc:1234}, le maître voleur de {area:2102} à {area:131}, vous envoie voir {npc:5165} à {zone:1455}.",
	["Pick Pocket Sethir the Ancient for {item:7737}"] = "Faites les poches de Sethir l'Ancien pour {item:7737}",
	["{spell:921} the {npc:7051} for the {item:7923}"] = "{spell:921} sur {npc:7051} pour {item:7923}",
	["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "Au niveau 30, {npc:6122}, dans la cave de {object:2164} dans {object:2101}, vous envoie voir {npc:6251} à {area:392}.",
	["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "Au niveau 30, {npc:6120}, dans {object:32383}, vous envoie voir {npc:6251} à {area:392}.",
	["Enter the {area:98} and come back"] = "Entrez dans {area:98} et revenez",
	["Roogug in {area:1717}"] = "Roogug à {area:1717}",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an Elixir of Water Breathing removes the risk."] = "Le {quest:1708} pousse au fond de la mer juste au sud de {area:150}, près des huttes des murlocs et d'un bateau échoué : huit là, et deux au sud-est du port, chacun repoussant en 3 minutes ; il faudra donc attendre la repousse pour arriver à 20. Les murlocs peuvent vous immobiliser sous l'eau dans leurs filets : surveillez votre souffle, un élixir de respiration aquatique supprime le risque.",
	["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Biscuits de manne enrichis : {npc:10857}, {area:3197}",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "Votre propre familier au niveau 10 : trois apprivoisements d'entraînement avec {item:15908} vous enseignent {spell:1515}, puis {spell:5149}.",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "Au niveau 10, {npc:254084}, un maître des chasseurs de {zone:2521}, peut vous envoyer à {area:16638} avec {quest:94007}. Ce n'est qu'une indication : passez-la si vous êtes déjà à {area:16638}.",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389} se tient avec les maîtres près de la porte ouest de {area:16638}, {npc:254411} à côté d'elle.",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to {npc:252389}."] = "Les rampants Chant-du-vent ne vivent qu'au bord de l'eau : les plus proches trottinent sur le rivage au sud-ouest de {area:16638}, parmi les crabes. Fonctionnement du bâtonnet : ciblez un rampant vivant, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'il vous frappe ; bouger, riposter ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet. En tuer un ne compte pas. Gardez chaque bâtonnet : il retourne à {npc:252389}.",
	["Use the {item:15908} on a living crawler"] = "Utilisez {item:15908} sur un rampant vivant",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "Renvoyez d'abord le rampant (clic droit sur le portrait du familier, {spell:2641}). Les coursiers du vent grincheux broutent à {area:16626}, les champs à quelques pas à l'ouest et au sud-ouest de {area:16638}.",
	["Use the {item:15908} on a living galestrider"] = "Utilisez {item:15908} sur un coursier du vent vivant",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "Renvoyez le coursier du vent. Les alphas vuldren chassent dans le même {area:16626}, un peu plus au sud.",
	["Use the {item:15908} on a living alpha"] = "Utilisez {item:15908} sur un alpha vivant",
	["{npc:254411}, beside her: {spell:5149}"] = "{npc:254411}, à côté d'elle : {spell:5149}",
	["At 10 go to {npc:1231}, the hunter trainer at the smithy in {area:131}. The Hunter's Path from {npc:5116} in {zone:1455}, {npc:11807} north-west of {area:131} or {npc:5515} in {zone:1453} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Au niveau 10, allez voir {npc:1231}, le maître des chasseurs à la forge de {area:131}. La Voie du chasseur, auprès de {npc:5116} à {zone:1455}, de {npc:11807} au nord-ouest de {area:131} ou de {npc:5515} à {zone:1453}, mène aussi ici, pour un peu d'expérience ; ce n'est qu'une indication. Vous êtes plutôt en Elwynn au niveau 10 ? La suite de {npc:251507} à {area:87} enseigne la même chose.",
	["Large Crag Boars (level 6-7) root around the fields west, south and north-west of {area:131} and respawn every 3 minutes. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:1231}. The boars use {spell:6268} from 25 yards, so start with the rod, not {spell:75}. Keep each rod: it goes back to {npc:1231}."] = "De grands sangliers des rochers (niveau 6-7) fouillent les champs à l'ouest, au sud et au nord-ouest de {area:131} et réapparaissent toutes les 3 minutes. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe. Bouger, riposter, être hors de portée ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet ; si elles sont épuisées, détruisez le bâtonnet, abandonnez la quête et reprenez-la auprès de {npc:1231}. Les sangliers utilisent {spell:6268} à 25 mètres : commencez avec le bâtonnet, pas avec {spell:75}. Gardez chaque bâtonnet : il retourne à {npc:1231}.",
	["Use the {item:15908} on a living boar"] = "Utilisez {item:15908} sur un sanglier vivant",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of {area:131}, more north-west and west of it; the smaller Juvenile Snow Leopards do not count."] = "Renvoyez d'abord le sanglier (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des léopards des neiges (niveau 7-8) rôdent sur les pentes au sud-est de {area:131}, d'autres au nord-ouest et à l'ouest ; les jeunes léopards des neiges, plus petits, ne comptent pas.",
	["Use the {item:15908} on a living leopard"] = "Utilisez {item:15908} sur un léopard vivant",
	["Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around {area:131}, many south-east of it and more north-west toward {area:77}; their {spell:3130} hits hard, so start at full health."] = "Renvoyez le léopard. Des ours Griffe-de-glace (niveau 7-8) parcourent les collines autour de {area:131}, beaucoup au sud-est et d'autres au nord-ouest vers {area:77} ; leur {spell:3130} frappe fort, commencez donc avec toute votre vie.",
	["Use the {item:15908} on a living bear"] = "Utilisez {item:15908} sur un ours vivant",
	["{npc:10090}, the pet trainer, stands in the {object:32390} in {zone:1455}'s {object:32359}, by the hunter trainers."] = "{npc:10090}, le maître des familiers, se tient dans {object:32390}, à {object:32359} de {zone:1455}, près des maîtres des chasseurs.",
	["At 10 go to {npc:3601}, the hunter trainer in {area:186}. The Hunter's Path from {npc:3596} at {area:256}, {npc:4146} in {zone:1457}, {npc:5515} in {zone:1453}, {npc:5116} in {zone:1455} or {npc:1231} in {area:131} also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? {npc:251507}'s chain in {area:87} teaches the same."] = "Au niveau 10, allez voir {npc:3601}, le maître des chasseurs à {area:186}. La Voie du chasseur, auprès de {npc:3596} à {area:256}, de {npc:4146} à {zone:1457}, de {npc:5515} à {zone:1453}, de {npc:5116} à {zone:1455} ou de {npc:1231} à {area:131}, mène aussi ici, pour un peu d'expérience ; ce n'est qu'une indication. Vous êtes plutôt en Elwynn au niveau 10 ? La suite de {npc:251507} à {area:87} enseigne la même chose.",
	["Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of {area:186}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their {spell:1265843} roots you but does not break the channel if you keep still. Keep each rod: it goes back to {npc:3601}."] = "Des rôdeuses Tisse-bois (niveau 5-6) rampent dans les bois juste au nord-est, au sud-ouest et à l'est de {area:186}. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe ; bouger, l'attaquer ou l'aide de quelqu'un d'autre l'interrompt et coûte l'une des rares charges du bâtonnet (plus de charges : détruisez le bâtonnet, abandonnez la quête, reprenez-la). Leur {spell:1265843} vous immobilise mais n'interrompt pas la canalisation si vous ne bougez pas. Gardez chaque bâtonnet : il retourne à {npc:3601}.",
	["Use the {item:15908} on a living spider"] = "Utilisez {item:15908} sur une araignée vivante",
	["Dismiss the spider first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of {area:259}, south of {area:186}; the plain Nightsabers by the village do not count."] = "Renvoyez d'abord l'araignée (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des traqueurs sabres-de-nuit (niveau 7-8) se couchent sur le flanc de colline au sud de {area:259}, au sud de {area:186} ; les simples sabres-de-nuit près du village ne comptent pas.",
	["Use the {item:15908} on a living stalker"] = "Utilisez {item:15908} sur un traqueur vivant",
	["Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of {area:186}."] = "Renvoyez le félin. Des hurleurs strigides (niveau 7-8), des chouettes, se perchent dans les bois au sud, au sud-ouest et à l'ouest de {area:186}.",
	["Use the {item:15908} on a living owl"] = "Utilisez {item:15908} sur une chouette vivante",
	["Take the road west from {area:186} to {zone:1457}. {npc:4146} stands inside the {area:1658} with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her."] = "Prenez la route vers l'ouest depuis {area:186} jusqu'à {zone:1457}. {npc:4146} se tient dans {area:1658} avec les maîtres des chasseurs ; Silvaria, la maîtresse des familiers, est en haut de la rampe à côté d'elle.",
	["At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same."] = "Au niveau 10, allez voir {npc:251507}, la maîtresse des chasseurs qui se tient avec les autres maîtres près de l'auberge de la Fierté du lion à {area:87} ; {npc:258930}, la maîtresse des familiers, est à côté d'elle. Célestes : ceci est pour qui a quitté {zone:2521} sans apprivoiser ; la quête enseigne la même chose.",
	["Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here."] = "Des sangliers Peau-de-roche (niveau 7-8) broutent en trois hardes au sud et au sud-est de {area:87}, vers {area:64}. Fonctionnement du bâtonnet : ciblez une bête vivante, utilisez {item:15908} et restez immobile pendant toute la canalisation pendant qu'elle vous frappe. Bouger, riposter, un soin de quelqu'un d'autre ou quelqu'un d'autre qui frappe la bête l'interrompt et coûte l'une des rares charges du bâtonnet ; si elles sont épuisées, détruisez le bâtonnet, abandonnez la quête et reprenez-la. Les sangliers utilisent {spell:6268} : commencez avec le bâtonnet, pas avec {spell:75}. Tuer un sanglier ne compte pas. Gardez chaque bâtonnet : il retourne à Josephine. Un nain ou un elfe de la nuit qui a pris le bâtonnet de Josephine plutôt que celui de son maître d'origine est guidé à travers {area:87} à partir d'ici.",
	["Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}."] = "Renvoyez d'abord le sanglier (clic droit sur le portrait du familier, {spell:2641}) : un familier d'entraînement relâché peut se retourner contre vous. Des loups gris des forêts (niveau 7-8) courent dans les bois à l'est de {area:87}, à l'est de {area:18}.",
	["Use the {item:15908} on a living wolf"] = "Utilisez {item:15908} sur un loup vivant",
	["Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town."] = "Renvoyez le loup. De jeunes ours des forêts (niveau 8-9) parcourent les bois juste au sud de {area:87}, d'autres au sud-ouest et au sud-est de la ville.",
	["Your first pet"] = "Votre premier familier",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515} fonctionne comme le bâtonnet : une bête de votre niveau ou moins, une canalisation pendant laquelle il ne faut pas bouger, la bête vous frappant tout du long. Un familier garde le niveau auquel vous l'apprivoisez et monte de niveau avec vous ; il ne peut jamais dépasser votre niveau, apprivoisez-en donc un proche du vôtre. Chaque famille a sa propre capacité sur Forever (la Charge d'un sanglier, par exemple). Pour monter en niveau, un félin frappe le plus fort (Griffe et {spell:17253}) et un sanglier encaisse davantage.",
	["Tame a beast of your level to keep"] = "Apprivoisez une bête de votre niveau à garder",
	["Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}."] = "Près de {area:87}, il n'y a pas de félins : des rôdeurs (loups, niveau 9-10) parcourent l'est d'Elwynn, des groins longs (sangliers, 10-11) son extrême sud-ouest près de la frontière de {zone:1436} ; aux niveaux 12-13, de jeunes broche-tripes (sangliers) broutent dans les champs du nord de {zone:1436}.",
	["Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}."] = "Près de {area:131} : des léopards des neiges (félins, niveau 7-8) rôdent partout à {zone:1426}, des sangliers des rochers balafrés (9-10) à l'est vers {zone:1432} ; aux niveaux 10-11, des sangliers des montagnes parcourent l'ouest de {zone:1432}.",
	["Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}."] = "Près de {area:186} : de vieux sabres-de-nuit (félins, niveau 8-9) et des sabres-de-nuit farouches (félins, 10-11) rôdent dans les bois du nord-ouest de {zone:1438}.",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "Près de {area:16638} : les alphas vuldren (niveau 10), la bête de votre dernier apprivoisement d'entraînement, chassent à {area:16626} ; les matriarches criardes (raptors, niveau 9) nichent juste à l'ouest de {area:16638} ; des urseras Ombre-bourrasque (ours, 10-11) parcourent le nord de {zone:2521}.",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584} : ouvrez votre grimoire, lancez {spell:1584} et cliquez sur une nourriture que mange la famille de votre familier (son infobulle les liste : les félins mangent viande et poisson, les sangliers presque tout). La viande crue ramassée sur les bêtes compte. Pour en acheter : Toddrick le boucher à {area:87}, Jaeana à {zone:1457} et les aubergistes de {zone:2521} vendent de la viande ; les aubergistes de {area:131} et de {area:186} vendent du pain. Une nourriture proche du niveau du familier le rend le plus heureux ; une nourriture bien plus basse donne environ moitié moins. Impossible de nourrir en combat.",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "Bonheur : le visage sur le cadre du familier. Un familier malheureux fait trois quarts de ses dégâts, un familier heureux un quart de plus. Le bonheur baisse lentement, plus vite quand le familier meurt ; un familier laissé malheureux trop longtemps peut s'enfuir.",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "La loyauté grandit avec le temps et les victimes. Chaque rang de loyauté augmente les points de dressage que vous dépensez dans {spell:5149} (niveau du familier multiplié par le rang de loyauté moins un).",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149} (grimoire, onglet Général) enseigne à votre familier actuel les capacités que vous connaissez. Pour apprendre une nouvelle capacité ou un nouveau rang : laissez votre familier chez un maître des écuries (Erma à {area:87}, {npc:9980} à {area:131}, Seriadne à {area:186}, {npc:265756} à {zone:2521}), apprivoisez une bête qui l'a (l'onglet du grimoire du familier montre ce qu'elle connaît), utilisez la capacité en combat jusqu'à ce que le jeu indique que vous l'avez apprise, puis reprenez votre familier et enseignez-la-lui avec {spell:5149}. Un familier a au plus quatre capacités actives.",
	["Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}."] = "Les maîtres des familiers vendent les rangs de {spell:1853} et les résistances. Alliance : {npc:258930} à {area:87}, {npc:2879} près des maîtres des chasseurs dans {object:28027} de {zone:1453}, {npc:2878} à {area:131}, {npc:10090} dans {object:32390} de {zone:1455}, Keldas à {area:186}, Silvaria dans l'Enclave cénarienne de {zone:1457}, {npc:254411} à {area:16638}.",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}, {spell:2641} et {spell:982} sont maintenant dans votre grimoire ; {spell:136} vient de votre maître au niveau 12. Un familier mort a besoin de {spell:982} ; un familier qui s'éloigne de plus d'environ 100 mètres est renvoyé et revient avec {spell:883}.",
	["A robe or a blouse for Alliance mages in their late 20s."] = "Une robe ou une blouse pour les mages de l'Alliance vers la fin de la vingtaine.",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her."] = "{npc:5497} se tient au sommet du Sanctum des sorciers, la tour violette de {object:2101} ; le portail près du haut de la rampe en spirale vous mène à elle.",
	["{npc:5694} (Skyborne)"] = "{npc:5694} (Célestes)",
	["You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:5694} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {npc:5694}, the pointer quest; it is only a pointer and you can skip it.)"] = "Pas besoin de lettre : au niveau 26, montez dans le Sanctum des sorciers, la tour violette de {object:2101} de {zone:1453}. {npc:5694} attend sur la passerelle en spirale, juste après la porte de la salle du portail près du sommet, et a la quête pour vous. ({npc:5497} peut aussi vous proposer {npc:5694}, la quête d'indication ; ce n'est qu'une indication et vous pouvez la passer.)",
	["{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers."] = "{quest:1939} attend sur la passerelle en spirale du Sanctum des sorciers, juste après la porte de la salle du portail en descendant depuis les maîtres.",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it."] = "Partez vers l'est à travers {zone:1429} jusqu'aux Carmines, ou volez jusqu'à {area:69}. {area:96} se dresse seule à l'est de la zone. Montez tout en haut (pas l'étage en dessous) : le traité est le livre qui dépasse de l'étagère là où arrive l'escalier. Deux chiens gnolls et un gnoll lanceur de sorts gardent l'étagère ; le {spell:2691} des chiens interrompt le clic, combattez-les donc dans l'escalier hors de leur vue. Morganth (élite de niveau 26) se tient de l'autre côté du dernier étage : vous n'avez pas besoin de lui, restez sur le bord gauche de la rampe pour qu'il ne bouge pas. Le livre revient deux secondes après qu'on le prend. Si vous mourez, votre fantôme peut monter et revenir à la vie à côté.",
	["{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him."] = "{area:492}, dans l'ouest de {zone:1431} : les six recluses charognardes (niveau 25-26, vertes, {spell:3609}) arpentent les tombes, la statue centrale et la berge, et chacune lâche une soie ; elles reviennent au bout de 5 minutes. Les jeunes veuves noires (24-25) sur les pentes à l'est du cimetière en lâchent environ une fois sur six, mêlez-les donc en attendant. {npc:522}, un squelette élite de niveau 35, arpente le cimetière : faites attention à lui.",
	["{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit."] = "{npc:1309} travaille à {object:23296} dans {object:2101}. La robe donne intelligence, endurance et esprit ; la blouse plus d'intelligence et d'endurance mais pas d'esprit.",
	["{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn."] = "{npc:328} est le maître des mages de {area:87}, à l'étage de l'auberge de la Fierté du lion.",
	["{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:5497} se tient au sommet du Sanctum des sorciers, la tour violette de {object:2101} : montez la rampe en spirale et prenez le portail près du sommet. {item:7247} et {item:7308} sont sur la table derrière elle (tous deux reviennent 5 minutes après qu'on les prend). Vous les rendez tous les deux à la fin, gardez-les donc.",
	["{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds."] = "{object:2169} est la taverne de {object:2101}. Lisez {item:7308} à l'intérieur pour faire apparaître les rejetons de faille invisibles (niveau 16-17) : à la cave il en fait venir un, sur le balcon ou dans la cuisine deux, dans la salle principale ou près de la porte trois ; lisez-la donc en bas. Ils frappent fort et se libèrent vite de {spell:122}. Mettez-en un à terre : il ne meurt pas mais reste étourdi avec une spirale au-dessus de la tête ; utilisez {item:7247} sur lui pendant qu'il est étourdi, puis cliquez sur {item:7292} qu'il laisse au sol (cliquer avant qu'il apparaisse gaspille une charge). Il en faut trois, et l'incantation ne marche qu'une fois toutes les 5 minutes (se déconnecter ne la réinitialise pas) : prévoyez trois tours.",
	["{npc:6492}, down to the stun"] = "{npc:6492}, jusqu'à l'étourdissement",
	["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}, sur {npc:6492} étourdi",
	["Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten."] = "N'importe quel humanoïde lâche {item:2589}, et les rats des tunnels de {area:149} en lâchent pendant que vous ramassez les gemmes ; l'hôtel des ventes de {object:2096} en vend. Vous en rendez dix.",
	["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest."] = "Prenez {area:2257} jusqu'à {zone:1455}, puis la route vers l'est par le tunnel de la porte Sud jusqu'à {zone:1432}. {area:149} est à l'extrémité nord du loch, au nord de {area:144} ; des kobolds rats des tunnels le tiennent. Les gemmes ne viennent que des hautes piles de {object:271} (le curseur montre un engrenage dessus ; les caisses seules ne contiennent rien) : chaque caisse en donne une, il y en a quatorze et elles reviennent au bout de 3 à 5 minutes. Il vous faudra peut-être aller jusqu'à la salle du fond pour en avoir six. Les mêmes caisses servent à la quête des Pattes sales des nains.",
	["Ley or {item:9514} or Orb (Alliance)"] = "Bâton ou {item:9514} ou orbe (Alliance)",
	["A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand."] = "Un bâton ou un orbe en main gauche au niveau 10, auprès du maître des mages de votre ville d'origine ; les Célestes y ajoutent une baguette.",
	["At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town."] = "Au niveau 10, {npc:252373}, le maître des mages de {area:16638}, vous envoie à {npc:256507}, le marchand de bâtons à quelques pas dans la même ville.",
	["The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it."] = "La branche gît au sol parmi les formations de Pierre-vent, le sanctuaire du vent sur la butte à l'ouest du camp de Fillion, au sud de {area:16636}. Elle ne scintille pas, regardez donc le sol près des pierres ; il y a deux emplacements possibles.",
	["{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15."] = "{quest:1861} (les étapes suivantes) vous attend auprès de {npc:5497} à {zone:1453}, vers le niveau 15.",
	["At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {npc:5144}'s quest in {zone:1455}; you get one staff-or-orb quest."] = "Au niveau 10, {npc:328}, le maître des mages de {area:87}, à l'étage de l'auberge de la Fierté du lion, vous envoie à {npc:5497} à {zone:1453}. La prendre ferme la quête de {npc:5144} à {zone:1455} ; vous n'avez qu'une quête de bâton ou d'orbe.",
	["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {npc:5497}'s {quest:1861}; you get one staff-or-orb quest. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "Au niveau 10, {npc:1228}, le maître des mages de {area:131} dans {area:2102}, vous envoie à {npc:5144} à {zone:1455}. La prendre ferme {quest:1861} de {npc:5497} ; vous n'avez qu'une quête de bâton ou d'orbe. (Un gnome qui a pris la quête de {npc:328} à {area:87} suit plutôt les étapes de {quest:1861} ; un humain qui a pris celle-ci, les étapes du Gizmoniteur.)",
	["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Suivez la route au nord jusqu'à {zone:1453} puis à l'ouest jusqu'à {object:2101}. {npc:5497} se tient au sommet du Sanctum des sorciers, la haute tour violette : montez la rampe en spirale et entrez dans le portail près du sommet, qui vous dépose à côté d'elle. Elle vous remet {item:7207}. Les mages célestes prennent {quest:1861} auprès d'elle en arrivant pour la première fois à {zone:1453}, vers le niveau 15.",
	["The {quest:1861} waterfall"] = "La cascade de {quest:1861}",
	["Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water."] = "Quittez {zone:1453} par la grande porte et partez au sud-ouest jusqu'à la cascade qui alimente {quest:1861}. Avancez dans l'eau sous la chute jusqu'au rocher derrière et utilisez-y {item:7207} (5 secondes d'incantation) ; ailleurs, ça échoue. Des lanceurs de sorts défias de niveau 10 se tiennent sur les rochers de part et d'autre des chutes et tirent à distance : attirez-les un par un ou remplissez la flasque depuis l'eau.",
	["{item:7207}, under the falls"] = "{item:7207}, sous les chutes",
	["Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "Remontez le Sanctum des sorciers et repassez le portail. L'orbe se tient en main gauche avec une arme à une main ; le bâton se tient à deux mains.",
	["{npc:5497}: {item:7508} or {item:9513}"] = "{npc:5497} : {item:7508} ou {item:9513}",
	["{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}."] = "{npc:5144} entraîne les mages dans {object:32362}, au fond de {zone:1455} après {object:32386}.",
	["Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone."] = "Prenez la route vers l'ouest jusqu'à {area:133}. Juste au nord de son entrée se dressent deux huttes ; la boîte à outils est dans la plus haute, à l'est, celle avec l'ascenseur : une petite boîte grise au rez-de-chaussée, à moitié sous la table à côté de l'ascenseur. Des gnomes lépreux (niveau 8) gardent les huttes : attirez-les un par un. Il n'y a qu'une boîte à outils et elle met 15 minutes à revenir après qu'on l'a ouverte ; si elle n'y est plus, attendez tout près.",
	["{npc:5144}: {item:7507} or {item:9514}"] = "{npc:5144} : {item:7507} ou {item:9514}",
	["{npc:256507}'s wand (optional)"] = "La baguette de {npc:256507} (facultative)",
	["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "La quête de {npc:256507} est aussi ouverte aux mages humains et gnomes, si vous passez un jour à {area:16638} sur {zone:2521}, chez les Célestes : {npc:252373}, le maître des mages de la ville, vous envoie à {npc:256507} juste à côté, qui veut {item:262668} ramassée au sol près des formations de Pierre-vent au sud de {area:16636}, pour {item:263430}. Elle ne ferme pas le bâton ni l'orbe.",
	["Teleports and Portals (Alliance)"] = "Téléportations et portails (Alliance)",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "Vos téléportations de ville aux niveaux 20 et 30 et les portails de groupe aux niveaux 40 et 50, auprès du maître des portails de chaque ville.",
	["At 20 go to the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {npc:2485}, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches {spell:3561} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor; {npc:1308} sells them at the foot of the tower), so carry a few."] = "Au niveau 20, allez au Sanctum des sorciers, la tour violette de {object:2101} de {zone:1453}. {npc:2485}, la maîtresse des portails, se tient tout en haut : montez la rampe en spirale et prenez le portail près du sommet. Elle enseigne {spell:3561} pour 20 pièces d'argent. Chaque téléportation consomme {item:17031} (10 pièces d'argent chez n'importe quel vendeur de composants ; {npc:1308} en vend au pied de la tour) : ayez-en quelques-unes sur vous.",
	["{item:17031}, 10s each"] = "{item:17031}, 10 pa pièce",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}. {npc:2489}, the portal trainer, stands with the mage trainers in the {object:32362} at the back of the city: {spell:3562}, 20 silver."] = "Prenez {area:2257} depuis {object:28027} de {zone:1453} jusqu'à {zone:1455}. {npc:2489}, le maître des portails, se tient avec les maîtres des mages dans {object:32362} au fond de la ville : {spell:3562}, 20 pièces d'argent.",
	["At 30. Take the boat from {area:17203} to {area:442} in {zone:1439}, then the boat to {area:702} and the pink portal up into {zone:1457}. {npc:4165}, the portal trainer, teaches {spell:3565} for 80 silver."] = "Au niveau 30. Prenez le bateau de {area:17203} à {area:442} à {zone:1439}, puis le bateau jusqu'à {area:702} et le portail rose qui monte à {zone:1457}. {npc:4165}, le maître des portails, enseigne {spell:3565} pour 80 pièces d'argent.",
	["Portals to {zone:1453} and {zone:1455}"] = "Portails vers {zone:1453} et {zone:1455}",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:2485} has {spell:10059} at the top of the Wizard's Sanctum; then the tram to {npc:2489} in {zone:1455}'s {object:32362} for {spell:11416}."] = "Au niveau 40, les maîtres des portails enseignent les portails : une porte que tout votre groupe peut franchir, pour 1 pièce d'or et 50 d'argent chacun. Chaque portail consomme {item:17032} (20 pièces d'argent chez n'importe quel vendeur de composants). {npc:2485} a {spell:10059} au sommet du Sanctum des sorciers ; puis le tram jusqu'à {npc:2489} dans {object:32362} de {zone:1455} pour {spell:11416}.",
	["{item:17032}, 20s each"] = "{item:17032}, 20 pa pièce",
	["At 50 {npc:4165} in {zone:1457} teaches the last one, {spell:11419}, for 3 gold 20 silver. Use your {spell:3565} to get there."] = "Au niveau 50, {npc:4165} à {zone:1457} enseigne le dernier, {spell:11419}, pour 3 pièces d'or et 20 d'argent. Utilisez votre {spell:3565} pour y aller.",
	["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "Une cape rare au niveau 30, tirée de l'ancienne histoire de {spell:407778} ; pour l'instant, seuls les paladins de l'Alliance peuvent la terminer.",
	["Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it."] = "Montez au sommet de {area:444} dans le nord de {zone:1439}. Les fanatiques du Sombre brin autour sont faciles (niveau 16-17), mais quatre invocateurs du Vide du Sombre brin (niveau 28-29) se tiennent dans la tour sur le chemin de l'orbe : chacun appelle un marcheur du Vide et lance {spell:686} à distance. Aux niveaux 22-25, venez avec un ou deux amis, attirez-les un par un et placez-vous derrière un mur pour qu'ils viennent à vous. Ramassez l'orbe étrange au sommet : elle vous donne l'orbe d'Althalaxx ; faites un clic droit dessus pour commencer la quête. Gardez l'orbe dans vos sacs jusqu'à {object:409311} : trois quêtes suivantes en ont besoin.",
	["{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb."] = "{npc:3663} se tient à {area:413}, dans l'ouest de {zone:1440}, au sud de la route de {zone:1439}. Il vous envoie à {zone:1453} avec l'orbe.",
	["{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion."] = "{npc:5492} se tient dans la cathédrale de la Lumière ; elle vous envoie demander un second avis à un démoniste.",
	["{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb."] = "{npc:5495}, la maîtresse des démonistes, est dans le sanctuaire des démonistes de {object:2101}, dans la cave de {object:2164}. Elle veut 14 {item:209778} pour lire l'orbe.",
	["The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west."] = "Les invocateurs, champions et pisteurs Rochenoire (niveau 22-25, non élites) campent au nord-ouest des Carmines et lâchent {item:209778} ; il vous en faut 14. Deux lanceurs d'ombre Rochenoire élites (22-23) se tiennent à l'entrée de la grotte à l'extrémité est du camp : contournez-les. Les camps Rochenoire à l'est de {area:69} lâchent aussi le sel, mais leurs lanceurs d'ombre, sentinelles et chasseurs sont élites (niveau 21-24), tout comme {npc:334} (26) : restez au nord-ouest.",
	["{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes."] = "{area:435} se trouve au sud-est de {zone:1440}, à l'est de {area:431} (un camp de la Horde : contournez-le). Les flagellants de Mannoroc, les infernaux brûlants, les gangregardes et les molosses de la Légion (niveau 29-30, non élites) lâchent les grains de Mannoroth ; il vous en faut 12. Sous le niveau 27 environ, ils sont durs seul : venez avec un second joueur ou plus tard. Les gangregardes vous renversent, les flagellants lancent {spell:686} et {spell:348}, les infernaux gardent un bouclier de feu. Ils réapparaissent en cinq minutes.",
	["The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the {object:409315} beside it starts the last quest."] = "{object:409311} se dresse à l'extrémité est de {area:435}. Rendez les grains à la lance avec l'orbe d'Althalaxx dans vos sacs : l'orbe se brise, et {object:409315} à côté commence la dernière quête.",
	["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Retour auprès de {npc:3663} à {area:413}, dans l'ouest de {zone:1440}, à travers toute la zone.",
	["A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever."] = "Une pierre à usage unique qui vous rend bien plus fort contre les morts-vivants pendant 10 minutes ; l'ancien choix d'objet a peut-être disparu sur Forever.",
	["At 50 {npc:928}, the paladin trainer in the Cathedral of Light, sends you to {area:3197} in the {zone:1422}. {npc:5149} in {zone:1455} gives the same quest."] = "Au niveau 50, {npc:928}, le maître des paladins de la cathédrale de la Lumière, vous envoie à {area:3197} dans {zone:1422}. {npc:5149} à {zone:1455} donne la même quête.",
	["At 50 {npc:5149}, the paladin trainer in the {object:32362}, sends you to {area:3197} in the {zone:1422}. {npc:928} in {zone:1453} gives the same quest."] = "Au niveau 50, {npc:5149}, le maître des paladins de {object:32362}, vous envoie à {area:3197} dans {zone:1422}. {npc:928} à {zone:1453} donne la même quête.",
	["{area:3197} is the Alliance camp at the south end of the {zone:1422}, north of the Alterac foothills. {npc:10838} commands it; {npc:10840} stands in the same camp."] = "{area:3197} est le camp de l'Alliance à l'extrémité sud de {zone:1422}, au nord des contreforts d'Alterac. {npc:10838} le commande ; {npc:10840} se tient dans le même camp.",
	["The Scourge drop no Scourgestones unless you wear an {item:12846}. {npc:10840} gives you one through her quest, {item:12846}, which you hand in straight away (if you already have one from {area:2268}, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones."] = "Le Fléau ne lâche pas de pierres du Fléau si vous ne portez pas {item:12846}. {npc:10840} vous en donne une par sa quête, {item:12846}, que vous rendez aussitôt (si vous en avez déjà une de {area:2268}, portez-la). Équipez-la dans un emplacement de bijou : elle apparaît comme une amélioration qui ne s'épuise jamais. Gardez-la jusqu'à avoir 20 pierres.",
	["{item:12846}: equip it"] = "{item:12846} : équipez-la",
	["Kill the Scourge of the {zone:1422} with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a {item:12840} about two kills in five. {area:197}, just east of {area:3197} around {area:196}, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast {spell:120} and {spell:1449} up close, Dark Summoners run for help at low health."] = "Tuez le Fléau de {zone:1422} avec la commission sur vous : squelettes, goules et cultistes (niveau 50-58) lâchent {item:12840} environ deux fois sur cinq. {area:197}, juste à l'est de {area:3197} autour de {area:196}, est l'endroit le plus proche. Évitez les golems de chair qui patrouillent dans les champs ; les gardiens squelettes lancent {spell:120} et {spell:1449} au contact, les invocateurs sombres fuient chercher de l'aide quand leur vie est basse.",
	["{item:12840} x20"] = "{item:12840} x20",
	["{npc:1854} keeps watch at {area:196} on {area:197}, east of the camp. He turns your 20 stones into one {item:20612}: keep it."] = "{npc:1854} monte la garde à {area:196} sur {area:197}, à l'est du camp. Il transforme vos 20 pierres en un {item:20612} : gardez-le.",
	["Back to {area:3197}. Ashlam needs the voodoo of the {area:1417}'s trolls for the stone."] = "Retour à {area:3197}. Ashlam a besoin du vaudou des trolls de {area:1417} pour la pierre.",
	["{area:1477}, the {area:1417}, lies in the {area:74} in eastern {zone:1435}: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first."] = "{area:1477}, {area:1417}, se trouve dans {area:74}, dans l'est de {zone:1435} : montez l'escalier de la ruine, plongez dans la salle inondée et suivez l'escalier jusqu'au portail. C'est un donjon pour un groupe de cinq vers les niveaux 50-55. Six mini-chefs trolls élites (niveau 51-52) se tiennent sur les balcons autour de la grande salle ronde du temple, chacun derrière un groupe d'élites sur son passage latéral. Chacun lâche sa plume à chaque fois : Gasher et {npc:5716} l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte ; il vous les faut toutes les six. Hukku appelle des gardiens et lance des salves de traits de l'ombre, Mijan soigne : tuez-les en premier.",
	["{item:20606} x2: Gasher, {npc:5716}"] = "{item:20606} x2 : Gasher, {npc:5716}",
	["{item:20607} x2: Hukku, Mijan"] = "{item:20607} x2 : Hukku, Mijan",
	["{item:20608} x2: Zolo, Loro"] = "{item:20608} x2 : Zolo, Loro",
	["Back to Ashlam in {area:3197}: he forges the {item:20620}. Look at the reward window before you hand in: Classic also offered the {item:20505}, the {item:20504} or the {item:20512}, and Forever's notes say that choice may be gone. Use the stone before a fight against undead ({area:2279}, {area:2057}): it lasts ten minutes and is gone after one use."] = "Retour auprès d'Ashlam à {area:3197} : il forge {item:20620}. Regardez la fenêtre de récompense avant de rendre : Classic proposait aussi {item:20505}, {item:20504} ou {item:20512}, et les notes de Forever disent que ce choix a peut-être disparu. Utilisez la pierre avant un combat contre des morts-vivants ({area:2279}, {area:2057}) : elle dure dix minutes et disparaît après un usage.",
	["{spell:7328} at 12, the paladin's resurrection: an easy chain through your capital and its home zone."] = "{spell:7328} au niveau 12, la résurrection du paladin : une suite facile à travers votre capitale et sa zone d'origine.",
	["The summons (Human)"] = "La convocation (humain)",
	["At 12 {npc:927}, the paladin trainer in {area:87}, sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. The errand is optional, a little XP: {npc:5149} in {zone:1455} gives the same one (taking one closes the other), and {npc:6171} starts the chain without it."] = "Au niveau 12, {npc:927}, le maître des paladins de {area:87}, vous envoie auprès de {npc:6171} dans la cathédrale de la Lumière de {zone:1453}. La course est facultative, un peu d'expérience : {npc:5149} à {zone:1455} donne la même (en prendre une ferme l'autre), et {npc:6171} commence la suite sans elle.",
	["The summons (Dwarf)"] = "La convocation (nain)",
	["At 12 {npc:5149}, the paladin trainer in {zone:1455}'s {object:32362}, sends you upstairs to {npc:6179}. The errand is optional, a little XP: {npc:1232} in {area:131} and {npc:928} in {zone:1453} give the same one (taking one closes the others), and {npc:6179} starts the chain without it."] = "Au niveau 12, {npc:5149}, le maître des paladins dans {object:32362} de {zone:1455}, vous envoie à l'étage auprès de {npc:6179}. La course est facultative, un peu d'expérience : {npc:1232} à {area:131} et {npc:928} à {zone:1453} donnent la même (en prendre une ferme les autres), et {npc:6179} commence la suite sans elle.",
	["{npc:6171} stands inside the Cathedral of Light. He hands you the {item:6775}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6171} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Il vous remet {item:6775} : faites un clic droit dessus dans vos sacs pour commencer la quête suivante. Si le livre indique que la quête est déjà faite, détruisez-le et demandez un nouvel exemplaire à {npc:6171}. Apportez 10 {item:2589} pour l'étape suivante si vous en avez.",
	["Right-click the {item:6775}"] = "Clic droit sur {item:6775}",
	["{npc:6174} stands at a corner in the middle of the {object:2096}, outside a general goods store. She wants 10 {item:2589}: humanoids drop it (Riverpaw gnolls in {zone:1436} about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the {object:2096}."] = "{npc:6174} se tient à un angle au milieu de {object:2096}, devant une boutique de fournitures. Elle veut 10 {item:2589} : les humanoïdes en lâchent (les gnolls Rivepatte de {zone:1436} environ une fois sur deux, les Défias et les kobolds un peu moins), ou achetez-en à l'hôtel des ventes à quelques pas dans {object:2096}.",
	["{item:2589} x10"] = "{item:2589} x10",
	["Back to the Cathedral. {npc:6171} gives you the {item:6866}; {npc:6173} lies wounded by the altar of the same hall. Keep the symbol: you need it on {npc:6172}. If you lose it, {npc:6171} gives you another (The {item:6866})."] = "Retour à la cathédrale. {npc:6171} vous donne {item:6866} ; {npc:6173} gît blessé près de l'autel de la même salle. Gardez le symbole : il vous servira sur {npc:6172}. Si vous le perdez, {npc:6171} vous en donne un autre ({item:6866}).",
	["{npc:6172} lies dead on {area:56}, the island in {area:86} in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast {spell:116} from far off: they stand apart, so pull one at a time."] = "{npc:6172} gît mort à {area:56}, l'île de {area:86} dans l'est d'Elwynn, au sommet de l'un des tertres autour du cercle de pierres. Ciblez son corps et utilisez {item:6866} pour le relever, puis parlez-lui. Si un autre paladin vient de le relever, son corps revient en trois minutes environ. Les sorciers renégats défias de l'île (niveau 9-10) lancent {spell:116} de loin : ils sont espacés, attirez-les donc un par un.",
	["{item:6866} on {npc:6172}'s body"] = "{item:6866} sur le corps de {npc:6172}",
	["The Defias Rogue Wizards around the big stone tablet east of {npc:6172} carry the {item:6846}: about one kill in two drops it, but some players need many kills. They respawn in three minutes."] = "Les sorciers renégats défias autour de la grande tablette de pierre à l'est de {npc:6172} portent {item:6846} : environ une victime sur deux le lâche, mais certains joueurs ont besoin de beaucoup de victimes. Ils réapparaissent en trois minutes.",
	["Back to the Cathedral of Light: {npc:6173} takes the script, {npc:6171} teaches you {spell:7328}."] = "Retour à la cathédrale de la Lumière : {npc:6173} prend le texte, {npc:6171} vous enseigne {spell:7328}.",
	["{npc:6179}, upstairs in the {object:32386}"] = "{npc:6179}, à l'étage de {object:32386}",
	["{npc:6179} stands upstairs in the {object:32386}, in the {object:32362}: take the ramp at the back of the hall. She hands you the {item:6916}: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask {npc:6179} for a new copy. Bring 10 {item:2589} for the next step if you have it."] = "{npc:6179} se tient à l'étage de {object:32386}, dans {object:32362} : prenez la rampe au fond de la salle. Elle vous remet {item:6916} : faites un clic droit dessus dans vos sacs pour commencer la quête suivante. Si le livre indique que la quête est déjà faite, détruisez-le et demandez un nouvel exemplaire à {npc:6179}. Apportez 10 {item:2589} pour l'étape suivante si vous en avez.",
	["Right-click the {item:6916}"] = "Clic droit sur {item:6916}",
	["{npc:6175} walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 {item:2589}: humanoids drop it ({npc:1245} in {area:131} every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring."] = "{npc:6175} arpente l'anneau extérieur de la Place commune, après la grande porte, la banque et l'hôtel des ventes. Il veut 10 {item:2589} : les humanoïdes en lâchent ({npc:1245} à {area:131} à chaque fois, les embusqués Sombrefer environ deux fois sur cinq), ou achetez-en à l'hôtel des ventes sur son anneau.",
	["Back upstairs in the {object:32386}. {npc:6179} gives you the {item:6866}; her husband {npc:6178} rests on the same floor. Keep the symbol: you need it on {npc:6177}. If you lose it, {npc:6179} gives you another (The {item:6866})."] = "Retour à l'étage de {object:32386}. {npc:6179} vous donne {item:6866} ; son mari {npc:6178} se repose au même étage. Gardez le symbole : il vous servira sur {npc:6177}. Si vous le perdez, {npc:6179} vous en donne un autre ({item:6866}).",
	["{npc:6177} lies dead in {zone:1426}, not {zone:1432}: east past {area:131}, north-east of Ironband's compound, on the smallest of three little hills between {area:212} and the {object:147516} camp. Target his body and use the {item:6866} to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes."] = "{npc:6177} gît mort à {zone:1426}, pas à {zone:1432} : à l'est après {area:131}, au nord-est du domaine d'Ironband, sur la plus petite de trois petites collines entre {area:212} et le camp {object:147516}. Ciblez son corps et utilisez {item:6866} pour le relever, puis parlez-lui. Si un autre paladin vient de le relever, son corps revient en trois minutes environ.",
	["{item:6866} on {npc:6177}'s body"] = "{item:6866} sur le corps de {npc:6177}",
	["The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the {item:6847}. They run for help at low health: finish them or step back. They respawn in three minutes."] = "Les espions Sombrefer (niveau 9-11, douze en tout) se faufilent autour de la petite maison en contrebas du lac, juste au sud de Narm ; vous les voyez depuis sa colline. Environ une victime sur deux lâche {item:6847}. Ils fuient chercher de l'aide quand leur vie est basse : achevez-les ou reculez. Ils réapparaissent en trois minutes.",
	["Back up to the {object:32386}: {npc:6178} takes the script, {npc:6179} teaches you {spell:7328}."] = "Remontez à {object:32386} : {npc:6178} prend le texte, {npc:6179} vous enseigne {spell:7328}.",
	["The Alliance paladin's rare two-handed mace for the 20s, with a shield and {spell:5502} on the way."] = "La masse à deux mains rare du paladin de l'Alliance pour la vingtaine, avec un bouclier et {spell:5502} en chemin.",
	["At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}."] = "Au niveau 20, {npc:6179}, à l'étage de {object:32386} dans {object:32362}, vous donne {item:6776}. Faites un clic droit dessus : il vous envoie auprès de {npc:6171} dans la cathédrale de la Lumière de {zone:1453}. Prenez {area:2257} de {zone:1455} à {zone:1453}.",
	["{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Les humains reçoivent {item:6776} de lui. Faites un clic droit sur le livre pour commencer sa quête et rendez-la-lui aussitôt.",
	["Right-click the {item:6776}"] = "Clic droit sur {item:6776}",
	["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "La ferme de {npc:6182} se trouve sur la côte sud-ouest de {zone:1436}, au sud de {area:20} : prenez le chemin qui descend au sud à côté de la sortie arrière de {area:1581}. Quand vous prenez sa quête, elle marche de son verger à la maison et trois vagues de pillards défias (niveau 17-18) attaquent : trois, puis quatre, puis cinq. Combattez près d'elle pour qu'ils ne l'encerclent pas, et soignez-la quand sa vie baisse. Vous avez le temps de manger et boire entre les vagues, et elle se soigne entièrement. Si vous ou {npc:6182} mourez, la quête échoue : abandonnez-la et reprenez-la auprès d'elle (elle revient cinq minutes après sa mort). Les joueurs la trouvent difficile seuls avant le niveau 24 environ.",
	["Protect {npc:6182}: three waves"] = "Protégez {npc:6182} : trois vagues",
	["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Retour à la cathédrale de la Lumière : {npc:6171} vous donne le bouclier {item:9607} et vous enseigne {spell:5502}.",
	["{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes."] = "{npc:6181} travaille devant les portes de {zone:1455}, pas à l'intérieur. Il vous donne {item:6996} : quatre pièces, dans n'importe quel ordre. Gardez les notes.",
	["{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's."] = "{npc:6241} est au rez-de-chaussée de la maison de {area:144} qui a un marchand de couture devant. Sa quête ne s'ouvre qu'une fois celle de Jordan en votre possession.",
	["The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one."] = "La caisse de minerai se trouve dehors, au milieu du camp des ogres Mo'grosh dans le nord-est de {zone:1432}, à côté d'un grand arbre et d'un chariot cassé, entre les grottes. Le camp abrite une quinzaine d'ogres Mo'grosh élites (niveau 18-19), qui vous renversent et reviennent au bout de cinq minutes : un groupe est conseillé ; aux niveaux 20-22, il faut un groupe d'environ trois. La caisse revient deux secondes après chaque ramassage, chaque paladin du groupe en a donc une.",
	["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "{npc:6241} transforme le minerai en {item:6993}, la pièce que veut Jordan.",
	["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "{area:1581} est un donjon pour cinq sous {area:20} ; le portail de l'instance est au fond de la mine de {area:20}. Les sculpteurs sur bois gobelins (élites, niveau 18-19) de la salle du mât avec Sneed lâchent le bois à chaque fois.",
	["{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it."] = "{area:236} est un donjon pour un groupe de cinq entre le début et le milieu de la vingtaine, dans le sud de {zone:1421}, en terre de la Horde : un long voyage pour l'Alliance, par {zone:1437}, Arathi et {area:287}. Le marteau est posé sur une caisse face aux chevaux dans les écuries, au début du donjon, au fond de la cour avant la rampe ; il revient cinq minutes après qu'on l'a pris.",
	["{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it."] = "{npc:3649} est à {area:442}. Prenez sa quête avant de chasser les nagas : la gemme de Kor ne tombe jamais sans elle.",
	["The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "Les nagas de Brassenoire des passages inondés autour de l'entrée de {area:2797}, sur la côte nord-ouest de {zone:1440}, lâchent {item:6995} : prêtresses des marées (niveau 20-21), oracles (21-22) et sorcières des mers (23-24), une fois sur deux. Inutile d'entrer dans l'instance. Tous sont élites : un groupe est conseillé ; les joueurs les battent seuls un par un, difficilement. Ils se soignent, fuient chercher de l'aide quand leur vie est basse, des satyres se tiennent près de certains, et les sorcières des mers lancent {spell:122} au contact. Certains joueurs signalent ne rien obtenir en groupe de raid.",
	["Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil."] = "Apportez les quatre pièces à {npc:6181} devant {zone:1455}. Acceptez sa dernière quête et attendez à côté de lui pendant qu'il forge la masse à son enclume.",
	["The Gnome priest spells, new in Forever: {quest:94817} at 10, {quest:94818} at 20. Free, no objectives."] = "Les sorts de prêtre gnome, nouveaux sur Forever : {quest:94817} au niveau 10, {quest:94818} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city."] = "Au niveau 10, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455}. {area:131} est sur la route qui monte à la ville.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455}.",
	["At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 10 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:94817} pour {npc:258785} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 10, go to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362} (north-west of the city), right beside {npc:11406}: she gives {quest:94817} and takes it back at once. No letter needed. {quest:94817} confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run."] = "Au niveau 10, allez voir {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} (au nord-ouest de la ville), juste à côté de {npc:11406} : elle donne {quest:94817} et la reprend aussitôt. Pas besoin de lettre. {quest:94817} désoriente jusqu'à cinq ennemis autour de vous pendant 3 secondes (tout dégât les réveille), avec 2 minutes de recharge : le temps de reculer et de vous soigner, ou de fuir.",
	["Follow the road up from {area:131} into {zone:1455} and to the {object:32362}: {npc:258785} in the {object:32386} takes the letter and teaches {quest:94824}."] = "Suivez la route qui monte de {area:131} jusqu'à {zone:1455} et {object:32362} : {npc:258785}, dans {object:32386}, prend la lettre et enseigne {quest:94824}.",
	["{quest:94822}: Josetta's letter"] = "{quest:94822} : la lettre de Josetta",
	["Hand the letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["{quest:94821}: Laurena's letter"] = "{quest:94821} : la lettre de Laurena",
	["Any {quest:94823} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94823} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["Any {quest:94825} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94825} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["Any {quest:94826} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94826} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94818} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:94818} pour {npc:258785} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 20, {npc:258785} in the {object:32386} teaches {quest:94818} with a quest she gives and takes back at once. {quest:94818} wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with {spell:139} and {spell:17}). 5-minute cooldown."] = "Au niveau 20, {npc:258785}, dans {object:32386}, enseigne {quest:94818} par une quête qu'elle donne et reprend aussitôt. {quest:94818} protège un allié pendant 30 secondes : s'il passe sous 35 % de vie, il reçoit aussitôt un bouclier et un soin sur la durée (cumulable avec {spell:139} et {spell:17}). 5 minutes de recharge.",
	["{quest:94819}: Laurena's letter"] = "{quest:94819} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre de Laurena à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["Any {quest:94820} letter goes to {npc:258785} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Toute lettre {quest:94820} va à {npc:258785} dans {object:32386}, {object:32362} de {zone:1455}.",
	["The Dwarf priest spells: {quest:5634} at 10, {quest:5641} (new in Forever) at 20. Free, no objectives."] = "Les sorts de prêtre nain : {quest:5634} au niveau 10, {quest:5641} (nouveau sur Forever) au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:5634} letter for {npc:11406}. {area:131} is on the road up to {zone:1455}."] = "Au niveau 10, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet une lettre {quest:5634} pour {npc:11406}. {area:131} est sur la route qui monte à {zone:1455}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455} (the {area:2257} from {zone:1453}'s {object:28027})."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455} ({area:2257} depuis {object:28027} de {zone:1453}).",
	["At 10 in {zone:1453}, {npc:11397}, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a {quest:5634} letter for {npc:11406} in {zone:1455}. {npc:376} in the Cathedral has none for Dwarves."] = "Au niveau 10 à {zone:1453}, {npc:11397}, le maître des prêtres du Parc (le quartier des elfes de la nuit, à l'ouest de la ville), vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}. {npc:376}, à la cathédrale, n'en a pas pour les nains.",
	["At 10 in {zone:1438}, {npc:3600}, in the building at the north edge of {area:186}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Au niveau 10 à {zone:1438}, {npc:3600}, dans le bâtiment au bord nord de {area:186}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}.",
	["At 10 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5634} letter for {npc:11406} in {zone:1455}."] = "Au niveau 10 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre {quest:5634} pour {npc:11406} à {zone:1455}.",
	["At 10, go to {npc:11406} in the {object:32386}, in {zone:1455}'s {object:32362} (north-west of the city): he gives {quest:5634} and takes it back at once. No letter needed. {quest:5634} heals you instantly, costs no mana and has a long cooldown: keep it for emergencies."] = "Au niveau 10, allez voir {npc:11406} dans {object:32386}, dans {object:32362} de {zone:1455} (au nord-ouest de la ville) : il donne {quest:5634} et la reprend aussitôt. Pas besoin de lettre. {quest:5634} vous soigne instantanément, ne coûte pas de mana et a une longue recharge : gardez-la pour les urgences.",
	["Follow the road up from {area:131} into {zone:1455} and west to the {object:32362}: {npc:11406} in the {object:32386} takes the letter and teaches {quest:5637}. The letter tells you to head to {zone:1453}, but the one who wants you is Rohan in {zone:1455}."] = "Suivez la route qui monte de {area:131} jusqu'à {zone:1455} puis à l'ouest jusqu'à {object:32362} : {npc:11406}, dans {object:32386}, prend la lettre et enseigne {quest:5637}. La lettre vous dit d'aller à {zone:1453}, mais celui qui vous attend est Rohan, à {zone:1455}.",
	["{quest:5635}: Josetta's letter"] = "{quest:5635} : la lettre de Josetta",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: the {area:2257} from {zone:1453}'s {object:28027}."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : {area:2257} depuis {object:28027} de {zone:1453}.",
	["{quest:5638}: Nara's letter"] = "{quest:5638} : la lettre de Nara",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1438}, the boat from {area:702} to {area:442}, the boat to {area:150} and the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : depuis {zone:1438}, le bateau de {area:702} à {area:442}, le bateau jusqu'à {area:150} et la route vers le nord par {zone:1437} et {zone:1432} (ou le bateau jusqu'à {area:17203} et {area:2257}).",
	["{quest:5640}: Alathea's letter"] = "{quest:5640} : la lettre d'Alathea",
	["Hand the letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: its text says {zone:1453}, but Rohan is in {zone:1455}. From {zone:1457}, the portal down to {area:702}, the boat to {area:442}, then {area:150} and the road north (or {area:17203} and the {area:2257})."] = "Remettez la lettre à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : son texte indique {zone:1453}, mais Rohan est à {zone:1455}. Depuis {zone:1457}, le portail qui descend à {area:702}, le bateau jusqu'à {area:442}, puis {area:150} et la route vers le nord (ou {area:17203} et {area:2257}).",
	["{quest:5634}: an old letter"] = "{quest:5634} : une ancienne lettre",
	["This letter also goes to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}."] = "Cette lettre va aussi à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:5641} letter for {npc:11406} in {zone:1455} (the {area:2257} from the {object:28027})."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {quest:5641} pour {npc:11406} à {zone:1455} ({area:2257} depuis {object:28027}).",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a {quest:5641} letter for {npc:11406} in {zone:1455}."] = "Au niveau 20 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre {quest:5641} pour {npc:11406} à {zone:1455}.",
	["At 20, {npc:11406} in the {object:32386} teaches {quest:5641} with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: {quest:5641} damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains {spell:6346}."] = "Au niveau 20, {npc:11406}, dans {object:32386}, enseigne {quest:5641} par une quête qu'il donne et reprend aussitôt. Forever l'a renommé (anciennement Absence de peur) : {quest:5641} inflige des dégâts à un humanoïde et l'immobilise 2 secondes (instantané, 2 minutes de recharge), et tous les prêtres apprennent maintenant {spell:6346}.",
	["{quest:5645}: Laurena's letter"] = "{quest:5645} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: he teaches {quest:5645}."] = "Remettez la lettre de Laurena à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : il enseigne {quest:5645}.",
	["{quest:5647}: Alathea's letter"] = "{quest:5647} : la lettre d'Alathea",
	["Hand Alathea's letter to {npc:11406} in the {object:32386}, {zone:1455}'s {object:32362}: from {zone:1457}, the boats via {area:702} and {area:442} to {area:150}, then the road north through the {zone:1437} and {zone:1432} (or the boat to {area:17203} and the {area:2257})."] = "Remettez la lettre d'Alathea à {npc:11406} dans {object:32386}, {object:32362} de {zone:1455} : depuis {zone:1457}, les bateaux par {area:702} et {area:442} jusqu'à {area:150}, puis la route vers le nord par {zone:1437} et {zone:1432} (ou le bateau jusqu'à {area:17203} et {area:2257}).",
	["The Human priest spells: {quest:94773} at 10 (new in Forever), {spell:13896} at 20. Free, no objectives."] = "Les sorts de prêtre humain : {quest:94773} au niveau 10 (nouveau sur Forever), {spell:13896} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a letter for {npc:376}. {area:87} is on the road north to {zone:1453}, so it costs no detour."] = "Au niveau 10, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet une lettre pour {npc:376}. {area:87} est sur la route du nord vers {zone:1453}, sans détour.",
	["A Human priest in {zone:1438} at 10: {npc:3600}, in the building at the north edge of {area:186}, hands you a letter for {npc:376} in {zone:1453}."] = "Un prêtre humain à {zone:1438} au niveau 10 : {npc:3600}, dans le bâtiment au bord nord de {area:186}, vous remet une lettre pour {npc:376} à {zone:1453}.",
	["At 10, go to {npc:376} at the altar of the Cathedral of Light, in {zone:1453}'s {object:2098}, and take her quest: she teaches {quest:94773} on the spot. No letter needed; one from another trainer works too (next steps). {quest:94773} instantly heals a friend below half health and clears {spell:6788}, so you can shield them again (5-minute cooldown); it does not work on yourself. Human priests do not get Desperate Prayer in Forever: this is their spell instead."] = "Au niveau 10, allez voir {npc:376} à l'autel de la cathédrale de la Lumière, dans {object:2098} de {zone:1453}, et prenez sa quête : elle enseigne {quest:94773} sur place. Pas besoin de lettre ; celle d'un autre maître marche aussi (étapes suivantes). {quest:94773} soigne instantanément un allié sous la moitié de sa vie et dissipe {spell:6788}, pour pouvoir le protéger à nouveau (5 minutes de recharge) ; ne fonctionne pas sur vous-même. Les prêtres humains n'ont pas Prière du désespoir sur Forever : c'est leur sort à la place.",
	["{quest:94774}: Josetta's letter"] = "{quest:94774} : la lettre de Josetta",
	["Hand Josetta's letter to {npc:376} at the altar of the Cathedral of Light: she teaches {quest:94774}."] = "Remettez la lettre de Josetta à {npc:376} à l'autel de la cathédrale de la Lumière : elle enseigne {quest:94774}.",
	["Hand {npc:3600}'s letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1438}: the boat from {area:702} to {area:442}, then the boat to {area:17203}): she teaches {quest:94775}."] = "Remettez la lettre de {npc:3600} à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} (depuis {zone:1438} : le bateau de {area:702} à {area:442}, puis le bateau jusqu'à {area:17203}) : elle enseigne {quest:94775}.",
	["Any {quest:94776} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94776} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94777} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94777} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94778} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94778} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["Any {quest:94779} letter goes to {npc:376} at the altar of the Cathedral of Light."] = "Toute lettre {quest:94779} va à {npc:376}, à l'autel de la cathédrale de la Lumière.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you a letter for {npc:376} in {zone:1453}. The {area:2257} from {object:171524} takes you there."] = "Au niveau 20 à {zone:1455}, {npc:11406}, dans {object:32386} ({object:32362}), vous remet une lettre pour {npc:376} à {zone:1453}. {area:2257} depuis {object:171524} vous y emmène.",
	["At 20 in {zone:1457}, {npc:11401}, on the upper balcony of the Temple of the Moon beside {npc:7999}, hands you a letter for {npc:376} in {zone:1453}."] = "Au niveau 20 à {zone:1457}, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, vous remet une lettre pour {npc:376} à {zone:1453}.",
	["At 20, {npc:376} at the altar of the Cathedral of Light teaches {spell:13896} with a quest she gives and takes back at once."] = "Au niveau 20, {npc:376}, à l'autel de la cathédrale de la Lumière, enseigne {spell:13896} par une quête qu'elle donne et reprend aussitôt.",
	["{spell:13896}: Rohan's letter"] = "{spell:13896} : la lettre de Rohan",
	["Hand Rohan's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (the {area:2257} from {object:171524} in {zone:1455}): she teaches {spell:13896}."] = "Remettez la lettre de Rohan à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} ({area:2257} depuis {object:171524} à {zone:1455}) : elle enseigne {spell:13896}.",
	["{spell:13896}: Alathea's letter"] = "{spell:13896} : la lettre d'Alathea",
	["Hand Alathea's letter to {npc:376} at the altar of {zone:1453}'s Cathedral of Light (from {zone:1457}: the portal down to {area:702}, the boat to {area:442}, then the boat to {area:17203}): she teaches {spell:13896}."] = "Remettez la lettre d'Alathea à {npc:376} à l'autel de la cathédrale de la Lumière de {zone:1453} (depuis {zone:1457} : le portail qui descend à {area:702}, le bateau jusqu'à {area:442}, puis le bateau jusqu'à {area:17203}) : elle enseigne {spell:13896}.",
	["Priest Robes at 5 (Alliance)"] = "Robes de prêtre au niveau 5 (Alliance)",
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Une robe inhabituelle gratuite au niveau 5 : soignez et fortifiez un garde blessé près de votre première ville.",
	["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:375}, le maître des prêtres dans {area:24}, vous envoie auprès de {npc:377} à {area:87}. Apprenez {spell:613} (rang 2) auprès d'Anetta tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Suivez la route au sud pour sortir de {area:9} jusqu'à {area:87}. {npc:377} est à l'étage de l'auberge de la Fierté du lion.",
	["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (rang 2), si Anetta ne l'a pas encore enseigné",
	["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} est agenouillé près d'un arbre sur la rive du lac à l'est de {area:87}, à l'écart de la route : longez la rive, la minimap ne le montre pas depuis la route. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243}. Le rang 1 de {spell:613} ne compte pas ; faites glisser le rang 2 du grimoire sur votre barre (ou lancez les deux depuis le grimoire si un addon de barres d'action gêne). Il s'en va une fois les deux sorts reçus et revient en 3 minutes environ.",
	["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "De retour à l'étage de l'auberge de la Fierté du lion : Josetta vous donne {item:16605}.",
	["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:837}, le maître des prêtres dans {area:77} à {area:132}, vous envoie auprès de {npc:1226} à {area:131}. Apprenez {spell:613} (rang 2) auprès de lui tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Prenez le tunnel au nord-est pour sortir de {area:132} et suivez la route vers l'est jusqu'à {area:131}. {npc:1226} est dans {area:2102}.",
	["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (rang 2), si {npc:837} ne l'a pas encore enseigné",
	["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} est agenouillé sur une crête entre deux murets juste au sud de {area:131}, de l'autre côté de la route du maître des familiers : si la route commence à descendre, vous l'avez dépassé. Lancez d'abord {spell:613} (rang 2) sur lui, puis {spell:1243} ; il parle après chaque sort. Le rang 1 de {spell:613} ne compte pas.",
	["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "De retour dans {area:2102} : {npc:1226} vous donne {item:16605}.",
	["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "Au niveau 5, {npc:3595}, la maîtresse des prêtres au deuxième niveau de {area:256}, le grand arbre de {area:188}, vous envoie auprès de {npc:3600} à {area:186}. Apprenez {spell:613} (rang 2) auprès d'elle tant que vous y êtes : il s'ouvre au niveau 4 pour 1 pièce d'argent, et la quête suivante demande exactement ce rang.",
	["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Quittez {area:188} par la rampe et suivez la route au sud-ouest jusqu'à {area:186}. {npc:3600} est dans le bâtiment au bord nord du village.",
	["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (rang 2), si {npc:3595} ne l'a pas encore enseigné",
	["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} est agenouillée sur les rochers au bord de {area:259}, à environ 100 mètres au sud de {area:186}, sans point d'exclamation au-dessus d'elle. Lancez d'abord {spell:613} (rang 2) sur elle, puis {spell:1243} ; elle court vers le lac une fois les deux sorts reçus et revient en 5 minutes environ. Le rang 1 de {spell:613} ne compte pas.",
	["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "De retour au bord nord de {area:186} : {npc:3600} vous donne {item:16604}.",
	["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "Les sorts de prêtre elfe de la nuit : {spell:10797} au niveau 10, {spell:2651} au niveau 20. Gratuits, sans objectif.",
	["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "Au niveau 10, {npc:3600}, le maître des prêtres dans le bâtiment au bord nord de {area:186}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {area:186} est sur la route de l'ouest vers {zone:1457}.",
	["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1429}, {npc:377}, à l'étage de l'auberge de la Fierté du lion à {area:87}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1426}, {npc:1226}, le maître des prêtres dans {area:2102} à {area:131}, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 10 à {zone:1453}, {npc:5489}, à l'autel de la cathédrale de la Lumière, vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}. {npc:11397}, au Parc, a la même lettre.",
	["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "Au niveau 10 à {zone:1455}, {npc:5142}, dans {object:32386} ({object:32362}), vous remet {quest:5628}, une lettre pour {npc:11401} à {zone:1457}.",
	["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "Au niveau 10, allez voir {npc:11401} sur le balcon supérieur du temple de la Lune, à l'extrémité sud de {zone:1457} : prenez la rampe qui monte du sol du temple ; elle se tient à côté de {npc:7999}. {quest:5627} est donnée et reprise aussitôt et enseigne {spell:10797}. Pas besoin de lettre. Forever a rendu {spell:10797} bien plus puissant, avec 30 secondes de recharge.",
	["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Prenez la route vers l'ouest depuis {area:186} jusqu'à {zone:1457} et montez au balcon supérieur du temple de la Lune, à côté de {npc:7999} : {npc:11401} prend {quest:5629} et enseigne {spell:10797}.",
	["{spell:10797}: Josetta's letter"] = "{spell:10797} : la lettre de Josetta",
	["{quest:5628} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5628} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5630} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5630} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{spell:10797}: Joshua's letter"] = "{spell:10797} : la lettre de Joshua",
	["{quest:5631} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5631} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{spell:10797}: Nara's letter"] = "{spell:10797} : la lettre de Nara",
	["{quest:5632} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5632} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5633} goes to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: take the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "{quest:5633} va à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : prenez le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "Au niveau 20 à {zone:1453}, {npc:376}, à l'autel de la cathédrale de la Lumière, vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}. {npc:11397}, au Parc, a la même lettre.",
	["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "Au niveau 20 à {zone:1455}, {npc:11406}, dans {object:32386} ({object:32362}), vous remet une lettre {spell:2651} pour {npc:11401} à {zone:1457}.",
	["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "Au niveau 20, {npc:11401}, sur le balcon supérieur du temple de la Lune à côté de {npc:7999}, enseigne {quest:5672} par une quête qu'elle donne et reprend aussitôt. Sur Forever, {quest:5672} divise par deux les chances des attaques de mêlée et à distance de vous toucher pendant 15 secondes ou jusqu'à ce que trois attaques ratent.",
	["{quest:5673}: Laurena's letter"] = "{quest:5673} : la lettre de Laurena",
	["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Laurena à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5674}: Nara's letter"] = "{quest:5674} : la lettre de Nara",
	["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Nara à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["{quest:5675}: Rohan's letter"] = "{quest:5675} : la lettre de Rohan",
	["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Remettez la lettre de Rohan à {npc:11401}, sur le balcon supérieur du temple de la Lune à {zone:1457}, à côté de {npc:7999} : le bateau de {area:17203} (ou de {area:150}) à {area:442}, puis le bateau jusqu'à {area:702}, puis le portail qui monte à {zone:1457}.",
	["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "Au niveau 10, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous donne un paquet pour {npc:332} à {zone:1453}. Apprenez {spell:921} si vous ne l'avez pas : cette suite en a besoin.",
	["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Partez au nord jusqu'à {zone:1453}. Shaw se tient à l'étage du bâtiment du SI:7 dans {object:2100} (la quête parle de la caserne ; il s'agit du SI:7).",
	["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "{npc:6846} (niveau 10, un gobelin) travaille dans la maison du quai à {area:797}, sur la rivière au bord sud d'Elwynn, au sud de {area:87}. Entrez camouflé et faites-lui {spell:921} par-derrière : l'horaire ne tombe jamais de son cadavre. N'ouvrez pas avec {spell:2070} ni par un combat : il appelle trois vagues de gardes du corps. Tenez-vous loin des cheminées de la maison ; elles vous font sortir du camouflage. Il revient 2 à 5 minutes après sa mort.",
	["{item:7675}: {spell:921} the {npc:6846}"] = "{item:7675} : {spell:921} sur {npc:6846}",
	["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} est dans {object:32383}, le quartier des voleurs au nord de {zone:1455} : entrez dans le bâtiment avec un marchand louche devant et descendez l'escalier.",
	["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Partez vers l'ouest jusqu'à {area:133}. À côté de la route qui mène à son entrée se dresse une tour en spirale en bois : {npc:6886} attend camouflé sur la plate-forme du haut, à côté d'un {npc:1211} de niveau 10 ; vous ne le voyez que de près.",
	["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "Au niveau 10, {npc:3599}, le maître des voleurs de l'auberge de {area:186}, vous donne une rose pour {npc:4163} à {zone:1457}. Si vous perdez la rose, abandonnez la quête et reprenez-la.",
	["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Partez vers l'ouest jusqu'à {zone:1457}. {npc:4163} est sous terre à {area:1658} : on descend par l'ouverture au pied de l'arbre fendu à gauche de l'arbre de l'archidruide, près du maître des sabres-de-nuit. Son repère sur la carte s'affiche à la surface.",
	["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (satyre de niveau 12) vit sur une grande branche au nord de {area:264} : passez par la brèche en V dans le mur au nord de la clairière et avancez le long de la branche. Faites-lui les poches pour le journal ; le tuer ne le donne pas, et un combat fait venir trois serviteurs de Sethir. Il marche entre la branche principale et une branche latérale : attendez camouflé au bout de la branche principale et faites-lui les poches par-derrière quand il revient. Puis {spell:2983} pour partir. Il revient 8 minutes et demie après sa mort.",
	["{item:7737}: Pick Pocket Sethir the Ancient"] = "{item:7737} : faire les poches de Sethir l'Ancien",
	["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}, then {item:7676} from {npc:7009}."] = "Votre premier crochetage au niveau 16 : le coffret de {npc:6966} à {quest:2282}, pour {quest:2300}, puis {item:7676} auprès de {npc:7009}.",
	["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "Au niveau 16, {npc:917}, le maître des voleurs à l'étage de l'auberge de la Fierté du lion à {area:87}, vous envoie auprès de {npc:6946} à {zone:1453}. La prendre ferme les indications des autres villes.",
	["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "Au niveau 16, {npc:1234}, dans {area:2102} à {area:131}, vous envoie auprès de {npc:5165} dans {object:32383} de {zone:1455}.",
	["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} est dans la maison avec un marchand louche devant, dans {object:32383}, en bas de l'escalier. Puis volez ou prenez {area:2257} jusqu'à {zone:1453}.",
	["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "Au niveau 16, {npc:3599}, à l'auberge de {area:186}, vous envoie auprès de {quest:2259} à {zone:1457}.",
	["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} se tient à {area:1658}. Puis le bateau de {area:702} à {area:442}, et le bateau de {area:442} à {area:17203}.",
	["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} se tient à l'étage du bâtiment de {quest:2300} dans {object:2100}, derrière les maîtres des voleurs. Avant de partir : si vous n'avez pas {spell:1804}, {npc:13283}, dans le bâtiment de {quest:2300}, l'enseigne ; le crochetage est l'épreuve de la quête suivante.",
	["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Partez vers l'est à travers {zone:1429} jusqu'aux Carmines, ou volez jusqu'à {area:69}. {npc:6966} se tient sur une caisse sur l'un des quais de {area:69}, au sud de la ville ; il vous donne {item:5060} avec la tâche ({npc:3090} à {area:69} en vend d'autres). {spell:1804} ne marche pas sans les outils dans vos sacs.",
	["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} se trouve à l'est de {area:69}, en hauteur à l'écart de la route ; des orcs Rochenoire rôdent tout près. À l'intérieur, les coffrets d'entraînement reviennent presque aussitôt : crochetez-les jusqu'à ce que {object:121264} s'ouvre pour vous (environ 25 en crochetage). Votre plafond de crochetage monte de 5 par niveau, un personnage de bas niveau peut donc plafonner. Certains coffrets sont piégés (un piège de givre, par exemple) ; la compétence monte quand même. Sur Forever, des araignées de niveau 20 errent près des coffrets : éliminez-les d'abord ou venez avec un ami. Le coffret contient toujours le jeton et revient deux secondes après usage. Continuez à vous entraîner tant que ça fait monter la compétence : la quête de classe suivante demande environ 75.",
	["{npc:7009}, beside {npc:6966}, wants the {quest:2358}, which the Blackrock orcs of Redridge carry: the first one you kill drops them. The easiest are the Blackrock Grunts (level 19) and Outrunners (20) east of {area:69}; the Shadowcasters (22) and {npc:334} (26) are elite."] = "{npc:7009}, à côté de {npc:6966}, veut {quest:2358}, que portent les orcs Rochenoire des Carmines : le premier que vous tuez les lâche. Les plus faciles sont les grunts (niveau 19) et les coursiers (20) Rochenoire à l'est de {area:69} ; les lanceurs d'ombre (22) et {npc:334} (26) sont élites.",
	["{quest:2358}: any Blackrock orc"] = "{quest:2358} : n'importe quel orc Rochenoire",
	["{npc:7009}: ten {item:7676}"] = "{npc:7009} : dix {item:7676}",
	["Poisons (Alliance)"] = "Poisons (Alliance)",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "Forever enseigne les poisons par cette suite de quêtes, pas par le maître ; la recette de {item:7676} vient avec.",
	["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "Au niveau 20, {npc:332}, à l'étage du bâtiment du SI:7 dans {object:2100}, vous envoie auprès de {npc:7024} à {zone:1436}. C'est ainsi qu'on apprend les poisons sur Forever : ne la passez pas.",
	["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen se cache, camouflé, contre le côté ouest d'un grand arbre précédé de deux petits arbres, juste au nord de la tour défias de {npc:7053}, tout à l'est de {zone:1436}, près de la frontière de {zone:1431}. Lisez {item:8046} pour le plan de la tour si vous le souhaitez.",
	["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "Prenez d'abord la clé. {npc:7051} (niveau 23, non élite) part de l'entrée de la tour et fait une boucle à l'extérieur ; c'est celui aux cheveux hérissés qui laisse des étincelles jaunes. Camouflez-vous et faites-lui {spell:921} par-derrière : il a toujours la clé. Il frappe fort : si le camouflage tombe, {spell:2983} pour partir. Attention à la paire de bourdons défias qui patrouille aussi.",
	["{item:7923}: {spell:921} the {npc:7051}"] = "{item:7923} : {spell:921} sur {npc:7051}",
	["Klaven's journal"] = "Le journal de Klaven",
	["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Montez la tour en vous faufilant. Des patrouilleurs (23) et des sentinelles (24) défias gardent les étages ; une Embuscade à la dague les tue d'un coup si vous préférez les éliminer. {npc:7053}, un élite de niveau 26, attend au dernier étage : assommez-le, ou venez avec un ami. {object:123214}, à côté de son bureau, demande environ 70-75 en crochetage (entraînez-vous d'abord sur les coffrets de {area:97} aux Carmines). Une astuce : pendant que les sentinelles sont ailleurs, sautez de la chaise à la lampe puis à l'étagère au-dessus du coffre, sortez du camouflage et ouvrez le coffre de là. L'ouvrir vous empoisonne avec {spell:9810}, qui bloque votre camouflage un moment et permet au bourdon de vous voir ; c'est pourquoi la clé passe en premier. Puis sortez.",
	["{item:7908}: the {object:123214}, top floor"] = "{item:7908} : {object:123214}, dernier étage",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Partez au nord à travers Elwynn jusqu'à {zone:1453} ; Mathias Shaw est à l'étage du SI:7. Il enseigne les poisons et vous donne la recette de {item:7676}. Les poisons se fabriquent, ils ne s'achètent pas : chaque lot de {item:6947} demande {item:2928} et {item:3371}, que {npc:1325} et {npc:1326} vendent dans {object:2100} à côté du SI:7. Achetez une pile de chaque, ouvrez Poisons depuis votre grimoire pour les fabriquer, puis appliquez un poison sur votre arme.",
	["{npc:332}: Poisons"] = "{npc:332} : Poisons",
	["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} est toujours sur vous. {npc:7207} travaille dans la cave du bâtiment du SI:7 : l'escalier qui descend est sous celui qui monte à l'étage, derrière {npc:1325}. Ciblez-le et tapez /allonger (rien après) pour être examiné, puis attendez. S'il ne fait rien, abandonnez la quête, reprenez-la et attendez qu'il vous demande de vous allonger.",
	["/lay with the Doc targeted"] = "/allonger en ciblant le docteur",
	["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: an engineering supplier, who keeps only a few (or an engineer or the Auction House). The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Les quatre sont à {zone:1453}. {item:3421} : chez Bernard ou chez le fleuriste {npc:1303} près du canal de {object:2096}. {item:3372} : chez beaucoup de marchands de fournitures et d'alchimie ({npc:1257}, {npc:1325} et d'autres). {item:4371} : chez un fournisseur d'ingénierie, qui n'en a que quelques-uns (ou un ingénieur ou l'hôtel des ventes). {item:8431} gît au sol à côté de l'extrémité gauche du comptoir dans {object:2177}, la boutique du tailleur sur les canaux ; vous ne pouvez la ramasser qu'avec cette quête. Si vous passez le remède, {item:6452} ({skill:129}) ou le {spell:526} d'un druide dissipe aussi {spell:9810}.",
	["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "Au niveau 30, {npc:258098}, le maître des chamans de {zone:1455}, vous envoie auprès de {npc:259023} à {zone:1417}. Vos totems d'air du niveau 30 (Glèbe, {spell:10596}) ont besoin de {item:5178} qu'il donne.",
	["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} campe dans les collines juste à l'ouest de {area:321}, la ville de la Horde au nord-est d'Arathi : attention à ses gardes. Volez jusqu'à {area:320} et partez au nord-est.",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} est un donjon pour cinq joueurs au bord sud de {zone:1413} (la flèche pointe son entrée) ; {npc:4421} (élite de niveau 33) en est le dernier boss. Elle lance {spell:8292}, {spell:139} sur ses alliés et Pureté ; {item:274463} ne tombe que sur elle.",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinq totems de feu tordus. Les troggs de Cave-pierre (cogne-crânes, brise-os et chamans, niveau 37-41) au sud de {area:338} dans {zone:1418} en portent ; les chamans lâchent des totems de Nova de feu et {npc:3560}, les brise-os fuient chercher de l'aide quand ils sont blessés. Réapparition en cinq minutes environ.",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinq totems de terre tordus. Les Égarés (murlocs, niveau 34-39) au nord et au nord-est de {area:75} dans {zone:1435} en portent ; la plupart fuient chercher de l'aide quand ils sont blessés.",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinq totems d'eau tordus. Les murlocs Nageoire-de-boue (niveau 35-38) au nord-est de {area:496}, dans le nord de {zone:1445}, en portent.",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinq totems d'air tordus. Les centaures maraudine (niveau 36-40) au nord et au nord-est de {area:2408}, dans l'ouest de {zone:1443}, en portent ; les éclaireurs en lâchent un presque une fois sur deux. Les dresseurs lancent Filet et Désarmement, les chasse-vent soignent, les tempétueux lancent {spell:9654} : attirez-les un par un. Réapparition en cinq minutes environ.",
	["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} vous remet {item:268582}. {zone:1441} est loin : le bateau jusqu'à Theramore et la route vers l'ouest, ou volez jusqu'à {area:489} à la frontière de {zone:1444} et partez à l'est dans le canyon. Placez {item:268582} aux bassins de vapeur au nord-ouest de {area:484} pour appeler les élémentaires corrompus puis {npc:216474} ; des huttiers Tranchecrin rejoignent le combat pendant le rituel. Une quête de groupe : venez avec au moins un ou deux amis. {item:212792} tombe environ une fois sur deux, et chaque membre du groupe peut la ramasser.",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} campe dans les ruines à l'est de {zone:1416} : depuis {area:272}, suivez la rivière à l'est de la ville vers le nord dans les collines. Choisissez votre arme : {item:280607}, {item:280605} ou {item:280604}.",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Votre {item:5175} : sans elle, aucun totem de terre ne peut être posé. {spell:8071} vient avec, au niveau 4.",
	["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} entraîne les chamans dans {area:77}, la salle à l'extrémité sud de {area:132}. La quête s'ouvre au niveau 4. Jamais prise et maintenant niveau 10 ou plus ? {npc:258098} à {zone:1455} ou {npc:258113} à {area:131} vous donne {quest:94373}, une indication pour retourner voir Teo : prenez-la pour l'expérience en chemin.",
	["Iceclaw Bear Pendants"] = "Pendentifs d'ours Griffe-de-glace",
	["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Les jeunes trolls Crins-de-givre (niveau 3-4) tiennent les pentes enneigées à l'ouest et au sud-ouest de {area:77}, et les novices Crins-de-givre (niveau 3-4, ils lancent des éclairs de givre à distance) campent au sud. Les deux portent les pendentifs ; ils réapparaissent en trois minutes environ.",
	["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "Retour auprès de Teo dans {area:77}. Il vous remet {item:6635} : ne le buvez pas encore.",
	["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Seulement si {quest:94472} n'est plus dans vos sacs (bue loin de la pierre, ou vendue) : Teo vous en donne une autre.",
	["The Spirit Stone"] = "La pierre de l'esprit",
	["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "La pierre de l'esprit se dresse sur une crête enneigée au nord-ouest de {area:77}. Le sentier est facile à manquer : il monte la colline depuis le fond de la vallée ; au petit camp près du sommet, tournez à gauche et la pierre apparaît. Placez-vous à côté, buvez {item:6635} et parlez à {npc:5891} avant qu'il ne s'efface.",
	["it hands you the {item:6656}: keep it"] = "il vous remet {item:6656} : gardez-le",
	["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Rapportez {item:6656} à Teo dans {area:77}. Gardez {item:5175} dans vos sacs pour de bon : chaque totem de terre en a besoin.",
	["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446} : {spell:8071} et votre {item:5175}",
	["the level 4 shaman spells"] = "les sorts de chaman du niveau 4",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Votre {item:5176} pour chaque totem de feu, {spell:3599} avec, et {item:263412} de Forever.",
	["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "Au niveau 10, {npc:258113}, le maître des chamans de {area:131}, ou {npc:258098}, le maître des chamans de {zone:1455}, vous envoie auprès de {npc:257597}.",
	["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131} ; ou {npc:258098}, {zone:1455}",
	["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Suivez la route vers l'est jusqu'au tunnel vers {area:806}. À la sortie du premier tunnel, restez à gauche après {npc:1959} et la tour : un sentier étroit, difficile à voir mais indiqué sur la minimap, serpente dans la montagne jusqu'à la grotte de {npc:257597} au-dessus de la ferme. Il vous remet {item:6653} : gardez-le jusqu'à la fin de la suite.",
	["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Depuis le rebord de {npc:257597}, vous pouvez descendre prudemment la montagne jusqu'à {zone:1432}, ou revenir à pied par le tunnel. {npc:257808} garde le sanctuaire sur le pic juste au sud de {area:144} : un sentier caché le long d'une corniche, balisé de totems de pierre, y monte depuis la route au nord du pic.",
	["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Les voyants Brise-pierre (niveau 13-14) se tiennent parmi les troggs de {area:923} au sud du loch, et dans les camps de troggs au nord-est de {area:144}. Ils lancent {spell:1245113} à 40 mètres et fuient chercher de l'aide quand ils sont blessés : attirez-les un par un. Réapparition en cinq minutes environ.",
	["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Les géomanciens rats des tunnels (niveau 12-13) ne travaillent que dans {area:149}, à l'extrémité nord du loch, après {area:144}. Ils lancent {spell:2136} derrière {spell:134} et fuient chercher de l'aide quand leur vie est basse.",
	["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Remontez le sentier jusqu'à {npc:257808}. Il fabrique {item:6636} avec le goudron et la bourse : gardez-le avec la torche.",
	["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Seulement si {quest:94473} n'est plus dans vos sacs : {npc:257808} vous en donne un autre.",
	["The Shrine of Eternal Flame"] = "Le sanctuaire de la Flamme éternelle",
	["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Continuez après {npc:257808} jusqu'au pic. Buvez {item:6636} à côté de la statue de pierre pour voir {npc:5893} (niveau 12) : il attend que vous frappiez, mais devient plus fort plus on le laisse, et il est insensible au feu. Ouvrez tout de suite avec {spell:8017} et {spell:8042}. Son {item:6655} tombe à chaque fois.",
	["{item:6636}, beside the statue"] = "{item:6636}, à côté de la statue",
	["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Cliquez sur {object:61934} au sommet du sanctuaire avec la torche dans vos sacs pour placer la braise, puis cliquez à nouveau pour la quête suivante : {item:277329} allumée.",
	["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Revenez par le tunnel de la porte Sud et remontez le sentier jusqu'à la grotte de {npc:257597}. Gardez {item:5176} dans vos sacs pour de bon : chaque totem de feu en a besoin.",
	["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597} : {spell:3599}, votre {item:5176} et {item:263412}",
	["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "Au niveau 20, {npc:258098}, le maître des chamans dans {object:32362} de {zone:1455}, vous envoie auprès de {npc:258043} à {zone:1432}.",
	["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "La hutte terrier de {npc:258043} se dresse sur la rive nord-ouest du loch, sous {area:146}, au nord de {area:144}.",
	["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "La famille de {npc:258203} vit dans une grotte sous les chutes sud de {zone:1437}, à l'est de {area:836} : pas dans une ville. Par le tunnel d'Algaz au nord de {zone:1432}, puis à l'est en quittant la route.",
	["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Remplissez {item:265732} au pied des cascades sous la grotte de {npc:258203}, là où l'eau douce rencontre l'eau saumâtre. Des nains {object:147516} rôdent près des chutes.",
	["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} jaillissent de {area:68} à l'extrémité est des Carmines (volez de {zone:1455} à {area:69}). Remplissez {item:265747} à leur pied, là où se rassemblent les rampants nocturnes murlocs ; éloignez d'abord les murlocs de l'endroit. Si l'outre disparaît sans compter, abandonnez la quête et reprenez-la auprès de {npc:258203} pour en avoir une nouvelle.",
	["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Prenez le bateau de {area:150} à {area:442} (il fait escale à {area:271}), puis volez ou marchez au sud à travers {zone:1439} jusqu'à {area:415} à {zone:1440}. Remplissez {item:265772} dans le lac autour de la ville, puis reprenez le bateau pour Menethil.",
	["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Retour auprès de {npc:258043} près de {area:146} avec {item:7810}. Il vous remet {item:6637} et {item:7811} : gardez les deux pour {zone:1436}.",
	["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Seulement si {quest:94616} n'est plus dans vos sacs : {npc:258043} vous en donne une autre avant votre départ pour {zone:1436}.",
	["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Volez jusqu'à {area:108} et partez au sud jusqu'à {area:20} : {area:919} et {object:619896} se trouvent juste au nord. Buvez {item:6637} près du sanctuaire pour voir {npc:5894} (niveau 22, {spell:8056} et {spell:122} ; un seul exemplaire, de retour trois minutes après sa mort), battez-le pour ses brassards (toujours lâchés), puis placez-les avec {item:7811} sur {object:619896} (c'est cela, et non {npc:258043}, qui termine la quête). Cliquez à nouveau sur le sanctuaire : {npc:5895} se lève à côté ; parlez-lui avant de partir (s'il a disparu, abandonnez et reprenez la quête au sanctuaire). Il vous donne {item:7813}.",
	["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Retour auprès de {npc:258043} avec {item:7813}. Gardez {item:5177} dans vos sacs pour de bon : chaque totem d'eau en a besoin.",
	["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Un chapeau en tissu vers la fin de la vingtaine : la course de Zardeth pour tout joueur de l'Alliance rapporte ce bonus aux démonistes.",
	["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "Au niveau 25, {npc:1435}, dans la cave de {object:2164} dans {object:2101} (à côté des maîtres des démonistes), veut deux ingrédients pour une décoction. Faites-la quand votre montée en niveau vous mène à {zone:1431} et à {zone:1437}.",
	["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} se trouve au nord-est de {zone:1431}, au nord de {area:42}. {object:321} est une petite fleur blanche au ras de l'herbe dans le jardin clôturé à côté de la maison de Stalvan : difficile à voir, balayez donc le jardin avec la souris. Des cadavres fétides (niveau 29) errent sur le domaine et arrivent vite : au niveau 25, envoyez votre marcheur du Vide sur le plus proche, prenez la fleur et partez. {npc:315} (32) est dans la maison ; laissez-le tranquille.",
	["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "La racine pousse au bord de l'eau dans le bassin sous les petites chutes à l'est de {area:836}, à côté de la grotte {object:147516} sous {area:146} : une grande racine de bois hérissée, pas au pied du barrage lui-même.",
	["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "Retour auprès de Zardeth. Il prépare {item:2788} et vous le donne pour {npc:1439} dans la salle des Requérants, la première salle à droite dans {object:2117}.",
	["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "Retour une dernière fois auprès de Zardeth : il offre une récompense aux démonistes, que son diablotin {npc:1733}, à côté de lui, vous remet.",
	["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} est un port gobelin neutre sur la côte de {zone:1413} : le bateau de {area:35} y accoste. {npc:6251} se tient sur la colline au-dessus de la ville, derrière la hutte des ingénieurs, près de sa petite tour ; {npc:6266} et deux acolytes sont avec lui. Il vous envoie auprès de {npc:6294} à {zone:1455}.",
	["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} est dans la bibliothèque de {object:32356}. Il veut deux morceaux perdus de {quest:1758} : un sur la côte de {area:287}, un à {zone:1441}.",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "Le tome est un petit livre gris-bleu posé dans le sable d'un camp de murlocs sur le rivage au sud-ouest de {area:271}, près du bord de l'eau. Six ou sept murlocs le gardent et d'autres se cachent sous l'eau : ils viennent en groupes, apeurez-en donc un et gardez votre marcheur du Vide sur les autres. Descendez jusqu'à l'eau pour cliquer dessus ; depuis le flanc de colline, les caisses bloquent le curseur.",
	["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, sur {quest:1802} dans le sable",
	["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "La grotte des centaures s'ouvre dans les falaises au nord de {area:484}, une ville de la Horde : tenez-vous loin de ses gardes. À l'intérieur, restez à droite à chaque embranchement, traversez le bassin près de la petite cascade et ouvrez la petite boîte sombre contre le mur à côté d'un coffre plus grand : le grand n'est pas le bon. Vous ne pouvez l'ouvrir qu'avec la quête. Les centaures réapparaissent derrière vous en sortant.",
	["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} reconstitue le tome et vous donne {item:7006} : gardez-le, {npc:6251} le prend avec les bâtonnets.",
	["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Les Gueule-de-dragon tiennent {area:1036} dans les collines à l'est de la route de {area:150} à {area:836}. Seuls les lanceurs de sorts lâchent les bâtonnets, quatre fois sur cinq : les gardes-os (niveau 27, avec des squelettes) et les gardes de l'ombre (28). Un sentier escarpé au nord du gardien des âmes central monte dans le camp en évitant la plupart des guerriers.",
	["Rods of Channeling, from the Dragonmaw casters"] = "Bâtonnets de canalisation, sur les lanceurs de sorts Gueule-de-dragon",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Retour auprès de {npc:6251} à {area:392}. Quand vous acceptez, il trace le cercle d'invocation et ses acolytes canalisent un cercle supérieur au-dessus : attendez dans la tour que les deux soient faits. Puis utilisez {quest:1804} sur le cercle. Le chasseur corrompu (niveau 30, non élite) réduit au silence et dévore le mana, et il disparaît au bout de deux minutes : sortez votre marcheur du Vide, ouvrez tout de suite avec vos dégâts sur la durée et laissez le marcheur du Vide encaisser. Si vous mourez ou s'il gagne, abandonnez {quest:1795} et reprenez-la auprès de {npc:6251}. Gardez le tome : {npc:6251} le reprend.",
	["{quest:1804}, on the circle"] = "{quest:1804}, sur le cercle",
	["Imp (Alliance)"] = "Diablotin (Alliance)",
	["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Votre premier démon aux niveaux 1-4 : le diablotin, auprès du maître des démonistes de votre zone de départ.",
	["{npc:459} (Humans)"] = "{npc:459} (humains)",
	["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Votre première lettre ({item:9576}, de {npc:197} après Nettoyage du camp kobold) vous envoie auprès de {npc:459}, la maîtresse des démonistes dans le petit cimetière à côté de {area:24}. Elle demande un livre que les Défias ont volé.",
	["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "La tente défias se dresse dans les vignes à l'est de l'abbaye. Le livre est petit : il est posé au sol juste à droite de l'entrée de la tente, à côté d'une cruche bleue. Trois brutes défias (niveau 3-4) gardent la tente ; attirez-les une par une, ou entrez dans la tente et cliquez sur le livre, là où elles ne peuvent pas vous atteindre. Le livre réapparaît trois minutes après qu'on l'a pris.",
	["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} vous enseigne {spell:688} au rendu : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
	["{npc:460} (Gnomes)"] = "{npc:460} (gnomes)",
	["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Votre première lettre ({item:9577}, de {npc:658} après Équipement nain) vous envoie auprès de {npc:460}, le maître des démonistes à l'étage dans {area:77}. Il demande trois charmes de plume.",
	["Feather Charms"] = "Charmes de plume",
	["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Les novices Crins-de-givre (niveau 3-4) se tiennent au fond de la grotte des trolls au sud de {area:77}, près de Grek'nir le Froid à côté du bassin gelé : prenez le tunnel de gauche après l'entrée. Quatre victimes sur cinq lâchent un charme, mais seuls deux ou trois novices apparaissent, vous attendrez donc peut-être leur réapparition de trois minutes. Ils lancent des éclairs de givre à distance ; les jeunes trolls à l'entrée de la grotte sautent sur tous ceux qui passent. Une fois les charmes en poche, votre pierre de foyer vous ramène directement : celle d'un nouveau personnage est liée à {area:132}.",
	["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} vous enseigne {spell:688} au rendu : invoquez-le tout de suite, il ne coûte rien et combat à vos côtés.",
	["Succubus and Incubus (Alliance)"] = "Succube et incube (Alliance)",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Au niveau 20 : la succube et l'incube de Forever, son jumeau masculin, chacun avec une bourse d'âmes pour vos fragments.",
	["{quest:1717} (Gnomes)"] = "{quest:1717} (gnomes)",
	["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "Au niveau 20, {npc:6120}, le maître des démonistes dans {object:32383} de {zone:1455}, vous envoie auprès de {npc:6122} à {zone:1453}. Prenez {area:2257}.",
	["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "Au niveau 20, {npc:6122}, dans la cave de {object:2164} dans {object:2101}, vous envoie auprès de {npc:6244} à {zone:1413} : un long voyage pour l'Alliance. Prenez le bateau de {area:150} à Theramore et partez vers l'ouest à travers {zone:1445}, ou le bateau de {area:35} à {area:392}.",
	["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} campe sous une tente avec un feu de camp juste au nord-est de {area:378}, à une bifurcation de la route : en terre de la Horde, arrivez donc par l'est et évitez les gardes de Taurajo. {npc:6247}, à côté de lui, commence {item:6898}. Takar propose les deux branches : prenez les deux.",
	["the succubus"] = "la succube",
	["the incubus"] = "l'incube",
	["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran se trouve dans le nord-ouest de {zone:1440}, au nord de {area:415} le long de la route vers {zone:1439}. Une vingtaine de cultistes du Sombre brin tiennent les ruines autour du grand arbre : longez le mur extérieur et cliquez sur {quest:1738} d'aussi loin que possible. Elle se rend à {npc:6122}, pas à Takar.",
	["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "La maison se dresse seule parmi les arbres du nord-ouest de {zone:1440}, au nord-ouest d'Ordil'Aran et bien au nord de {area:413} : faites-la lors du même voyage que {quest:1738}. Prenez {item:190307} sur la table dehors, allumez-la à un feu de camp ({object:29784} à vous, ou le feu de Talen à {area:414}) et revenez aussitôt : {item:190308} s'éteint au bout de cinq minutes, un feu à vous à côté de la maison est donc le plus rapide. Sans elle, la silhouette de la maison vous arrête. La figurine est à l'étage.",
	["{item:190307}, on the table outside"] = "{item:190307}, sur la table dehors",
	["{quest:1739}: succubus"] = "{quest:1739} : succube",
	["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "Retour auprès de {npc:6122} avec {quest:1738}. Il vous remet {item:6913} : prenez l'escalier derrière lui jusqu'à la crypte ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à la salle au cercle violet. Placez-vous dessus et utilisez le noyau. Invoquez d'abord votre marcheur du Vide et gardez la succube (niveau 20, non élite) sur le cercle, sinon les gardes risquent de la tuer et la victoire ne compte pas. Si elle gagne, utilisez à nouveau le noyau ; gardez-le, {npc:6122} le reprend.",
	["{item:6913}, on the circle in the crypt"] = "{item:6913}, sur le cercle de la crypte",
	["{quest:65603}: incubus"] = "{quest:65603} : incube",
	["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Donnez la figurine à Gakin, puis utilisez {item:190309} au milieu du même cercle et battez l'incube qu'il appelle (niveau 20, non élite ; il peut vous charmer), votre marcheur du Vide encaissant. Gardez la figurine : {npc:6122} la reprend.",
	["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, au cercle de la crypte",
	["Voidwalker (Alliance)"] = "Marcheur du Vide (Alliance)",
	["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Votre démon protecteur au niveau 10 : le marcheur du Vide, après le collier d'une sorcière noire et un combat dans la crypte de {npc:6122}.",
	["{quest:1685} (Humans)"] = "{quest:1685} (humains)",
	["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "Au niveau 10, {npc:6121}, dans la cave de l'auberge de la Fierté du lion à {area:87} (l'escalier descend dans l'arrière-salle après la table du boucher), vous envoie auprès de {npc:6122} à {zone:1453}.",
	["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, cave de l'auberge de la Fierté du lion",
	["{quest:1715} (Gnomes)"] = "{quest:1715} (gnomes)",
	["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "Au niveau 10, {npc:6120}, le maître des démonistes dans {object:32383} de {zone:1455}, vous envoie auprès de {npc:6122} à {zone:1453}. Prenez {area:2257} depuis {object:171524}. Si {npc:6120} ne la propose pas, allez quand même voir {npc:6122} : il vous donne quand même la quête suivante.",
	["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} est la taverne de {object:2101} ; {npc:6122} est dans sa cave, en bas de l'escalier intérieur.",
	["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (niveau 9) est dans la ferme de {area:62}, au sud-est d'Elwynn près de la route des Carmines. {npc:473} (niveau 10) et un guerrier se tiennent avec elle et rejoignent le combat ; Morgan suriine et s'en prend à votre diablotin, gardez-le donc apeuré. Posez d'abord vos dégâts sur la durée sur {npc:881}, apeurez les autres, et ramassez son collier avant de les achever : il reste à vous même si vous mourez ensuite. Elle lance des boules de feu à distance et revient trois minutes après sa mort. Ayez la quête avant de la tuer, sinon le collier ne tombe pas.",
	["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "Retour auprès de {npc:6122}. Il vous remet {item:6928}. Le cercle est difficile à trouver : prenez l'escalier derrière {npc:6122} ; à mi-chemin du couloir le plus bas, un escalier latéral à gauche mène à une salle avec un cercle violet lumineux au milieu. Placez-vous dessus et utilisez le collier. Le marcheur du Vide (niveau 10, non élite) devient dangereux sous 30 % de vie : {spell:14868}, Corruption et {spell:348} avec votre diablotin dessus, Peur quand il s'approche. S'il vous bat, utilisez à nouveau le collier. Gardez le collier : {npc:6122} le reprend.",
	["{item:6928}, on the circle in the crypt"] = "{item:6928}, sur le cercle de la crypte",
	["A hauberk at 28, a coif, leggings and gauntlets from three smiths, and a shield on the way."] = "Un haubert au niveau 28, une coiffe, des jambières et des gantelets de trois forgerons, et un bouclier en chemin.",
	["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "Au niveau 20, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres des guerriers de {object:2100}, vous envoie auprès de {quest:1698} aux Carmines.",
	["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} est assis à l'auberge de {area:69}. Son épreuve est chronométrée : avant de la prendre, éliminez les gnolls des Carmines sur le chemin de {area:98} dans les collines au nord-ouest de {area:69}, y compris les deux sur le rocher près de l'entrée de la grotte (montez-y par son côté droit).",
	["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Vous avez une heure, et {spell:8553} de {npc:6166} vous laisse ivre pendant 8 à 10 minutes. Courez au nord-ouest jusqu'à {area:98}, en longeant la falaise pour éviter la plupart des groupes de gnolls, et entrez jusqu'au premier embranchement ; puis revenez voir {npc:6166} (depuis la crête, vous pouvez sauter jusqu'à {area:69}). Mourir et libérer votre esprit fait échouer la quête : abandonnez-la et {npc:6166} vous la redonne.",
	["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413} travaille dans le quartier des Nains de Hurlevent. Il prend {item:6843} (perdu ? abandonnez la quête et {npc:6166} en donne un nouveau) et vous donne {item:6970}, un bouclier ; {quest:1701} est une quête de niveau 28, {item:6842} listant ce qu'il faut.",
	["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "Il vous faut 50 crocs. Les traqueurs sangsues et les traqueurs des cavernes (niveau 21-22) rampent au milieu de {zone:1437}, au nord de {area:836} ; tous lâchent un croc. Ils empoisonnent ; de retour en 5 minutes.",
	["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "Les chimères vivent au sud-ouest de {area:460} à {area:465} : il vous faut 12 cornes calcinées sur les chimères novices (niveau 25-27) et les jeunes chimères (23-25), quatre fois sur cinq, et {item:6840} sur {npc:6167} (28, la grande), aussi quatre fois sur cinq. Seules trois novices, deux jeunes et une matriarche y vivent, chacune de retour en 5 minutes : attendez-vous à patienter. Les novices et la matriarche crachent {spell:3396}, les jeunes lancent {spell:403}. Alliance : volez jusqu'à {area:467} et partez au sud.",
	["{item:6839}, from the young chimaeras"] = "{item:6839}, sur les jeunes chimères",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Roogug est un huttier élite (niveau 28) dans {area:1717}, le donjon à l'extrémité sud de {zone:1413} ; un donjon pour cinq : il faut un groupe de cinq, et ses gardes viennent avec lui. À l'intérieur, prenez à gauche au premier embranchement, traversez le pont de racines, passez le grand chaudron vide : il est dans un cul-de-sac à droite, avec une dizaine d'élites en chemin. Il lance {spell:403} et appelle des grondeurs de terre. La fiole tombe toujours.",
	["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "Retour auprès de {npc:5413} dans {object:28027} pour le haubert. Il vous envoie ensuite au forgeron de votre race ; les pièces des deux autres forgerons vous sont aussi ouvertes : parlez-leur directement.",
	["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} tient l'armurerie au nord-ouest de {object:28027}, à quelques pas de {npc:5413}. Il veut 20 {quest:1705} et {item:6845}.",
	["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Les worgens Plaie-de-nuit de {zone:1431} (coureurs sombres, crocs infâmes, tisseurs d'ombre, worgens et souillés, niveau 26-31) au sud et à l'ouest de {area:42} lâchent {quest:1705} quatre fois sur cinq. {npc:6170} (niveau 32, non élite) porte {item:6845} (aussi quatre fois sur cinq) : il va et vient entre l'intérieur et l'entrée de la mine de {area:2161} au sud-est de {area:42} ; attendez donc à l'entrée et attirez-le dehors. {npc:6170} et les souillés empoisonnent et hurlent ; les crocs infâmes causent {spell:3427}.",
	["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, sur les worgens Plaie-de-nuit",
	["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} travaille du côté sud de {area:1660} à {zone:1457}. Il veut 20 {quest:1710}.",
	["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "Les coquilles gisent au sol sous les nids de wyvernes de {area:482}, dans l'ouest de {zone:1441}, plus loin dans la gorge. Il n'en existe que neuf et chacune revient 3 minutes après ramassage, vous attendrez donc ; certaines choses qui y ressemblent ne se ramassent pas. Des wyvernes Haut-perchoir (niveau 28-31) les gardent et viennent parfois à plusieurs.",
	["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Prenez {area:2257} de {zone:1453} à {zone:1455}. {quest:1704}, un forgeron gnome, travaille dans {object:171524} près des maîtres ingénieurs. Il veut 20 {item:6848}.",
	["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and an {item:5996} removes the risk."] = "{quest:1708} pousse au fond de la mer juste au sud de {area:150}, près des huttes des murlocs et d'un bateau échoué : huit là et deux au sud-est du port, chacune de retour en 3 minutes ; vous attendrez donc les réapparitions pour arriver à 20. Les murlocs peuvent vous prendre au filet sous l'eau : surveillez votre souffle, et {item:5996} supprime le risque.",
	["{spell:71} and a Weapon (Alliance)"] = "{spell:71} et une arme (Alliance)",
	["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} au niveau 10 et une arme à une main de votre choix à {zone:1453}, {zone:1455} ou {zone:1457}.",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "Au niveau 10, {npc:252377} se tient avec les maîtres près de la porte ouest de {area:16638}. Un cultiste, {npc:257196}, détient le bouclier de sa famille à {area:16629}.",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Partez au nord-ouest depuis {area:16638} jusqu'à {area:16629}. {npc:257196} se tient à l'ouest de l'accès au sanctuaire, parmi les gardiens, les invocateurs d'esprits et les maîtres-lames du culte : attirez-les un par un avant de vous en prendre à lui. Il lâche {item:263993}.",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "Retour auprès de {npc:252377} à {area:16638}. Elle enseigne {spell:71} et vous donne {item:275290}, un bouclier pour s'en servir. La route de {npc:6090} ci-dessous donne toujours une arme, une fois arrivé à {zone:1453}.",
	["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "Au niveau 10, {npc:1229}, le maître des guerriers de {area:131}, vous envoie auprès de {quest:1679} à {zone:1455}. Tout guerrier de l'Alliance peut prendre l'une des trois routes, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? {quest:1638} de {npc:5480} est la posture la plus rapide (un combat dans une taverne), suivie d'une arme de Haggard.",
	["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} se tient dans {object:32390}, à {object:32359}.",
	["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (niveau 11, un troll seul) attend à sa hutte sur une colline au sud de {area:135}, près des montagnes, en haut d'une petite rampe, sans autre troll autour ; la hutte devant {area:135} n'est pas la bonne. Il combat en {spell:71} et fracasse votre armure ; {spell:6343} le ralentit. Sa tête tombe toujours ; il revient environ 8 minutes après sa mort.",
	["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "Retour auprès de {npc:6114} pour {spell:71}, puis auprès de {quest:1680} à {object:32372}, au milieu de {zone:1455}.",
	["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} se trouve dans l'est de {zone:1426}, sous {area:212}, sur son côté sud. Des espions Sombrefer (niveau 8-10) se tiennent en chemin, assez espacés pour être attirés un par un. {object:85562} est dans la cave de la maison la plus au sud ; {npc:6124} (niveau 11) se tient à côté et charge dès qu'il vous voit. La boîte contient toujours le minerai et se remplit 15 minutes après ouverture.",
	["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "Au niveau 10, {npc:3598}, le maître des guerriers de {area:186}, ou {npc:2151}, qui patrouille sur la route à l'ouest de {area:186}, vous envoie auprès de {quest:1684} sur {area:1660} à {zone:1457}. Tout guerrier de l'Alliance peut prendre l'une des trois routes, jamais deux : vous êtes de toute façon à {zone:1453} au niveau 10 ? {quest:1638} de {npc:5480} enseigne la même posture après un combat dans une taverne.",
	["{quest:1684} stands on the {area:1660}."] = "{quest:1684} se tient sur {area:1660}.",
	["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (niveau 10, un satyre) se tient à un puits de lune caché en haut d'un flanc de colline à l'ouest de {area:186}. Le sentier est difficile à repérer : il part derrière un camp Pin-tordu et monte en lacets bordés de lampadaires. Les furbolgs en contrebas peuvent venir en groupes. Son cor tombe toujours ; il revient 5 minutes après sa mort.",
	["Elunite under {area:442}"] = "L'élunite sous {area:442}",
	["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Prenez le bateau de {area:702} à {area:442}. L'épave repose sous l'eau juste au sud de la jetée sud de {area:442}, où accoste le bateau de Menethil. Ouvrez des caisses d'élunite au fond de la mer autour de l'épave, près d'une énorme tortue engloutie, vers la plage et sous la jetée, jusqu'à en avoir huit ; chaque caisse contient du minerai et revient en 3 à 5 minutes. {npc:6133} gris (niveau 11) dérive au milieu de l'épave et lâche toujours le médaillon : ciblez-le quand vous le voyez, pour le retrouver après être remonté respirer. Surveillez votre souffle ; des batteurs peuvent s'en mêler.",
	["{item:6808}, from Crates of Elunite"] = "{item:6808}, dans les caisses d'élunite",
	["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "De retour sur {area:1660} : {npc:4088} vous remet {item:6812} ; {npc:6142} travaille de l'autre côté, au sud de la même terrasse, facile à manquer.",
	["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "Au niveau 10, {npc:913}, le maître des guerriers près de l'auberge de {area:87}, vous envoie auprès de {npc:6089} à {zone:1453} ; {npc:5480}, le maître des guerriers dans {object:2100} de {zone:1453}, la propose aussi.",
	["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} et {npc:6090} sont à la taverne du Cochon et du Sifflet dans {object:2100} ; {npc:6090} est l'ivrogne au bout du comptoir. {npc:6090} (niveau 10) frappe plus fort que son niveau, commencez donc avec toute votre vie ; il abandonne quand sa vie est basse au lieu de mourir. S'il gagne, il disparaît environ trois minutes : gardez la quête et reparlez-lui à son retour. Un nain, un gnome ou un elfe de la nuit qui a pris {quest:1638} auprès de {npc:5480} plutôt que sa route d'origine est guidé à travers {zone:1453} à partir d'ici.",
	["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "Le manoir de {npc:294} se dresse au bord sud-est de {area:88}, dans l'est d'Elwynn, au bout d'une petite route qui ne rejoint pas la grande.",
	["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (niveau 11) campe tout au sud-est d'Elwynn. Un garde se tient à côté de lui et des Défias et des loups sont répartis autour du camp (de temps en temps un garde plus rare aussi) : éliminez-les un par un, puis tuez Jack. Il lâche toujours {item:6783} ; ouvrez {object:85563} dans les caisses près de lui pour {item:6782}. Jack revient 3 minutes après sa mort, la boîte 1 minute après ouverture.",
	["from {npc:6093}"] = "sur {npc:6093}",
	["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "La suite de {spell:23214} est longue : {area:2279}, Hache-tripes Ouest et {area:2057} en groupe, 350 pièces d'or de dons, et des composants valant plusieurs centaines de plus (6 barres d'arcanite, 40 {item:14047}, 10 {item:8836}, deux diamants). Commencez à économiser tôt. Seigneur Grayson se tient dans la cathédrale de la Lumière, {npc:6171} tout près.",
	["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, le maître des prêtres, se promène dans {object:32386}, dans {object:32362} de {zone:1455}. Il vous donne son encensoir contre un don de 150 pièces d'or, prélevé au rendu. Gardez l'encensoir.",
	["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Seigneur Grayson bénit l'encensoir, qui devient {item:18752}, pour {area:2627}.",
	["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} se trouve tout au nord-ouest de {zone:1423}, à l'ouest des portes de {area:2279}. Placez-vous dans une tache verte lumineuse au sol ({object:179747} ; certaines sont dans les maisons en ruine) et utilisez {item:18752} : jusqu'à trois esprits de Terreval (niveau 59-60) se lèvent et attaquent. Leur {spell:7713} réduit toutes vos caractéristiques de 30 % : combattez-les un par un et utilisez {spell:2878}. Les taches reviennent vite ; plusieurs paladins peuvent travailler côte à côte.",
	["{item:18752}, inside a green patch"] = "{item:18752}, dans une tache verte",
	["Terrordale Spirits x25"] = "Esprits de Terreval x25",
	["Lord Grayson takes the censer back."] = "Seigneur Grayson reprend l'encensoir.",
	["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} travaille dans {object:28027} de {zone:1453}. Il forge {item:18753} avec vos composants et 150 pièces d'or.",
	["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047} tombe sur les humanoïdes de niveau 50 et plus (les cogneurs de {area:2255}, la Croisade écarlate dans les Maleterres, les ogres de {area:2577}). {item:8836} est une herbe des Maleterres ({skill:182} 220), courante autour de {area:3197}. {item:12360} est une transmutation d'alchimiste à partir de {item:12359} et de {item:12363}, une fois tous les deux jours par alchimiste : demandez tôt à un alchimiste de guilde, ou achetez les barres. L'hôtel des ventes vend les trois.",
	["{item:14047} x40"] = "{item:14047} x40",
	["{item:8836} x10"] = "{item:8836} x10",
	["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Barres d'arcanite x6 : un alchimiste, ou l'hôtel des ventes du quartier commerçant",
	["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} est un donjon pour un groupe de cinq aux niveaux 58-60, à l'extrémité nord de {zone:1423}. Les caisses de ravitaillement de Stratholme le long des rues des deux moitiés contiennent l'eau bénite, une à trois chacune ; elles reviennent au bout de trois minutes. Certaines caisses libèrent un essaim de rats pestiférés ou d'asticots : soyez prêt. La grande porte (la moitié écarlate) ne demande pas de clé.",
	["Stratholme Supply Crates, inside"] = "Caisses de ravitaillement de Stratholme, à l'intérieur",
	["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Apportez les composants et 150 pièces d'or, prélevées au rendu. {npc:1416} va à sa forge et vous remet {item:18753}.",
	["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Seigneur Grayson garde le caparaçon pour l'instant : vous le récupérez avec la quête suivante.",
	["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Les intendants de {object:2160} vendent des biscuits de manne enrichis, cinq pour 60 pièces d'argent, dès que {object:92525} est Amical envers vous : {npc:10857} à {area:3197} ou {npc:11536} à {area:2268}. Les pierres du Fléau et les quêtes des Maleterres font monter la réputation.",
	["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} élève des chevaux dans l'écurie de {area:271}. Elle fabrique {quest:7645} avec les 20 biscuits et 50 pièces d'or, prélevées au rendu.",
	["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} se trouve au centre de {zone:1444}. Depuis la porte au pied des ruines, montez à travers les cours extérieures jusqu'à la porte de l'aile Ouest à leur extrémité nord ; elle demande {item:18249} (sur Pusillin à Hache-tripes Est) ou le crochetage d'un voleur. {npc:11489} (élite de niveau 60) se tient au fond de la première cour de l'aile Ouest. Une fois attaqué, il appelle tous les {npc:11459} encore en vie dans la cour : tuez-les d'abord. Sa mort libère {quest:7643} : parlez-lui pour lui donner la nourriture du cheval et {item:18753}, et il bénit le caparaçon. Un groupe de cinq au niveau 60.",
	["Dire Maul West's door"] = "La porte de Hache-tripes Ouest",
	["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "{item:12800} vient des filons de thorium et de l'obsidienne, environ un filon sur cent ; {item:18335} tombe rarement sur les élites de niveau 59 et plus (Revanchion et {npc:14695} environ une fois sur neuf et une fois sur cent). L'hôtel des ventes est la source habituelle des deux.",
	["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Seigneur Grayson vous remet {item:18804} : ouvrez-la pour {item:18746} et {item:18792}. Gardez les deux.",
	["{item:18792}, from the satchel"] = "{item:18792}, dans la sacoche",
	["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} se trouve sous {area:2298}, la ville insulaire au sud-est de {zone:1422} ; la porte demande {item:13704} (La clé de {area:2057}). Videz {object:179746}, la salle de Cliquettripes au sous-sol, puis utilisez {item:18746} en son centre. Quatre vagues d'esprits arrivent, chacune se terminant par un Aspect : les joueurs les jugent avec {spell:1105}, Justice, Vertu puis Lumière, ce qui les étourdit. {npc:14516} (élite de niveau 62) arrive après la dernière ; il contrôle l'esprit des joueurs. Ramassez {item:18749}, utilisez-le dans l'ossuaire pour le racheter, et donnez-le avec {item:18792} à {npc:14568}. Si le groupe est anéanti, les portes se verrouillent et le scrutateur disparaît : abandonnez la quête et reprenez-la auprès de Seigneur Grayson pour une nouvelle sacoche. Un groupe de cinq au niveau 60. De nouveau dans {object:179746}, après la monture, vous permet de l'affronter à nouveau.",
	["{item:18749}, inside the {object:179746}"] = "{item:18749}, dans {object:179746}",
	["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "Au niveau 40, {npc:6179}, à l'étage de {object:32386}, vous envoie auprès de {npc:6171} à {zone:1453} ({npc:5149}, en bas, donne la même course ; prenez-en une). Prenez {area:2257} jusqu'à {zone:1453}.",
	["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} se tient dans la cathédrale de la Lumière. Au niveau 40, il propose {quest:1661} : acceptez-la et rendez-la-lui aussitôt pour apprendre {spell:13819}. Les paladins n'achètent pas de cheval.",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382} s'obtiennent en champs de bataille, par les quêtes JcJ et les tâches hebdomadaires de la saison, avec un plafond hebdomadaire ; Commandant (rang 11) débloque les montures de guerre noires. L'onglet Joueur contre Joueur de la fiche de personnage indique votre rang et ce que vous pouvez acheter. {skill:762} : en monter une à pleine vitesse demande {skill:762} Compagnon (niveau 60). Polestar ne peut pas lire votre rang : cette étape attend donc le niveau 60 et {skill:762} Compagnon.",
	["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} vend les montures dans {object:2100} de {zone:1453}, près de {area:2918}, à côté des autres intendants d'honneur. Le client Forever les affiche à 100 po chacune. Chacune demande aussi la monte de son espèce : les Humains montent le destrier, les Elfes de la nuit le tigre, les Gnomes le trotteur, les Nains le bélier. Un Céleste, ou quiconque choisit la monture d'une autre race, doit d'abord apprendre cette monte auprès de son maître (Exalté auprès de la ville de cette race).",
	["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100 po",
	["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100 po",
	["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100 po",
	["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100 po",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732} et l'enclos à chevaux de {npc:384} sont à {area:88}, dans l'est de {zone:1429}. Au niveau 40, {npc:4732} enseigne {skill:762} aux Humains pour 100 po (10 % de moins à Honoré auprès de {faction:72}), avec un cheval offert. Les autres races apprennent {skill:762}, avec leur première monture, auprès du maître de monte de leur propre race.",
	["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Toutes les races de l'Alliance peuvent acheter ces chevaux, mais en monter un demande aussi {spell:824}, que seuls les Humains obtiennent avec {skill:762}. {npc:4732} l'enseigne aux autres races une fois Exalté auprès de {faction:72} (le guide de réputation de Hurlevent montre comment). D'ici là, n'achetez pas de cheval pour ce personnage.",
	["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "{npc:5404} n'est pas chez {npc:384} : c'est {npc:1460} qui le vend, aux écuries de {area:150} dans {zone:1437} (20 po dans le client Forever). Passez si cette couleur ne vous intéresse pas.",
	["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189} est juste à l'est de {area:131} ; {npc:7954} se tient à côté des mécanotrotteurs de {npc:7955}. Au niveau 40, {npc:7954} enseigne {skill:762} aux Gnomes pour 100 po (10 % de moins à Honoré auprès de {faction:54}), avec un mécanotrotteur offert. Les autres races apprennent {skill:762}, avec leur première monture, auprès du maître de monte de leur propre race.",
	["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Toutes les races de l'Alliance peuvent acheter ces mécanotrotteurs, mais en monter un demande aussi {spell:10907}, que seuls les Gnomes obtiennent avec {skill:762}. {npc:7954} l'enseigne aux autres races une fois Exalté auprès de {faction:54} (le guide de réputation des Exilés de Gnomeregan montre comment). D'ici là, n'achetez pas de mécanotrotteur pour ce personnage.",
	["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "Dans Classic, seuls les Nains et les Gnomes pouvaient monter les mécanotrotteurs ; dans Forever, toutes les races de l'Alliance peuvent apprendre {spell:10907}.",
	["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "Le camp est à {area:1002}, dans l'ouest de {zone:1433}, là où se rejoignent les routes de {zone:1429}, de {zone:1431} et de {area:69}. {npc:256736} ne vend {npc:10636} qu'une fois Exalté auprès de {faction:2586}, pour 6 000 faveurs de marchand. Les caisses ne rapportent que des faveurs (environ 15 par caisse rendue) ; la réputation vient des commandes d'artisan et de {item:280179}, une seule fois : suivez le guide de réputation des factions de ravitaillement et gardez 6 000 faveurs de côté.",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803} est à l'est de {area:131}, sur la route de {zone:1432} ; {npc:4772} se tient à côté des béliers de {npc:1261}. Au niveau 40, {npc:4772} enseigne {skill:762} aux Nains pour 100 po (10 % de moins à Honoré auprès de {faction:47}), avec un bélier offert. Les autres races apprennent {skill:762}, avec leur première monture, auprès du maître de monte de leur propre race.",
	["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Toutes les races de l'Alliance peuvent acheter ces béliers, mais en monter un demande aussi {spell:826}, que seuls les Nains obtiennent avec {skill:762}. {npc:4772} l'enseigne aux autres races une fois Exalté auprès de {faction:47} (le guide de réputation de Forgefer montre comment). D'ici là, n'achetez pas de bélier pour ce personnage.",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753} et les sabres de {npc:4730} sont sur le terrain d'équitation de {area:1658}, à {faction:69}. Au niveau 40, {npc:4753} enseigne {skill:762} aux Elfes de la nuit pour 100 po (10 % de moins à Honoré auprès de {faction:69}), avec un sabre offert. Les autres races apprennent {skill:762}, avec leur première monture, auprès du maître de monte de leur propre race.",
	["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Toutes les races de l'Alliance peuvent acheter ces sabres, mais en monter un demande aussi {spell:828}, que seuls les Elfes de la nuit obtiennent avec {skill:762}. {npc:4753} l'enseigne aux autres races une fois Exalté auprès de {faction:69} (le guide de réputation de Darnassus montre comment). D'ici là, n'achetez pas de sabre pour ce personnage.",
	["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839} (niveau 51 et plus) fait monter {faction:730} : gagnez, prenez tours et cimetières, et rendez les objets du champ de bataille ; le guide de réputation de la vallée d'Alterac montre le plus rapide. {npc:13217} attend devant le champ de bataille, à la limite de {zone:1416}, au-dessus de {area:287} ; {npc:13216}, dans {area:2839}, vend la même monture.",
	["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732} et l'enclos à chevaux de {npc:384} sont à {area:88}, dans l'est de {zone:1429}. Au niveau 60, {npc:4732} enseigne {skill:762} Compagnon aux Humains pour 1 000 po (10 % de moins à Honoré auprès de {faction:72}) ; selon Blizzard, une monture est offerte. Les autres races l'apprennent auprès du maître de monte de leur propre race. Chaque cheval rapide coûte ici 200 po.",
	["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 60 {npc:7954} teaches Journeyman {skill:762} to Gnomes for 1,000g (10% less at Honored with {faction:54}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift mechanostrider costs 200g here."] = "{area:189} est juste à l'est de {area:131} ; {npc:7954} se tient à côté des mécanotrotteurs de {npc:7955}. Au niveau 60, {npc:7954} enseigne {skill:762} Compagnon aux Gnomes pour 1 000 po (10 % de moins à Honoré auprès de {faction:54}) ; selon Blizzard, une monture est offerte. Les autres races l'apprennent auprès du maître de monte de leur propre race. Chaque mécanotrotteur rapide coûte ici 200 po.",
	["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 60 {npc:4772} teaches Journeyman {skill:762} to Dwarves for 1,000g (10% less at Honored with {faction:47}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift ram costs 200g here."] = "{area:803} est à l'est de {area:131}, sur la route de {zone:1432} ; {npc:4772} se tient à côté des béliers de {npc:1261}. Au niveau 60, {npc:4772} enseigne {skill:762} Compagnon aux Nains pour 1 000 po (10 % de moins à Honoré auprès de {faction:47}) ; selon Blizzard, une monture est offerte. Les autres races l'apprennent auprès du maître de monte de leur propre race. Chaque bélier rapide coûte ici 200 po.",
	["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 60 {npc:4753} teaches Journeyman {skill:762} to Night Elves for 1,000g (10% less at Honored with {faction:69}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift saber costs 200g here."] = "{npc:4753} et les sabres de {npc:4730} sont sur le terrain d'équitation de {area:1658}, à {faction:69}. Au niveau 60, {npc:4753} enseigne {skill:762} Compagnon aux Elfes de la nuit pour 1 000 po (10 % de moins à Honoré auprès de {faction:69}) ; selon Blizzard, une monture est offerte. Les autres races l'apprennent auprès du maître de monte de leur propre race. Chaque sabre rapide coûte ici 200 po.",
	["{npc:10618} stands on top of {area:2241} in the far north of {zone:1452}. Only the Alliance can earn the {faction:589}' favour, from level 58: three repeatable quests worth 50 each, about 840 turn-ins from Neutral to Exalted. Frostsaber Provisions is open from the start, Winterfall Intrusion from halfway through Neutral and Rampaging Giants from Honored. The Wintersaber Trainers Reputation guide takes you through it."] = "{npc:10618} se tient au sommet de {area:2241}, à l'extrême nord de {zone:1452}. Seule l'Alliance peut gagner la faveur de {faction:589}, à partir du niveau 58 : trois quêtes répétables qui rapportent 50 chacune, soit environ 840 quêtes rendues de Neutre à Exalté. Les provisions de sabres-de-givre sont disponibles dès le début, L'intrusion des Tombe-Hiver à mi-chemin de Neutre et Les géants déchaînés à partir d'Honoré. Le guide de réputation des Dresseurs de sabres-d'hiver vous accompagne.",
	["{npc:6367} has a farmhouse north of {area:87}. Each cat carrier costs 40s, 1g 60s for all four. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:6367} a une ferme au nord de {area:87}. Chaque panier à chat coûte 40 pa, 1 po 60 pa pour les quatre. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; les objectifs restent cochés ensuite.",
	["{npc:8665}, the owl trainer, stands on the {area:1659} in {zone:1457}, beside the food and general goods vendors. She sells three owls (50s each); the {item:280803} is new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:8665}, la dresseuse de chouettes, se tient sur {area:1659} à {zone:1457}, à côté des vendeurs de nourriture et de marchandises. Elle vend trois chouettes (50 pa chacune) ; {item:280803} est une nouveauté de Forever. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; les objectifs restent cochés ensuite.",
	["{npc:1263} stands at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}, the ram breeder. Each rabbit crate costs 20s; the Arctic and Brown crates are new in Forever. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:1263} se tient à {area:803}, à l'est de {area:131} sur la route de {zone:1432}, à côté de {npc:1261}, l'éleveur de béliers. Chaque caisse à lapin coûte 20 pa ; les caisses arctique et brune sont des nouveautés de Forever. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; les objectifs restent cochés ensuite.",
	["On the road from {zone:1453} to {area:40}, {area:87} is the first stop: {npc:241} stands outside the inn, {npc:240} beside him. {npc:241}'s {quest:40} goes straight to Dughan, who then gives {quest:35}; his {quest:109} goes with you to {area:40}."] = "Sur la route de {zone:1453} à {area:40}, {area:87} est le premier arrêt : {npc:241} se tient devant l'auberge, {npc:240} à côté de lui. {quest:40} de {npc:241} mène directement à Dughan, qui donne ensuite {quest:35} ; {quest:109} vous accompagne jusqu'à {area:40}.",
	["{npc:240}: for {npc:234} at {area:108}"] = "{npc:240} : pour {npc:234} à {area:108}",
	["East along the road past {area:18}: {npc:248242} and {npc:248248} stand at the foot of the tower."] = "Vers l'est par la route, après {area:18} : {npc:248242} et {npc:248248} se tiennent au pied de la tour.",
	["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it. His tools and Thomas's Prowlers and bears are south of the bridge, on the way back."] = "{npc:261} garde le pont sur la route vers l'est ; {npc:248265} se tient juste de l'autre côté. Ses outils, les rôdeurs et les ours de Thomas sont au sud du pont, sur le chemin du retour.",
	["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Des sorciers renégats défias campent sur les rives de {area:86} ; ils lâchent aussi les bandanas en lin rouge. {object:56} se trouve dans le village murloc sur la rive nord-est.",
	["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Les gnolls Rivepatte campent dans les collines à l'ouest de {area:86} ; {quest:91725} se trouvent dans leurs camps.",
	["The {area:54}'s entrance"] = "L'entrée de {area:54}",
	["East along the road, then into the river south of the bridge: the {item:247813}, Axe and Toolbox lie in it. Prowlers and Young Forest Bears roam its banks."] = "Vers l'est par la route, puis dans la rivière au sud du pont : {item:247813}, la hache et la boîte à outils s'y trouvent. Des rôdeurs et de jeunes ours des forêts parcourent ses rives.",
	["Follow the road west to {area:87}, on the way to {area:40}: {npc:240} stands outside the inn."] = "Suivez la route vers l'ouest jusqu'à {area:87}, sur le chemin de {area:40} : {npc:240} se tient devant l'auberge.",
	["Goretusk Snouts"] = "Groins de broche-tripes",
	["Young Goretusks root in the fields along the road south from Saldean's to {area:108}: take their snouts on the way."] = "De jeunes broche-tripes fouillent les champs le long de la route qui va de chez les Saldean à {area:108} : prenez leurs groins en chemin.",
	["{area:108}'s tower and {npc:523}"] = "La tour de {area:108} et {npc:523}",
	["{npc:234} and {npc:821} stand at the top of the stone tower, {npc:491} inside it, {npc:523} the gryphon master on the south side of the hill with {npc:878} beside him. {npc:523} gives you Lewis' note for {npc:1323} with a free flight to {zone:1453}: take it now. In {zone:1453}, {npc:279}'s shop is in the {object:2096} by the gryphons, {npc:1323}'s shop, {object:2156}, in {object:2100}; {npc:1646} stands in {object:2098} on the way back to {npc:352}, the gryphon master."] = "{npc:234} et {npc:821} se tiennent en haut de la tour de pierre, {npc:491} à l'intérieur, {npc:523}, le maître des griffons, sur le flanc sud de la colline avec {npc:878} à côté de lui. {npc:523} vous donne la note de Lewis pour {npc:1323}, avec un vol gratuit vers {zone:1453} : prenez-le maintenant. À {zone:1453}, la boutique de {npc:279} est dans {object:2096} près des griffons, celle de {npc:1323}, {object:2156}, dans {object:2100} ; {npc:1646} se tient dans {object:2098}, sur le chemin du retour vers {npc:352}, le maître des griffons.",
	["{npc:523}: the free flight he offers goes to {zone:1453}"] = "{npc:523} : le vol gratuit qu'il propose va à {zone:1453}",
	["{npc:279}, {object:2096}, by the gryphons"] = "{npc:279}, {object:2096}, près des griffons",
	["{npc:1323}, {object:2156} in {object:2100}"] = "{npc:1323}, {object:2156} dans {object:2100}",
	["{npc:1646}, {object:2098}: his compass is in his old house in {area:40}"] = "{npc:1646}, {object:2098} : sa boussole est dans son ancienne maison à {area:40}",
	["{npc:352}, the gryphon master"] = "{npc:352}, le maître des griffons",
	["{npc:234}: from {npc:963} at Westbrook"] = "{npc:234} : de la part de {npc:963} à Westbrook",
	["{npc:491}, inside: back from {zone:1453}"] = "{npc:491}, à l'intérieur : au retour de {zone:1453}",
	["Defias Trappers and Smugglers camp in the fields between {area:108} and {area:918}.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone.\nYoung Goretusks and Fleshrippers roam every leg of this loop: their livers and meat are for the pie and the stew."] = "Des trappeurs et des contrebandiers défias campent dans les champs entre {area:108} et {area:918}.\nÀ l'ouest de chez les Saldean. Des guetteurs et des golems des moissons travaillent les champs ; ils lâchent les isoressorts, les gyrostabilisateurs, {item:732} et parfois {item:255155}. {npc:573}, un rare de niveau 20, se promène ici : laissez-le tranquille.\nDe jeunes broche-tripes et des étripeurs parcourent chaque étape de cette boucle : leur foie et leur viande servent à la tourte et au ragoût.",
	["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {area:111} east to the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: {object:290} stands in the ruined house east of the mine, on the way to the {area:916}. Two Defias stand guard inside, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "Des gnolls et des éclaireurs Rivepatte (niveau 11-13) parcourent les collines au sud de la côte, d'au-dessus de {area:111} jusqu'à {area:916} à l'est. Les gnolls plus au sud et à l'ouest sont de niveau 13-19 : restez dans les collines du nord.\nDes coureurs de la côte et des pillards murlocs bordent la plage au nord de la mine. Ils fuient quand leur vie est basse : attirez-les un par un.\nAttention : les gnolls proches les uns des autres ont tendance à rejoindre le combat en groupe. Il est plus sûr de les attirer un par un.\nAttention : {object:290} se dresse dans la maison en ruine à l'est de la mine, sur le chemin de {area:916}. Deux Défias montent la garde à l'intérieur, dont {npc:502}, un nommé de niveau 15. Ils sont liés : attaquer l'un attire les deux.",
	["{quest:153}: every Defias drops them, from {area:111} to the {area:916}"] = "{quest:153} : tous les Défias en lâchent, de {area:111} jusqu'à {area:916}",
	["For {npc:266} in {area:69}, Redridge"] = "Pour {npc:266} à {area:69}, dans les Carmines",
	["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "Retour au nord après {area:918} jusqu'à la mine : des kobolds terrassiers y travaillent.",
	["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "Au sud-ouest jusqu'à la côte, à l'ouest de {area:918}. Des mineurs Rivepatte travaillent dans la carrière.",
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}. {object:1166} stands in the farmhouse at the {area:219}, among them: {npc:1646}' compass is inside.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Des pilleurs et des détrousseurs défias tiennent les fermes à l'ouest de {area:108}, entre la route côtière et {area:20}. {object:1166} se trouve dans la ferme de {area:219}, au milieu d'eux : la boussole de {npc:1646} est à l'intérieur.\nAttention : la grotte de {area:113} contient beaucoup de Défias serrés les uns contre les autres, il est facile d'en attirer plusieurs à la fois.",
	["{area:20} and the Defias hills"] = "{area:20} et les collines des Défias",
	["{item:254676}, from the crates around {area:20}"] = "{item:254676}, dans les caisses autour de {area:20}",
	["From {area:40}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "Depuis {area:40}, marchez jusqu'à {zone:1453} ; le tram de {zone:1455} arrive dans {object:28027}. {npc:5480} entraîne les guerriers dans {object:2100} ; {npc:6089} et {npc:6090} se tiennent ensemble près de {object:2152}. {npc:6090} vous affronte pour sa chope. Si {npc:5480} ne propose pas {quest:1638}, allez directement voir {npc:6089} : il donne {quest:1639} sans elle.",
	["Walk to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Marchez jusqu'à {zone:1453}. {npc:376} est dans la cathédrale de la Lumière.",
	["Head to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Rendez-vous à {zone:1453}. Il n'y a pas de maître chaman : prenez {area:2257} depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous auprès de {npc:258098}, puis reprenez le tram pour le bateau.",
	["Walk to {zone:1453}, or fly if you know its flight path. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "Marchez jusqu'à {zone:1453}, ou volez-y si vous connaissez son point de vol. Maîtres : {object:2100} (guerriers, voleurs), la cathédrale (paladins, prêtres), {object:2101} (mages, démonistes), le parc (druides).",
	["{npc:7232}, {object:28027}: for his brother in {area:442}"] = "{npc:7232}, {object:28027} : pour son frère à {area:442}",
	["The boat docks west of the village: {npc:3644} waits where the pier meets the shore. Go up to {npc:3649} at the north end of the village first, then down the main street to the inn. The flight master stands on the hill south of the inn. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Le bateau accoste à l'ouest du village : {npc:3644} attend là où le ponton rejoint la rive. Montez d'abord voir {npc:3649} au nord du village, puis descendez la rue principale jusqu'à l'auberge. Le maître de vol se tient sur la colline au sud de l'auberge. {npc:3666} est à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["{npc:3666}, upstairs in the inn"] = "{npc:3666}, à l'étage de l'auberge",
	["{npc:10216}, on the pier"] = "{npc:10216}, sur le ponton",
	["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Pêcheurs seulement : {npc:10216} se tient sur le ponton. Son {item:12238} se pêche depuis le ponton même.",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Des ours chardon enragés parcourent les collines juste à l'est de {area:442}. Utilisez {quest:2139} sur l'un d'eux et ramenez-le-lui.",
	["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Tuez des ours chardon enragés dans les collines à l'est de {area:442}, puis montez au camp furbolg au sud-est : rien à tuer pour l'instant.",
	["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Grimpez dans les montagnes à l'est de {area:447} ; {object:175524} se trouve sur une corniche.",
	["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Volez de {area:442} à {area:702} et prenez le portail qui monte vers {npc:4217} dans {area:1658}.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Lancez {spell:18960}. {npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages. Les babioles du sanctuaire se trouvent dans les récipients au sol de {area:656}, sous {area:2361} : apportez-en une à {area:2362} au nord-ouest, utilisez-la là-bas et parlez à {npc:11799}. Revolez ensuite vers {area:442} depuis {area:2361}.",
	["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122} : remplissez l'échantillonneur à {area:445}",
	["At the {area:2362}"] = "À {area:2362}",
	["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Des éclaireurs et des parle-vent Noirbois tiennent le camp au sud-est de {area:442}.",
	["The flame burns in the south of {area:447}."] = "La flamme brûle au sud de {area:447}.",
	["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Suivez les collines vers le nord jusqu'à {area:456} et remontez jusqu'aux chutes. Deux autres restes échoués se trouvent sur la rive nord : près de {area:443} et au nord de {quest:954}.",
	["{item:12237} from {npc:2233} and {npc:2235}, by this stop"] = "{item:12237} sur {npc:2233} et {npc:2235}, près de cet arrêt",
	["East of Buzzbox 323, {npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "À l'est de Buzzbox 323, {npc:3661} se cache au pied de la tour parmi les fanatiques du Sombre Brin. Gardez sa lettre pour Delgren, en {zone:1440}.",
	["For {quest:948} at the Grove, on {zone:1439}'s southern loop after the trip east"] = "Pour {quest:948} au Bosquet, sur la boucle sud de {zone:1439} après l'expédition vers l'est",
	["From the dock, up to the north end of the village first ({npc:3702} by the moonwell, {npc:2913}), then down the main street: the WANTED poster outside the inn, {npc:3693} at its east end, where the road leaves south."] = "Depuis le quai, montez d'abord au nord du village ({npc:3702} près du puits de lune, {npc:2913}), puis descendez la rue principale : l'affiche AVIS DE RECHERCHE devant l'auberge, {npc:3693} à l'extrémité est, là où la route part vers le sud.",
	["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Les floraisons fongiques lunaires poussent dans les grottes des séléniens dans les collines juste à l'est de {area:442} ; les séléniens y sont irritables. {item:2449} demande {skill:182} : les herboristes en cueillent partout en {zone:1439}, les autres l'apportent de {zone:1453} ({npc:1313}) ou de l'hôtel des ventes.",
	["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Four beached remains lie on the beaches west and south-west of {area:450}: take them on the way north to his camp."] = "{npc:10323} campe sur la plage à l'ouest du glaive : tuez les murlocs du feu de camp ; il arrive à la troisième vague avec son chien. Quatre restes échoués se trouvent sur les plages à l'ouest et au sud-ouest de {area:450} : prenez-les en remontant vers son camp au nord.",
	["The shore west of the Grove"] = "La rive à l'ouest du Bosquet",
	["On the way north to {area:442}, the last {quest:4728} lies on the shore west of the Grove."] = "En remontant vers {area:442}, le dernier {quest:4728} se trouve sur la rive à l'ouest du Bosquet.",
	["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Suivez la côte vers le nord-est jusqu'à {area:443}. {quest:951} se trouvent parmi les ruines ; des myrmidons, des ensorceleuses et des guerriers Écaille-tempête les tiennent, et des maîtresses des bêtes Écaille-tempête arpentent la rive.",
	["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out. {npc:3693} takes the escort in {area:442} on the next visit there."] = "{npc:3692} se cache dans les collines à l'est de {area:449}. Aidez-le à regagner la route ; il se bat en chemin. {npc:3693} prend en charge l'escorte à {area:442}, à la prochaine visite.",
	["His walk ends at the road, where Grimclaw waits"] = "Sa marche se termine à la route, où Grimclaw l'attend",
	["{npc:3694}: for {npc:3691} in {area:415}, in the next guide"] = "{npc:3694} : pour {npc:3691} à {area:415}, dans le guide suivant",
	["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Les elfes de la nuit volent de {area:442} à {area:702} ; les Célestes prennent le bateau au quai de {area:442} et apprennent là-bas le point de vol de Rut'theran. Prenez le portail qui monte vers {npc:4217} dans {area:1658}.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "Lancez {spell:18960}. {npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages. Apprenez-y le point de vol si vous ne l'avez pas.",
	["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (elfes de la nuit) et {npc:272054} (Célestes) attendent au sud de {area:493}. Les trois reliques se trouvent dans {area:2363}, à leur est. D'après les retours des premières semaines, une relique ne donne rien pendant qu'un autre joueur la fouille : attendez un instant et réessayez.",
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Retour auprès de {npc:11802} à {area:2361}, puis {npc:11800} y emmène les druides directement à {area:702}. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Take the portal up to {npc:4217}, then fly back to {area:442} for the road south to {zone:1440}."] = "Prenez le portail qui monte vers {npc:4217}, puis revolez vers {area:442} pour la route du sud vers {zone:1440}.",
	["Sell and repair in {area:442} first: the next stretch is a long one."] = "Vendez et réparez d'abord à {area:442} : la suite est longue.",
	["Off the boat, walk up the pier to the flight master by the inn. Nothing to take here yet: Menethil's quests are for your {zone:1437} visit at about 22."] = "En descendant du bateau, remontez le ponton jusqu'au maître de vol près de l'auberge. Rien à prendre ici pour l'instant : les quêtes de Menethil sont pour votre visite des {zone:1437} vers le niveau 22.",
	["Follow the road east out of Menethil and south through the {area:836} pass. Keep to the road: the {zone:1437} crocolisks and raptors beside it are over your level."] = "Suivez la route vers l'est en sortant de Menethil, puis vers le sud par le col de {area:836}. Restez sur la route : les crocilisques et les raptors des {zone:1437} qui la bordent sont au-dessus de votre niveau.",
	["{npc:1343} stands at the {area:925}, at the south end of the pass."] = "{npc:1343} se tient à {area:925}, au bout sud du col.",
	["East along the hills to the mine: the Miners' League crates sit in its tunnels among the Tunnel Rat kobolds."] = "Vers l'est le long des collines jusqu'à la mine : les caisses de la Ligue des mineurs sont dans ses galeries, parmi les kobolds rats des tunnels.",
	["{item:2640}, from the crates; below ground"] = "{item:2640}, dans les caisses ; sous terre",
	["Back to the {area:925}"] = "Retour à {area:925}",
	["Chief Engineer Hinderweir stands on top of the dam, up the ramp at its west end."] = "L'ingénieur en chef Hinderweir se tient au sommet du barrage, en haut de la rampe à son extrémité ouest.",
	["Walk east along the dam, down its eastern ramp, then back west along the foot of the dam on the land side: two Dark Iron Sappers guard the barrel. Kill them, then open the barrel: it ends this quest and starts the next."] = "Longez le barrage vers l'est, descendez sa rampe est, puis revenez vers l'ouest au pied du barrage, côté terre : deux sapeurs Sombrefer gardent le tonneau. Tuez-les, puis ouvrez le tonneau : cela termine cette quête et lance la suivante.",
	["The loch"] = "Le loch",
	["South along the west shore. A {object:665289} lies on the loch bed east of {area:144} (it moves between several spots): open it for the {item:278051}, which starts the quest."] = "Vers le sud le long de la rive ouest. {object:665289} repose au fond du loch à l'est de {area:144} (il change de place entre plusieurs endroits) : ouvrez-le pour {item:278051}, qui lance la quête.",
	["{npc:1684} stands on the shore north-east of town, {npc:1105} by the inn."] = "{npc:1684} se tient sur la rive au nord-est de la ville, {npc:1105} près de l'auberge.",
	["Round the south end of the loch and head east to the dig. {npc:1345} and {npc:1344} stand together at its west edge."] = "Contournez le loch par le sud et allez vers l'est jusqu'au chantier de fouilles. {npc:1345} et {npc:1344} se tiennent ensemble à son bord ouest.",
	["The dig site"] = "Le chantier de fouilles",
	["Stonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a {item:2636}. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start {quest:86613}, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health."] = "Des terrassiers, des géomanciens et des troggs berserkers Brise-pierre tiennent le chantier à l'est d'Ironband ; chacun d'eux peut lâcher {item:2636}. Des tas d'outils de fouille sont éparpillés sur le chantier : ouvrez-en un et faites un clic droit sur les outils pour lancer {quest:86613}, puis ramassez-en six.\nAttention : les troggs berserkers (19-20) enragent sous 40 % de vie.",
	["{quest:86613}: open a pile at the dig"] = "{quest:86613} : ouvrez un tas sur le chantier",
	["Right-click the {quest:86613}"] = "Clic droit sur {quest:86613}",
	["North-east to the lodge on the hill. {npc:1154} stands inside, {npc:1187} outside."] = "Au nord-est jusqu'au pavillon sur la colline. {npc:1154} se tient à l'intérieur, {npc:1187} dehors.",
	["{npc:1187}: 15 minutes"] = "{npc:1187} : 15 minutes",
	["Mountain Buzzards"] = "Busards des montagnes",
	["Mountain Buzzards circle the hills west and south of the lodge, back toward the dig. {quest:257} runs for 15 minutes."] = "Des busards des montagnes tournoient au-dessus des collines à l'ouest et au sud du pavillon, en revenant vers le chantier. {quest:257} dure 15 minutes.",
	["12 minutes"] = "12 minutes",
	["Elder Mountain Boars and {npc:270693}"] = "Vieux sangliers des montagnes et {npc:270693}",
	["The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore. {npc:270693}, a crocolisk, patrols the shore below them. {quest:258} runs for 12 minutes."] = "Les vieux sangliers des montagnes parcourent les collines au nord-ouest du pavillon, le long de la rive est. {npc:270693}, un crocilisque, patrouille sur la rive en contrebas. {quest:258} dure 12 minutes.",
	["Back west along the south shore to {area:144}: {npc:1105} by the inn, then {npc:1572} with the gryphons on the west side of town, on the way south."] = "Retour vers l'ouest par la rive sud jusqu'à {area:144} : {npc:1105} près de l'auberge, puis {npc:1572} avec les griffons à l'ouest de la ville, sur le chemin du sud.",
	["For {npc:1356} in {zone:1455}"] = "Pour {npc:1356} à {zone:1455}",
	["South of Thelsamar, Ylva lies dead in the mouth of a trogg cave. Take her banner, raise it beside her and hold the spot: troggs come in waves from both sides, then {npc:269185}."] = "Au sud de Thelsamar, Ylva gît morte à l'entrée d'une grotte de troggs. Prenez sa bannière, plantez-la à côté d'elle et tenez la position : des troggs arrivent par vagues des deux côtés, puis {npc:269185}.",
	["The tunnel post"] = "Le poste du tunnel",
	["West to the dwarven post at the tunnel to {zone:1426}."] = "Vers l'ouest jusqu'au poste nain à l'entrée du tunnel vers {zone:1426}.",
	["Through the South Gate tunnel and west along the road to {zone:1455}."] = "Par le tunnel de la porte Sud, puis vers l'ouest par la route jusqu'à {zone:1455}.",
	["{npc:1573} keeps the gryphons in the {object:32372}; {npc:1356} is in the {object:32356}, north-east of it, on the way to the tram in {object:171524}."] = "{npc:1573} garde les griffons dans {object:32372} ; {npc:1356} est dans {object:32356}, au nord-est, sur le chemin du tram dans {object:171524}.",
	["From the tram, leave {zone:1453} by the main gate and follow the road through {area:87} and east through Elwynn to Redridge."] = "En descendant du tram, quittez {zone:1453} par la grande porte et suivez la route par {area:87}, puis vers l'est à travers Elwynn jusqu'aux Carmines.",
	["{npc:261} guards the bridge on this road east, past the {area:91}: {npc:240}'s {quest:35}, from your walk through {area:87}, goes to him."] = "{npc:261} garde le pont sur cette route vers l'est, après {area:91} : {quest:35} de {npc:240}, reçue en passant par {area:87}, est pour lui.",
	["{npc:261}, on the bridge"] = "{npc:261}, sur le pont",
	["The road crosses into Redridge at {area:1002}. {npc:464} walks around the crossroads."] = "La route entre dans les Carmines à {area:1002}. {npc:464} fait des rondes autour du carrefour.",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} stands by the road next to her."] = "Suivez la route le long de la rive sud de {area:68} jusqu'à la maîtresse des griffons. {npc:1070} se tient au bord de la route à côté d'elle.",
	["Cross the long bridge north into town: {npc:8965} and {npc:8962} play by the shore at its north end, {npc:341} and {npc:382} stand there too, {npc:415} by the smithy, {npc:344} in the town hall, {npc:381} on the docks, {npc:266} upstairs in the inn and {npc:379} and {npc:343} inside it."] = "Traversez le long pont vers le nord jusqu'à la ville : {npc:8965} et {npc:8962} jouent au bord de l'eau à son extrémité nord, {npc:341} et {npc:382} s'y tiennent aussi, {npc:415} près de la forge, {npc:344} à l'hôtel de ville, {npc:381} sur les quais, {npc:266} à l'étage de l'auberge, {npc:379} et {npc:343} à l'intérieur.",
	["{npc:382}: the Blackrock camps are for your next Redridge visit, at about 24"] = "{npc:382} : les camps Rochenoire sont pour votre prochaine visite des Carmines, vers le niveau 24",
	["{npc:415}: for {npc:514} in {area:87}"] = "{npc:415} : pour {npc:514} à {area:87}",
	["{npc:344}, in the town hall: for {npc:466} in {zone:1453}"] = "{npc:344}, à l'hôtel de ville : pour {npc:466} à {zone:1453}",
	["{npc:266}, in the inn; upstairs"] = "{npc:266}, dans l'auberge ; à l'étage",
	["West along the road to {area:1002} first; the gnolls are on the way back east."] = "D'abord vers l'ouest par la route jusqu'à {area:1002} ; les gnolls sont sur le chemin du retour vers l'est.",
	["Redridge Mongrels and Thrashers hold the hills east of {area:1002}, north of the road; Poachers camp south of the road. Great Goretusks root around the same hills and Dire Condors circle south of the lake; Tarantulas crawl round {area:1002}."] = "Des bâtards et des cogneurs des Carmines tiennent les collines à l'est de {area:1002}, au nord de la route ; des braconniers campent au sud de la route. De grands broche-tripes fouillent les mêmes collines et des condors redoutables tournoient au sud du lac ; des tarentules rôdent autour de {area:1002}.",
	["{item:1081}: Tarantulas"] = "{item:1081} : tarentules",
	["East along the road to the gryphon master; {npc:1070} stands beside her."] = "Vers l'est par la route jusqu'à la maîtresse des griffons ; {npc:1070} se tient à côté d'elle.",
	["Back toward town, swim east from the bridge into {area:68}; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a {item:1467}."] = "En revenant vers la ville, nagez vers l'est depuis le pont dans {area:68} ; le coffre repose au fond du lac à côté d'un bateau coulé. Des murlocs mange-chair et des appelle-marées bordent la rive sud autour : chacun d'eux peut porter {item:1467}.",
	["Then west under the bridge: a {object:154357} mound on the lake bed beside town holds the necklace. Only one mound shows at a time, anywhere from under the dock to past the bridge."] = "Puis vers l'ouest sous le pont : un monticule {object:154357} au fond du lac, près de la ville, contient le collier. Un seul monticule apparaît à la fois, quelque part entre le dessous du quai et l'au-delà du pont.",
	["Through town east to west: {npc:8962} and {npc:341} at the north end of the bridge, {npc:381} on the docks, then {npc:342}'s garden at the west end; {npc:379} and {npc:343} are in the inn."] = "À travers la ville d'est en ouest : {npc:8962} et {npc:341} au bout nord du pont, {npc:381} sur les quais, puis le jardin de {npc:342} à l'extrémité ouest ; {npc:379} et {npc:343} sont dans l'auberge.",
	["Its pikes and rivets come from the gnolls north of the lake, on the loop after {area:40}"] = "Ses piques et ses rivets viennent des gnolls au nord du lac, sur la boucle après {area:40}",
	["From level 20 {npc:381} gives {quest:150}: take it now if he offers it (otherwise on the last {area:69} stop). Its murlocs are for your next Redridge visit, at about 24."] = "À partir du niveau 20, {npc:381} donne {quest:150} : prenez-la maintenant s'il la propose (sinon au dernier arrêt à {area:69}). Ses murlocs sont pour votre prochaine visite des Carmines, vers le niveau 24.",
	["{npc:381}, on the docks"] = "{npc:381}, sur les quais",
	["West out of Redridge by {area:1002} and along the road through Elwynn to {area:87}."] = "Sortez des Carmines vers l'ouest par {area:1002}, puis suivez la route à travers Elwynn jusqu'à {area:87}.",
	["{npc:514} works at the {area:87} smithy."] = "{npc:514} travaille à la forge de {area:87}.",
	["West through Westbrook into {area:40}."] = "Vers l'ouest par Westbrook jusqu'à {area:40}.",
	["Down the road to {area:108}. {npc:234} stands at the top of the stone tower."] = "Descendez la route jusqu'à {area:108}. {npc:234} se tient en haut de la tour de pierre.",
	["For {npc:332} in {zone:1453}"] = "Pour {npc:332} à {zone:1453}",
	["{npc:332} is upstairs in the SI:7 building in {object:2100}: the stairs are hard to see at first. {npc:466} sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the {object:2096}."] = "{npc:332} est à l'étage du bâtiment du SI:7 dans {object:2100} : l'escalier est difficile à voir au début. {npc:466} est assis sur son cheval au bout du pont, devant la grande porte ; revenez ensuite aux griffons dans {object:2096}.",
	["{npc:332}, SI:7; upstairs"] = "{npc:332}, SI:7 ; à l'étage",
	["{npc:466}, outside the main gate"] = "{npc:466}, devant la grande porte",
	["{npc:234}, at the top of the tower"] = "{npc:234}, en haut de la tour",
	["South along the road to {area:20}. The {npc:550} starts in front of the {area:20} smithy and walks north to the {area:113} and the back of the {area:111}, then back: look along his road. Slow him when he runs at 30% health."] = "Vers le sud par la route jusqu'à {area:20}. {npc:550} part de devant la forge de {area:20} et marche vers le nord jusqu'à {area:113} et l'arrière de {area:111}, puis revient : cherchez-le le long de son chemin. Ralentissez-le quand il s'enfuit à 30 % de vie.",
	["South-west from {area:20} to the lighthouse on the point: {npc:392} waits on its steps. {npc:391} walks the beach and the shallows north-east of it among the murlocs: pull him away from the Oracles."] = "Au sud-ouest de {area:20}, jusqu'au phare sur la pointe : {npc:392} attend sur ses marches. {npc:391} arpente la plage et les hauts-fonds au nord-est, parmi les murlocs : éloignez-le des oracles avant de l'attaquer.",
	["Back north up the road to {area:108}. {npc:467} waits at the foot of the tower ramp; if he is missing, someone is escorting him and he is back within minutes."] = "Retour au nord par la route jusqu'à {area:108}. {npc:467} attend au pied de la rampe de la tour ; s'il n'est pas là, quelqu'un l'escorte et il revient en quelques minutes.",
	["Stay with the traitor as he walks south to {area:20}; he does not stop for fights, so clear what follows him. His walk ends at the Defias hideout below {area:20}."] = "Restez avec le traître pendant qu'il marche vers le sud jusqu'à {area:20} ; il ne s'arrête pas pour combattre, alors occupez-vous de ce qui le suit. Sa marche se termine au repaire des Défias sous {area:20}.",
	["{npc:467}, at the foot of the tower ramp"] = "{npc:467}, au pied de la rampe de la tour",
	["Back north to {npc:234} and the gryphons."] = "Retour au nord auprès de {npc:234} et des griffons.",
	["From the gryphons, over the bridge into town: {npc:415} by the smithy, {npc:344} in the town hall."] = "Depuis les griffons, traversez le pont jusqu'à la ville : {npc:415} près de la forge, {npc:344} à l'hôtel de ville.",
	["Redridge Brutes and Mystics hold the hills north and north-west of town; both carry the Iron Pikes and Rivets. Black Dragon Whelps nest in the same hills.\nCareful: The whelps cast {spell:133} from range, and the gnolls run for help at low health."] = "Des brutes et des mystiques des Carmines tiennent les collines au nord et au nord-ouest de la ville ; tous portent les piques et les rivets de fer. Des dragonnets noirs nichent dans les mêmes collines.\nAttention : les dragonnets lancent {spell:133} à distance, et les gnolls courent chercher de l'aide quand leur vie est basse.",
	["{item:1221}: Black Dragon Whelps"] = "{item:1221} : dragonnets noirs",
	["Back down into town: {npc:415} by the smithy, {npc:341} at the north end of the bridge, {npc:381} on the docks."] = "Redescendez en ville : {npc:415} près de la forge, {npc:341} au bout nord du pont, {npc:381} sur les quais.",
	["{npc:341}: {quest:98386}, for your next Redridge visit"] = "{npc:341} : {quest:98386}, pour votre prochaine visite des Carmines",
	["{npc:381}, on the docks: the murlocs are for your next Redridge visit"] = "{npc:381}, sur les quais : les murlocs sont pour votre prochaine visite des Carmines",
	["Back to {area:442} for {zone:1439}'s southern loops: the gryphon to {zone:1453}, then the boat from the harbour."] = "Retour à {area:442} pour les boucles sud de {zone:1439} : le griffon jusqu'à {zone:1453}, puis le bateau depuis le port.",
	["Train, then leave by the main gate and follow the road east through {area:12}."] = "Entraînez-vous, puis sortez par la grande porte et suivez la route vers l'est par {area:12}.",
	["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} n'a pas de maître chaman : prenez {area:2257} depuis {object:28027} jusqu'à {zone:1455}, entraînez-vous auprès de {npc:258098}, puis reprenez le tram.",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn."] = "Volez jusqu'à {area:108} et allez au nord-ouest jusqu'à la côte : {object:177790} repose au fond de la mer, au large. Repartez ensuite vers l'est par la route à travers Elwynn.",
	["The road east through Elwynn crosses into Redridge at {area:1002}, where the roads to Redridge, {area:10} and Elwynn meet: south to {area:10} first."] = "La route vers l'est à travers Elwynn entre dans les Carmines à {area:1002}, où se croisent les routes des Carmines, de {area:10} et d'Elwynn : d'abord au sud vers {area:10}.",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest.\nNo {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "Suivez la route au sud depuis {area:1002} jusqu'à {area:10} ; {area:42} se trouve à l'est de la forêt.\nPas de {item:4371} pour {quest:174} ? {npc:3133} en vend dans la maison à côté de celle de {npc:276}, en stock limité ; {npc:1448} à {area:150} en vend aussi.\nLa maison de {npc:276} se trouve à l'extrémité est du village. {npc:3133} vend des fournitures d'ingénierie dans la maison voisine.",
	["{npc:633}: {npc:288}, at {quest:163}"] = "{npc:633} : {npc:288}, à {quest:163}",
	["For {npc:302}, on the hill south-east of town"] = "Pour {npc:302}, sur la colline au sud-est de la ville",
	["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888} se tient au sud de la route, à {area:245}.",
	["Continue west to {quest:163}. The {object:673515} glows by the ruined house south of the road; {npc:288} hides in the house at the west end of the village."] = "Continuez vers l'ouest jusqu'à {quest:163}. {object:673515} luit près de la maison en ruine au sud de la route ; {npc:288} se cache dans la maison à l'extrémité ouest du village.",
	["for {npc:272} in {area:42}"] = "pour {npc:272} à {area:42}",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the {area:1097} west of {quest:163}, fewer up north towards {npc:311}'s camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the {zone:1436} border, so pull with care."] = "Des loups redoutables enragés parcourent les bois autour du cimetière et de {npc:289}, des loups redoutables affamés les collines au nord-est de lui. Les araignées pygmées toile-venin sont les petites araignées, et elles sont rares : la plupart rôdent le long de {area:1097} à l'ouest de {quest:163}, quelques-unes plus au nord vers le camp de {npc:311} ; elles lâchent aussi le venin. Chaque goule de la moitié nord du cimetière peut lâcher un croc. Les loups et les grosses araignées occupent aussi la bordure de {zone:1436} : attirez-les avec prudence.",
	["{item:1130}: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses"] = "{item:1130} : araignées pygmées toile-venin, araignées toile-venin et recluses vertes",
	["The hermit's shack stands in the woods north-east of the {area:492}."] = "La cabane de l'ermite se dresse dans les bois au nord-est de {area:492}.",
	["{npc:272}, in the Scarlet Raven Tavern"] = "{npc:272}, dans la taverne du Corbeau écarlate",
	["Back north along the road from {area:42} to {area:1002}."] = "Retour au nord par la route, de {area:42} à {area:1002}.",
	["Follow the road along the south shore of {area:68} to the gryphon master. {npc:903} stands by the road next to her."] = "Suivez la route le long de la rive sud de {area:68} jusqu'à la maîtresse des griffons. {npc:903} se tient au bord de la route à côté d'elle.",
	["{area:68}'s murlocs: kill these as you meet them"] = "Les murlocs de {area:68} : tuez-les quand vous les croisez",
	["Murloc Flesheaters and Tidecallers line the south shore of {area:68}, just east of the gryphons and the bridge. Any of them can carry a fin."] = "Des murlocs mange-chair et des appelle-marées bordent la rive sud de {area:68}, juste à l'est des griffons et du pont. Chacun d'eux peut porter une nageoire.",
	["Cross the long bridge north into town: {npc:381} on the docks, {npc:900} in the town hall, the innkeeper in the inn, {npc:342} in her garden at the west end. {npc:382}'s Blackrock quests and {quest:98386} came with you from your first Redridge visit."] = "Traversez le long pont vers le nord jusqu'à la ville : {npc:381} sur les quais, {npc:900} à l'hôtel de ville, l'aubergiste dans l'auberge, {npc:342} dans son jardin à l'extrémité ouest. Les quêtes Rochenoire de {npc:382} et {quest:98386} viennent de votre première visite des Carmines.",
	["{npc:900}, in the town hall"] = "{npc:900}, à l'hôtel de ville",
	["{npc:345} (level 24) roots around the pen just west of {area:69}, beside {npc:342}'s garden. Pull him away from the other boars and fight at full health."] = "{npc:345} (niveau 24) fouille autour de l'enclos juste à l'ouest de {area:69}, à côté du jardin de {npc:342}. Éloignez-le des autres sangliers et combattez-le avec toute votre vie.",
	["{npc:342}'s garden is at the west end of town."] = "Le jardin de {npc:342} est à l'extrémité ouest de la ville.",
	["Back east through town from {npc:342}'s garden: two Wanted posters hang on the town hall doorway."] = "Retour vers l'est à travers la ville depuis le jardin de {npc:342} : deux avis de recherche sont accrochés à l'entrée de l'hôtel de ville.",
	["The Wanted poster on the town hall doorway"] = "L'avis de recherche à l'entrée de l'hôtel de ville",
	["The Wanted poster beside it"] = "L'avis de recherche juste à côté",
	["Greater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "De grandes tarentules rampent sur les pentes autour du moulin au nord-est du lac.",
	["South-east from the mill, west of {area:1000}'s gnolls, to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies."] = "Au sud-est du moulin, à l'ouest des gnolls de {area:1000}, jusqu'aux camps Rochenoire à l'est de {area:2099}. Des renégats, des grunts et des coursiers les remplissent ; restez à l'est du donjon, dont les orcs sont élites. Des râteliers d'armes et des épées traînent dans les camps ; les jambons, les sacs de grain et les tonneaux d'eau contiennent les provisions.",
	["{item:280841}: weapon racks and swords on the ground"] = "{item:280841} : râteliers d'armes et épées au sol",
	["{item:280839}: meat haunches, grain sacks, water barrels"] = "{item:280839} : jambons, sacs de grain, tonneaux d'eau",
	["Gar'im keeps to the cave at the camps' south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast."] = "Gar'im reste dans la grotte au bout sud des camps, avec son diablotin et deux orcs. Élite : groupez-vous si vous pouvez ; seul, attirez d'abord les orcs de l'entrée et interrompez son sort de feu.",
	["North up the valley's east side. Shadowhide gnolls fill it; {npc:703} (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of {area:2099} to the west until the watch tower: its orcs are elite."] = "Au nord en remontant le flanc est de la vallée. Les gnolls Peau-d'ombre la remplissent ; {npc:703} (26) et ses deux gardes se tiennent à son extrémité nord : éliminez d'abord les gnolls autour de lui et combattez avec toute votre vie. Restez hors de {area:2099}, à l'ouest, jusqu'à la tour de guet : ses orcs sont élites.",
	["The {object:31} stands at the valley's east edge."] = "{object:31} se dresse au bord est de la vallée.",
	["West to the intact watch tower beside {area:2099}: climb it and leave the Glyph in the empty jar at the top."] = "Vers l'ouest jusqu'à la tour de guet intacte à côté de {area:2099} : montez-y et déposez le glyphe dans la jarre vide au sommet.",
	["The keep stands beside the tower. {npc:334} (elite) waits in the keep's top room with two guards and a dragon; Blackrock Shadowcasters (elite) and Sentries stand on its west side, so pull one at a time on the way in, and hug the right wall as you enter his room so you don't pull him at once. Elite: group up if you can."] = "Le donjon se dresse à côté de la tour. {npc:334} (élite) attend dans la salle du haut avec deux gardes et un dragon ; des lanceurs d'ombre (élites) et des sentinelles Rochenoire se tiennent sur son côté ouest, alors attirez-les un par un en entrant, et longez le mur de droite en entrant dans sa salle pour ne pas l'attirer tout de suite. Élite : groupez-vous si vous pouvez.",
	["From the keep head back west along the lake's north shore and north up the {area:95} to {area:997}; {area:69}'s hand-ins wait for Keeshan's escort, which ends there. Blackrock Champions camp in the valley."] = "Depuis le donjon, revenez vers l'ouest par la rive nord du lac, puis montez vers le nord par {area:95} jusqu'à {area:997} ; les rendus de {area:69} attendent l'escorte de Keeshan, qui s'y termine. Des champions Rochenoire campent dans la vallée.",
	["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "Keeshan se cache tout au nord de la vallée, près de la bordure de {zone:1428}. Escortez-le jusqu'à {area:69} ; des orcs Rochenoire vous tendent des embuscades en chemin.",
	["Into {area:69} from the north with Keeshan: {npc:900} and {npc:344} in the town hall, {npc:382} and {npc:341} at the north end of the bridge, then over the bridge to {npc:903} and the gryphons."] = "Entrez dans {area:69} par le nord avec Keeshan : {npc:900} et {npc:344} à l'hôtel de ville, {npc:382} et {npc:341} au bout nord du pont, puis traversez le pont jusqu'à {npc:903} et les griffons.",
	["Next: the gryphon to {area:42} for {area:10}'s second loop (05-duskwood)."] = "Ensuite : le griffon jusqu'à {area:42} pour la seconde boucle de {area:10} (05-duskwood).",
	["Back to the {area:69} gryphon master: fly to {area:42} for {zone:1431}'s second loop."] = "Retour à la maîtresse des griffons de {area:69} : volez jusqu'à {area:42} pour la seconde boucle de {zone:1431}.",
	["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "Sa maison se dresse sur la colline au sud-est de {area:42}, au-dessus de {area:121}.",
	["{item:1946}: the {npc:511} in the cemetery's crypt is level 26; it waits for the {zone:1431} return"] = "{item:1946} : {npc:511}, dans la crypte du cimetière, est de niveau 26 ; il attend votre retour en {zone:1431}",
	["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "Des horreurs squelettiques arpentent le flanc de colline entre {area:42} et {area:121}, au sud-est de la ville ; elles lâchent les fleurs de pourriture.",
	["Head south through the cemetery towards {area:94}. Skeletal Fiends and Skeletal Horrors walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "Allez vers le sud à travers le cimetière en direction de {area:94}. Des démons squelettiques et des horreurs squelettiques arpentent sa moitié sud. {npc:522}, un élite, erre entre les tombes : tenez-vous à l'écart.",
	["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288} se cache dans la maison à l'extrémité ouest de {area:94}.",
	["Next: training, then the flight from {zone:1453} to {area:150} for the {zone:1437}."] = "Ensuite : l'entraînement, puis le vol de {zone:1453} jusqu'à {area:150} pour les {zone:1437}.",
	["North from {area:94} through Elwynn: {area:87} is on the road to {zone:1453}."] = "Au nord depuis {area:94} à travers Elwynn : {area:87} est sur la route de {zone:1453}.",
	["On into {zone:1453}: {npc:6173} and {npc:6171} are in the Cathedral of Light, on the way to the gryphon master."] = "Continuez jusqu'à {zone:1453} : {npc:6173} et {npc:6171} sont dans la cathédrale de la Lumière, sur le chemin du maître des griffons.",
	["Back north from the glaive (Druids: south along the road from {area:442}) to the {area:448}, where {npc:11218} sleeps beside Arbal. Take his quest, open his chest for the {item:13536}, use it to wake him and lead him south along the road into {area:331} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {area:413}."] = "Revenez au nord depuis le glaive (druides : au sud par la route depuis {area:442}) jusqu'à {area:448}, où {npc:11218} dort à côté d'Arbal. Prenez sa quête, ouvrez son coffre pour {item:13536}, utilisez-le pour le réveiller et guidez-le vers le sud par la route jusqu'en {area:331}, auprès de {npc:11219} à {area:413} ; sonnez à nouveau du cor chaque fois qu'il s'endort.\nAttention : des embuscades de trois monstres attaquent le long de la route : des furbolgs sur le tronçon de {zone:1439} et des morts-vivants près de {area:413}.",
	["Escort {npc:11218} to {area:413} in {area:331}."] = "Escortez {npc:11218} jusqu'à {area:413}, en {area:331}.",
	["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Au nord du poste de Maestra, des fagots de plantes traînent autour des ruines de {area:411}. Des cultistes du Sombre Brin tiennent les ruines juste au sud : chacun d'eux peut lâcher {item:5366}.",
	["The road from {area:413} comes in by the flight master: {npc:3845} and {npc:4079} stand there, {npc:3691} in the inn, {npc:3894} inside the building beyond it."] = "La route de {area:413} arrive près du maître de vol : {npc:3845} et {npc:4079} s'y tiennent, {npc:3691} dans l'auberge, {npc:3894} dans le bâtiment juste après.",
	["{npc:3691}: {quest:990}, from {area:442} (others take it on the next {area:331} visit)"] = "{npc:3691} : {quest:990}, depuis {area:442} (les autres la prennent à la prochaine visite en {area:331})",
	["South of the murlocs, {npc:3585} waits at the {area:416}."] = "Au sud des murlocs, {npc:3585} attend à {area:416}.",
	["The tears glow on the small isle east of {area:415}."] = "Les larmes luisent sur le petit îlot à l'est de {area:415}.",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}, by the {area:2160}."] = "Allez vers le sud après {area:421} jusqu'au tunnel de {area:1276} ; il débouche dans {area:461} des Serres-Rocheuses, près de {area:2160}.",
	["{npc:4080} and {npc:4077} camp on the {area:1076}, south-west of the mine."] = "{npc:4080} et {npc:4077} campent sur {area:1076}, au sud-ouest de la mine.",
	["His hut stands just north of {npc:4080} and {npc:4077}."] = "Sa hutte se dresse juste au nord de {npc:4080} et {npc:4077}.",
	["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "La KapitalRisk défriche la forêt de {area:461}. Des bûcherons et des déboiseurs y travaillent partout ; les opérateurs conduisent les déchiqueteuses et l'un d'eux porte les plans.",
	["Back north through the {area:1276}: west of {area:421}, the stardust bushes grow among the ruins."] = "Retour au nord par {area:1276} : à l'ouest de {area:421}, les buissons de poussière d'étoile poussent parmi les ruines.",
	["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885} se tient à {area:420}, sur la rive est de {area:421} ; {npc:210995} campe sur sa rive ouest. Des élémentaires d'eau souillée pataugent dans le lac entre les deux.",
	["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "Les furbolgs Mauvebois vivent dans les bois au sud de la route, au sud-est de {area:415}. Le guetteur de la tanière et les Ursas gardent la tanière.",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Suivez la route vers l'est jusqu'à {area:419} ; {npc:3916} se tient près du puits de lune.",
	["From {npc:3987}'s camp head south-west past {area:415} (its hand-ins wait for the way back) to the {area:412} south of the shrine: {npc:3664} and his voidwalkers hold them. Pull his guards first."] = "Depuis le camp de {npc:3987}, allez au sud-ouest après {area:415} (ses rendus attendent le retour) jusqu'à {area:412}, au sud du sanctuaire : {npc:3664} et ses marcheurs du Vide les tiennent. Attirez d'abord ses gardes.",
	["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Suivez la côte vers le nord jusqu'à {area:414}. {npc:3846} campe sur la plage ; les nagas Queue-fureur remplissent le rivage.",
	["{item:5490}: any Wrathtail naga on the strand"] = "{item:5490} : n'importe quel naga Queue-fureur de la grève",
	["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009} arpente la pointe nord de {area:414} avec des gardes Queue-fureur.",
	["{npc:3663}: its circles are for your next {area:331} visit, at about 28"] = "{npc:3663} : ses cercles sont pour votre prochaine visite en {area:331}, vers le niveau 28",
	["Follow the road south-east from {area:413} back to {area:415}: {npc:3845} by the flight master, {npc:3691} in the inn, {npc:3894} inside."] = "Suivez la route au sud-est depuis {area:413} pour revenir à {area:415} : {npc:3845} près du maître de vol, {npc:3691} dans l'auberge, {npc:3894} à l'intérieur.",
	["Off the boat, walk up the pier: {npc:1242} on the pier, {npc:2094} by the docks to the north, {npc:2086} in the keep, the inn ({npc:1239}) east of it with {npc:1480} and {npc:2111} beside it, {npc:2096} by the north gate on the way out east."] = "En descendant du bateau, remontez le ponton : {npc:1242} sur le ponton, {npc:2094} près des quais au nord, {npc:2086} dans le donjon, l'auberge ({npc:1239}) à l'est avec {npc:1480} et {npc:2111} à côté, {npc:2096} près de la porte nord, en sortant vers l'est.",
	["From the marsh head east across the {zone:1437}. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Depuis le marais, traversez les {zone:1437} vers l'est. De jeunes crocilisques des Paluns se cachent dans les mares au nord du site de fouilles.",
	["{npc:1078}: the bigger raptors in the valley west of the dig are for your next {zone:1437} visit, at about 27"] = "{npc:1078} : les grands raptors de la vallée à l'ouest du chantier sont pour votre prochaine visite des {zone:1437}, vers le niveau 27",
	["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "Des traqueurs des cavernes et des traqueurs sangsues remplissent {area:1021}, la grotte au sud-est du site de fouilles.",
	["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "Des gnolls et des bâtards Peau-de-mousse tiennent les collines au sud-est de {area:1025}.",
	["Its flint comes from the Mosshide Fenrunners on the way to {area:309}; {npc:1244} takes it on your next {zone:1437} visit"] = "Son silex vient des coureurs des marais Peau-de-mousse, sur le chemin de {area:309} ; {npc:1244} le prend à votre prochaine visite des {zone:1437}",
	["North-west from {npc:1244}: Mosshide Fenrunners and Mistweavers roam the riverbanks on the way, and almost every one drops flint. Black, Crimson and Monstrous Oozes fill {area:309}, just west of the road to {area:205} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag."] = "Au nord-ouest de {npc:1244} : des coureurs des marais et des tisse-brume Peau-de-mousse parcourent les berges en chemin, et presque tous lâchent du silex. Des limons noirs, cramoisis et monstrueux remplissent {area:309}, juste à l'ouest de la route de {area:205} et au nord du camp d'Einar. N'importe quel limon peut contenir le sac de {npc:2111}.",
	["{item:2611}: Mosshide Fenrunners and Mistweavers"] = "{item:2611} : coureurs des marais et tisse-brume Peau-de-mousse",
	["Back west along the road into Menethil: {npc:2096} by the road in, {npc:2111} and {npc:1480} at the inn, {npc:2086} in the keep, {npc:2094} on the west side by the docks, {npc:1242} on the pier north of the inn."] = "Retour vers l'ouest par la route jusqu'à Menethil : {npc:2096} au bord de la route en entrant, {npc:2111} et {npc:1480} à l'auberge, {npc:2086} dans le donjon, {npc:2094} côté ouest près des quais, {npc:1242} sur le ponton au nord de l'auberge.",
	["{npc:2086}, in the keep"] = "{npc:2086}, dans le donjon",
	["{npc:1242}, on the pier"] = "{npc:1242}, sur le ponton",
	["{npc:1571} is the flight master by Menethil's inn: you have both flight paths since your first trip east."] = "{npc:1571} est le maître de vol près de l'auberge de Menethil : vous avez les deux points de vol depuis votre premier voyage vers l'est.",
	["The gryphons land in the {object:32372}. {npc:4081} stands in {object:171524}, east of it, by the {area:2257}."] = "Les griffons se posent dans {object:32372}. {npc:4081} se tient dans {object:171524}, à l'est, près de {area:2257}.",
	["The tram comes in at the {object:28027}; walk west to the {object:2098}. {npc:1646} stands at its east side, {npc:376} in the Cathedral of Light."] = "Le tram arrive à {object:28027} ; marchez vers l'ouest jusqu'à {object:2098}. {npc:1646} se tient du côté est, {npc:376} dans la cathédrale de la Lumière.",
	["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646} : la lettre de Thundris, depuis {area:442}",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-wetlands)"] = "Seulement une fois {quest:97914} rendue : pour {npc:3649}, de retour à {area:442} (06-wetlands)",
	["Mathias Shaw is at SI:7 in {object:2100}, south of the Keep."] = "Mathias Shaw est au SI:7 dans {object:2100}, au sud du donjon.",
	["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}'s second loop"] = "{npc:332} : {npc:7024}, en {zone:1436}, la prend à la fin de la seconde boucle de {zone:1431}",
	["{object:2164} is in the {object:2101}. Warlocks: {npc:6122} is in its cellar."] = "{object:2164} est dans {object:2101}. Démonistes : {npc:6122} est dans sa cave.",
	["Next: training in {zone:1453}, then the road east through Elwynn and south to {zone:1431}."] = "Ensuite : l'entraînement à {zone:1453}, puis la route vers l'est à travers Elwynn et vers le sud jusqu'à {zone:1431}.",
	["In {zone:1453}, join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "À {zone:1453}, assemblez les deux moitiés de pendentif en {item:15885} et lancez {spell:18960} : {npc:11802} est à {area:2361}. Ensuite, {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Take the portal up to the {area:1658}, then fly back to {area:442} for the boat to {area:150}."] = "Prenez le portail qui monte vers {area:1658}, puis revolez vers {area:442} pour le bateau vers {area:150}.",
	["Take the boat from {area:442}'s dock to {area:150}."] = "Prenez le bateau au quai de {area:442} jusqu'à {area:150}.",
	["Flagon of Mead, from {npc:1464}"] = "Une chope d'hydromel, chez {npc:1464}",
	["{npc:2104}, by the keep; on the top floor"] = "{npc:2104}, près du donjon ; au dernier étage",
	["{npc:2104}: {quest:98221}, the Attack Plans in the {area:1036}"] = "{npc:2104} : {quest:98221}, les plans d'attaque dans {area:1036}",
	["{npc:2104}: for {npc:270637} in the {area:1025}"] = "{npc:2104} : pour {npc:270637} à {area:1025}",
	["{npc:2094}, by the docks"] = "{npc:2094}, près des quais",
	["{npc:2097}, by the north gate: {npc:1071} takes it on 30-40/01-hillsbrad-foothills' {area:205} stop"] = "{npc:2097}, près de la porte nord : {npc:1071} la prend à l'arrêt à {area:205} de 30-40/01-hillsbrad-foothills",
	["Follow the coast north out of Menethil into {area:1022}. Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Suivez la côte vers le nord en sortant de Menethil jusqu'à {area:1022}. Trois récipients dans les huttes murlocs, du sud au nord : {object:261}, puis {object:142151}, puis {object:259} tout au nord.",
	["In from the north: {npc:2094} by the docks, {npc:1242} on the pier, {npc:2104} in the keep, then {npc:1239} in the inn."] = "En revenant par le nord : {npc:2094} près des quais, {npc:1242} sur le ponton, {npc:2104} dans le donjon, puis {npc:1239} dans l'auberge.",
	["For {npc:1284} in {zone:1453}, at the end of this guide"] = "Pour {npc:1284} à {zone:1453}, à la fin de ce guide",
	["Follow the road east: the bigger raptors for {quest:295} hunt in the valley just west of the excavation site."] = "Suivez la route vers l'est : les grands raptors de {quest:295} chassent dans la vallée juste à l'ouest du site de fouilles.",
	["The excavation site sits on the hill south of the road: {npc:1078} at the top, {npc:1077} below ground."] = "Le site de fouilles se trouve sur la colline au sud de la route : {npc:1078} en haut, {npc:1077} sous terre.",
	["{npc:1077}, below ground: the {item:279993}, from the elite Goaz Warders"] = "{npc:1077}, sous terre : {item:279993}, sur les gardiens Goaz élites",
	["Goaz Warders"] = "Gardiens Goaz",
	["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one.\n{npc:270892} is elite: grouping up is advised."] = "Les gardiens goaz se tiennent juste à l'ouest du camp de Whelgar : utilisez à côté de l'un d'eux {item:279996} qu'il vous a donné.\n{npc:270892} est élite : il est conseillé de se grouper.",
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground. Their hearts drop from level 32 elites on the {area:205} visit"] = "Un nouveau {item:279996}, pour les quatre gardiens titans autour des {zone:1437} ; sous terre. Leurs cœurs tombent sur des élites de niveau 32, lors de la visite de {area:205}",
	["South-east from the dig to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "Au sud-est du chantier jusqu'au camp Gueule-de-dragon. Les quatre jeux de plans d'attaque se trouvent dans {area:1036} ; {npc:2091}, un élite, se tient aussi dans le camp.",
	["{item:3337}: the camp's Raiders and Swamprunners"] = "{item:3337} : les pillards et les coureurs des marais du camp",
	["Follow the road east to the {area:1025}; {npc:1244} stands by the river. {quest:277}'s flint came with you from your last {zone:1437} visit."] = "Suivez la route vers l'est jusqu'à {area:1025} ; {npc:1244} se tient près de la rivière. Le silex de {quest:277} vient de votre dernière visite des {zone:1437}.",
	["{npc:270637} camps among the Fenrunners, just west of {npc:1244}."] = "{npc:270637} campe parmi les coureurs des marais, juste à l'ouest de {npc:1244}.",
	["Razormaw Incisors: from the raptors by the {area:1038}, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "Incisives de Tranchegueule : sur les raptors près de {area:1038}, lors de la boucle des {zone:1437} de 30-40/01-hillsbrad-foothills",
	["For King Magni in {zone:1455}, at the end of 30-40/01-hillsbrad-foothills"] = "Pour le roi Magni à {zone:1455}, à la fin de 30-40/01-hillsbrad-foothills",
	["East from {npc:270637}: {npc:2093} stands beside the road."] = "À l'est de {npc:270637} : {npc:2093} se tient au bord de la route.",
	["{npc:2093}: for {npc:2094} in Menethil"] = "{npc:2093} : pour {npc:2094} à Menethil",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "Des dragonnets rouges remplissent les collines à l'ouest des portes, des griffes-pourries enragées {area:1025}, des tranchegueules les pentes nord ; Neru se tient au nord-est (utilisez {item:279996}).\nDes rampants des marais se cachent dans les mares au nord-ouest de {area:1025}.\nAttention : hors combat, les rampants des marais lancent Camouflage de temps en temps ; ils sont alors furtifs et difficiles à voir.",
	["{quest:98283}, an elite raptor, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "{quest:98283}, un raptor élite, lors de la boucle des {zone:1437} de 30-40/01-hillsbrad-foothills",
	["Back west along the road to {area:150}: {npc:2104} stands on the top floor of {area:2103}."] = "Retour vers l'ouest par la route jusqu'à {area:150} : {npc:2104} se tient au dernier étage de {area:2103}.",
	["For the Dragonmaw catapult, on the {zone:1437} loop of 30-40/01-hillsbrad-foothills"] = "Pour la catapulte Gueule-de-dragon, lors de la boucle des {zone:1437} de 30-40/01-hillsbrad-foothills",
	["{npc:2094}, by the docks, on the way to the boat"] = "{npc:2094}, près des quais, sur le chemin du bateau",
	["The boat to {area:442} leaves from the far end of Menethil's western pier."] = "Le bateau pour {area:442} part du bout du ponton ouest de Menethil.",
	["{npc:3649} stands at the north end of {area:442}, {npc:3693} and {npc:3694} by the flight master."] = "{npc:3649} se tient au nord de {area:442}, {npc:3693} et {npc:3694} près du maître de vol.",
	["{npc:3693}: Volcor's escort from the end of {zone:1439}"] = "{npc:3693} : l'escorte de Volcor, à la fin de {zone:1439}",
	["{npc:3694}: for {npc:3691} in {area:415}"] = "{npc:3694} : pour {npc:3691} à {area:415}",
	["{npc:3845} stands by {area:415}'s flight master."] = "{npc:3845} se tient près du maître de vol de {area:415}.",
	["For {quest:4581} at {area:2358}"] = "Pour {quest:4581} à {area:2358}",
	["The two stand together at the western end of the road, south-west of {area:415}."] = "Les deux se tiennent ensemble à l'extrémité ouest de la route, au sud-ouest de {area:415}.",
	["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Prenez le tunnel jusqu'à {area:419} ; le tome se trouve dans les ruines à son extrémité ouest.",
	["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Suivez la route vers l'est jusqu'aux camps des satyres de {area:429} ; {npc:3920} se cache en bordure.",
	["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} dirige les satyres de {area:429} ; il porte la branche.",
	["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}, l'avant-poste elfe de la nuit au bout est de la route : {npc:3848} s'y tient.",
	["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176} : pour {npc:3961} à {area:415}",
	["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "Le second {object:19901} se trouve dans la vallée de {area:428}, sur le chemin de l'ouest.",
	["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, un furbolg épargné par la corruption, est assis au sud de la route, en contrebas de {area:421}.",
	["West from {npc:3897} along the southern hills to the {area:416}: Melyria and {npc:3901} stand together by it."] = "À l'ouest de {npc:3897}, par les collines du sud jusqu'à {area:416} : Melyria et {npc:3901} se tiennent ensemble à côté.",
	["North to {area:413}."] = "Au nord jusqu'à {area:413}.",
	["South-east along the road to {area:415}: {npc:3691} in the inn, {npc:3961} and {npc:3894} inside, the flight master at the west end."] = "Au sud-est par la route jusqu'à {area:415} : {npc:3691} dans l'auberge, {npc:3961} et {npc:3894} à l'intérieur, le maître de vol à l'extrémité ouest.",
	["{npc:1571} is the flight master by Menethil's inn."] = "{npc:1571} est le maître de vol près de l'auberge de Menethil.",
	["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Prenez {area:2257} depuis {object:171524} jusqu'à {object:28027} de {zone:1453}, puis marchez jusqu'à {object:2098}.",
	["For {npc:2228} in {area:271}: keep it"] = "Pour {npc:2228} à {area:271} : gardez-la",
	["Next: fly to {area:42}."] = "Ensuite : volez jusqu'à {area:42}.",
	["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Les worgens tiennent les bois de Clairbois, à l'ouest de {area:42} et au nord de la route. Attirez-les un par un.",
	["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Les coureurs noirs rôdent dans les bois au sud de la route, à l'ouest de {area:42}.",
	["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Allez au sud-ouest de {area:42} jusqu'au tertre des ogres. {object:119} se trouve dans le camp à son entrée ; des ogres Poing-d'éclat le gardent.",
	["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 from level 28, but no fight."] = "La tombe se dresse parmi les squelettes au coin nord-ouest du cimetière, sur le chemin de {npc:311}. Sa quête et la suivante ne demandent que de parler, à {npc:268} et à la commandante Althea à {area:42} : niveau 35 dès le niveau 28, mais sans combat.",
	["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "La maison de {npc:276} se dresse à l'extrémité est de la ville, sur le chemin du maître de vol.",
	["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Au sud-est de Menethil jusqu'à {area:1036} des Gueule-de-dragon : la première catapulte est sur le chemin, et {object:671518} se trouve dans le camp.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "Ce sont des monstres élites : il est conseillé de se grouper, cherchez des joueurs pour les faire avec vous. {npc:271462}, {npc:271338}, {npc:271458} et {npc:271460} sont des élites de niveau 32, chacun appelé en utilisant {item:279996} à côté de lui. Passez-les si vous êtes seul. {npc:271462} se tient dans les collines du sud-est.",
	["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "Les dragonnets nichent dans les collines au nord-est de {area:1036} ; {quest:98283} rôde plus au nord, et les raptors Tranchegueule chassent sur les hauteurs, sur le chemin du nord vers {area:205}.\n{quest:98283} est élite : un groupe est conseillé.",
	["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458} se tient dans les collines entre {area:1038} et {area:205} (utilisez {item:279996}).",
	["Maddened Rotclaws roam the {area:1025} around {npc:1244}."] = "Des griffes-pourries enragés parcourent {area:1025} autour de {npc:1244}.",
	["North along the road to {area:205}. {npc:1071}, {npc:1075} and {npc:1072} stand together in the dwarves' camp; the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "Au nord par la route jusqu'à {area:205}. {npc:1071}, {npc:1075} et {npc:1072} se tiennent ensemble dans le camp des nains ; {npc:271481} est retenu du côté ouest : conduisez-le jusqu'à {npc:1072}.",
	["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460} se tient dans les ruines de {area:205} (utilisez {item:279996}).",
	["Comar Villard waits on the road north of {area:205}, towards the {area:880}; {npc:271322} a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to {npc:1075}."] = "Comar Villard attend sur la route au nord de {area:205}, vers {area:880} ; {npc:271322} un peu plus loin au nord-est, et le cadavre d'Ebenezer Rustlocke gît sous le pont à côté d'elle. Le parchemin de Rustlocke est pour {npc:1075}.",
	["Comar Villard"] = "Comar Villard",
	["the same corpse"] = "le même cadavre",
	["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "Redescendez la route jusqu'à {area:205} : {npc:1075} veut que les explosifs {object:147516}, sous l'autre bout du pont, soient détruits.",
	["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end. {npc:2696} stands a short walk west of it."] = "Sur {area:880} : la réserve d'explosifs des Sombrefer se trouve du côté de l'Arathi. {npc:2696} se tient un peu à l'ouest.",
	["Back over the span and down the road through {area:205} on the way south."] = "Retraversez le pont, puis descendez la route par {area:205} en repartant vers le sud.",
	["for {npc:2700} at {area:320}, in 05-arathi-highlands"] = "pour {npc:2700} à {area:320}, dans 05-arathi-highlands",
	["{npc:2104} stands on the top floor of {area:2103}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104} se tient au dernier étage de {area:2103} : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Level 30.8"] = "Niveau 30,8",
	["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "Vous avez passé {quest:474} et il vous manque de quoi atteindre 30,8 ? Tuez les murlocs Branchie-bleue sur la côte au sud de Menethil jusqu'au niveau 30,8. Ou, en groupe, faites plutôt le donjon de {area:133} ou celui de {area:796} (cimetière).",
	["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2705} below it and {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side."] = "En descendant du bateau, remontez le ponton jusqu'à la ville : {npc:2711} et le lieutenant Farren se tiennent près de l'auberge, {npc:2705} en contrebas et {npc:2430} à l'étage, {npc:2382} à l'est ; la maîtresse de vol est au nord, {npc:2381} et {npc:2438} entre elle et l'auberge, Maleb à l'hôtel de ville, du côté ouest.",
	["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, dans l'auberge : pour {area:35} (04-stranglethorn-vale)",
	["{npc:2438}: only if you have or can buy a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells them"] = "{npc:2438} : seulement si vous avez ou pouvez acheter {item:3719} ({skill:165}) et {item:2997} ({skill:197}) ; aucun marchand ne les vend",
	["The naga hold the shore south-east of {area:271}."] = "Les nagas tiennent la côte au sud-est de {area:271}.",
	["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave."] = "{npc:251493} se tient au nord-ouest de la maîtresse de vol, sur le chemin du nord vers la grotte des yétis.",
	["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp."] = "Les yétis vivent dans la grotte des collines au nord de {area:271}, sur le chemin du nord vers le camp du Syndicat.",
	["{npc:2438} also wants a {item:3719} ({skill:165}), a {item:2997} ({skill:197}) and {item:2321} (any trade supplier): the cloak is turned in when you are back in {area:271} later."] = "{npc:2438} veut aussi {item:3719} ({skill:165}), {item:2997} ({skill:197}) et {item:2321} (n'importe quel fournisseur d'artisanat) : la cape se rend quand vous revenez plus tard à {area:271}.",
	["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp, and its Footpads and Thieves are the Syndicate Maleb wants."] = "Le camp du Syndicat se trouve sur la frontière d'Alterac, au nord de {area:287}, à l'ouest de {area:272} (Horde) ; les documents sont dans le camp, et ses détrousseurs et ses voleurs sont les membres du Syndicat que veut Maleb.",
	["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "Les tortues Mordeuses se dorent le long de la rivière à l'est de {area:271}, au sud de {area:272} (Horde).",
	["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}, {npc:2916} et {npc:5637} se tiennent dans {object:32356}, au nord-est du maître de vol.",
	["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} entraîne les guerriers dans {object:2100}, à côté du Cochon et Sifflet. {npc:6236} attend sur {area:720} dans {zone:1413}, sur le chemin de {area:392} bien plus tard (40-50/01).",
	["{npc:2708} is in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708} est dans {object:2164} ; {npc:5081} au sud de {object:2101}.",
	["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455} n'a pas de maître druide : {npc:5504} se tient à {zone:1453}, au nord-ouest de {object:2101}.",
	["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Suivez la route vers l'ouest après {area:460} (Horde), puis au sud-ouest par {area:465} jusqu'à {zone:1443} ; {area:608} se dresse en haut du col.",
	["The chest lies in the ruins south-west of {area:608}."] = "Le coffre se trouve dans les ruines au sud-ouest de {area:608}.",
	["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "La tour de {npc:11863} se dresse sur la colline à l'ouest de {area:599} : prenez d'abord sa quête, le sceptre qu'il veut est dans la forteresse.",
	["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} se cache dans la forteresse de la Lame ardente, au sud-ouest de {area:608}.",
	["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Faites sortir {npc:5644} de la forteresse ; elle s'en va une fois que vous en êtes sortis. {npc:5642} prend le rendu à {area:608}, à la fin du guide.",
	["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "Le camp de {npc:11596} est sur la route au sud de {area:609}, près de {area:596}.",
	["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp. There, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom."] = "Utilisez {item:13892} de {npc:11596} sur {npc:4700} et ramenez le kodo apprivoisé à son camp. Là, parlez au kodo : il est compté, et vous pouvez apprivoiser le suivant. Cinq kodos, un à la fois ; les vieux kodos lâchent aussi les peaux, et les fouetteurs Scorpashi qui chassent autour du cimetière portent le venin.",
	["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Les Kolkar parcourent les plaines autour de {area:609} ; leurs oreilles sont pour {npc:5752}.",
	["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "Pour {npc:1416} à {zone:1453}, après Strangleronce",
	["{npc:4456}: the wyverns are in {area:400}, later in this guide"] = "{npc:4456} : les wyvernes sont à {area:400}, plus loin dans ce guide",
	["Follow the road west out of Theramore to the burned inn on the road toward the {zone:1413}: the black shield lies in the ashes and the hoofprints are in the mud beside the inn."] = "Suivez la route vers l'ouest en sortant de Theramore jusqu'à l'auberge incendiée, sur la route de {zone:1413} : le bouclier noir se trouve dans les cendres et les traces de sabots dans la boue à côté de l'auberge.",
	["Down the {area:485} into {area:400}, then west to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "Descendez {area:485} jusqu'à {area:400}, puis vers l'ouest jusqu'aux falaises des wyvernes à {area:482}. Chaque wyverne peut y lâcher une glande à venin.",
	["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Suivez les canyons vers l'est jusqu'aux plaines de sel. Les gobelins et les gnomes de {area:2240} sont neutres et donnent des quêtes aux deux factions.",
	["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Snappers (tortoises) the whole flats. Saltstone Basilisks and Crystalhides hold the middle; the Gazers (34-35) only the far south."] = "{object:19868} se trouve partout sur les plaines. Des scorpides ravageurs et des charognards des plaines de sel parcourent la moitié nord, des claque-bec Écaille-scintillante (tortues) toutes les plaines. Des basilics Roche-saline et Peau-de-cristal tiennent le milieu ; les contemplateurs (34-35) seulement l'extrême sud.",
	["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454} : pour Martek dans {zone:1418}, à la fin du 30-40",
	["From the raceway follow the road south out of the {area:439} into {zone:1446}; {area:976} is a short walk down it. Keep to the road. {npc:7823}, the Alliance flight master, stands inside the walls."] = "Depuis le circuit, suivez la route vers le sud en sortant de {area:439} jusqu'en {zone:1446} ; {area:976} est un peu plus bas. Restez sur la route. {npc:7823}, le maître de vol de l'Alliance, se tient dans l'enceinte.",
	["{npc:4456} is in the north of town, Captain Vimes in {area:514}; {npc:4941} stands in the town."] = "{npc:4456} est au nord de la ville, le capitaine Vimes à {area:514} ; {npc:4941} se tient en ville.",
	["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "Depuis {zone:1431}, prenez la route vers le sud jusqu'à Strangleronce ; les tentes des chasseurs se dressent juste à l'ouest de la route, après l'embranchement de {area:99}.",
	["The elder tigers come later, on the way back from the {area:99}"] = "Les vieux tigres viennent plus tard, au retour de {area:99}",
	["{npc:469}: {quest:200}'s records, on the northern loop (04b)"] = "{npc:469} : les registres de {quest:200}, lors de la boucle nord (04b)",
	["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Les rebelles Kurzen tiennent le camp à l'est de {area:99} ; restez en bordure, où se tiennent les combattants de la jungle et les hommes-médecine, et fouillez les caisses de ravitaillement près des tentes.",
	["Level 34"] = "Niveau 34",
	["The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the {area:796} dungeon (Library or Armory) instead."] = "Les quêtes suivantes sont de niveau 37 : s'il vous manque de quoi atteindre 34, continuez sur les vieux tigres dans les collines au sud-ouest du camp de Nesingwary jusqu'au niveau 34. Ou, en groupe, faites plutôt le donjon de {area:796} (bibliothèque ou armurerie).",
	["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, le grand tigre, a son repaire au sommet de la colline au sud-ouest du camp ; des raptors fouette-queue courent au sud, sur le chemin de {area:35}.",
	["Down to {area:35}"] = "Descente vers {area:35}",
	["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Suivez la route principale vers le sud sur toute la longueur de la jungle, après l'embranchement de {object:3202}, jusqu'à {area:35} sur le cap sud.",
	["{npc:737}: the Tumbled Crystals, on the northern loop"] = "{npc:737} : les cristaux éboulés, lors de la boucle nord",
	["From {area:108} the way leads south out of {zone:1436} into Stranglethorn's north-west, to the {area:310} near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach it. The Bloodscalp trolls hold the ruins on the coast to the north."] = "Depuis {area:108}, le chemin mène au sud hors de {zone:1436} jusqu'au nord-ouest de Strangleronce, à {area:310} près de la côte ; les basilics Échine-de-cristal alentour lâchent les éclats.\nL'île hantée se trouve juste au large de la côte, au sud-ouest de la mine : il suffit de l'atteindre. Les trolls Scalp-rouge tiennent les ruines de la côte au nord.",
	["River Crocolisks swim the river by the {area:99}."] = "Des crocilisques de rivière nagent dans la rivière près de {area:99}.",
	["Thorsen patrols the road north of camp, toward the {area:99}."] = "Thorsen patrouille sur la route au nord du camp, vers {area:99}.",
	["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495} : les crocilisques Mordeurs, lors de la boucle nord",
	["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496} : les élémentaires d'eau surgissent autour de l'île hantée, lors de la boucle nord",
	["{npc:5504}, the druid trainer, stands in {zone:1453}, north-west of the {object:2101}."] = "{npc:5504}, le maître druide, se tient à {zone:1453}, au nord-ouest de {object:2101}.",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "Depuis {area:415}, allez au nord-ouest dans les collines : {quest:1738} est un arbre lumineux au nord de la route de {area:413}. Si vous avez pris {quest:65602}, {item:190309} se trouve dans une maison parmi les arbres au nord de {area:413} (26.6,22.0). Prenez ensuite la route vers l'ouest jusqu'aux Serres-Rocheuses.",
	["{item:190309}, north of {area:413}"] = "{item:190309}, au nord de {area:413}",
	["Mauren, from Stonetalon"] = "Mauren, depuis les Serres-Rocheuses",
	["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "Depuis {zone:1431}, prenez la route vers le sud ; le camp se trouve dans les collines à l'ouest de la route.",
	["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770} : pour {npc:773} à {area:35}",
	["Herod's records lie in a hut on the west side of {area:101}, east of the {area:99}."] = "Les registres d'Hérode se trouvent dans une hutte du côté ouest de {area:101}, à l'est de {area:99}.",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "Les réducteurs de têtes se tiennent plus au fond de l'enceinte ; les commandos rôdent camouflés autour et dans la grotte, et le coffret d'Hérode se trouve à l'entrée de la grotte. Ramassez les pages des Collines verdoyantes quand elles tombent.\nAttention : les commandos kurzen sont de niveau 34-35, non élites, et apparaissent souvent furtifs ; près de la mort, ils utilisent {spell:7964}.",
	["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733} : les commandos et les réducteurs de têtes tués dans l'enceinte",
	["South along the road: the hunters' tents stand just west of it."] = "Au sud par la route : les tentes des chasseurs se dressent juste à l'ouest.",
	["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Faites une boucle par les ruines trolls du nord et du centre : chacune contient une tablette de pierre des légendes trolls. Des panthères Gueule-d'ombre rôdent camouflées dans la jungle alentour ; le camp de la KapitalRisk à {area:37} porte les cristaux éboulés.",
	["Follow the west coast north to the haunted island off the shore west of Nesingwary's camp: the Lesser Water Elementals rise from the water around it."] = "Suivez la côte ouest vers le nord jusqu'à l'île hantée, au large de la rive à l'ouest du camp de Nesingwary : les élémentaires d'eau inférieurs surgissent de l'eau autour.",
	["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to the Skullsplitter ruins."] = "Des crocilisques Mordeurs se dorent le long de la rivière au milieu de la jungle, sur le chemin du sud vers les ruines Brise-crâne.",
	["{quest:205}'s Skullsplitter trolls are 39-42. Below 36? Keep killing the Snapjaw Crocolisks along the river until level 36. Or, with a group, run the {area:796} dungeon (Armory) or the {area:1316} dungeon instead."] = "Les trolls Brise-crâne de {quest:205} sont de niveau 39-42. Moins de 36 ? Continuez à tuer les crocilisques Mordeurs le long de la rivière jusqu'au niveau 36. Ou, en groupe, faites plutôt le donjon de {area:796} (armurerie) ou celui de {area:1316}.",
	["{npc:773}: the ore drops from Drywhisker kobolds in {zone:1417}, next"] = "{npc:773} : le minerai tombe sur les kobolds Sèche-moustache en {zone:1417}, ensuite",
	["Follow the road north to the draenei of the {area:657}."] = "Suivez la route vers le nord jusqu'aux draeneï de {area:657}.",
	["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Vers l'est par la route jusqu'à {area:76}. Les {npc:256028} lâchent les cristaux ; Noboru arpente les ruines et lâche son gourdin.",
	["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "Le coffre de la caravane détruite se trouve au nord de {area:76}, à côté de la cage de {npc:5391}.\nAttention : le camp est plein d'Égarés d'environ niveau 38. Ils se tiennent en groupes liés de 2 ou 3, beaucoup lancent des sorts, et ils réapparaissent vite.",
	["{npc:1141}, {area:17203} road"] = "{npc:1141}, route de {area:17203}",
	["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "{npc:2434} rôde sans être vu en bordure de {area:271} ; tuez-le et lisez le contrat qu'il porte.",
	["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Suivez la route vers l'est en sortant de {area:287}, par {area:1057}, jusqu'à {area:320}.",
	["{npc:2700}: {npc:1075}'s plea, from 01-hillsbrad-foothills"] = "{npc:2700} : la requête de {npc:1075}, depuis 01-hillsbrad-foothills",
	["South-east from Northfold to the Witherbark trolls in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley. Every troll here can drop a tusk."] = "Au sud-est de Northfold jusqu'aux trolls Fanécorce dans les collines au sud de {area:314} ; les sorciers-docteurs se tiennent dans le village, les chasseurs des ombres gardent le fond de la vallée. Chaque troll ici peut lâcher une défense.",
	["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Allez au nord après {area:314} ; les éclats scintillent sur la colline près de {area:333}.",
	["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435} sur {npc:2572}, {npc:2573} et {npc:2574}, près de cet arrêt",
	["The shards lie at the far end of {area:318}."] = "Les éclats se trouvent au fond de {area:318}.",
	["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "Le coursier marche sur la route à l'ouest de {area:314} avec deux gardes ; éloignez-les de la route.",
	["For {npc:2711} in {area:271}"] = "Pour {npc:2711} à {area:271}",
	["South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Au sud le long de la côte ouest jusqu'à la crique des gobelins ; Lolo monte la garde sur les rochers au-dessus.",
	["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Escortez le professeur en haut de la colline jusqu'à la grotte au-dessus de la crique et protégez-le pendant qu'il travaille. Deux élémentaires d'eau de niveau 40 l'attaquent là-haut, et ils sont insensibles au givre. Retenez-les à l'entrée de la grotte, loin de lui : si le combat a lieu dans la grotte, il s'y joint au lieu de travailler et d'autres élémentaires arrivent sans cesse.",
	["For {npc:2487} in {area:35}: keep it"] = "Pour {npc:2487} à {area:35} : gardez-la",
	["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Les ogres Cassecrête tiennent les collines au nord de {area:280}. Plus au nord, un coffre en bois usé contient {item:3706} ; {npc:2320}, de {quest:537}, se tient juste à côté.",
	["For {npc:2542} in {area:35}: keep it"] = "Pour {npc:2542} à {area:35} : gardez-la",
	["{npc:2438}, if you took his cloak quest"] = "{npc:2438}, si vous avez pris sa quête de la cape",
	["{npc:1356}, {object:32356}: for {npc:1344} in {area:38}, next"] = "{npc:1356}, {object:32356} : pour {npc:1344} à {area:38}, ensuite",
	["Ryedol's next errand goes into {area:1517}: skip it."] = "La course suivante de Ryedol mène à {area:1517} : passez-la.",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Les ogres Crache-poussière campent juste au sud de la vallée ; tous lâchent de la ferraille. Des busards tournent au-dessus de la plaine à l'est.\nLe squelette abîmé gît au bord du camp des troggs de Cave-pierre ; {quest:739}, le meurtrier d'Agmond, se promène parmi les brise-os.\nAttention : les seigneurs Crache-poussière sont de niveau 44-45. Ils utilisent {spell:5242} et {spell:1160}, et sous 50 % de vie ils appellent les alliés à moins de 15 mètres. Sept d'entre eux se tiennent à environ 750 mètres au sud de {area:340}.",
	["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {area:3} guide at 43, and kill the Bonesnappers for this quest now."] = "{quest:739} lui-même (42) se promène parmi les claque-os : laissez-le pour le guide de {area:3} plus tard, au niveau 43, et tuez maintenant les claque-os pour cette quête.",
	["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "Les élémentaires de roche inférieurs errent dans {area:1878} à l'ouest de {npc:2921} ; chaque élémentaire de roche peut lâcher les éclats d'élémentaire de roche de {npc:1470}.",
	["{npc:2920}, beside {npc:2921}, wants {item:2868}, a blacksmith's craft: skip him unless you carry a pair."] = "{npc:2920}, à côté de {npc:2921}, veut {item:2868}, une fabrication de forgeron : passez-le sauf si vous en avez une paire.",
	["Head south down the road: {npc:4618} and {npc:2817} camp in the {area:1877}, on the way to {area:345}."] = "Descendez la route vers le sud : {npc:4618} et {npc:2817} campent à {area:1877}, sur le chemin de {area:345}.",
	["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "Pour {npc:4454} à {area:2240} : le guide de {zone:1446} passe devant lui au niveau 45, gardez-la",
	["{npc:2921}'s last test is optional: five {item:4628}, which only the Greater Rock Elementals (42-44) in the south-western gulches drop, about one kill in five, well above your level. Take it only if you can handle them one at a time; otherwise hand in the slabs and move on."] = "La dernière épreuve de {npc:2921} est facultative : cinq {item:4628}, que seuls les élémentaires de roche supérieurs (42-44) des ravines du sud-ouest lâchent, environ une fois sur cinq, bien au-dessus de votre niveau. Ne la prenez que si vous pouvez les affronter un par un ; sinon, rendez les dalles et continuez.",
	["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "En descendant du bateau, remontez le ponton jusqu'à Baldruc, le maître de vol près de la porte de {area:514}.",
	["{npc:5638}: the wreck is on the north-west coast, at the end of the loop"] = "{npc:5638} : l'épave est sur la côte nord-ouest, à la fin de la boucle",
	["Follow the road south to {area:2407}."] = "Suivez la route vers le sud jusqu'à {area:2407}.",
	["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} se tient en bordure de {area:596}, au sud-ouest de {area:2407} ; {object:176751} se trouvent parmi les squelettes. Un {npc:217590} rampe dans le cimetière : attrapez-en un avec le kit de débutant en entomologie, puis cochez-le.",
	["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Les centaures Maraudine tiennent {area:607} à l'ouest du cimetière ; tous lâchent les totems.",
	["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Suivez la route vers l'ouest à travers le nord de {zone:1443} jusqu'aux ruines de {area:2405}. La tour de {npc:11863} se dresse sur la colline, sur le chemin de l'épave.",
	["Follow the road north to {area:608}."] = "Suivez la route vers le nord jusqu'à {area:608}.",
	["for {npc:3980} in {area:271}: keep it"] = "pour {npc:3980} à {area:271} : gardez-la",
	["{npc:4964}, on the top floor of {area:514}"] = "{npc:4964}, au dernier étage de {area:514}",
	["{npc:4794}: the crawlers are on the {area:8} shore, keep it"] = "{npc:4794} : les rampants sont sur la rive de {area:8}, gardez-la",
	["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Stinky attend à l'ouest du manoir, dans le marais en contrebas de {area:504}. Conduisez-le jusqu'à ses feuilles de fève des marais et tenez les créatures du marais à l'écart.",
	["The burned inn stands on the road west, toward the {area:17}; the guard's badge lies in the ashes."] = "L'auberge incendiée se dresse sur la route de l'ouest, vers {area:17} ; l'insigne du garde se trouve dans les cendres.",
	["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Suivez la route vers l'est pour revenir à Theramore. Tervosh, dame Jaina et les officiers sont dans la tour et à {area:514}.",
	["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Les murlocs Nageboue se pressent sur la côte nord après {area:497} ; finissez les langues sur les tortues à côté.",
	["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "En montant vers le nord jusqu'à {area:392}, {area:720} se trouve au large de {area:391}, au sud de la ville : traversez à gué les hauts-fonds du banc de sable. {npc:6236} vous envoie quatre adversaires puis {npc:6238} (niveau 33), un à la fois.",
	["for {npc:770} at the {area:99}, on the northern loop"] = "pour {npc:770} à {area:99}, lors de la boucle nord",
	["{npc:737}, upstairs: the Skullsplitter trolls, on the northern loop"] = "{npc:737}, à l'étage : les trolls Brise-crâne, lors de la boucle nord",
	["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Chaque Voile-sanglante lâche du tabac à priser et l'un d'eux porte l'œil de {npc:2493} ; les bretteurs arpentent la rive juste au nord de la ville. Les cartes et les ordres se trouvent dans le camp des pirates à {area:43}, au sud de {area:35}.",
	["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Les capitaines se tiennent sur les navires ancrés au large de {area:43}, chacun avec un équipage de pirates de niveau 42-45 : Stillwater (45) et Keelhaul (46) sur les ponts les plus proches, {npc:2546} (48) sur le vaisseau amiral. Au niveau 42, c'est un combat de groupe ou pour la fin du guide ; si vous y allez, nettoyez chaque pont d'abord. Le parchemin de Cortello se trouve sur l'épave près de la rive.",
	["Level 42.06"] = "Niveau 42,06",
	["If you skipped {quest:193}, grind here to level 42.06 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Si vous avez passé {quest:193}, tuez des monstres ici jusqu'au niveau 42,06 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1517}.",
	["Level 42.1"] = "Niveau 42,1",
	["If you skipped {quest:196}, grind here to level 42.1 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Si vous avez passé {quest:196}, tuez des monstres ici jusqu'au niveau 42,1 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1517}.",
	["Level 42.16"] = "Niveau 42,16",
	["If you skipped {quest:208}, grind here to level 42.16 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Si vous avez passé {quest:208}, tuez des monstres ici jusqu'au niveau 42,16 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1517}.",
	["Ride south down the road to {area:35}."] = "Descendez la route vers le sud jusqu'à {area:35}.",
	["{npc:5694}: for {npc:5464} in {area:42}, on the way to the swamp"] = "{npc:5694} : pour {npc:5464} à {area:42}, sur le chemin du marais",
	["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, dans {object:2164} : {npc:6251}, à {area:392}, la prend à la fin du guide suivant",
	["{npc:5464}, by the flight master"] = "{npc:5464}, près du maître de vol",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Si vous avez passé {quest:543}, tuez des monstres ici jusqu'au niveau 42,46 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1517}.",
	["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Allez vers l'est ; les horreurs enchevêtrées en chemin lâchent aussi les essais. Fouillez le bord de {area:74}, là où les ruines du temple percent l'eau.",
	["{item:5938}, from the Silt Crawlers on the same shore"] = "{item:5938}, sur les rampants du limon de la même rive",
	["for {area:1438}: keep it"] = "pour {area:1438} : gardez-la",
	["for {npc:5635} at {area:348}: keep it"] = "pour {npc:5635} à {area:348} : gardez-la",
	["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637} est dans la salle des Reconquérants près de {object:32356}, {npc:2786} dans {object:32383}.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à chevaucher, et l'apprentissage vous donne une monture. {npc:4772} forme les nains à {area:803}, à l'est de {area:131} sur la route de {zone:1432}, à côté des béliers de {npc:1261}. Forever laisse peut-être chaque race apprendre auprès de n'importe quel maître d'équitation (non confirmé). Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à chevaucher, et l'apprentissage vous donne une monture. {npc:7954} forme les gnomes à {area:189}, juste à l'est de {area:131}, à côté des mécanotrotteurs de {npc:7955}. Forever laisse peut-être chaque race apprendre auprès de n'importe quel maître d'équitation (non confirmé). Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817} : des perles bleues de Strangleronce",
	["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Chevauchez vers l'ouest à travers {zone:1418} jusqu'au camp Rotegueule à {area:342}. {npc:2944} se tient au milieu, entouré de chasseurs de wyrms et de cogneurs.",
	["Ride back east to {area:1898}."] = "Revenez à cheval vers l'est jusqu'à {area:1898}.",
	["{npc:3980} preaches by the inn."] = "{npc:3980} prêche près de l'auberge.",
	["Raleigh's next errand is in the {area:796}: skip it."] = "La course suivante de Raleigh est dans {area:796} : passez-la.",
	["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} campe sur la route à l'est de {area:348}.",
	["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "Depuis Theramore, chevauchez vers le nord dans {zone:1413} jusqu'à {area:392}, ou volez-y si vous connaissez son point de vol. {npc:6251} enseigne dans la maison près de la banque.",
	["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116} se dresse sur {area:1120}, au large de {area:1108} : le bateau du quai de la côte y mène. {npc:7880} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764} : sa réponse attend à {area:702}, plus tard",
	["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Retour à {area:1117}. Chaque naga Crête-haine peut y lâcher des écailles.",
	["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Prenez le bateau jusqu'à {area:1108} et suivez la rive vers le sud jusqu'à la barque échouée sur la plage.",
	["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Depuis {area:489}, chevauchez vers l'ouest par la route jusqu'au camp Totem-sinistre au nord. {npc:7956} attend devant ; libérez les follets fléchettes de l'enclos au milieu et gardez en vie {npc:7956} et au moins six d'entre eux.",
	["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Chevauchez au sud-est jusqu'aux gnolls Patte-de-bois ; les sacs à dos du coursier se trouvent dans leur camp sud, et un colis à l'intérieur lance une livraison vers {area:489}. La ruche Zukk'ash est juste au sud : descendez jusqu'à la cosse qui retient Raschal, libérez-le et gardez-le en vie à la sortie.",
	["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} vous demande ensuite de porter des nouvelles à {zone:1457} : passez-la, {area:976} vous y envoie à la place.",
	["Ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "Chevauchez vers l'est jusqu'à {area:1105}. Les quêtes de {npc:14637} sur la côte demandent le niveau 45. Ou, en groupe, faites plutôt le donjon de {area:978} ou celui de {area:1517}.",
	["Ride back to the {area:1108}; the goblin stands by the dock."] = "Revenez à cheval jusqu'à {area:1108} ; le gobelin se tient près du quai.",
	["The {zone:1446} guide starts with the trip east, past {area:489}."] = "Le guide de {zone:1446} commence par le voyage vers l'est, après {area:489}.",
	["The {area:2240} lies on the {area:439} in south-east {area:400}: {npc:4454} is in the gnomes' camp beside the track, {npc:4709} by the goblin camp."] = "{area:2240} se trouve sur {area:439}, au sud-est de {area:400} : {npc:4454} est dans le camp des gnomes à côté de la piste, {npc:4709} près du camp des gobelins.",
	["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454} : {quest:1137}, de la part de Martek dans {zone:1418}",
	["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763} : sa caisse va à {area:702}, plus tard",
	["The same poster: {npc:7847} comes much later, after {area:976}"] = "La même affiche : {npc:7847} vient bien plus tard, après {area:976}",
	["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "La livraison suivante de {npc:7881} retourne à {area:35} : passez-la.",
	["The pool by {area:979}"] = "Le bassin près de {area:979}",
	["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Chevauchez au nord-ouest jusqu'au camp des trolls Furie-des-sables à {area:979}. Utilisez {item:8584} au bord de son bassin ; les trolls sont tout près, alors attirez d'abord le plus proche.",
	["Pool by {area:979}"] = "Bassin près de {area:979}",
	["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Chevauchez vers le sud jusqu'au camp de fouilles de {area:1938}. {npc:7771} vous donne un casque détecteur : portez-le pour voir les monticules de {quest:3161}, nombreux dans le sable autour du camp et vers le sud-ouest, en direction des ogres.",
	["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "La petite tortue {npc:5955} se cache au nord de la vallée. Ramenez-la chez sa femme {npc:6015}, au bord de l'eau juste à l'est de {area:977} : elle marche lentement et les bêtes du désert s'en prennent à elle, alors gardez-la en vie.",
	["Ride back west to {area:976}."] = "Revenez à cheval vers l'ouest jusqu'à {area:976}.",
	["{npc:5636}, beside the flight master"] = "{npc:5636}, à côté du maître de vol",
	["for {quest:2990} at {area:1438}, later"] = "pour {quest:2990} à {area:1438}, plus tard",
	["The {area:1517} dig"] = "Les fouilles de {area:1517}",
	["Ride back west along the loch to {area:144}."] = "Revenez à cheval vers l'ouest le long du loch jusqu'à {area:144}.",
	["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} se tient à l'étage, au-dessus de {npc:7916} : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Chevauchez d'abord vers l'est par la route jusqu'au donjon : {item:6091} expire une heure après {area:42}, et les bêtes des mages de sang prennent plus de temps que ça.",
	["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "La tâche suivante de {npc:8022}, {item:9471}, est une quête de {area:978} : passez-la.",
	["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {area:51}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Depuis {area:144}, chevauchez vers le sud jusqu'à {zone:1418}, puis vers l'ouest après {area:340}, la ville de la Horde (gardez vos distances), et montez le sentier jusqu'à {area:51} : {area:247} est juste à l'entrée, au sud-est. Le prisonnier de la cabane en bois veut 15 {item:4306} et huit géologues Sombrefer tués sur le chantier de fouilles alentour. La cabane s'ouvre aussi avec la clé, si vous en avez trouvé une.",
	["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Si vous avez passé {item:3985} ou Face à Negolash, tuez des monstres ici jusqu'au niveau 48,27 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:2100} ou celui de {area:978}.",
	["Ride north-west across the Cauldron to {area:1446}, the scaffolded camp on the north-west rim."] = "Chevauchez au nord-ouest à travers le Chaudron jusqu'à {area:1446}, le camp à échafaudages sur le rebord nord-ouest.",
	["The night elf stands alone west of {area:1446}. Hear his story."] = "L'elfe de la nuit se tient seul à l'ouest de {area:1446}. Écoutez son histoire.",
	["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to Kalaran."] = "Les araignées parcourent les plateaux et les bassins de lave au sud de {npc:8436}, sur le chemin de Kalaran.",
	["Kalaran Windblade"] = "Kalaran Lamevent",
	["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "Kalaran se tient sur le rebord du Chaudron, au sud de {area:1446}. Écoutez son histoire.",
	["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "De lourds golems de guerre patrouillent au fond du Chaudron sous Kalaran ; des élémentaires de magma dérivent parmi eux. Les golems et les élémentaires lâchent l'huile, les élémentaires les cœurs.\nLes maîtres de corvée et les esclavagistes mènent les esclaves partout dans le Chaudron, et n'importe lequel peut porter {item:10551}. Les forgerons à vapeur travaillent aux fourneaux au milieu ({item:18959}), les guetteurs se tiennent sur les crêtes sud (la longue-vue). N'importe quel {object:147516} peut lâcher {item:11818} : gardez-le.\nAttention : les esclavagistes Sombrefer (niveau 45-46) appellent les alliés à moins de 15 mètres quand on les attire, lancent Filet jusqu'à 15 mètres et utilisent Pourfendre au corps à corps.",
	["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} s'ouvre au nord du Chaudron. Les plans secrets se trouvent sur sa corniche supérieure ; des incendosaures nagent dans les bassins de lave plus loin, alors attirez-les vers le bord. Tenez-vous loin de {npc:14621} et de ses gardes élites tout au fond.",
	["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Si vous avez passé {quest:7701}, tuez des monstres ici jusqu'au niveau 48,66 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:2100} ou celui de {area:978}.",
	["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Si vous avez passé {quest:3452}, tuez des monstres ici jusqu'au niveau 48,98 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:2100} ou celui de {area:978}.",
	["Back at the {area:247}: Dorius stands by the road. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "De retour à {area:247} : Dorius se tient au bord de la route. Escortez-le au nord-est jusqu'à {area:1959} et gardez-le en vie ; à la fin, lisez {object:175704} qu'il laisse sur la route.",
	["The flight from Theramore lands in {area:976}."] = "Le vol depuis Theramore se pose à {area:976}.",
	["{npc:7564}, once he has brewed the elixir: a few seconds"] = "{npc:7564}, une fois l'élixir préparé : quelques secondes",
	["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Chevauchez vers le sud jusqu'à {area:537}, au milieu du cratère, puis vers l'est dans la jungle orientale. Des amas de cristaux se dressent partout dans le cratère, beaucoup autour de {area:537} : prenez-en quelques-uns de plus de chaque couleur. Les fouetteurs et les batteurs Pétale-de-sang lâchent les pétales ; {item:11113} de l'expédition se trouve dans un camp abandonné de la jungle orientale.",
	["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Chevauchez vers le nord jusqu'à {area:1943}, où le robot se tient parmi les gorilles. Restez hors de la grande grotte.",
	["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50. Or, with a group, run the {area:2100} dungeon instead."] = "Complétez ici jusqu'au niveau 49,51 avant les rendus de {area:541} : ils vous font passer au niveau 50. Ou, en groupe, faites plutôt le donjon de {area:2100}.",
	["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales. The crate sits at the abandoned camp in the eastern jungle."] = "Chevauchez vers le sud par le côté est. De jeunes diemetradons broutent dans la jungle orientale et des {npc:9165} volent près des falaises de l'est ; les deux lâchent les écailles de {npc:9998}. La caisse se trouve au camp abandonné de la jungle orientale.",
	["Ride south-west past {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "Chevauchez au sud-ouest après {npc:9619} : la ruche silithide occupe le sud du cratère. Utilisez la fiole de raclage sur une couveuse, une salle où pendent des larves. Les guêpes et les ouvriers Gorishi lâchent {quest:3764} ; des pterrordax nichent sur les falaises du sud s'il vous manque des victimes.\nAttention : les silithides gorishi sont de niveau 51-54 et lancent {spell:8137} ou {spell:14120} au corps à corps ; les ouvriers gorishi ont 50 % de chances d'appeler à l'aide à moins de 25 mètres une fois sous 45 % de vie.",
	["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51. Or, with a group, run the {area:2100} dungeon or the {area:1417} dungeon instead."] = "Complétez ici jusqu'au niveau 50,4 avant les rendus de {area:3137} : ils vous font passer au niveau 51. Ou, en groupe, faites plutôt le donjon de {area:2100} ou celui de {area:1417}.",
	["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Chevauchez au nord-est depuis le sanctuaire : {npc:8405} campe à {area:1224}, dans les collines au-dessus de la route.",
	["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Les coursiers Sabot-moussu les plus proches broutent dans les collines au nord-est de {area:1224}, vers {area:1219} ; un plus grand troupeau parcourt le terrain dégagé au sud.",
	["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} campe à {area:1219}, au nord ; son équipement est éparpillé partout dans {area:1220}, juste au sud-est de lui.",
	["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Les nagas Fouette-bile de {area:1221} portent {item:13815}. Les quatre runes de {npc:8507} se dressent parmi les ruines : utilisez son {item:10445} sur chacune.",
	["Ride north from {area:271} up the road through Alterac to {area:3197}."] = "Chevauchez vers le nord depuis {area:271} par la route qui traverse Alterac jusqu'à {area:3197}.",
	["{npc:10838} stands in the middle of the camp."] = "{npc:10838} se tient au milieu du camp.",
	["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "Le fantôme de {npc:10778} erre près de la ferme de {area:199}, à l'ouest de {area:200} ; son colis est à l'intérieur.",
	["{area:199} cauldron"] = "Chaudron de {area:199}",
	["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} garde le chaudron de {area:199}, à l'ouest d'Andorhal.",
	["grind on {npc:7033}: {npc:9177} gives {quest:4283} from level 51"] = "tuez des {npc:7033} : {npc:9177} donne {quest:4283} à partir du niveau 51",
	["Top up here to level 52 on the ogres of {area:249}, on the way to {area:251}: the hand-ins there take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complétez ici jusqu'au niveau 52 sur les ogres de {area:249}, sur le chemin de {area:251} : les rendus là-bas vous font passer au niveau 53. Ou, en groupe, faites plutôt le donjon de {area:1417} ou celui de {area:2100}.",
	["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Suivez la route vers l'ouest, puis montez vers le nord jusqu'au camp gobelin de {area:251}.",
	["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Se termine par {quest:4808} à {area:2255}, en {zone:1452} : gardez-la",
	["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Si vous avez passé {quest:4022}, tuez des monstres ici jusqu'au niveau 52,08 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1417} ou celui de {area:2100}.",
	["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Montez au sommet de {area:249} et plantez la tête dans le monticule de terre meuble.",
	["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455} n'a pas de maître druide : prenez le portail qui monte vers {zone:1457} et entraînez-vous à {area:1658}, puis redescendez à {area:702}.",
	["Ride north out of {area:415} into {area:361} to the {area:2479}, the druids' camp by the road."] = "Chevauchez vers le nord en sortant de {area:415} jusqu'en {area:361}, à {area:2479}, le camp des druides au bord de la route.",
	["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "{npc:11554} le furbolg se tient au bord de la route, juste au sud de {area:2479}.",
	["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Si vous avez passé La corne de la bête ou {item:9328}, tuez des monstres ici jusqu'au niveau 52,58 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1417} ou celui de {area:2100}.",
	["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complétez ici jusqu'au niveau 52,69 avant les rendus de {area:1763} : ils vous font passer au niveau 53. Ou, en groupe, faites plutôt le donjon de {area:1417} ou celui de {area:2100}.",
	["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Les satyres Feu-de-jade tiennent le vallon à l'ouest de la route, avec {npc:9454} au fond.\nAttention : les traqueurs de l'ombre Feu-de-jade (niveau 51-52) utilisent Camouflage et {spell:7992} et sont furtifs ; ils rejoignent donc souvent les combats sans y être invités.\nDes limons maudits glissent dans les ruisseaux du vallon : tuez-les et utilisez le bocal à limon vide de Laris sur leurs restes.",
	["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763} est le temple en ruine au nord du vallon. Certains de ses cultistes lâchent {item:13140}, environ une fois sur trente : elle ouvre la cellule de {npc:11018} à {area:1770}, la grotte du fond. Si elle tombe, dégagez le chemin de sortie avant de la libérer ; sinon, passez ses quêtes.",
	["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949} : des limons souillés glissent autour des bassins gangrenés de {area:1763}",
	["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complétez ici jusqu'au niveau 52,9 avant les rendus de {area:2479} : ils vous font passer au niveau 53. Ou, en groupe, faites plutôt le donjon de {area:1417} ou celui de {area:2100}.",
	["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Les tréants Bois-tordu de {area:1767}, à l'est de {area:2618}, portent {item:11503}.",
	["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Suivez la route vers le nord jusqu'à l'entrée de la grotte de {area:1769} ; {npc:15395} la garde.",
	["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} est la vallée des satyres au nord-ouest, avec {npc:10648} tout au fond. Il lâche {quest:939} ; chaque satyre Feu-de-jade peut lâcher {item:11674}.",
	["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {area:361}."] = "Chevauchez au sud-est depuis {area:1763} jusqu'à {area:2479}, le camp des druides au bord de la route, au sud de {area:361}.",
	["{npc:11556} stands right at the {area:618} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} se tient juste à la sortie du tunnel de {area:1769} côté {area:618}, là où vous débouchez.",
	["{item:12383}, 110 yd north"] = "{item:12383}, à 110 mètres au nord",
	["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Les yétis Glacechardon vivent dans les collines au sud de {area:2244}, les chimères Ventfroid dans la vallée vers {area:2255}.",
	["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "Les ruines entourent le lac gelé au sud de {area:2253}. Ramassez les quatre fragments de relique dans les ruines et les plumes de lune au sol, là où errent les séléniens.",
	["For Kernda in {area:1769}: keep it"] = "Pour Kernda à {area:1769} : gardez-la",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56. Grind the Winterfall furbolgs camped by {area:2246} (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through {area:1769} need. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "Complétez ici jusqu'au niveau 55,05 avant les rendus de {area:2255} : ils vous font passer au niveau 56. Tuez les furbolgs Tombe-hiver qui campent près de {area:2246} (éclaireurs, totémiques, guetteurs de la tanière) : cela augmente votre réputation auprès des Grumegueules, dont les quêtes d'ici et la traversée de {area:1769} ont besoin. Ou, en groupe, faites plutôt le donjon de {area:1584} ou celui de {area:1583} (partie basse).",
	["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "Le village des furbolgs Tombe-hiver se trouve à l'est de {area:2255} : chamans (56-57), guetteurs de la tanière (55-56) et Ursas (57-58), tous au-dessus de vous. Tuez d'abord les chamans, qui soignent, et attirez depuis le bord. {npc:10738}, dans la grotte du fond, est élite : n'y allez pas.",
	["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns."] = "Retour aux collines : seuls les matriarches et les patriarches Glacechardon portent les cornes.",
	["From {area:271}, ride north up the road through Alterac to {area:3197}."] = "Depuis {area:271}, chevauchez vers le nord par la route qui traverse Alterac jusqu'à {area:3197}.",
	["{npc:10838}: the watchtowers are in Andorhal, keep it"] = "{npc:10838} : les tours de guet sont à Andorhal, gardez-la",
	["{npc:11053}: the cauldron is at {area:200}, keep it"] = "{npc:11053} : le chaudron est à {area:200}, gardez-la",
	["{npc:10739} stands by the farm at the {area:202}, on the road east to the {area:139}."] = "{npc:10739} se tient près de la ferme de {area:202}, sur la route de l'est vers {area:139}.",
	["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "Les trois morceaux de la poupée se trouvent dans les maisons en ruine de {area:2262} ; en ramasser un peut faire apparaître des fantômes. Assemblez-les pour former la poupée.",
	["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "Le Fléau autour de {area:2264}, à l'ouest de la chapelle, lâche les deux sortes de pierres du Fléau ; des esprits de Darrowshire s'en élèvent : parlez à chacun pour le libérer.",
	["The next guide starts here and flies to {area:3197}."] = "Le guide suivant commence ici et vole jusqu'à {area:3197}.",
	["{area:200} cauldron"] = "Chaudron de {area:200}",
	["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "Le chaudron se trouve à {area:200}, au nord-est de Felstone ; son seigneur du chaudron se tient à côté.",
	["{area:202} cauldron"] = "Chaudron de {area:202}",
	["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "Le chaudron se trouve à {area:202}, près de la ferme de {npc:10739}.",
	["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, à {area:2268} : gardez-la",
	["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Les médecins, chasseurs, chevaliers et mages écarlates patrouillent dans le camp de bûcherons et sur la route vers {area:190}.",
	["{area:190} overlook"] = "Belvédère de {area:190}",
	["{area:201} cauldron"] = "Chaudron de {area:201}",
	["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Chevauchez vers le sud jusqu'à {area:201}, où {npc:11078} garde le chaudron.",
	["{npc:5411} in {area:976}: keep it"] = "{npc:5411} à {area:976} : gardez-la",
	["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Chevauchez au nord-ouest jusqu'à {area:2276}, en bordure de {area:2277}.",
	["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "Le crâne d'Horgus se trouve à {area:2624} et l'épée de Marduk dans {area:2623}, chacun là où se battent des fantômes ; des molosses de la peste adultes chassent dans les plaines entre les deux.",
	["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Chevauchez vers l'ouest jusqu'à {area:2627}. Des avortons de molosse de la peste, des chauves-souris de la peste et des larves charognardes parcourent ses bois ; remplissez {item:15042} aux grandes termitières et tuez les molosses de la peste frénétiques plus au nord.",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Chevauchez au nord jusqu'à {area:2627}. {npc:12384} vit dans la hutte en ruine, et son carnet de reçus se trouve dans l'auberge en ruine voisine.",
	["{npc:8598}, 170 yd north-east"] = "{npc:8598}, à 170 mètres au nord-est",
	["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} se trouve dans l'hôtel de ville de {area:190}, à l'ouest de {npc:1855} : les gardes écarlates sont serrés les uns contre les autres.",
	["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} se trouve à l'est de la grange de {area:201}.",
	["{npc:7740}: keep it for {area:976}"] = "{npc:7740} : gardez-la pour {area:976}",
	["From {area:702}, fly to {area:1116}."] = "Depuis {area:702}, volez jusqu'à {area:1116}.",
	["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Prenez le bateau vers le continent et chevauchez au nord-est jusqu'au camp de {npc:14637}, près de {area:1119}.",
	["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Les géants rapetissés parcourent {area:1119} ; les élémentaires de mer pataugent le long de la côte à l'ouest.",
	["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "Le camp de {npc:7775} se trouve au nord de {area:1119}. Il vend {item:11243} une fois qu'il a son appât.",
	["From Theramore, ride west into the {area:17} and north up the coast to {area:392}."] = "Depuis Theramore, chevauchez vers l'ouest jusqu'à {area:17}, puis au nord le long de la côte jusqu'à {area:392}.",
	["{npc:7876}, north side of town: the tar is in Un'Goro, keep it"] = "{npc:7876}, au nord de la ville : le goudron est à Un'Goro, gardez-la",
	["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Chevauchez au sud-ouest jusqu'au camp de {npc:7771} à {area:1938}.",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Volez de {area:976} à {area:541}. La hutte de {npc:8737} se dresse à {area:538}, à l'ouest du refuge ; {npc:9117} est en haut de la colline derrière.\n{npc:9999}, l'ami de {npc:9997}, a disparu.",
	["Ride out of the crater's north-western pass into {area:1377} and on to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Sortez du cratère par le col nord-ouest jusqu'à {area:1377} et continuez jusqu'à {area:3425}. {npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "Si vous avez passé {item:9328}, tuez des monstres ici jusqu'au niveau 56,89 pour rester dans le rythme du parcours. Ou, en groupe, faites plutôt le donjon de {area:1584} ou celui de {area:1583} (partie basse).",
	["Follow the road south-west out of the pass to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Suivez la route au sud-ouest en sortant du col jusqu'à {area:3425}. {npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Fly from {area:541} to {area:392}."] = "Volez de {area:541} à {area:392}.",
	["{npc:11038}, by the graves south of the chapel: Egan is in {area:2627}, keep it"] = "{npc:11038}, près des tombes au sud de la chapelle : Egan est à {area:2627}, gardez-la",
	["From {area:3137} ride into {area:361}: the {area:2479} is the druids' camp on the road just past the {zone:1440} border."] = "Depuis {area:3137}, chevauchez jusqu'en {area:361} : {area:2479} est le camp des druides sur la route, juste après la frontière de {zone:1440}.",
	["{area:1770} braziers"] = "Braseros de {area:1770}",
	["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Suivez la route vers le nord jusqu'à {area:1767}. Les écraseurs Bois-de-fer portent le cœur ; finissez les griffes sur les grizzlis Griffe-colère et les ravageurs Patte-gangrenée du nord.",
	["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Chevauchez vers le nord jusqu'au village des furbolgs Mort-bois, près de l'entrée de la grotte de {area:1769}.",
	["Fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Volez jusqu'à {area:976}. Achetez ici deux barres de thorium à l'hôtel des ventes pour {quest:5801}.",
	["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Prenez la route de l'ouest qui descend dans le cratère et chevauchez jusqu'à {area:540}, la grotte silithide du sud. {npc:10041} attend dans sa salle la plus profonde.",
	["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Chevauchez vers le nord jusqu'à {area:541}. Utilisez {npc:10980} à côté de {npc:10977}.",
	["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190}, à l'étage à côté de {npc:15189}",
	["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Chevauchez vers l'est jusqu'aux ruines de {area:2738}. {object:179565} se trouve parmi les bâtiments en ruine, surveillé par des sentinelles torturées.",
	["The hermit hides among the rocks south-east of {area:2738}."] = "L'ermite se cache parmi les rochers au sud-est de {area:2738}.",
	["Havunth's camp sits just west of {area:3425}."] = "Le camp d'Havunth se trouve juste à l'ouest de {area:3425}.",
	["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Fly to {area:976}."] = "Volez jusqu'à {area:976}.",
	["Ride north-west up the road to {area:2253}."] = "Chevauchez au nord-ouest par la route jusqu'à {area:2253}.",
	["Ride back east past {area:2255} and south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Revenez à cheval vers l'est après {area:2255}, puis descendez la vallée au sud-est jusqu'à la caisse endommagée de {npc:10301}, dans la neige à {area:2245}, avec son chariot détruit juste à l'est.",
	["Ride north up the valley, past {area:2255}, to {area:2253}."] = "Chevauchez vers le nord en remontant la vallée, après {area:2255}, jusqu'à {area:2253}.",
	["{area:2577} (optional)"] = "{area:2577} (facultatif)",
	["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Faire {area:2577} en {zone:1444} plutôt que tuer des monstres vous y amène plus vite en groupe. Passez cette étape pour monter seul.",
	["{area:2577} fits levels 55 to 60; alone, the {area:2627} grind at the end of this guide gets you to 60."] = "{area:2577} convient du niveau 55 au niveau 60 ; seul, la chasse de {area:2627} à la fin de ce guide vous amène au niveau 60.",
	["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "La maison de {npc:11801} se dresse à {area:2361}, à l'est de {npc:11939}.",
	["Learn the flight path in {area:2361}."] = "Apprenez le point de vol à {area:2361}.",
	["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "Le vol se pose à {area:702}. {npc:7916} se tient un peu au nord-ouest du maître de vol.",
	["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, au sommet de {area:1658}",
	["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722} prend soixante étoffes de soie, soixante de tisse-mage et soixante {item:14047} : rendez ce que vous portez (ou achetez-en à l'hôtel des ventes), passez le reste.",
	["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "Prenez {area:2257} jusqu'à {zone:1455}. {npc:14724} et {npc:14723} prennent chacun soixante étoffes de laine, soixante de soie et soixante de tisse-mage, puis soixante {item:14047} : rendez ce que vous portez (ou achetez à l'hôtel des ventes), passez le reste.",
	["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "Le fantôme de {npc:10778} erre près de la ferme de {area:199}, à l'ouest d'Andorhal. Les goules jacassantes du champ portent l'autre moitié du charme : assemblez les deux moitiés.",
	["Cross the river east of {npc:1855}'s hut into {area:2627}: {npc:11140} stands by Augustus' ruined hut."] = "Traversez la rivière à l'est de la hutte de {npc:1855} jusqu'à {area:2627} : {npc:11140} se tient près de la hutte en ruine d'Augustus.",
	["{area:2057} (optional)"] = "{area:2057} (facultatif)",
	["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} convient du niveau 58 au niveau 60 ; {quest:5505} se rend à {area:3197}, ci-dessous.",
	["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "Traversez la rivière à l'est de {npc:1855} jusqu'à {area:2627}. Les esprits de Terrordale hantent les bois. Ou, en groupe, faites plutôt le donjon de {area:2057} ou celui de {area:2279}.",
	["Ride back south-west to {area:3197}."] = "Revenez à cheval au sud-ouest jusqu'à {area:3197}.",
	["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Vous commencez devant {area:77}, la salle de pierre au nord de la vallée. {npc:658} attend devant la porte.",
	["Ragged Young Wolves roam the snow just south of {area:77}."] = "De jeunes loups dépenaillés parcourent la neige juste au sud de {area:77}.",
	["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Des troggs et des troggs costauds Mâchoire-de-roche creusent partout au fond de la vallée, au sud de {area:77}.",
	["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738} : chronométrée, cinq minutes pour rejoindre {npc:836} à {area:77}",
	["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "La Bière du matin brûlante dure cinq minutes : allez directement au nord auprès de {npc:836}, à l'intérieur de {area:77}.",
	["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} se tient à côté de {npc:8416}, à la porte de {area:77}. Le camp de Gozwin est dans les collines juste au nord-ouest ; {npc:269075} rôde autour.",
	["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "Retour auprès de {npc:257446} à {area:77}. Il vous donne {item:6635} : prenez le chemin marqué de gravats qui monte vers l'ouest depuis le sud de la vallée jusqu'à la pierre de l'esprit sur la crête, buvez le Sapta à côté et parlez à {npc:5891}, puis rapportez son {item:6656} à Teo.",
	["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} garde le tunnel qui sort de la vallée, à l'est de {area:77} ; {npc:6782} se tient à côté de lui à l'entrée.",
	["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Suivez la route au nord-est depuis {area:131} jusqu'au dépôt sous la route de {zone:1455}.",
	["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Les cargaisons de Flintfire se trouvent au sol de la grotte, et {npc:278166} a disparu quelque part à l'intérieur.\nAttention : les wendigos sont serrés dans la grotte, les combats en attirent donc facilement plusieurs ; les attirer un par un avec des attaques à distance depuis l'extérieur l'évite.",
	["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Des sangliers des rochers et de jeunes ours noirs parcourent les champs, du camp de Rumbleshot au nord-est jusqu'à {area:131} et au dépôt : tuez-les sur le chemin du retour.",
	["{npc:1252} stands by Eric's campfire in front of the {area:2102}; {npc:1241} is in the cellar west of it."] = "{npc:1252} se tient près du feu de camp d'Eric, devant {area:2102} ; {npc:1241} est dans la cave à l'ouest.",
	["{area:131} and the depot"] = "{area:131} et le dépôt",
	["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Les pilotes se tiennent au dépôt ; {npc:1269} est sur la route du retour vers l'ouest, au nord de {area:131}.",
	["{npc:1377}, beside him"] = "{npc:1377}, à côté de lui",
	["{npc:1269}, on the way back; below ground"] = "{npc:1269}, sur le chemin du retour ; sous terre",
	["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Les gnomes lépreux autour de Brewnall et de la route de {area:133} portent les rouages et les engrenages. Des ours Griffe-de-glace, de vieux sangliers des rochers et des léopards des neiges parcourent les collines autour du lac.",
	["Follow the road east past the depot to {area:138}."] = "Suivez la route vers l'est après le dépôt jusqu'à {area:138}.",
	["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Chaque quête de Grif Cœur-sauvage vous remet {item:15908} : utilisez-le sur la bête qu'il nomme, puis rapportez-lui la baguette à la forge de {area:131}. De grands sangliers des rochers, des léopards des neiges et des ours Griffe-de-glace parcourent tous les champs juste au sud et à l'est de {area:131}.",
	["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen campe sur la crête qui domine {area:134} par l'ouest. Parlez-lui pour sa vision lointaine.",
	["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Les cogne-crânes, les claque-os et les embusqués Mâchoire-de-roche se partagent la carrière et les pentes au nord ; les embusqués lâchent {item:268548}.",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Les embusqués Mâchoire-de-roche près de {area:212}, au nord de la carrière, et les brise-échine Mâchoire-de-roche plus à l'est lâchent {quest:95214}. Des espions Sombrefer rôdent sur la rive du lac à l'est de la carrière ; l'un d'eux lâche {item:274268}.",
	["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} attend dans une grotte au-dessus de la ferme, au nord-ouest de {area:806} ; le chemin qui y monte part de derrière la ferme.",
	["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Des voyants Brise-pierre (niveau 13) se tiennent parmi les troggs au sud de {area:923}, au sud de {npc:257808} ; des géomanciens rats des tunnels (niveau 12) travaillent à {area:149}, au nord du loch. Les troggs vont en groupes et certains lancent des projectiles à distance : attirez-les un par un.",
	["East through the South Gate tunnel into {area:38}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "Vers l'est par le tunnel de la porte Sud jusqu'à {area:38}. {npc:1089} et {npc:1092} se tiennent au poste nain juste après.",
	["Stonesplinter troggs"] = "Troggs Brise-pierre",
	["North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth."] = "Au nord du poste, à l'ouest de la route : les troggs et les éclaireurs Brise-pierre campent dans les collines. Les deux lâchent les dents de pierre de trogg.",
	["Back to the tunnel post"] = "Retour au poste du tunnel",
	["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "Au nord par la route jusqu'à {area:144}. {npc:1340} arpente la route qui traverse la ville, {npc:1963} se tient devant {area:2101}, {npc:1681} à l'est de la ville ; {npc:1572} s'occupe des griffons.",
	["{npc:1572}: for {npc:4256} in {zone:1455}"] = "{npc:1572} : pour {npc:4256} à {zone:1455}",
	["The west hills and the {area:925}"] = "Les collines de l'ouest et {area:925}",
	["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "Vers le nord par les collines à l'ouest de la route jusqu'à {npc:1343} à {area:925}. Les kobolds rats des tunnels creusent dans les collines en chemin ; de vieux ours noirs, des sangliers des montagnes et des rôdeurs des forêts parcourent le même terrain.",
	["{item:3110}: Tunnel Rat kobolds"] = "{item:3110} : kobolds rats des tunnels",
	["{item:3172}: Mountain Boars"] = "{item:3172} : sangliers des montagnes",
	["{item:3173}: Elder Black Bears"] = "{item:3173} : vieux ours noirs",
	["{item:3174}: Forest Lurkers"] = "{item:3174} : rôdeurs des forêts",
	["{npc:5413} in {zone:1453} takes it"] = "{npc:5413}, à {zone:1453}, la prend",
	["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats."] = "Vers l'est le long des collines jusqu'à la mine au nord du loch : les caisses de la Ligue des mineurs sont dans ses galeries, parmi d'autres rats des tunnels.",
	["{item:2640}, from the crates"] = "{item:2640}, dans les caisses",
	["South down the road to {area:144}, finishing the ears, meat and ichor on the way."] = "Au sud par la route jusqu'à {area:144}, en finissant les oreilles, la viande et l'ichor en chemin.",
	["The gryphons land in the {object:32372}: {npc:4256} works at its north end, and {npc:1573} keeps the gryphons where you landed."] = "Les griffons se posent dans {object:32372} : {npc:4256} travaille à son extrémité nord, et {npc:1573} s'occupe des griffons là où vous avez atterri.",
	["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "Vers l'est depuis {object:32372} jusqu'à {object:171524} : {object:660964} se trouvent près de sa boîte aux lettres. D'ici, le guide fait une fois le tour de la ville : au nord vers {object:32383}, à l'ouest vers {object:32362}, au sud par la Place commune jusqu'à {object:171709}, à l'est par {object:32359}, puis retour à {object:171524} pour le tram.",
	["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "Au nord de {object:32372} : {npc:258098}, le maître chaman, se tient au sud de {object:32383}, les maîtres voleurs et démonistes et {npc:6120} juste au nord de lui.",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Vers l'ouest depuis {object:32383} jusqu'à {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, {npc:6179} et {npc:6178} à l'étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "Les maîtres paladins, prêtres et mages sont dans {object:32386}, dans {object:32362}.",
	["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "Au sud par la Place commune : {npc:1274} se tient dans {object:171709} avec le roi Magni.",
	["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "Vers l'est jusqu'à {object:32359} : les maîtres guerriers et {npc:11865} dans {object:32390}, les maîtres chasseurs à côté.",
	["{npc:5505} in {zone:1453}; {area:1} has no druid trainer"] = "{npc:5505} à {zone:1453} ; {area:1} n'a pas de maître druide",
	["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "Vers l'est pour revenir dans {object:171524} : {area:2257} part de son extrémité est. Prenez-le jusqu'à {zone:1453}.",
	["On the {zone:1455} platform of the {area:2257}, {npc:12997} asks for help with the rats: use his {item:17117} on the Deeprun Rats around the platform, hand them in, then take his letter to his brother {npc:13018} at the {zone:1453} end."] = "Sur le quai de {zone:1455} de {area:2257}, {npc:12997} demande de l'aide contre les rats : utilisez son {item:17117} sur les rats des profondeurs autour du quai, rendez-les-lui, puis portez sa lettre à son frère {npc:13018}, au terminus de {zone:1453}.",
	["{npc:12997}, on the {zone:1455} platform"] = "{npc:12997}, sur le quai de {zone:1455}",
	["{npc:13016}: use the {item:17117}"] = "{npc:13016} : utilisez {item:17117}",
	["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "Prenez le tram jusqu'à {zone:1453} : {npc:13018} attend sur le quai de {zone:1453}. {npc:5413} se tient dans {object:28027}, juste à la sortie du tram.",
	["{npc:13018}, on the {zone:1453} platform"] = "{npc:13018}, sur le quai de {zone:1453}",
	["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "Depuis {object:28027}, au sud-ouest jusqu'à {object:2098} : la boussole de {npc:1646} est dans son ancienne maison en {zone:1436}, en chemin. Le maître de vol et {object:2096} sont au sud de la place.",
	["From {zone:1436}, walk to {zone:1453}; the tram from {zone:1455} arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "Depuis {zone:1436}, marchez jusqu'à {zone:1453} ; le tram de {zone:1455} arrive dans {object:28027}. {npc:5480} entraîne les guerriers dans {object:2100} ; {npc:6089} et {npc:6090} se tiennent ensemble près de {object:2152}. {npc:6090} vous affronte pour sa chope. Si {npc:5480} ne propose pas {quest:1638}, allez directement voir {npc:6089} : il donne {quest:1639} sans elle.",
	["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Quittez {zone:1453} par la grande porte, allez au sud jusqu'à {area:87}, puis à l'est par la route jusqu'à {area:62}. {npc:881} (niveau 9) se tient près de sa ferme.",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:87} and east Elwynn are next, then {zone:1436}."] = "Retour auprès de {npc:6122}. Utilisez {item:6928} au cercle d'invocation dans la cave de {object:2164} et vainquez le marcheur du Vide qu'il appelle. {area:87} et l'est d'Elwynn viennent ensuite, puis {zone:1436}.",
	["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "Quittez {zone:1453} par la grande porte et suivez la route vers le sud jusqu'à {area:87} : l'est d'Elwynn passe avant {zone:1436}.",
	["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, le maître mage, à l'intérieur de {area:77}",
	["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Vers l'ouest depuis {object:32383} jusqu'à {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, Tiza et Muiredon à l'étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Mages : {npc:198}, le maître mage, se tient à l'étage de l'abbaye : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} se tient derrière l'abbaye, près des écuries. {npc:198}, le maître mage, se tient à l'étage de l'abbaye : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["{npc:823}, at the Abbey steps"] = "{npc:823}, sur les marches de l'abbaye",
	["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "son pisteur de kobolds montre les kobolds à cliquer sur la route de {area:87}",
	["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Suivez la route vers le sud en sortant de la vallée jusqu'à {area:87}. {npc:240} se tient devant la forge du côté ouest de la route, {npc:241} au bord de la route au sud, et {npc:295} et {npc:253} dans l'auberge de la Fierté du lion, de l'autre côté de la route.",
	["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399} campe au nord-est de l'auberge ; {npc:6306}, {npc:383} et {npc:1651} se tiennent sur la rive de {area:18}, à l'est de la ville.",
	["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} cuisine dans la cuisine de l'auberge. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Suivez la route vers le sud en sortant de {area:87} jusqu'à {area:64}. {npc:251} attend près de la maison.",
	["Billy plays in the {area:64}, east of the mine."] = "Billy joue dans {area:64}, à l'est de la mine.",
	["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} est à l'intérieur de {area:57}, pas sur la colline au-dessus : entrez par l'ouverture et restez à gauche jusqu'au fond de la mine ; ne prenez pas l'escalier. Les bandits défias autour des vignes lâchent de temps en temps {item:1972} : faites un clic droit dessus.",
	["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} à {zone:1453} ; {area:87} n'a pas de maître druide",
	["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Sortez de {area:87} vers l'est le long de la rive du lac. {npc:383} se tient sur la rive au nord-est de la ville.",
	["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Les murlocs de la rive est lâchent le varech. Dépeceurs : des loups gris des forêts parcourent les bois entre le lac et {area:91} ; les rôdeurs plus à l'est donnent aussi des peaux.",
	["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group or once you're level 10; otherwise leave him: it's optional."] = "{item:247813}, la hache et la boîte à outils se trouvent dans la rivière au sud du pont. {npc:330}, une grosse laie, fouille {area:62} à l'ouest de la rivière avec ses {npc:390} : éloignez d'abord les marcassins. Tuez les rôdeurs et les jeunes ours des forêts en chemin. Attention : {npc:248278} est un élite de niveau 11 sur la rive des murlocs. N'allez chercher sa tête qu'en groupe ou une fois niveau 10 ; sinon laissez-le : c'est facultatif.",
	["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Suivez la route vers l'ouest pour revenir à {area:87} ; {npc:6306} se tient sur la rive du lac avant la ville. {npc:377} (prêtres), {npc:328} (mages) et {npc:917} (voleurs) se tiennent à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["{npc:514}, at the smithy: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, à la forge : {npc:1416}, à {zone:1453}, la prend (02-westfall)",
	["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377} : {npc:376}, à {zone:1453}, la prend",
	["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Suivez la route vers le nord depuis {area:87} jusqu'à {zone:1453}. {npc:5497} se tient dans le Sanctum du sorcier, la tour de {object:2101} ; elle vous donne une fiole pour la cascade de {quest:1861}.",
	["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Suivez la route vers le nord depuis {area:87} jusqu'à {zone:1453}. {npc:6122} attend dans la cave de {object:2164}, dans {object:2101}.",
	["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Ressortez par {area:87} et suivez la route vers l'est jusqu'à {area:62}. {npc:881} (niveau 9) se tient près de sa ferme.",
	["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} se tient avec les maîtres de {area:87}. Chacune de ses quêtes vous remet {item:15908} : utilisez-le sur la bête qu'elle nomme, puis rapportez-lui la baguette. Des sangliers Peau-de-roche et de jeunes ours des forêts parcourent les collines au sud de {area:64}, des loups gris des forêts les bois à l'est de {area:18}.",
	["South down the road to the {area:64}."] = "Au sud par la route jusqu'à {area:64}.",
	["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "{quest:91736} se dresse au nord de {area:120}. Cliquez dessus avec quatre pommes rouges brillantes dans vos sacs : il les prend et vous donne aussitôt {item:247824} (la quête n'apparaît jamais dans votre journal). Gardez l'eau-de-vie de pomme pour {npc:955} : ne la buvez pas.",
	["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Suivez la route vers le sud jusqu'à {area:120}, sur le chemin de {zone:1436}. {npc:963} se tient devant la caserne ; {npc:955} se tient à l'intérieur. Il ne propose {quest:91738} que tant que vous portez {item:247824} : parlez-lui et vous passez directement au rendu.",
	["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963} : pour {npc:234} à {area:108}",
	["You start at the foot of {area:256}, the great tree of {area:188}."] = "Vous commencez au pied de {area:256}, le grand arbre de {area:188}.",
	["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "De jeunes sabres-de-nuit et de jeunes sangliers chardon parcourent les alentours de {area:256}. Les grells portent {item:3297} dans les bois à l'ouest de l'arbre, là où se dressent les totems Pin-tordu.",
	["Back at {area:256}"] = "De retour à {area:256}",
	["North to {area:257}"] = "Au nord jusqu'à {area:257}",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Des sabres-de-nuit galeux et des sangliers chardon parcourent le nord de {area:256}, sur le chemin de la grotte. {npc:1994} est assis tout au fond. {npc:8584} attend dans les arbres à l'ouest de l'entrée de la grotte.",
	["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Les maîtres se tiennent à l'intérieur de {area:256}, le long de la rampe qui monte en spirale dans l'arbre : {npc:3593} et {npc:3594} au premier niveau, {npc:3595} au-dessus, {npc:3596} et {npc:3597} tout en haut. La flèche ne distingue pas les niveaux.",
	["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, le maître druide de {area:256}",
	["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} se trouvent au fond de {area:257} : prenez le chemin central, puis à gauche à l'embranchement, jusqu'à la haute corniche. Les champignons jacinthe tombent sur les grells, les lys pétale-de-lune poussent près des mares au nord de {area:256}.",
	["Grells"] = "Grells",
	["Back to the top of {area:256}. The {object:654846} lies beside him."] = "Retour en haut de {area:256}. {object:654846} se trouve à côté de lui.",
	["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Quittez {area:188} par le chemin au sud-est de {area:256} : {npc:6780} se tient à côté, là où il descend vers la route de {area:186}.",
	["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Suivez la route au sud-ouest en sortant de {area:188}. {npc:2150} est assis à côté, juste à l'est de {area:186}.",
	["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150} est assis au bord de la route, juste à l'est de {area:186}, entre {area:186} et {area:260}.",
	["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} se tient à l'étage d'une maison du village, à l'est du puits de lune : montez par l'intérieur, la flèche ne distingue pas les étages. {object:126158} est dans la maison sur la colline, à l'extrémité est du village.",
	["{area:258}'s mouth"] = "L'entrée de {area:258}",
	["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Des embusqués Pin-tordu se cachent le long de la route à l'ouest de {area:258}.",
	["West along the road to the city gate: Shayla stands beside it. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "Vers l'ouest par la route jusqu'à la porte de la ville : Shayla se tient à côté. Chaque furbolg Pin-tordu lâche des crocs : les embusqués de cette route, ceux du tertre et ceux de {area:261} comptent tous.",
	["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Entrez dans la ville par la porte. {quest:922} est juste au sud de {area:1658}, au nord, {npc:7316} à l'ouest, {npc:7313} et {npc:8396} dans le temple de la Lune, au sud. En ressortant, utilisez {item:279378} de Dalia à la banque et à la porte de la ville ; les deux autres chouettes attendent votre dernière visite.",
	["{npc:7313}, in the Temple of the Moon"] = "{npc:7313}, dans le temple de la Lune",
	["{npc:8396}, beside her"] = "{npc:8396}, à côté d'elle",
	["{item:279378}: the bank, on the way out"] = "{item:279378} : la banque, en sortant",
	["the city gate"] = "la porte de la ville",
	["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs."] = "Le tertre est au sud de la route. {npc:275744} y est retenu, {npc:7317} dort dans ses profondeurs, et les quatre coffres à reliques se trouvent dans les salles du bas. Ses furbolgs lâchent les crocs de Shayla.",
	["{item:5220}: any Gnarlpine furbolg"] = "{item:5220} : n'importe quel furbolg Pin-tordu",
	["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escortez {npc:275744} hors du tertre ; {npc:2081}, à {area:186}, prend le rapport.",
	["{area:736}, outside the barrow"] = "{area:736}, devant le tertre",
	["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs."] = "Au sud des bassins. {object:6751} pousse près du repaire ; les furbolgs alentour lâchent le reste des crocs.",
	["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "La route de l'ouest vers {area:264} passe par {area:186} : remettez le joyau à {npc:3567} en chemin.",
	["West along the road from {area:186}: Shayla still stands beside it, before the turn north to the glade."] = "Vers l'ouest par la route depuis {area:186} : Shayla se tient toujours à côté, avant l'embranchement nord vers la clairière.",
	["North from the road the path to the glade crosses the {area:265}: the timberlings along it drop the Mossy Tumors."] = "Au nord de la route, le chemin de la clairière traverse {area:265} : les sylvains qui le bordent lâchent les tumeurs moussues.",
	["{item:5170}: timberlings"] = "{item:5170} : sylvains",
	["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Les harpies Plumesang nichent sur les pentes à l'ouest et au nord de la clairière. {quest:938}, un félin à dents de sabre blessé, est couchée près du mur ouest de la clairière, au milieu d'elles : ramenez-la à la sentinelle Arynia au puits de lune avant la fin du temps imparti.\nAttention : les harpies sont serrées, d'autres rejoignent donc souvent le combat. Des lanceuses de sorts sont mêlées aux autres.",
	["{quest:938}, by the west wall"] = "{quest:938}, près du mur ouest",
	["Lead {quest:938} to the moonwell"] = "Conduisez {quest:938} jusqu'au puits de lune",
	["The {object:6752} grows at the glade's north end, on the way: then north of {npc:272046}, along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752} pousse au nord de la clairière, en chemin : puis au nord de {npc:272046}, le long du bord nord de l'île près de {area:266}, rôde {npc:7319}, une araignée de niveau 12.",
	["North-east from Ursal's den, back to {area:186}."] = "Au nord-est de la tanière d'Ursal, retour à {area:186}.",
	["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Chaque quête de Dazalar vous remet {item:15908} : utilisez-le sur la bête qu'il nomme, puis rapportez-lui la baguette à {area:186}. Des rôdeurs Bois-tisse rampent autour du village, des traqueurs sabres-de-nuit et des hurleurs strigides parcourent les bois au sud.",
	["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Reprenez la route au nord-ouest depuis {area:186} ; elle est toujours couchée à côté, sur le chemin de {zone:1457}.",
	["{npc:4241}, on the {area:1659} just inside the city"] = "{npc:4241}, sur {area:1659}, juste à l'entrée de la ville",
	["Follow the road west into {zone:1457} and use the {item:279378} at the inn on the {area:1659} and at the tunnel mouth below {area:3425} for the last two owls. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the Moon at the south end."] = "Suivez la route vers l'ouest jusqu'à {zone:1457} et utilisez {item:279378} à l'auberge de {area:1659} et à l'entrée du tunnel sous {area:3425} pour les deux dernières chouettes. {npc:4241} se tient sur {area:1659}, juste à l'entrée de la ville. {npc:3516} est à {area:1658}, au nord de la ville, {quest:922} juste au sud ; {npc:4092}, {npc:7999}, {npc:7313} et {npc:8396} sont dans le temple de la Lune, au sud.",
	["{item:279378}: the inn on the {area:1659}"] = "{item:279378} : l'auberge de {area:1659}",
	["the tunnel mouth below {area:3425}, on the way south"] = "l'entrée du tunnel sous {area:3425}, sur le chemin du sud",
	["{quest:2520}, standing in the temple's central fountain"] = "{quest:2520}, debout dans la fontaine centrale du temple",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Revolez vers {area:702} depuis {npc:3841}, remettez {item:16263} à {npc:10118} sur le quai, puis revolez vers {area:442}.",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; {quest:5929} se trouve dans les bois au nord-ouest. Ensuite, {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}, sans point de vol. {npc:11802} se tient à l'étage de son bâtiment : montez par l'intérieur, la flèche ne distingue pas les étages.",
	["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Redescendez à {area:702} et volez jusqu'à {area:442}. {object:177525} se dresse dans les collines juste à l'est du village : utilisez-y {item:15208}, vainquez Griffe-de-lune et parlez à {npc:12144}.",
	["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Volez encore une fois jusqu'à {area:702} et prenez le portail qui monte vers {npc:4217}, puis revolez vers {area:442}.",
	["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. {npc:3666} stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Le bateau accoste à l'ouest du village. Le maître de vol se tient sur la colline au sud de l'auberge ; les donneurs de quêtes sont répartis le long de la rue principale. {npc:3666} se tient à l'étage de l'auberge : prenez l'escalier intérieur, la flèche ne distingue pas les étages.",
	["Rabid Thistle Bears roam the hills south of {area:442}: use {item:7586} on one to capture it. Then walk up to the furbolg camp just east of them: nothing to kill yet."] = "Des ours chardon enragés parcourent les collines au sud de {area:442} : utilisez {item:7586} sur l'un d'eux pour le capturer. Montez ensuite au camp furbolg juste à l'est : rien à tuer pour l'instant.",
	["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Suivez la côte vers le sud après {area:447} : un {quest:4728} se trouve sur la rive à l'ouest du Bosquet, un autre plus au sud, près de {area:450}. Trois autres restes se trouvent plus au sud-ouest, parmi les oracles et les chasseurs des marées Brume-grise (18-20) : le guide les garde pour la dernière boucle, quand vous serez plus proche de leur niveau.",
	["Back north to {area:447}: the flame burns in the south of the ruins."] = "Retour au nord jusqu'à {area:447} : la flamme brûle au sud des ruines.",
	["North along the hills to {npc:3650}, then west down to {area:442}."] = "Au nord le long des collines jusqu'à {npc:3650}, puis à l'ouest en descendant vers {area:442}.",
	["Off the boat, {npc:268511} stands on the harbor: his shipment goes to {npc:483}' cheese shop in the {object:2096}, beside the flight master."] = "En descendant du bateau, {npc:268511} se tient sur le port : sa livraison va à la fromagerie de {npc:483} dans {object:2096}, à côté du maître de vol.",
	["{npc:483}, in her cheese shop"] = "{npc:483}, dans sa fromagerie",
	["Up the stairs in her shop: leave the shipment at the {object:460004}"] = "Montez l'escalier de sa boutique : déposez la livraison à {object:460004}",
	["{npc:1646} stands in {object:2098}, west of the {object:2096}: his compass is in his old house in {zone:1436}, on the way."] = "{npc:1646} se tient dans {object:2098}, à l'ouest de {object:2096} : sa boussole est dans son ancienne maison en {zone:1436}, en chemin.",
	["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Vous vous réveillez à {area:16622}. {npc:251362} se tient à côté de vous ; {npc:251361} est à quelques pas à l'ouest, {npc:251368} au bord sud du bosquet.",
	["{area:16622} turn-ins"] = "Rendus de {area:16622}",
	["The Ursera Scavengers den west of the grove, with {npc:251115}, the matriarch, at the back of the den; {npc:250926} prowl the woods between the den and the grove."] = "Les charognards Ursera ont leur tanière à l'ouest du bosquet, avec {npc:251115}, la matriarche, au fond ; des {npc:250926} rôdent dans les bois entre la tanière et le bosquet.",
	["Back east out of the den to the grove."] = "Ressortez de la tanière vers l'est jusqu'au bosquet.",
	["{npc:252095} camps south-west of the grove, south of the Ursera den, on the way south to Shen'dar. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} campe au sud-ouest du bosquet, au sud de la tanière Ursera, sur le chemin du sud vers Shen'dar. Les voyous Al'Aketh tiennent le camp au sud-ouest d'elle ; {npc:256935} se tient en son milieu.\nAttention : {npc:256935} lance des horions ; éloignez-le des autres cultistes avant de combattre pour qu'ils ne le rejoignent pas.",
	["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Suivez la route vers le sud jusqu'à {area:16624}. {npc:263664} campe près du feu à l'ouest du village ; {npc:251523} et {npc:251903} se tiennent en son milieu.",
	["Highlands Bandits"] = "Bandits des hautes terres",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar, on the way back to the village."] = "Partez au nord-ouest jusqu'aux nids d'hippogriffes sur les falaises ouest. {item:263493} se trouve autour des nids ; la matriarche patrouille parmi eux.\nLes voyants novices s'exercent dans la clairière à l'ouest de Shen'dar, sur le chemin du retour au village.",
	["On the road south-east to {area:16638}, {npc:273017} watches the {quest:98512} just north of him."] = "Sur la route au sud-est vers {area:16638}, {npc:273017} surveille {quest:98512}, juste au nord de lui.",
	["{area:16638}, the turncoat"] = "{area:16638}, le traître",
	["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} et {npc:252476} se tiennent au nord de {area:16638}, {npc:252475} et {npc:253204} au sud.",
	["Skyhoppers swarm the fields west of {area:16638}."] = "Des sauteurs du ciel grouillent dans les champs à l'ouest de {area:16638}.",
	["The road to {area:16638}"] = "La route de {area:16638}",
	["{area:16638} turn-ins"] = "Rendus de {area:16638}",
	["{npc:252359}, between the west gate and Valennia's house: {quest:94006}"] = "{npc:252359}, entre la porte ouest et la maison de Valennia : {quest:94006}",
	["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} tient la tour de guet au nord de {area:16638}. Le camp Al'Aketh est juste à l'ouest de la tour, ses soigneurs vers 65,68 et 65,65 ; {npc:252666} se tient à son extrémité nord. Les Al'Aketh de ce camp lâchent des charmes de pierre-vent.",
	["{npc:255853} waits by the falls just north of the watchtower. {npc:258443} prowls the {area:16623} south-west of the dead cultist, where you go after {area:16638}."] = "{npc:255853} attend près des chutes, juste au nord de la tour de guet. {npc:258443} rôde dans {area:16623}, au sud-ouest du cultiste mort, où vous allez après {area:16638}.",
	["North-west of Valanaar along the road, past {npc:273017}: the dead cultist lies just north of him."] = "Au nord-ouest de Valanaar par la route, après {npc:273017} : le cultiste mort gît juste au nord de lui.",
	["Head north into {area:16631}. {npc:257944} camps in its east."] = "Allez vers le nord jusqu'à {area:16631}. {npc:257944} campe dans sa partie est.",
	["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Frayez-vous un chemin vers le nord jusqu'à {area:16629}. Des gardiens, des appelle-esprits et des maîtres-lames tiennent l'approche ; {npc:253576} attend à la porte du sanctuaire, {npc:253590} dans le sanctuaire intérieur.",
	["{area:16638}, the fate of Zephras"] = "{area:16638}, le sort de Zephras",
	["The {object:617084} sets you down beside {npc:252475} at the south end of the town. {npc:252476} is at the north end, {npc:259012} a few steps north-west of her."] = "{object:617084} vous dépose à côté de {npc:252475}, au sud de la ville. {npc:252476} est au nord, {npc:259012} à quelques pas au nord-ouest d'elle.",
	["{npc:252475} sends you on to {area:279}. Take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475} vous envoie à {area:279}. Prenez le tranche-ciel à la tour du quai juste au sud de {area:16638} : il se pose près du camp du Kirin Tor à l'ouest de {area:279}, à côté de {npc:259084} et du portail des Célestes.",
	["For {npc:234} at {area:108}"] = "Pour {npc:234} à {area:108}",
	["{npc:1646} stands in {object:2098}, on the way from the Keep to the main gate: his compass is in his old house in {area:40}, on the way."] = "{npc:1646} se tient dans {object:2098}, sur le chemin du donjon à la grande porte : sa boussole est dans son ancienne maison à {area:40}, en chemin.",
	["Follow the road from Elwynn into {area:40}: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any {object:2724} you pass on the loop: the rest are gathered in the fields here on the way back."] = "Suivez la route depuis Elwynn jusqu'à {area:40} : les Furlbrow sont assis près de leur ferme incendiée, la première sur la route. Ramassez de l'avoine sur chaque {object:2724} que vous croisez pendant la boucle : le reste se ramasse dans les champs d'ici au retour.",
	["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine.\nWest of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "Au nord de la ferme des Molsen. Des trappeurs et des contrebandiers défias campent devant la mine. {object:290} se dresse près de la maison en ruine à l'est de la mine.\nÀ l'ouest de chez les Saldean. Des guetteurs et des golems des moissons travaillent les champs ; ils lâchent les isoressorts, les gyrostabilisateurs, {item:732} et parfois {item:255155}. {npc:573}, un rare de niveau 20, se promène ici : laissez-le tranquille. Continuez à tuer des broche-tripes et des déchireurs à chaque étape de cette boucle.",
	["Riverpaw Gnolls and Scouts (level 11-13) roam the hills south of the coast, from above {area:111} east to the {area:916}. The gnolls further south and west are 13-19: stay in the north hills.\nMurloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.\nCareful: Two Defias stand guard inside the house, one of them the level 15 named {npc:502}. They are linked, so attacking either one brings both."] = "Des gnolls et des éclaireurs Rivepatte (niveau 11-13) parcourent les collines au sud de la côte, d'au-dessus de {area:111} jusqu'à {area:916} à l'est. Les gnolls plus au sud et à l'ouest sont de niveau 13-19 : restez dans les collines du nord.\nDes coureurs de la côte et des pillards murlocs bordent la plage au nord de la mine. Ils fuient quand leur vie est basse : attirez-les un par un.\nAttention : les gnolls proches les uns des autres ont tendance à rejoindre le combat en groupe. Il est plus sûr de les attirer un par un.\nAttention : deux Défias montent la garde dans la maison, dont {npc:502}, un nommé de niveau 15. Ils sont liés : attaquer l'un attire les deux.",
	["Sacks of Oats in the fields around the farm"] = "Sacs d'avoine dans les champs autour de la ferme",
	["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}.\nCareful: The {area:113} cave holds many Defias packed together, so it is easy to pull several at once there."] = "Des pilleurs et des détrousseurs défias tiennent les fermes à l'ouest de {area:108}, entre la route côtière et {area:20}.\nAttention : la grotte de {area:113} contient beaucoup de Défias serrés les uns contre les autres, il est facile d'en attirer plusieurs à la fois.",
	["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level."] = "Des rôdeurs et des cogneurs défias arpentent {area:20} ; des bandits de grand chemin (niveau 17) patrouillent par deux dans les collines au sud et à l'est : séparez-les. L'entrée de {area:1581}, dans la forge, est un donjon de groupe.\nAttention : les camps des collines abritent des groupes mêlés de Défias, il est facile d'en attirer plusieurs à la fois si votre niveau est bas.",
	["{npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in the {object:2096} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "{npc:6171} et {npc:6173} sont dans la cathédrale de la Lumière ; {npc:6174} se tient dans {object:2096} et demande dix {item:2589} (les humanoïdes en lâchent ; l'hôtel des ventes en vend).",
	["Right-click the {item:6775} he gives you"] = "Clic droit sur {item:6775} qu'il vous donne",
	["{npc:6172}, by {area:86} in Elwynn, on the road to Redridge"] = "{npc:6172}, près de {area:86} en Elwynn, sur la route de Les Carmines",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Tant que vous êtes ici : apprenez {spell:202} auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Tant que vous êtes ici : apprenez les épées auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; une épée en main droite fait monter un voleur régulièrement.",
	["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11867} ({object:2096}, 10 pièces d'argent) ; un bâton porte plus de caractéristiques de sorts qu'une arme à une main pendant la montée en niveau.",
	["{item:12289}, on the beach west of the docks; underwater"] = "{item:12289}, sur la plage à l'ouest des quais ; sous l'eau",
	["the Rabid Thistle Bears nearest {npc:3701}"] = "les ours chardon enragés les plus proches de {npc:3701}",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361}. Des babioles du sanctuaire se trouvent dans les récipients au sol de {area:656}, sous {area:2361} : apportez-en une à {area:2362} au nord-ouest, utilisez-la là-bas et parlez à {npc:11799}. Puis revenez en vol à {area:442} depuis {area:2361}.",
	["{item:12347}: fill the {item:12346} at the {object:174795}"] = "{item:12347} : remplissez {item:12346} à {object:174795}",
	["Thresher Eyes; underwater"] = "Yeux de batteur ; sous l'eau",
	["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs."] = "Deux épaves reposent au fond de la baie au nord de {area:442} ; chacune contient un coffret. Des rampants des récifs et des rampants des marées incrustés bordent ce rivage.\nAttention : les murlocs à l'intérieur des épaves sont serrés et rapides. Ils traversent souvent les parois et les trous de la coque, vous en attirerez donc généralement d'autres.",
	["Scaber Stalks; below ground"] = "Tiges de scabre ; sous terre",
	["The northern Blackwood camp"] = "Le camp nord des Bois-noirs",
	["The furbolg camp south of the {area:456} keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the {item:12347} in your bags (the {item:12346} is filled at the {object:174795}), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the {item:12355} lies in his Demon Bag."] = "Le camp furbolg au sud de {area:456} garde ses réserves de noix, de fruits et de grain près des feux de camp. Avec un échantillon de chaque et {item:12347} dans vos sacs ({item:12346} se remplit à {object:174795}), utilisez le bol près du feu le plus proche de la rivière : il invoque Xabraxxis, le corrupteur satyre, et {item:12355} se trouve dans son sac démoniaque.",
	["By the bonfire closest to the river: summons Xabraxxis"] = "Près du feu le plus proche de la rivière : invoque Xabraxxis",
	["Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time."] = "Attention : si vous attaquez un ourson, les autres et souvent la mère rejoignent le combat ; attendez-vous à en affronter plusieurs à la fois.",
	["{quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "{quest:948} est l'ancien du Bosquet ; {npc:270269} et {npc:11218} dorment à côté de lui.",
	["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."] = "{area:450} se trouve sur la côte au sud de la plage de {npc:10323}. Protégez le prospecteur pendant qu'il cherche le fossile.\nAttention : des embusqués surgissent quand il passe à certains endroits : un éclaireur sort de sous la rampe de planches, et d'autres sortent quand il fouille la tente.",
	["Level 18.47"] = "Niveau 18,47",
	["Top up here to level 18.47 before the hand-ins at {quest:952}: they take you to level 19."] = "Montez ici jusqu'au niveau 18,47 avant les rendus de {quest:952} : ils vous amènent au niveau 19.",
	["Level 20"] = "Niveau 20",
	["Top up here to level 20 before the hand-ins at {zone:1453}: they take you to level 21."] = "Montez ici jusqu'au niveau 20 avant les rendus à {zone:1453} : ils vous amènent au niveau 21.",
	["Back to {npc:11802} in {area:2361}, then {npc:11800} there flies Druids straight to {area:702}."] = "Retour auprès de {npc:11802} à {area:2361}, puis {npc:11800}, sur place, emmène les druides directement à {area:702}.",
	["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {area:12}."] = "Le bateau de {area:442} accoste à {area:17203}. Montez en ville pour l'entraînement et {npc:1646}, puis sortez par la grande porte et suivez la route vers l'est à travers {area:12}.",
	["Only once {quest:97914} is handed in: for {npc:3649}, back in {area:442} (06-ashenvale)"] = "Seulement une fois {quest:97914} rendue : pour {npc:3649}, de retour à {area:442} (06-ashenvale)",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez les armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn Polearms from {npc:11867} ({object:2096}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les armes d'hast auprès de {npc:11867} ({object:2096}, 1 pièce d'or) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["Fly to {area:108} and head north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then head east along the road through Elwynn to Redridge."] = "Volez jusqu'à {area:108} et partez au nord-ouest vers la côte : {object:177790} repose au fond de la mer au large du rivage. Puis prenez la route vers l'est à travers Elwynn jusqu'aux Carmines.",
	["On the road east, past the {area:91}, head north from the bridge to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Sur la route vers l'est, après {area:91}, partez au nord depuis le pont jusqu'à {area:86}. {npc:6172} est étendu au sud du lac : utilisez {item:6866} sur lui. Les sorciers renégats défias autour de lui portent {item:6846}.",
	["Use the {item:6866} on {npc:6172}"] = "Utilisez {item:6866} sur {npc:6172}",
	["{item:6846}: Defias Rogue Wizards"] = "{item:6846} : sorciers renégats défias",
	["{npc:266}, by the docks; upstairs"] = "{npc:266}, près des quais ; à l'étage",
	["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Redridge Brutes, for the Iron Pikes and Rivets, hold the hills further north; Dire Condors and Great Goretusks roam the hills east of them."] = "Des bâtards des Carmines et d'autres gnolls tiennent les collines à l'est de {area:1002}, au nord de la route ; des batteurs des Carmines rôdent parmi eux, des braconniers campent au sud de la route. Les brutes des Carmines, pour les piques et les rivets en fer, tiennent les collines plus au nord ; des condors redoutables et de grands broche-tripes parcourent les collines à leur est.",
	["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345} (niveau 24) fouille le sol autour de l'enclos juste à l'ouest de {area:69}. Éloignez-le des autres sangliers et combattez-le avec toute votre vie.",
	["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin.\nGreater Tarantulas crawl on the slopes around the mill north-east of the lake."] = "Des mangeurs de chair et des mande-flots murlocs bordent la rive sud à l'est du pont. N'importe lequel peut porter {item:1467} ou une nageoire.\nDe grandes tarentules rampent sur les pentes autour du moulin au nord-est du lac.",
	["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite.\nCareful: Two gnoll guards stay with him and join the fight whenever he is attacked, even if he has wandered a short way off; other gnolls stand close by and wander through the area."] = "À l'est après le moulin, de l'autre côté de la rivière. Les gnolls Peau-d'ombre remplissent la vallée ; {npc:703} (26, bien au-dessus de vous) les mène à son extrémité nord : éliminez d'abord son escorte et combattez-le avec toute votre vie. Évitez {area:2099} au sud : ses orcs sont élites.\nAttention : deux gardes gnolls restent avec lui et rejoignent le combat dès qu'il est attaqué, même s'il s'est un peu éloigné ; d'autres gnolls se tiennent près de là et se promènent dans la zone.",
	["Blackrock camps"] = "Camps Rochenoire",
	["South down the valley's east side to the Blackrock camps east of {area:2099}. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite."] = "Descendez au sud par le côté est de la vallée jusqu'aux camps Rochenoire à l'est de {area:2099}. Des renégats, des grunts et des coursiers les remplissent ; restez à l'est du donjon, dont les orcs sont élites.",
	["Follow the road south from {area:1002} into {area:10}; {area:42} lies on the east side of the forest."] = "Suivez la route au sud depuis {area:1002} jusqu'à {area:10} ; {area:42} se trouve à l'est de la forêt.",
	["{npc:265}, in her house by the tavern; inside"] = "{npc:265}, dans sa maison près de la taverne ; à l'intérieur",
	["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too.\n{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "Pas de {item:4371} pour {quest:174} ? {npc:3133} en vend dans la maison à côté de celle de {npc:276}, en stock limité ; {npc:1448} à {area:150} en vend aussi.\nLa maison de {npc:276} se trouve à l'extrémité est du village. {npc:3133} vend des fournitures d'ingénierie dans la maison voisine.",
	["{npc:633}, at the south end of town; inside"] = "{npc:633}, à l'extrémité sud du village ; à l'intérieur",
	["{npc:663}, by the town hall"] = "{npc:663}, près de l'hôtel de ville",
	["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {area:10} can drop a {item:2378}.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once."] = "Des guerriers et des mages squelettes errent parmi les tombes au sud-est de {area:42}, en contrebas de la maison de {npc:302} sur la colline. Chaque squelette de {area:10} peut lâcher {item:2378}.\nAttention : les squelettes étant proches les uns des autres, foncer dans le tas en attire souvent plusieurs à la fois.",
	["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang.\nCareful: Wolves and other spider types share the area along the {area:40} border, so you can easily pull several mobs at once."] = "Des loups redoutables enragés parcourent les bois autour du cimetière et de {npc:289}, des loups redoutables affamés les collines au nord-est de lui. Des araignées pygmées venimeuses rampent à l'est du cimetière et lâchent le venin. Chaque goule de la moitié nord du cimetière peut lâcher un croc.\nAttention : des loups et d'autres types d'araignées partagent la zone le long de la frontière de {area:40}, vous pouvez facilement attirer plusieurs monstres à la fois.",
	["Head back east along the road to the {area:245}."] = "Revenez vers l'est par la route jusqu'à {area:245}.",
	["{quest:337}: a rare drop from {area:10}'s mobs"] = "{quest:337} : un butin rare des monstres de {area:10}",
	["Head west along the road once more."] = "Repartez vers l'ouest par la route.",
	["Head back east to {area:42}."] = "Revenez vers l'est jusqu'à {area:42}.",
	["Head west to the hermit once more."] = "Retournez à l'ouest chez l'ermite.",
	["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A {npc:948} casts {spell:3428} as it dies, which brings extra adds."] = "Chaque goule de la moitié nord de {area:492} peut lâcher une côte : mangeurs de chair, mâcheurs d'os, propagateurs de peste et mangeurs de cervelle.\nAttention : {npc:948} lance {spell:3428} en mourant, ce qui fait venir des renforts.",
	["Head west along the road out of {area:94} into {area:40}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Prenez la route vers l'ouest pour sortir de {area:94} et entrer dans {area:40}. {npc:7024} surveille la tour de {npc:7053} depuis les collines juste après la frontière. {npc:7051} (niveau 23) qui garde la tour porte sa clé ; le journal de Klaven est dans le coffre au sommet.",
	["Head north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Partez au nord à travers Elwynn jusqu'à {zone:1453} ; Mathias Shaw est au SI:7 dans {object:2100}.",
	["{npc:6173} and {npc:6171} are in the Cathedral of Light."] = "{npc:6173} et {npc:6171} sont dans la cathédrale de la Lumière.",
	["{npc:6171}: Redemption"] = "{npc:6171} : Rédemption",
	["Rogue training"] = "Entraînement du voleur",
	["Train here, in {zone:1453}, before you go on."] = "Entraînez-vous ici, à {zone:1453}, avant de continuer.",
	["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}."] = "Prenez le bateau de {area:17203} à {area:442}. Assemblez les deux moitiés de pendentif en {item:15885} et lancez {spell:18960} : {npc:11802} est à {area:2361}. Puis {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}.",
	["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then head south along the road through {zone:1439}."] = "Depuis {area:17203}, prenez le bateau pour {area:442} ; {npc:3649} se tient à l'extrémité nord du village. Puis partez au sud par la route à travers {zone:1439}.",
	["{npc:3649}: Alexston's reply, if you took it in {zone:1453}"] = "{npc:3649} : la réponse d'Alexston, si vous l'avez prise à {zone:1453}",
	["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {area:331} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep.\nCareful: Scripted ambushes of three mobs each attack along the road: furbolgs on the {zone:1439} stretch and undead nearer {area:413}."] = "Kerlonian dort à {area:448}, dans le sud de {zone:1439}. Utilisez {item:13536} pour le réveiller et conduisez-le au sud par la route jusqu'à {area:331}, auprès de {npc:11219} à {area:413} ; sonnez à nouveau du cor chaque fois qu'il s'endort.\nAttention : des embuscades de trois monstres attaquent le long de la route : des furbolgs sur le tronçon de {zone:1439} et des morts-vivants près de {area:413}.",
	["{object:176634}, beside him"] = "{object:176634}, à côté de lui",
	["Escort Kerlonian to {area:413} in {area:331}."] = "Escortez Kerlonian jusqu'à {area:413} dans {area:331}.",
	["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide; inside"] = "{npc:3970} : pour {npc:1480} à Menethil, à la fin de ce guide ; à l'intérieur",
	["The two stand together at the western end of the road.\nSouth of the murlocs, {npc:3585} waits at the {area:416}."] = "Les deux se tiennent ensemble à l'extrémité ouest de la route.\nAu sud des murlocs, {npc:3585} attend à {area:416}.",
	["Head west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Partez à l'ouest vers le rivage de {area:441}. Teronis gît parmi les murlocs Crache-sel ; n'importe quel murloc peut lâcher {item:5463}.",
	["{npc:3987} (25) leads the Thistlefur furbolgs at the camp north of {area:415}. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone."] = "{npc:3987} (25) mène les furbolgs Crins-de-chardon au camp au nord de {area:415}. Éliminez d'abord ses gardes, un par un.\nAttention : les furbolgs proches de lui le rejoignent généralement quand on l'attire. Tuer d'abord ceux qui sont sur son chemin permet de l'affronter seul.",
	["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell.\nThe moonwell lies in the hills north-east of {area:415}."] = "Suivez la route vers l'est jusqu'à {area:419} ; {npc:3916} se tient près du puits de lune.\nLe puits de lune se trouve dans les collines au nord-est de {area:415}.",
	["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around {area:1276}: the map marks where to look"] = "{npc:210995} ne les propose peut-être pas à toutes les classes ; s'il ne le fait pas, continuez. ; se promène autour de {area:1276} : la carte indique où chercher",
	["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines.\nCareful: The kobolds arrive in waves. The first wave is melee fighters, and the second adds casters to the mix. Regular mobs in the mine respawn quickly and can join the fight while the waves are coming. A group is recommended."] = "{npc:4276} creuse dans {area:2160} à l'extrémité est de la falaise. Parlez-lui et repoussez les pillards de la KapitalRisk pendant qu'il mine.\nAttention : les kobolds arrivent par vagues. La première vague est composée de combattants au corps à corps, la seconde ajoute des lanceurs de sorts. Les monstres ordinaires de la mine réapparaissent vite et peuvent rejoindre le combat pendant les vagues. Un groupe est conseillé.",
	["Head south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "Partez au sud après {area:421} dans le tunnel de {area:1276} ; il débouche sur {area:461} des Serres-Rocheuses. {npc:4080} et {npc:4077} campent sur {area:1076} au sud-ouest de la falaise.",
	["{npc:4201}, in the hut north of them; inside"] = "{npc:4201}, dans la hutte au nord d'eux ; à l'intérieur",
	["{npc:5082}, Mikhail and Tapoke Jahn are all at Menethil's inn; Tapoke fights you when you talk to Mikhail, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn.\n{npc:2104} stands in {area:2103}, a short walk from {npc:1242}.\n{npc:2104} stands in {area:2103}."] = "{npc:5082}, Mikhail et Tapoke Jahn sont tous à l'auberge de Menethil ; Tapoke vous attaque quand vous parlez à Mikhail, mais abandonne une fois battu. {npc:1480} se tient à quelques pas au nord-est de l'auberge.\n{npc:2104} se tient à {area:2103}, à quelques pas de {npc:1242}.\n{npc:2104} se tient à {area:2103}.",
	["{npc:1217}, upstairs in the inn"] = "{npc:1217}, à l'étage de l'auberge",
	["{npc:2086}, by the keep; inside"] = "{npc:2086}, près du donjon ; à l'intérieur",
	["{npc:2104}, by the keep"] = "{npc:2104}, près du donjon",
	["{npc:2096}: he won't offer 305 while you carry it"] = "{npc:2096} : il ne propose pas la 305 tant que vous la portez",
	["{npc:2094} stands by the north gate."] = "{npc:2094} se tient près de la porte nord.",
	["The excavation site sits on the hill south of the road."] = "Le site de fouilles se trouve sur la colline au sud de la route.",
	["A new {item:279996}, for the four titan watchers around the {zone:1437}; below ground"] = "Un nouveau {item:279996}, pour les quatre gardiens titans autour de {zone:1437} ; sous terre",
	["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Pour {npc:2916} à {zone:1455}, à la fin de ce guide",
	["The raptor hills"] = "Les collines des raptors",
	["Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a {npc:1021} drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight."] = "Des raptors tachetés et des hurleurs parcourent les collines à l'ouest du site de fouilles.\nAttention : une fois à 30 % de vie, {npc:1021} appelle à l'aide les créatures à moins de 20 mètres. Les hurleurs tachetés viennent souvent par trois, et les raptors appelés à l'aide peuvent aussi rejoindre le combat.",
	["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244} : {quest:98283}, un raptor élite",
	["Black, Crimson and Monstrous Oozes fill {area:309}, just west of the road to {area:205} and north of Einar's camp. Any ooze there may hold {npc:2111}'s bag.\nMosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Des limons noirs, cramoisis et monstrueux remplissent {area:309}, juste à l'ouest de la route de {area:205} et au nord du camp d'Einar. N'importe quel limon peut détenir le sac de {npc:2111}.\nDes coureurs des marais et des tisse-brume Peau-de-mousse parcourent les berges juste à l'ouest et au sud de {npc:1244} ; presque tous lâchent du silex.",
	["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; Neru stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised.\nFen Creepers hide in the marsh pools north-west of the {area:1025}.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."] = "Des dragonnets rouges remplissent les collines à l'ouest des portes, des griffes-pourries enragées {area:1025}, des tranchegueules les pentes nord ; Neru se tient au nord-est (utilisez {item:279996}).\n{quest:98283} est élite : un groupe est conseillé.\nDes rampants des marais se cachent dans les mares au nord-ouest de {area:1025}.\nAttention : hors combat, les rampants des marais lancent Camouflage de temps en temps ; ils sont alors furtifs et difficiles à voir.",
	["Menethil"] = "Menethil",
	["{npc:2092}'s quest in {zone:1455} needs level 28. If you are short of it after these hand-ins, grind the Dragonmaw orcs at the camps along the road east to {area:836} before you go on."] = "La quête de {npc:2092} à {zone:1455} demande le niveau 28. S'il vous manque après ces rendus, tuez des orcs Gueule-de-dragon dans les camps le long de la route vers l'est jusqu'à {area:836} avant de continuer.",
	["Head east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "Partez vers l'est par la route de {zone:1437}, au sud à travers {area:836} jusqu'à {zone:1432}, puis à l'ouest par le tunnel jusqu'à {zone:1426} et {area:1537}.",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Tant que vous êtes ici : apprenez {spell:199} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un guerrier le plus vite.",
	["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Tant que vous êtes ici : apprenez {spell:197} auprès de {npc:11865} ({object:32359}, 10 pièces d'argent) ; les armes à deux mains font monter un paladin le plus vite.",
	["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, à l'entrée nord du village ; se promène autour de {area:42} : cherchez dans le cercle sur la carte",
	["{npc:276}, at the east end of town; inside"] = "{npc:276}, à l'extrémité est du village ; à l'intérieur",
	["Nightbane Shadow Weavers"] = "Tisseurs d'ombre Plaie-de-nuit",
	["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance."] = "Les worgens les plus forts parcourent les bois au sud de {area:42}, à l'ouest et au sud de {area:121}. {npc:511} se cache dans la petite crypte près du cimetière.\nAttention : {spell:8282} dure 10 minutes et ajoute 13 à chaque coup physique que vous subissez.\nAttention : certains worgens devant la grotte se tiennent en groupes, dont un camp de quatre. Pour éviter les renforts, attirez-les un par un depuis la butte près de l'entrée de la grotte.",
	["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, près de la maison de {npc:633} ; à l'intérieur",
	["Head east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Partez vers l'est jusqu'au tertre des ogres. {object:119} se trouve dans le camp à son entrée ; des ogres Poing-éclaté le gardent.",
	["The Defias camp lies in the south-west of {area:10}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "Le camp défias se trouve au sud-ouest de {area:10}, au sud de {area:94} près de la frontière de {zone:1436}. Le coffre-fort se trouve parmi les tentes.",
	["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Les propagateurs de peste arpentent la moitié nord de {area:492}. {npc:522}, un élite, erre parmi les tombes : tenez-vous à l'écart.\nDes pillards, des soigneurs et des gardiens squelettes tiennent la partie ouest du cimetière, juste à l'est du camp de {npc:311}.\nAttention : les squelettes des catacombes sont serrés les uns contre les autres, vous pouvez facilement attirer d'autres monstres.",
	["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight."] = "Suivez la côte vers le nord jusqu'à l'épave. Des marins maudits arpentent la plage, des fusiliers marins maudits le pont ; {npc:1159} se tient sur la plage près de la proue. De grands crocilisques des Paluns rôdent sur la côte juste au nord.\nAttention : des rampants des marais se cachent, furtifs, là où la rivière se divise près du vaisseau fantôme, et peuvent rejoindre un combat.",
	["{item:2658} along the way to {npc:1078} and Whelgar"] = "{item:2658} en allant vers {npc:1078} et Whelgar",
	["{item:2659} along the way to {npc:1078} and Whelgar"] = "{item:2659} en allant vers {npc:1078} et Whelgar",
	["{item:2660} along the way to {npc:1078} and Whelgar"] = "{item:2660} en allant vers {npc:1078} et Whelgar",
	["{item:2661} along the way to {npc:1078} and Whelgar"] = "{item:2661} en allant vers {npc:1078} et Whelgar",
	["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one.\nThe relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it.\nThe Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Les gardiens goaz se tiennent juste à l'ouest du camp de Whelgar : utilisez à côté de l'un d'eux {item:279996} qu'il vous a donné.\nLes reliques se trouvent dans les fouilles elles-mêmes. {npc:1353}, un grand tranchegueule, rôde dans la vallée des raptors juste à l'ouest.\nLes orcs Gueule-de-dragon campent à l'est du site de fouilles. Les pillards et les coureurs des marais portent les bannières de guerre.",
	["Head east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "Repartez vers l'est jusqu'au camp Gueule-de-dragon. Les quatre plans d'attaque se trouvent à {area:1036} ; {npc:2091}, un élite, se tient aussi dans le camp.",
	["{npc:2104}, in {area:2103}; on the top floor"] = "{npc:2104}, à {area:2103} ; au dernier étage",
	["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "Pour la catapulte Gueule-de-dragon, sur la boucle de {zone:1437} du guide suivant",
	["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Sur la route vers le sud à travers {zone:1413}, {npc:6244} campe à l'est de la route, au nord-est de {area:378} ; arrivez par l'est et évitez les gardes de la Horde.",
	["{npc:2104}: for {npc:270637}; on the top floor"] = "{npc:2104} : pour {npc:270637} ; au dernier étage",
	["The next step, {quest:474}, pits you against an elite chieftain: skip it."] = "L'étape suivante, {quest:474}, vous oppose à un chef élite : passez-la.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:2091} est un élite de niveau 32 : la plupart des classes le battent seules au niveau 34, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.\nAttention : des lanceurs d'ombre se tiennent de chaque côté de lui, et au moins un lui est lié : il le rejoint quand on l'attire. Des centurions et des capitaines non élites sont répartis autour de son cercle de tentes.",
	["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Au nord-est jusqu'à {area:1038} : {npc:271338} se tient aux portes (utilisez {item:279996}).",
	["The Villards"] = "Les Villard",
	["{npc:5683} waits north of {area:205} by the {area:880}; {npc:271322} a short walk further north-east."] = "{npc:5683} attend au nord de {area:205}, près de {area:880} ; {npc:271322} à quelques pas plus au nord-est.",
	["{npc:1071} stands in the dwarves' camp."] = "{npc:1071} se tient dans le camp des nains.",
	["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "Suivez la route au sud par le pont jusqu'à {area:205}, côté {zone:1437}, où {npc:1075} attend.",
	["Level 31.23"] = "Niveau 31,23",
	["If you skipped {quest:474}, grind here to level 31.23 to stay on the route's plan."] = "Si vous avez passé {quest:474}, montez ici jusqu'au niveau 31,23 pour rester dans le plan de la route.",
	["Pick up everything in town before heading out. {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Prenez tout ce qu'il y a en ville avant de partir. {npc:2381} et {npc:2438} se tiennent entre le maître de vol et l'auberge, Farren et {npc:2366} à l'auberge, Maleb à l'hôtel de ville.",
	["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Les murlocs Nageoire-déchirée se pressent à {area:295}, au sud-ouest de {area:271}.\nAttention : un camp contient un groupe serré d'oracles qui attaquent tous ensemble.",
	["A report for {object:2117}; inside"] = "Un rapport pour {object:2117} ; à l'intérieur",
	["Off the boat, {npc:251493} is the first you meet, north-west of the flight master."] = "En descendant du bateau, {npc:251493} est le premier que vous rencontrez, au nord-ouest du maître de vol.",
	["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
	["{npc:211033}: only offered once you have handed in library books (the Library Books guide)"] = "{npc:211033} : proposée seulement une fois les livres de la bibliothèque rendus (le guide des livres de la bibliothèque)",
	["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Les satyres Hainefurie tiennent les ruines de {area:603}, à l'est de {area:608}.\nAttention : les voleurs Hainefurie apparaissent furtifs, et les filous Hainefurie peuvent empoisonner avec leurs attaques.",
	["{quest:5741}; on the top floor"] = "{quest:5741} ; au dernier étage",
	["Follow the road west out of {area:415}; {area:413} lies north of it."] = "Suivez la route vers l'ouest pour sortir de {area:415} ; {area:413} se trouve au nord.",
	["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "Depuis {area:415}, partez au nord-ouest dans les collines : {quest:1738} est un arbre lumineux au nord de la route de {area:413}. Si vous avez pris {quest:65602}, {item:190309} se trouve dans une maison parmi les arbres au nord de {area:413} (26,6 ; 22,0). Puis revenez par {area:415} jusqu'à {area:1276}.",
	["The Forsaken's camp lies in the woods south of {area:2358}.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together."] = "Le camp des Réprouvés se trouve dans les bois au sud de {area:2358}.\nDes coffres rouillés se trouvent autour des camps furbolgs Fourré-d'ombre à l'ouest des Réprouvés ; ouvrez-les jusqu'à trouver le pommeau.\nAttention : des Réprouvés non élites d'environ niveau 28-30 gardent le camp. Certains sont furtifs, et ceux autour de la table attaquent souvent ensemble.",
	["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle."] = "{npc:3931} arpente la rive de {quest:1035}, au sud-ouest des coffres ; {object:669176} se trouve au nord du lac, sur le chemin.\nAttention : d'autres monstres, certains sous l'eau, se trouvent près de l'île. Éliminez-les d'abord pour qu'ils ne rejoignent pas le combat quand vous attirez l'oracle.",
	["Insane druids"] = "Druides déments",
	["The three druids stand together at the Forsaken camp south of {area:2358}.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight."] = "Les trois druides se tiennent ensemble au camp des Réprouvés au sud de {area:2358}.\nAttention : la tanière abrite beaucoup de monstres qui réapparaissent vite, dont des morts-vivants furtifs et des patrouilles ; d'autres monstres rejoignent donc souvent le combat.",
	["The {object:19901} stands in the satyr camp of {area:430}, further east along the road.\nCareful: The Felmusk Rogues in {area:428} often go stealthed, and {area:430} has satyr casters."] = "{object:19901} se dresse dans le camp satyre de {area:430}, plus à l'est sur la route.\nAttention : les voleurs Musc-gangrené de {area:428} sont souvent furtifs, et {area:430} abrite des satyres lanceurs de sorts.",
	["{npc:3696} and his guards camp just east of {npc:3897}.\nCareful: Wolves and spiders roam near the camp and can join a fight. Some of the wolves come in pairs."] = "{npc:3696} et ses gardes campent juste à l'est de {npc:3897}.\nAttention : des loups et des araignées rôdent près du camp et peuvent rejoindre un combat. Certains loups vont par deux.",
	["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} se tient à l'étage supérieur du donjon de Menethil.",
	["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "L'épave de l'Orfraie volante repose dans les hauts-fonds au sud du donjon.",
	["{zone:1455} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{zone:1455} n'a pas de maître des druides : prenez {area:2257} depuis {object:171524} jusqu'à {zone:1453} et entraînez-vous auprès de {npc:5504}.",
	["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Attention : des camps de trolls sont proches de la zone des tigres, et les trolls peuvent rejoindre un combat si vous attirez sans précaution.\nAttention : le nid de raptors contient de jeunes raptors qui rejoignent le combat quand vous attaquez les adultes.",
	["{npc:2495}, by the bank; inside"] = "{npc:2495}, près de la banque ; à l'intérieur",
	["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910} ; à l'étage",
	["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, dans {object:56910} ; à l'étage",
	["{npc:773}, in the tavern; upstairs"] = "{npc:773}, dans la taverne ; à l'étage",
	["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards.\nThe Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Revenez vers le nord ; {area:310} se trouve à l'ouest de la route, au milieu de la jungle. Les basilics à épines cristallines qui y vivent lâchent les éclats.\nLes trolls Scalp-rouge tiennent les ruines sur la côte à l'ouest du camp de Nesingwary.",
	["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "Des réducteurs de têtes se tiennent au fond de l'enceinte ; les commandos rôdent, furtifs, autour d'elle et dans la grotte. Ramassez les pages des Vertes collines quand elles tombent.\nAttention : les commandos kurzen sont de niveau 34-35, non élites, et apparaissent souvent furtifs ; près de la mort, ils utilisent {spell:7964}.",
	["{item:2006}: {object:58}; underwater"] = "{item:2006} : {object:58} ; sous l'eau",
	["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} est le grand bâtiment qui domine le port ; la plupart des donneurs de quêtes sont à ses étages ou sur les quais en contrebas.",
	["\"Sea Wolf\" MacKinley, on the top floor"] = "« Loup de mer » MacKinley, au dernier étage",
	["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him."] = "{npc:5476} garde le carrefour à l'ouest du marais. {npc:217412} se tient un peu au nord de lui.",
	["The wrecked caravan lies off the road near Biggs.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "La caravane détruite se trouve à l'écart de la route, près de Biggs.\nAttention : le camp est plein d'Égarés d'environ niveau 38. Ils se tiennent en groupes liés de 2 ou 3, beaucoup lancent des sorts, et ils réapparaissent vite.",
	["Back west through {zone:1430} to {area:42}."] = "Retour vers l'ouest à travers {zone:1430} jusqu'à {area:42}.",
	["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "Le Syndicat tient la ferme au nord-ouest de {area:320}. {npc:217589} rampe dans la ferme : attrapez-en un avec la trousse d'entomologie de {npc:217412}, puis cochez-le.\nAttention : les bandits de grand chemin du Syndicat sont de niveau 30-31 et lancent Camouflage hors combat ; ils sont donc souvent furtifs et difficiles à repérer.",
	["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "Escortez le professeur jusqu'à la plage au nord de la crique et protégez-le pendant qu'il travaille ; les nagas attaquent par vagues.\nAttention : l'embuscade compte deux élémentaires d'eau de niveau 40, insensibles au givre. Si le combat a lieu dans la grotte, le professeur se bat au lieu de travailler et d'autres élémentaires continuent d'apparaître ; retenir les élémentaires à l'entrée de la grotte, loin de lui, lui permet de finir avec seulement les deux premiers à gérer.",
	["{npc:2595}, underwater"] = "{npc:2595}, sous l'eau",
	["{npc:2596}, underwater"] = "{npc:2596}, sous l'eau",
	["Ebenezer Rustlocke"] = "Ebenezer Rustlocke",
	["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Revenez sur le pont : Ebenezer gît sous son extrémité côté Arathi.",
	["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Les kobolds Sèche-moustache creusent dans la gorge à l'est de {area:321} (Horde) ; contournez la ville par le nord. Ils lâchent à la fois les grains et le minerai de Krazek.\nAttention : chaque type de kobold s'enfuit chercher de l'aide quand sa vie est basse (kobolds à 30 %, géomètres et creuseurs à 15 %), ce qui peut en attirer d'autres.",
	["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Chaque clé se trouve à l'un des cercles de pierres levées des Hautes-terres : à l'est des éclats, près de {area:320} et à l'ouest. {object:2702} se dresse à l'ouest de {area:320}.\nAttention : chaque pierre centrale est gardée par environ trois élémentaires proches du niveau 39 qui attaquent ensemble si vous cliquez sur la pierre sans les avoir éliminés : exilés brûlants à l'ouest, exilés tonnants au cercle extérieur, exilés déferlants à l'est.",
	["Head back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "Revenez au nord-est après {area:320} ; {npc:2712} et {npc:2713} campent dans les collines au nord de {area:314}.",
	["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Restez avec {npc:2713} pendant qu'elle s'infiltre dans {area:314} et en revient ; des orcs de la Horde vous attaquent en chemin.\nAttention : les orcs dont la vie baisse s'enfuient. {npc:2713} les suit et peut attirer d'autres monstres : tuez ou ralentissez vite les fuyards.",
	["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Suivez la route au nord pour sortir de {area:271} vers les montagnes. Des lions des montagnes parcourent les pentes ; les membres du Syndicat de {area:280} portent les chevalières, et {npc:2306} arpente le domaine du manoir au nord de la ville.",
	["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health."] = "Les tomes se trouvent dans le donjon en ruine à l'ouest de {area:280} ; des mages de l'ombre d'Argus tiennent les ruines.\nAttention : les va-t-en-guerre Brise-échine appellent les alliés à moins de 15 mètres dès qu'ils passent sous la moitié de leur vie.",
	["{item:3659}: the {object:1760}; inside"] = "{item:3659} : {object:1760} ; à l'intérieur",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:2417} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "Attention : les espions et les assassins du Syndicat peuvent être furtifs. Les assassins vous empoisonnent aussi.\nAttention : environ trois membres furtifs du Syndicat sont dans la maison de {npc:2320}. {npc:2320} ne les rejoint pas quand on les attire, et une attaque à distance par la porte le fait sortir seul.",
	["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {area:130}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Au sud-ouest jusqu'au camp du Kirin Tor sur la rive du lac à l'ouest de {area:279}, juste après la frontière de {area:130} : {npc:269127} s'y tient. L'archimage Ansirem se tient au sud-est, près du dôme.",
	["From {zone:1455} take the tunnel east through {zone:1426} into {area:38} and follow the road to {area:144}."] = "Depuis {zone:1455}, prenez le tunnel vers l'est à travers {zone:1426} jusqu'à {area:38} et suivez la route jusqu'à {area:144}.",
	["Head back west to the road and follow it south out of {zone:1432} through the pass into the {area:3}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Revenez à l'ouest jusqu'à la route et suivez-la au sud pour sortir de {zone:1432} par le col jusqu'à {area:3}. {npc:2910} et {npc:2860} campent côte à côte aux fouilles.",
	["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Partez au nord-est jusqu'aux fouilles abandonnées ; la caisse de fournitures s'y trouve, parmi les ogres Crache-poussière.",
	["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {area:3}."] = "{npc:4618} et {npc:2817} campent ensemble à {area:1877}, au milieu de {area:3}.",
	["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "Le squelette abîmé gît juste à l'est des ogres, au bord du camp des troggs de Cave-pierre ; les brise-os et les chamans autour lâchent les éclats. Theldurin est assis près du camp en ruine plus au sud.",
	["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Partez à l'ouest jusqu'à {area:1878} ; {npc:2921} travaille près de ses machines au milieu.",
	["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nThe Lesser Rock Elementals wander the {area:1878} west of {npc:2921}.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Les ogres Crache-poussière campent juste au sud de la vallée ; tous lâchent de la ferraille. Des busards tournent au-dessus de la plaine à l'est.\nLe squelette abîmé gît au bord du camp des troggs de Cave-pierre ; {quest:739}, le meurtrier d'Agmond, se promène parmi les brise-os.\nLes petits élémentaires de roche errent dans {area:1878} à l'ouest de {npc:2921}.\nAttention : les seigneurs Crache-poussière sont de niveau 44-45. Ils utilisent {spell:5242} et {spell:1160}, et sous 50 % de vie ils appellent les alliés à moins de 15 mètres. Sept d'entre eux se tiennent à environ 750 mètres au sud de {area:340}.",
	["The skeleton's next task, {quest:739}, waits until the later {area:3} guide at 43."] = "La tâche suivante du squelette, {quest:739}, attend le guide ultérieur de {area:3}, au niveau 43.",
	["Head north-east to the dwarven ruins in the north of the {area:3}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Partez au nord-est jusqu'aux ruines naines au nord de {area:3} ; le coffre se trouve parmi les nains Sombrefer. {npc:2745}, tout près, est élite : laissez-lui de la place.",
	["Head south to {area:345}."] = "Partez au sud jusqu'à {area:345}.",
	["{npc:1470}, in the inn; below ground"] = "{npc:1470}, dans l'auberge ; sous terre",
	["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "Le maître de vol se tient près de la porte de {area:514} ; {npc:5083} et {npc:4964} sont dans la citadelle.",
	["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} est retenue au camp centaure à l'ouest du cimetière. Libérez-la et gardez-la en vie pendant la sortie ; elle s'arrête près du cimetière.\nAttention : les groupes de l'embuscade sont liés et n'apparaissent que pendant l'escorte ; impossible de les éliminer à l'avance ou de les attirer un par un. Éliminer avant de partir les centaures ordinaires sur le chemin aide quand même.",
	["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Les démons se rassemblent à {area:602}, dans le sud de {zone:1443} : des gangrechiens (mangeurs de mana, chasseurs de mages et de lignes telluriques), des vierges et des sœurs du Néant, et des capitaines gardiens funestes autour de la fosse.\nAttention : la plupart des monstres ici suivent des patrouilles, vous pouvez facilement en attirer d'autres.",
	["The next guide starts in Theramore."] = "Le guide suivant commence à Theramore.",
	["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} se tient près de l'auberge ; {npc:4897}, un fournisseur à quelques pas au sud, vend les épices que veut Jarl.",
	["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, pour « Œil-des-marais » Jarl",
	["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "Suivez la route au nord-ouest pour sortir de Theramore jusqu'à la tour de guet de {area:503}. Des fouisseurs de Roche-boue parcourent le marais alentour.",
	["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "De retour à Theramore : Tervosh attend avec dame Jaina dans la tour de {area:514}.",
	["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}, pour « Œil-des-marais » Jarl",
	["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders."] = "{npc:4966} tient la tour avec quelques déserteurs. Il se retourne contre vous : battez-le jusqu'à ce qu'il se rende.\nAttention : Hendel a deux gardes qui rejoignent le combat quand il devient hostile. Les gardes s'enfuient une fois qu'il se rend.",
	["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Les araignées Sombrebrume nichent autour de la caverne au nord-ouest du marais ; toutes lâchent des yeux.\nAttention : les rôdeuses Sombrebrume se déplacent furtivement et empoisonnent une fois en combat. Les araignées sont serrées, les renforts sont donc fréquents ; attirer des cibles isolées depuis le bord extérieur en limite le nombre.",
	["The burned inn stands on the road west, toward the {area:17}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "L'auberge incendiée se trouve sur la route à l'ouest, vers {area:17} ; l'insigne du garde est dans les cendres et les traces de sabots dans la boue à côté de l'auberge.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {area:12}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. {npc:4732} l'enseigne aux humains à {area:88}, dans l'est de {area:12}, à côté des chevaux de {npc:384}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître d'équitation (non confirmé). Le guide Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. Les Célestes l'apprennent auprès de {npc:265756}, maître des écuries et d'équitation à {area:17684}, à {area:16638} sur l'île de Zephras, qui vend aussi les coursiers du vent : le vaisseau volant vers l'île part du côté nord de {area:279} environ toutes les cinq minutes. Le guide Collection, Montures · Niveau 40 liste les coursiers du vent.",
	["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Équitation et coursiers du vent : {npc:265756}, à {area:17684}, à {area:16638} sur l'île de Zephras.",
	["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Vaisseau volant vers l'île de Zephras : côté nord de {area:279}, environ toutes les cinq minutes.",
	["for Stoley in {zone:1446}: keep it; on the top floor"] = "pour Stoley à {zone:1446} : gardez-le ; au dernier étage",
	["for the {area:8} later"] = "pour {area:8} plus tard",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:728} est un élite de niveau 40 : la plupart des classes le battent seules au niveau 42, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Les trolls Brise-crâne tiennent les ruines juste à l'est de la mine ; tous peuvent lâcher des défenses, leurs panthères en lâchent toujours.\nSuivez la route au nord-est jusqu'au camp de la KapitalRisk à {area:310} ; les mineurs, les géomètres et les contremaîtres lâchent les cristaux.\nAttention : des panthères Gueule-d'ombre et des tigresses de Strangleronce furtives parcourent les environs du camp.",
	["Level 42.23"] = "Niveau 42,23",
	["If you skipped {quest:193}, grind here to level 42.23 to stay on the route's plan."] = "Si vous avez passé {quest:193}, montez ici jusqu'au niveau 42,23 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:730} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 42.27"] = "Niveau 42,27",
	["If you skipped {quest:196}, grind here to level 42.27 to stay on the route's plan."] = "Si vous avez passé {quest:196}, montez ici jusqu'au niveau 42,27 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:731} est un élite de niveau 43 : la plupart des classes le battent seules au niveau 45, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.\nAttention : des tigres et des panthères Gueule-d'ombre furtives rôdent près de lui. Éliminez-les avant de l'attirer. Quand on l'attire, {npc:731} appelle à l'aide les créatures à moins de 20 mètres.",
	["Level 42.33"] = "Niveau 42,33",
	["If you skipped {quest:208}, grind here to level 42.33 to stay on the route's plan."] = "Si vous avez passé {quest:208}, montez ici jusqu'au niveau 42,33 pour rester dans le plan de la route.",
	["Level 42.46"] = "Niveau 42,46",
	["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan."] = "Si vous avez passé {quest:543}, montez ici jusqu'au niveau 42,46 pour rester dans le plan de la route.",
	["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} se tient près du carrefour à l'ouest du marais.",
	["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {area:12}. Collectibles, Mounts · Level 40 lists every colour."] = "Au niveau 40, avec 100 pièces d'or, vous pouvez apprendre à monter, et l'apprentissage vous donne une monture. {npc:4753} l'enseigne aux elfes de la nuit à {zone:1457}, à côté des sabres de {npc:4730} : le bateau de {area:17203} à {area:442}, puis le vol jusqu'à {area:702}. Forever permet peut-être à toutes les races d'apprendre auprès de n'importe quel maître d'équitation (non confirmé), comme {npc:4732} à {area:88} dans {area:12}. Le guide Collection, Montures · Niveau 40 liste toutes les couleurs.",
	["Ride south out of {zone:1432} through the pass into the {area:3}; {npc:2860} camps at the dig."] = "Chevauchez au sud pour sortir de {zone:1432} par le col jusqu'à {area:3} ; {npc:2860} campe aux fouilles.",
	["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} campe seul à {area:1898}, au sud-est du site de fouilles.",
	["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "pour {npc:4454} à {area:439} : le guide de {zone:1446} les croise au niveau 45, gardez-le",
	["Ride west across the {area:3} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Chevauchez vers l'ouest à travers {area:3} jusqu'au camp Crache-poussière de {area:342}. {npc:2944} se tient au milieu, entouré de chasseurs de wyrms et de cogneurs.",
	["Ride north-east out of {area:271} on the road into the {area:47}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Chevauchez au nord-est pour sortir de {area:271} par la route jusqu'à {area:47} ; {area:348} se trouve juste après la frontière. {npc:5635} tient sa cour au sommet, {quest:1450} s'occupe de la volière et {npc:7884} se tient près de l'auberge.",
	["{npc:7744}: the last guide binds here, so this usually ticks at once; below ground"] = "{npc:7744} : le guide précédent vous y fait lier votre pierre de foyer, cet objectif se coche donc généralement aussitôt ; sous terre",
	["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, à côté du maître de vol au sommet ; à l'intérieur",
	["Talonaxe's next task waits for a later {area:47} guide."] = "La tâche suivante de Hache-serre attend un guide ultérieur de {area:47}.",
	["Theramore flight master"] = "Maître de vol de Theramore",
	["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it."] = "{area:1116} se dresse sur {area:1120}, au large de {area:1108} : le bateau du quai de la côte y traverse.",
	["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121} est l'île juste au sud de {area:1120} : traversez à la nage. Des gardes serpents et des ensorceleuses Crête-haineuse la tiennent ; {npc:8136} (niveau 47) attend dans la grotte à son extrémité sud. Attirez d'abord ses gardes.",
	["Feathermoon flight master"] = "Maître de vol de Pennelune",
	["Boat to the {area:1108} and ride east across {area:357} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Bateau jusqu'à {area:1108}, puis chevauchez vers l'est à travers {area:357} jusqu'au camp Totem-sinistre au nord de la route. {npc:7956} attend devant ; libérez les fées-dards de l'enclos au milieu et gardez en vie {npc:7956} et au moins six d'entre elles.",
	["{npc:7765}'s camp"] = "Le camp de {npc:7765}",
	["The {area:2240} lies on the {area:439} in south-east {area:400}. {npc:4454} and {npc:4630} are in the camps beside the track.\n{npc:4709} stands by the goblin camp.\nWhile {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{area:2240} se trouve sur {area:439}, dans le sud-est de {area:400}. {npc:4454} et {npc:4630} sont dans les camps près de la piste.\n{npc:4709} se tient près du camp gobelin.\nPendant que {npc:4709} retient Rizzle en discutant, ses plans restent sans surveillance dans le camp gnome de l'autre côté de la piste.",
	["Ride south-east off the {area:439} into {area:440}. {area:976} is just inside the border."] = "Chevauchez au sud-est en quittant {area:439} vers {area:440}. {area:976} se trouve juste après la frontière.",
	["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, dans la taverne du port ; à l'intérieur",
	["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Chevauchez vers l'ouest en direction de {area:976}. Les bandits et les voleurs Rôdeurs-des-sables tiennent les dunes en chemin ; n'importe lequel peut porter une outre d'eau.\nAttention : les voleurs Rôdeurs-des-sables (niveau 43-44) se déplacent furtivement et peuvent donc approcher sans être vus.",
	["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Les voleurs, les mages de l'ombre et les assassins Rôdeurs-des-sables les plus coriaces campent au sud-est de {area:976}, au sud des bandits. Laissez {npc:7847}, au milieu du camp sud, pour plus tard.\nAttention : les voleurs Rôdeurs-des-sables restent camouflés hors combat ; des voleurs cachés peuvent donc rejoindre un combat engagé dans un camp.",
	["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Suivez la côte vers le sud jusqu'à la crique des pirates. Les pirates de la Voile sanglante se pressent sur la plage et les bateaux : avancez par les bords et attirez-les un par un. {npc:7883} se tient de l'autre côté ; la cargaison volée de {npc:7881} se trouve dans le camp.\nAttention : deux ou trois pirates se tiennent avec {npc:7883}, et beaucoup d'autres pirates de la ville rejoignent le combat dès qu'il commence.",
	["{quest:2873}; upstairs"] = "{quest:2873} ; à l'étage",
	["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Attention : les voleurs lancent Désarmement. Les voleurs restent cachés grâce à Camouflage. Les assassins utilisent Exécution quand votre vie est à 20 % ou moins.",
	["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Chevauchez au nord-ouest jusqu'à la ruche Centipaar dans les dunes. N'importe quel Centipaar peut lâcher des morceaux d'insecte.\nAttention : les essaimeurs Centipaar lancent {npc:4196} en combat comme hors combat, ce qui fait venir de petits renforts qui vous interrompent.",
	["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "Chevauchez au sud jusqu'à {quest:3362}. Les collecteurs de rosée lâchent les glandes ; seules certaines sont pleines, gardez donc la chargée. Des chardonniers noueux et des façonneurs de racines partagent la vallée. Les chardonniers sont de niveau 48-50, au-dessus de vous : attirez-les un par un.\nAttention : les autres monstres chardonniers de la zone sont de niveau 49-50 et se déplacent beaucoup, vous pouvez facilement en attirer d'autres.",
	["{npc:7583}'s next ingredient grows in the {area:47}, and the route never brings it back: skip it."] = "L'ingrédient suivant de {npc:7583} pousse à {area:47}, et la route n'y revient jamais : passez-le.",
	["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Chevauchez au sud-est jusqu'à {area:985}. {npc:7847} se tient au milieu du camp sud des Rôdeurs-des-sables : faites d'abord le ménage autour de lui.\nAttention : deux voleurs Rôdeurs-des-sables furtifs l'accompagnent partout. À son camp d'apparition, deux mages de l'ombre et leurs serviteurs sont assez proches pour rejoindre le combat. Près des tours, vous pouvez l'affronter sans eux.",
	["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Chevauchez au sud après {area:1938} jusqu'à {area:981}, les tunnels Hazzali ; l'équipement de Scrimshank se trouve tout au fond.\nAttention : un insecte garde l'équipement. Beaucoup d'insectes patrouillent dans les tunnels, certains de niveau 50, les combats attirent donc souvent des renforts.",
	["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Chevauchez au sud-est jusqu'à {area:355}, le temple à degrés Vilebranch au sud de {zone:1425}, et grimpez au sommet. Qiaga et {npc:8636} (élite, 50) s'y tiennent : touchez le sommet et redescendez aussitôt.\nAttention : des trolls élites gardent la plate-forme du sommet, dont {npc:7996} et {npc:8636}, avec plusieurs devins Vilebranch. Les devins lancent des sorts et sont liés au reste du groupe.",
	["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Chevauchez au nord jusqu'à {area:351}, au milieu de {zone:1425}. Des vases vertes et des limons de jade rampent tout autour.\nAttention : des panthères se déplacent furtivement dans la zone.",
	["Ride south through the pass into the {area:3}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Chevauchez au sud par le col jusqu'au bord nord de {area:3} : les troggs de Cave-pierre creusent devant {area:1517}. Les urnes sculptées et les touffes de champignons magenta se trouvent dans leurs grottes et tunnels, hors du donjon lui-même.",
	["The bloodmages' camp is the first stop beside the road into the {area:4}, north-west of {area:1438}."] = "Le camp des mages de sang est la première étape au bord de la route vers {area:4}, au nord-ouest de {area:1438}.",
	["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "Chevauchez vers l'ouest : des ricaneurs affamés parcourent les collines sèches juste au sud du camp des mages de sang ; des dards scorpok (niveau 50) trottinent au milieu du nord. Des vautours {npc:5982} tournent au-dessus de tout cela. Attirez-les un par un.\nDes sangliers Crins-de-cendre et des basilics de Roche-rouge partagent les pentes au sud-ouest du donjon. Évitez les sangliers infernaux plus au sud : ils sont de niveau 52.\nAttention : les dards scorpok utilisent {spell:5416} ; {npc:8301} ajoute un renversement.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:8552} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:1494} (élite de niveau 52) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.\nThe dwarf stands by the road at the dig site. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "Chevauchez vers l'est à travers le Chaudron jusqu'à {area:247} au sud-est. Le prisonnier dans la cabane en bois veut 15 {item:4306} et huit géologues Sombrefer tués sur le site de fouilles alentour. La cabane s'ouvre aussi avec la clé, si vous en avez trouvé une.\nLe nain se tient près de la route au site de fouilles. Une fois terminé, lisez {object:175704} qu'il laisse sur la route à {area:1959}.",
	["Level 48.27"] = "Niveau 48,27",
	["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan."] = "Si vous avez passé {item:3985} ou Affronter Negolash, montez ici jusqu'au niveau 48,27 pour rester dans le plan de la route.",
	["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {area:51}. {area:1446} is the scaffolded camp on the north-west rim."] = "Depuis {area:144}, chevauchez au sud jusqu'à {zone:1418}, puis à l'ouest après la ville de la Horde de {area:340} (gardez vos distances) et montez le sentier jusqu'à {area:51}. {area:1446} est le camp aux échafaudages sur le rebord nord-ouest.",
	["The spiders roam the plateaus and lava pools in the south-west of the gorge.\nHeavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.\nTaskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "Les araignées parcourent les plateaux et les bassins de lave au sud-ouest de la gorge.\nDe lourds golems de guerre patrouillent au fond du Chaudron sous Kalaran ; des élémentaires de magma dérivent parmi eux. Les golems et les élémentaires lâchent l'huile, les élémentaires les cœurs.\nLes maîtres de corvée et les esclavagistes mènent les esclaves partout dans le Chaudron, et n'importe lequel peut porter {item:10551}. Les forgerons à vapeur travaillent aux fourneaux au milieu ({item:18959}), les guetteurs se tiennent sur les crêtes sud (la longue-vue). N'importe quel {object:147516} peut lâcher {item:11818} : gardez-le.\nAttention : les esclavagistes Sombrefer (niveau 45-46) appellent les alliés à moins de 15 mètres quand on les attire, lancent Filet jusqu'à 15 mètres et utilisent Pourfendre au corps à corps.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:14621} est un élite de niveau 50 : la plupart des classes le battent seules au niveau 52, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 48.66"] = "Niveau 48,66",
	["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan."] = "Si vous avez passé {quest:7701}, montez ici jusqu'au niveau 48,66 pour rester dans le plan de la route.",
	["{object:147516} dwarves"] = "Nains {object:147516}",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:5860} (élite de niveau 50) demande un groupe de 3. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 48.98"] = "Niveau 48,98",
	["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan."] = "Si vous avez passé {quest:3452}, montez ici jusqu'au niveau 48,98 pour rester dans le plan de la route.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:3181} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["For {npc:8256} in {area:1537}, later"] = "Pour {npc:8256} à {area:1537}, plus tard",
	["From {area:392}, fly to {area:976}."] = "Depuis {area:392}, volez jusqu'à {area:976}.",
	["Ride west out of {area:976} to the long ramp down into {area:490}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Chevauchez vers l'ouest pour sortir de {area:976} jusqu'à la longue rampe qui descend dans {area:490}. {npc:9619} campe au pied de la rampe, dans l'angle sud-est du cratère.",
	["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Chevauchez vers l'ouest pour revenir au refuge.\nÉvitez largement les diablosaures et les stégodons élites. Ramassez chaque cristal de pouvoir et chaque {object:157936} que vous croisez à partir d'ici.",
	["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, au fond de la grotte ; sous terre",
	["{area:537} and the eastern jungle"] = "{area:537} et la jungle de l'est",
	["{object:161504}, underwater"] = "{object:161504}, sous l'eau",
	["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "Le pylône se dresse sur la pente à l'est du refuge. Des ptérreurdactyles tournent sur les pentes autour : ils comptent pour Spraggle et lâchent les écailles de {npc:9998}.",
	["Level 49.51"] = "Niveau 49,51",
	["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50."] = "Montez ici jusqu'au niveau 49,51 avant les rendus de {area:541} : ils vous amènent au niveau 50.",
	["grind on Pterrordax"] = "tuer des ptérreurdactyles",
	["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "Chevauchez vers l'ouest depuis {npc:9619} : la ruche silithide remplit le sud du cratère. Utilisez la fiole de raclage sur une couveuse, une salle aux larves suspendues. Les guêpes et les ouvriers gorishi lâchent {quest:3764} ; des ptérreurdactyles nichent sur les falaises sud s'il vous faut encore des victimes.\nAttention : les silithides gorishi sont de niveau 51-54 et lancent {spell:8137} ou {spell:14120} au corps à corps ; les ouvriers gorishi ont 50 % de chances d'appeler à l'aide à moins de 25 mètres une fois sous 45 % de vie.",
	["Level 50.4"] = "Niveau 50,4",
	["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51."] = "Montez ici jusqu'au niveau 50,4 avant les rendus de {area:3137} : ils vous amènent au niveau 51.",
	["The shrine lies in the south-west corner of {area:16}, south of {area:3137}."] = "Le sanctuaire se trouve dans l'angle sud-ouest de {area:16}, au sud de {area:3137}.",
	["Swim to the small island off the southern tip of {area:16}: {npc:8392} waits by the monument."] = "Nagez jusqu'au petit îlot au large de la pointe sud de {area:16} : {npc:8392} attend près du monument.",
	["Level 50.89"] = "Niveau 50,89",
	["Top up here to level 50.89 before the hand-ins at {zone:1426}: they take you to level 51."] = "Montez ici jusqu'au niveau 50,89 avant les rendus à {zone:1426} : ils vous amènent au niveau 51.",
	["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} se trouve au sud-est des Steppes, en haut du col qui monte des Carmines.",
	["Level 51.39"] = "Niveau 51,39",
	["Top up here to level 51.39 before the hand-ins at {area:251}: they take you to level 52."] = "Montez ici jusqu'au niveau 51,39 avant les rendus de {area:251} : ils vous amènent au niveau 52.",
	["Level 52"] = "Niveau 52",
	["Top up here to level 52 before the hand-ins at {area:251}: they take you to level 53."] = "Montez ici jusqu'au niveau 52 avant les rendus de {area:251} : ils vous amènent au niveau 53.",
	["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Les reliques sont les pierres sculptées éparpillées dans {area:250} autour de {area:251} : cliquez dessus jusqu'à récupérer les informations.\nLisez la tablette du camp {object:147516} parmi les ruines, au sud-ouest de {area:251}, pour recopier la transcription.\nUtilisez {item:12284} sur {npc:7047} sur les pentes à l'est de {area:251} juste avant sa mort, puis ramassez l'essence qu'il laisse.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:9461} est un élite de niveau 54 : la plupart des classes le battent seules au niveau 56, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 52.08"] = "Niveau 52,08",
	["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan."] = "Si vous avez passé {quest:4022}, montez ici jusqu'au niveau 52,08 pour rester dans le plan de la route.",
	["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176} et les orcs Rochenoire tiennent les camps et la forteresse au pied de {area:254}, à l'ouest de {area:251}. Attirez-les un par un ; chaque orc et chaque worg peut lâcher un médaillon, tuez-en donc jusqu'à en avoir cinquante.\nAttention : {npc:9176} a un garde lié qui rejoint le combat, et un second soldat patrouille tout près ; éliminez la patrouille avant d'attirer.",
	["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%."] = "Kum'isha attend à {area:2517}, la colline au sud-ouest du donjon. Les monstres de {zone:1419} en chemin lâchent les fragments de draenéthyste imparfaits ; apportez-lui ce que vous avez.\nAttention : Felcular, {npc:7664} et Ilifar sont tous des élites de niveau 60. Razelikh lance {spell:2691}, {spell:8255} et Décimer, et à mesure que sa vie baisse il ajoute {object:141891}, {spell:10854} puis Enrager à 15 %.",
	["The Wildkin Feathers lie on the ground across the {area:47}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Les plumes de sauvage gisent au sol à travers {area:47}, au sud et à l'est de {area:348}, là où rôdent les chouettards ; les monstres d'ici sont maintenant bien en dessous de votre niveau.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:7977} (élite de niveau 48) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Ride north out of {area:415} into {area:361}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Chevauchez au nord pour sortir de {area:415} jusqu'à {area:361}. Le furbolg {npc:11554} se tient près de la route juste au sud de {area:2479}.",
	["Level 52.58"] = "Niveau 52,58",
	["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan."] = "Si vous avez passé Le cor de la bête ou {item:9328}, montez ici jusqu'au niveau 52,58 pour rester dans le plan de la route.",
	["{npc:15395} waits at the north end of {area:361}"] = "{npc:15395} attend à l'extrémité nord de {area:361}",
	["Level 52.69"] = "Niveau 52,69",
	["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53."] = "Montez ici jusqu'au niveau 52,69 avant les rendus de {area:1763} : ils vous amènent au niveau 53.",
	["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited."] = "Les satyres Feu-de-jade tiennent le vallon à l'ouest de la route, avec {npc:9454} au fond.\nAttention : les traqueurs de l'ombre Feu-de-jade (niveau 51-52) utilisent Camouflage et {spell:7992} et sont furtifs ; ils rejoignent donc souvent les combats sans y être invités.",
	["{npc:11016}, in {area:1770}; below ground"] = "{npc:11016}, à {area:1770} ; sous terre",
	["Level 52.9"] = "Niveau 52,9",
	["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53."] = "Montez ici jusqu'au niveau 52,9 avant les rendus de {area:2479} : ils vous amènent au niveau 53.",
	["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Les furbolgs Mort-bois de {area:1762} remplissent les collines à l'ouest de la grotte. Les vengeurs peuvent lâcher {quest:8470}.\nAttention : les guetteurs de la tanière sont de niveau 53-54 ; ils appellent les alliés à moins de 25 mètres une fois sous 50 % de vie et s'enfuient chercher de l'aide sous 15 %.",
	["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558} : les Grumegueules ne vous parlent qu'à partir de Neutre ; se promène par ici : cherchez dans le cercle sur la carte",
	["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57; below ground"] = "{npc:11557} : trente {quest:6031}, rendues quand vous repasserez au niveau 57 ; sous terre",
	["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}."] = "Utilisez {item:12922} au puits de lune corrompu au milieu de {area:1763}. Si vous avez libéré {npc:11018}, retournez dans {area:1770} pour la succube {npc:9518}.",
	["Trey Lightforge's remains lie beside her."] = "La dépouille de Trey Forge-lumière gît à côté d'elle.",
	["The vial is filled in {zone:1457}: keep it; inside"] = "La fiole se remplit à {zone:1457} : gardez-la ; à l'intérieur",
	["{npc:11629}: keep it for {area:2262}; inside"] = "{npc:11629} : gardez-le pour {area:2262} ; à l'intérieur",
	["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431} : gardez les deux pour les Maleterres ; à l'intérieur",
	["Level 55.05"] = "Niveau 55,05",
	["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56."] = "Montez ici jusqu'au niveau 55,05 avant les rendus de {area:2255} : ils vous amènent au niveau 56.",
	["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616} : les termites viennent plus tard, à {area:2627}",
	["Follow the southern road east into the {area:139}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Suivez la route du sud vers l'est jusqu'à {area:139} ; les ruines de {area:2262} se trouvent au sud. Le fantôme de {npc:10926} joue près de la maison en ruine à l'extrémité sud.",
	["{quest:5152}, in the {area:28}: keep it"] = "{quest:5152}, à {area:28} : gardez-le",
	["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038} : Zaeldarr est un élite de niveau 54",
	["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, près des tombes au sud de la chapelle",
	["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Zaeldarr est élite : un groupe est conseillé. Il attend au fond de {area:2261}, la crypte au sud-ouest de la zone.",
	["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "Attention : {npc:10411} devient invisible hors combat et appelle des gargouilles Aile-de-roche dès qu'un combat commence. Il n'en existe que 3 et elles réapparaissent toutes les 15 minutes.",
	["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Des écorcheurs squelettes et des goules baveuses parcourent les champs au nord du camp ; tout le Fléau d'ici lâche des pierres du Fléau.\nAttention : ces morts-vivants vous repèrent de loin, et les morts-vivants proches rejoignent le combat quand on en attire un.\nAttention : {npc:10411} (3 exemplaires, réapparition en 15 minutes) devient invisible hors combat et appelle des gargouilles Aile-de-roche dès qu'un combat commence.",
	["{object:175924}, in the farmhouse; inside"] = "{object:175924}, dans la ferme ; à l'intérieur",
	["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal.\nSmall lockboxes lie in the rubble all over Andorhal; each holds a watch.\nCareful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "{npc:1852} est élite : un groupe est conseillé. Il garde son phylactère au milieu d'Andorhal.\nDe petits coffrets gisent dans les décombres partout dans Andorhal ; chacun contient une montre.\nAttention : des goules et des squelettes se tiennent généralement près des coffrets et attaquent quand vous approchez. Les goules brûlantes blessent aussi tout ce qui est proche et rompent le camouflage.",
	["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} arpente le camp de Crête-du-nord à l'est de {npc:11610} ; {npc:11611} garde la tour à l'approche sud de {area:190}.\nAttention : des gardes se tiennent au pied de la tour et un autre tourne autour en patrouille. Éliminez-les avant d'engager Durgen pour qu'ils ne rejoignent pas le combat.",
	["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Montez sur la colline à l'ouest de {area:190} pour dominer la ville.\nAttention : les sentinelles postées à la porte détectent les joueurs camouflés. D'autres sentinelles se trouvent en ville, et un élite patrouille tout près.",
	["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby.\n{npc:11140} stands by {npc:12384}' hut in {area:2627}."] = "Chevauchez au nord jusqu'à {area:2627}. {npc:12384} vit dans la hutte en ruine, et son carnet de reçus se trouve dans l'auberge en ruine voisine.\n{npc:11140} se tient près de la hutte de {npc:12384} à {area:2627}.",
	["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Traversez la rivière vers l'est jusqu'à {area:2261}, la crypte au sud-ouest de la zone. {object:177667} se trouve à l'intérieur : sa clé est sur {npc:12248}, tout au nord-est, au guide suivant.",
	["The portal in {area:702} leads up to {zone:1457}."] = "Le portail de {area:702} mène à {zone:1457}.",
	["{quest:6762} in {area:493}: keep it"] = "{quest:6762} à {area:493} : gardez-le",
	["Ranshalla in {area:618}: keep it"] = "Ranshalla à {area:618} : gardez-le",
	["{npc:7900}: keep it for {area:440}"] = "{npc:7900} : gardez-le pour {area:440}",
	["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496} : gardez-le pour Un'Goro ; à l'intérieur",
	["{npc:9299} in {area:976}: keep it"] = "{npc:9299} à {area:976} : gardez-le",
	["Walk into {area:1769} and take the {area:493} branch of the tunnel to {area:2361}."] = "Entrez dans {area:1769} et prenez l'embranchement de {area:493} du tunnel jusqu'à {area:2361}.",
	["For {area:1377}: keep it"] = "Pour {area:1377} : gardez-le",
	["On {npc:7583}"] = "Sur {npc:7583}",
	["For {area:3197}: keep it"] = "Pour {area:3197} : gardez-le",
	["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} attend au cimetière juste à l'est de la ville ; la pierre tombale se dresse tout près.",
	["{quest:3444} is in {area:392}"] = "{quest:3444} est à {area:392}",
	["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; J.D.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Volez de {area:976} à {area:541}. La hutte de {npc:8737} se trouve à {area:538}, à l'ouest du refuge ; J.D.\n{npc:9999}, l'ami de {npc:9997}, a disparu.",
	["The wooden sign beside {npc:9997}"] = "Le panneau de bois à côté de {npc:9997}",
	["Ride out of the crater's north-western pass into {area:1377} and on to {area:3425}."] = "Sortez du cratère par le col nord-ouest jusqu'à {area:1377}, puis jusqu'à {area:3425}.",
	["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Des frappeurs dragueurs creusent dans les dunes au nord-ouest du fort ; des scorpides Fouette-pierre et des trotteurs des sables rôdent tout autour.",
	["Level 56.89"] = "Niveau 56,89",
	["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan."] = "Si vous avez passé {item:9328}, montez ici jusqu'au niveau 56,89 pour rester dans le plan de la route.",
	["Follow the road south-west out of the pass to {area:3425}."] = "Suivez la route au sud-ouest en sortant du col jusqu'à {area:3425}.",
	["{npc:17082}, at the Alliance tents"] = "{npc:17082}, aux tentes de l'Alliance",
	["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Les écraseurs dragueurs creusent plus à l'ouest ; des pinces, des écorcheurs Fouette-pierre et des traqueurs des roches chassent dans les mêmes sables.",
	["Ride east to {npc:13220}."] = "Chevauchez vers l'est jusqu'à {npc:13220}.",
	["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Les druides et les sentinelles torturés hantent le village en ruine au sud-ouest de {npc:13220}.",
	["The {area:2742} tower"] = "La tour de {area:2742}",
	["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Chevauchez vers l'est jusqu'à la tour de {area:2742} à {area:2738} ; grimpez-y et tuez les embusqués qui surgissent pour l'objet incrusté.",
	["Umber in {area:493}: keep it"] = "Umber à {area:493} : gardez-le",
	["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "Chevauchez vers l'ouest après {area:541} et descendez le côté ouest jusqu'à {area:543} : le gobelin {npc:10302} est assis au bord de l'eau.",
	["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Chevauchez vers l'est jusqu'à {area:537}, grimpez-y et utilisez {npc:10541} aux bouches de lave près du sommet.",
	["Ends with {npc:9298} in {area:618}: keep it"] = "Se termine auprès de {npc:9298} à {area:618} : gardez-le",
	["Collie is up the hill behind it."] = "Collie est en haut de la colline derrière.",
	["The crater"] = "Le cratère",
	["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Des bêtes de goudron se vautrent dans {area:538} ; les élémentaires de feu de {area:537}, au milieu, portent la cendre ; les guêpes gorishi de {area:540}, au sud, portent la glande. Toutes les créatures du cratère peuvent lâcher {item:11018}.\nAttention : les ouvriers gorishi qui passent sous 45 % de vie ont 50 % de chances d'appeler à l'aide les alliés à moins de 25 mètres.",
	["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Descendez la rampe dans le cratère : {npc:9619} campe en bas.",
	["The pelts come after loop 2, on the gorilla plateau"] = "Les peaux viennent après la boucle 2, sur le plateau des gorilles",
	["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Les gorilles vivent à {area:1943}, à l'est de {area:541}. Gardez leurs peaux pour {npc:9619}. Évitez la grotte la plus profonde : {npc:9622} est de niveau 55.\nAttention : les gorilles d'Un'Goro (niveau 50-51) appellent les alliés à moins de 20 mètres une fois à 25 % de vie. La zone contient une grotte pleine de singes, et y combattre attire beaucoup de renforts.",
	["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Chevauchez au nord par le côté est jusqu'au plateau des gorilles. {npc:9622}, un gorille de niveau 55, se tient dans la grotte la plus profonde : éliminez d'abord les gorilles à l'entrée de la grotte.",
	["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "Le repaire de {npc:9684} se trouve dans la jungle au nord de {npc:9619}, au pied des falaises est : utilisez-y {item:11568}. {npc:9684} est de niveau 56 : commencez avec toute votre vie.",
	["Cross the south of the crater to {npc:9619} by the ramp."] = "Traversez le sud du cratère jusqu'à {npc:9619}, près de la rampe.",
	["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} est assis sur la pente sud-est de {area:537}, au milieu du cratère.",
	["Escort {npc:9999}"] = "Escortez {npc:9999}",
	["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Conduisez {npc:9999} au nord jusqu'à {area:541}. Quand il s'évanouit, utilisez {item:11804} sur lui pour le réveiller.",
	["Ride back to {area:3425} and fly to {area:392}."] = "Revenez à {area:3425} et volez jusqu'à {area:392}.",
	["Take the {area:2257} to {zone:1455}."] = "Prenez {area:2257} jusqu'à {zone:1455}.",
	["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Prenez le bateau de {area:392} à {area:35} et volez jusqu'à {zone:1453}.",
	["{npc:3520}, who walks the canals"] = "{npc:3520}, qui arpente les canaux",
	["For {npc:10778}: keep it"] = "Pour {npc:10778} : gardez-le",
	["{npc:332}, in SI:7"] = "{npc:332}, au SI:7",
	["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} à {area:3197} : gardez-le",
	["Its jars are filled on the next Un'Goro visit"] = "Ses bocaux se remplissent lors du prochain passage à Un'Goro",
	["{npc:14724}, by the tram"] = "{npc:14724}, près du tram",
	["Ride on north to {area:3197} and fly to {area:2268}."] = "Continuez au nord jusqu'à {area:3197} et volez jusqu'à {area:2268}.",
	["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Des champions du Fléau (59) parcourent {area:2270}, au nord de {area:2268}. Passez {item:13156} de {npc:11063} au-dessus de chacun de ceux que vous tuez : les crânes qui résonnent sont ceux qu'il veut. Attirez-les un par un.",
	["{item:13155}, from the Scourge Champions"] = "{item:13155}, sur les champions du Fléau",
	["Chromie in Andorhal: keep it"] = "Chromie à Andorhal : gardez-le",
	["Ride north to the {area:2277}'s north-eastern edge.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Chevauchez au nord jusqu'au bord nord-est de {area:2277}.\nAttention : les trolls le long du chemin vers {area:2273} sont de niveau 57-59. Ils s'enfuient quand leur vie est basse et appellent à l'aide, ils ramènent donc souvent des renforts.",
	["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Chevauchez au sud-ouest jusqu'à {area:2261}. Le tas de terre se trouve à l'intérieur. {npc:11886} est élite : un groupe est conseillé.\nAttention : environ quatre renforts non élites arrivent avec Mercutio. Ils marchent jusqu'à la tombe au lieu d'apparaître sur place.",
	["{zone:1451}, {area:361}, {area:618} & the Plaguelands"] = "{zone:1451}, {area:361}, {area:618} et les Maleterres",
	["Ride north out of {area:415} into {area:361} to the druids' camp on the road just past the border."] = "Chevauchez au nord pour sortir de {area:415} jusqu'à {area:361}, au camp des druides sur la route juste après la frontière.",
	["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended."] = "{area:1770} est la grotte au fond de {area:1763}, à l'ouest de la route. Utilisez {item:12906} sur les quatre braseros à l'intérieur. Tuez les ours Griffe-colère et les loups Gangrepatte que vous croisez pour {item:11172}.\nAttention : des monstres du Conseil des ombres de niveau 53-55 remplissent la grotte et viennent souvent en grands groupes liés, beaucoup avec des étourdissements. Un groupe de 2 ou 3 joueurs est conseillé.",
	["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive.\nCareful: Three {quest:5086} ambush you soon after the escort starts."] = "{npc:9598} attend à {area:1767}. Escortez-la hors des bois et gardez-la en vie.\nAttention : trois {quest:5086} vous tendent une embuscade peu après le début de l'escorte.",
	["{object:176091}, if you found the Firewater flask in {area:618}"] = "{object:176091}, si vous avez trouvé la flasque d'eau-de-feu à {area:618}",
	["{quest:5085}: {npc:9298} in {area:618}, keep it"] = "{quest:5085} : {npc:9298} à {area:618}, gardez-le",
	["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "Retournez dans {area:1770} : {npc:9861} et {npc:9860} gardent {npc:9517} dans la salle la plus profonde.\nAttention : les trois chefs combattent ensemble. Tuez d'abord les monstres proches pour ne pas attirer d'ennemis en plus.",
	["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Grimpez sur {area:537} au milieu du cratère et utilisez {item:14644} près du lac de lave au sommet, avec deux barres de thorium dans vos sacs. Remplissez les bocaux à échantillon pur vides de {npc:9616} sur les limons primordiaux des mares autour de la crête.",
	["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} campe devant {area:2743}, la ruche ouest. Ramassez de la silithyste à l'un des geysers rouges tout près et apportez-la à l'extracteur de l'Alliance de son camp.\nAttention : vous perdez la silithyste si vous montez en selle, vous camouflez, utilisez {spell:642}, {spell:5384} ou Disparition. Transfert et {spell:17} ne la font pas tomber.",
	["Fly to {area:3137} in {area:16} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Volez jusqu'à {area:3137} à {area:16} et chevauchez vers l'ouest par la route jusqu'à {area:2358}, juste après la frontière de {zone:1440}.",
	["{npc:10300} waits at {area:2250}, south of {area:2255}.\nProtect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "{npc:10300} attend à {area:2250}, au sud de {area:2255}.\nProtégez {npc:10300} pendant qu'elle allume les torches en chemin vers {object:177404}.",
	["{npc:10300}: her escort comes later on the route"] = "{npc:10300} : son escorte vient plus tard sur la route",
	["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Suivez les indications de {npc:9298} jusqu'à l'entrée de {area:2256}, après les géants Cognegivre : passez-les un par un.",
	["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw; walks around here: look inside the circle on the map"] = "{npc:11558}, juste à l'entrée de la grotte : seulement à partir de Neutre avec les Grumegueules ; se promène par ici : cherchez dans le cercle sur la carte",
	["{npc:11557}, if you have thirty {quest:6031}; below ground"] = "{npc:11557}, si vous avez trente {quest:6031} ; sous terre",
	["The western Winterfall furbolgs drop the beads.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Les furbolgs Tombe-hiver de l'ouest lâchent les perles.\nAttention : le rendu fait apparaître trois ou quatre embusqués Tombe-hiver de niveau 56-57 qui vous attaquent ; vous pouvez leur échapper en monture, camouflé ou avec {spell:5384}, et ils se regroupent ensuite près du lac, ce qui vous permet de prendre la quête suivante.",
	["Take the {area:1769} tunnel from its {area:618} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Prenez le tunnel de {area:1769} depuis son entrée côté {area:618}, à l'ouest de {npc:9298}, et suivez l'embranchement de {area:493} jusqu'à {area:2361}. {npc:11939} étudie sur la rive du lac.",
	["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {quest:6031}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722} prend soixante étoffes de soie, soixante de tisse-mage et soixante {quest:6031} : rendez ce que vous portez (ou achetez à l'hôtel des ventes), passez le reste.",
	["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest.\nCareful: Jadefire Shadowstalkers are level 51-52 and move stealthed. They use {spell:7992} and are found about 550 yd south of {area:1997}.\nCareful: Jadefire Shadowstalkers sneak around and use {spell:7992}."] = "Prenez {area:2257} jusqu'à {zone:1455}. {npc:14724} et {npc:14723} prennent chacun soixante étoffes de laine, soixante de soie et soixante de tisse-mage, puis soixante {item:14047} : rendez ce que vous portez (ou achetez à l'hôtel des ventes), passez le reste.\nAttention : les traqueurs de l'ombre Feu-de-jade sont de niveau 51-52 et se déplacent furtivement. Ils utilisent {spell:7992} et se trouvent à environ 550 mètres au sud de {area:1997}.\nAttention : les traqueurs de l'ombre Feu-de-jade se faufilent et utilisent {spell:7992}.",
	["Sixty {item:2592}, if you carry them"] = "Soixante {item:2592}, si vous en portez",
	["Running {area:2057} ({area:2298}, south-east {area:28}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Faire {area:2057} ({area:2298}, sud-est de {area:28}) ou {area:2279} en groupe au lieu de tuer des monstres vous y amène plus vite. Passez cette étape pour monter seul.",
	["{npc:912}, the warrior trainer; inside"] = "{npc:912}, le maître des guerriers ; à l'intérieur",
	["{npc:8416}, by the door of {area:77}; inside"] = "{npc:8416}, à la porte de {area:77} ; à l'intérieur",
	["{npc:836}, inside {area:77}; below ground"] = "{npc:836}, dans {area:77} ; sous terre",
	["{npc:8416}, at the door on the way out; inside"] = "{npc:8416}, à la porte en sortant ; à l'intérieur",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "Suivez la route par le tunnel puis au nord-est jusqu'à {area:131}. Commencez dehors : {npc:1252} et le feu de camp d'Eric sont devant {area:2102}.",
	["Sit by Eric's campfire (type /sit) and wait for the buff."] = "Asseyez-vous près du feu de camp d'Eric (tapez /assis) et attendez l'amélioration.",
	["{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "{npc:1872} travaille à la forge à l'ouest de la distillerie.\nPuis entrez : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez les pièces de cuivre.",
	["Last: some classes' trainers stand outside"] = "Enfin : certains maîtres de classe se tiennent dehors",
	["{npc:1694}, beside him"] = "{npc:1694}, à côté de lui",
	["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "Gretchen campe juste devant {area:136}, la grotte des wendigos au sud-ouest de {area:131}.",
	["Flintfire's shipments lie on the cave floor, and {object:460004} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Les cargaisons de Flintfire gisent au sol de la grotte, et {object:460004} a disparu quelque part à l'intérieur.\nAttention : les wendigos sont serrés dans la grotte, les combats en attirent donc facilement plusieurs ; les attirer un par un avec des attaques à distance depuis l'extérieur l'évite.",
	["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "{object:176785} se trouve à côté de {npc:271546}, au sud de {area:136}.",
	["{npc:1243} camps south-west of it, by the road to Coldridge."] = "{npc:1243} campe au sud-ouest, près de la route de Frigèbre.",
	["{item:2894}, from {npc:1247}; upstairs"] = "{item:2894}, auprès de {npc:1247} ; à l'étage",
	["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Tuez les sangliers des rochers en chemin : leurs côtes tombent avant que vous ayez la quête de {npc:1267} et comptent pour elle. De retour à la distillerie : {npc:1699} enseigne {skill:185}, puis les côtes vont à {npc:1267}.",
	["{npc:1699}: Camping 101 asks you to learn it; below ground"] = "{npc:1699} : Le camping pour les nuls vous demande de l'apprendre ; sous terre",
	["{npc:1269}, by the depot; below ground"] = "{npc:1269}, près du dépôt ; sous terre",
	["{area:137} sits on the lake west of {area:131}. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "{area:137} se trouve sur le lac à l'ouest de {area:131}. Le quai de {npc:8508} est le premier arrêt ; {npc:1374} et {npc:1375} sont dans le village au-delà.",
	["{npc:8508}, on the dock"] = "{npc:8508}, sur le quai",
	["{npc:1196}, on the way to the Hold"] = "{npc:1196}, en allant au fort",
	["{npc:1127}, on the way"] = "{npc:1127}, en chemin",
	["{npc:1201}, on the way"] = "{npc:1201}, en chemin",
	["{area:135} is the troll cave in the hills south-west of {area:137}. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} est la grotte des trolls dans les collines au sud-ouest de {area:137}. Les ours Griffe-de-glace, les vieux sangliers des rochers et les léopards des neiges tués en chemin comptent pour {npc:1374}. Tuez les chasseurs de têtes à l'entrée et traversez jusqu'au fond.",
	["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373} garde les tonneaux de {item:2686} dans la cave de la distillerie. Achetez {item:2686} auprès de {npc:1247}, cliquez sur le tonneau gardé, puis donnez la bière à {npc:1373} depuis sa fenêtre de quête (il n'y a pas de quête à accepter) ; ensuite, le tonneau non gardé donne {spell:8553}.",
	["{npc:1252}: {npc:1274} in {zone:1455} takes it"] = "{npc:1252} : {npc:1274} à {zone:1455} le prend",
	["{item:2686}, from {npc:1247} in the distillery; upstairs"] = "{item:2686}, auprès de {npc:1247} dans la distillerie ; à l'étage",
	["{npc:1373}, beside the barrel; below ground"] = "{npc:1373}, à côté du tonneau ; sous terre",
	["The {object:270} in the distillery; below ground"] = "{object:270} dans la distillerie ; sous terre",
	["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "{item:2676} pousse dans des paniers en haut de {area:802}, la pente enneigée au nord de la route entre {area:131} et Brewnall : grimpez depuis la route à l'ouest de {area:131}. Les voyants Crins-de-givre qui campent sur la crête en lâchent aussi.",
	["{npc:1266} camps in {area:801}, south of the road back east from Brewnall to {area:131}. His meats are in the locker in {npc:1271}'s cave, east of his camp. {npc:1271} is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him."] = "{npc:1266} campe à {area:801}, au sud de la route qui revient de Brewnall vers {area:131} à l'est. Ses viandes sont dans le garde-manger de la grotte de {npc:1271}, à l'est de son camp. {npc:1271} est un yéti élite : attendez hors de vue qu'il parte en patrouille, puis prenez les viandes et repartez avant son retour. Inutile de le combattre.",
	["{item:2667}: the meat locker; below ground"] = "{item:2667} : le garde-manger ; sous terre",
	["Back east through {area:131}: the class quests here wait for level 10."] = "Retour à l'est par {area:131} : les quêtes de classe d'ici attendent le niveau 10.",
	["Follow the road north-east from {area:131} to the depot: the whole east of {area:1} is one sweep from here."] = "Suivez la route au nord-est depuis {area:131} jusqu'au dépôt : tout l'est de {area:1} se fait d'une traite à partir d'ici.",
	["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Les trois fusils gisent dans la neige autour du lac gelé près du refuge. Des petits élémentaires de glace dérivent autour du lac et en chemin : tuez-les au passage pour {quest:99160}.\nFinissez les petits élémentaires de glace autour du petit lac juste à l'ouest du refuge s'il vous en manque.",
	["{npc:276003}, around the small lake"] = "{npc:276003}, autour du petit lac",
	["The quarry lies just east of Farsen's ridge."] = "La carrière se trouve juste à l'est de la crête de Farsen.",
	["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Rockjaw Bonesnappers prowl the quarry and the lake; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Les embusqués Mâchoire-de-roche près de {area:212}, au nord de la carrière, et les brise-échines Mâchoire-de-roche plus à l'est lâchent {quest:95214}. Les brise-os Mâchoire-de-roche rôdent dans la carrière et près du lac ; des espions Sombrefer se faufilent sur la rive du lac. Un espion lâche {item:274268}.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:1388} est un élite de niveau 12 : la plupart des classes le battent seules au niveau 14, mais vous aurez peut-être besoin d'aide. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["On the road back west to {zone:1455}."] = "Sur la route du retour vers l'ouest jusqu'à {zone:1455}.",
	["Level 11.6"] = "Niveau 11,6",
	["If you skipped {quest:314}, grind here to level 11.6 to stay on the route's plan."] = "Si vous avez passé {quest:314}, montez ici jusqu'au niveau 11,6 pour rester dans le plan de la route.",
	["Follow the road all the way east to the {area:806} at the {area:38} tunnel."] = "Suivez la route tout à l'est jusqu'à {area:806}, au tunnel de {area:38}.",
	["Go through the tunnel into {area:38}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Passez le tunnel jusqu'à {area:38}. Juste après, un chemin balisé de pierres monte dans les collines à droite de la route, au nord, jusqu'au camp de {npc:257808}.",
	["{npc:1960} waits at the {area:808}, north of the South Gate; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960} attend à {area:808}, au nord de la porte Sud ; le cadavre du nain gît en haut du col, à l'ouest de lui.",
	["Instead of walking back up to {area:1537}, go east through the South Gate tunnel into {area:38} and follow the road north to {area:144}. {npc:1681} stands on the east side of town, past the {area:2101}; his errand pays for a flight back to {area:1537}."] = "Au lieu de remonter à pied jusqu'à {area:1537}, passez par le tunnel de la porte Sud vers l'est jusqu'à {area:38} et suivez la route au nord jusqu'à {area:144}. {npc:1681} se tient à l'est de la ville, après {area:2101} ; sa course paie un vol de retour vers {area:1537}.",
	["{npc:1572}, the gryphon master"] = "{npc:1572}, le maître des griffons",
	["{npc:1573}, the gryphon master where you landed"] = "{npc:1573}, le maître des griffons là où vous avez atterri",
	["Inn and flight master"] = "Auberge et maître de vol",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, {npc:6179} et {npc:6178} à son étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Ressortez de {zone:1455} et prenez la route vers l'est jusqu'à {area:212}. {npc:6177} gît mort sur la rive : utilisez {item:6866} sur lui. Les espions Sombrefer qui se faufilent autour du lac portent le texte.",
	["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090} est dans {object:32390}, {npc:258785} dans {object:32386}, {npc:6120} dans {object:32383}.",
	["{npc:270459} in {zone:1416}; {area:1} has no druid trainer"] = "{npc:270459} à {zone:1416} ; {area:1} n'a pas de maître des druides",
	["{npc:1274}, in the {object:171709} with King Magni"] = "{npc:1274}, dans {object:171709} avec le roi Magni",
	["{npc:376} is in the Cathedral of Light."] = "{npc:376} est dans la cathédrale de la Lumière.",
	["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:40} is next, west of {area:87}."] = "Retour auprès de {npc:6122}. Utilisez {item:6928} au cercle d'invocation de la cave de {object:2164} et battez le marcheur du Vide qu'il appelle. {area:40} est la suite, à l'ouest de {area:87}.",
	["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}.\n{npc:1872} works the forge west of the distillery.\nThen go in: {npc:6806}, the innkeeper, {npc:1226} and {npc:1267}. {npc:1699}'s {skill:185} lesson waits for the return with the ribs, when the copper is there for it."] = "Suivez la route par le tunnel puis au nord-est jusqu'à {area:131}. Commencez dehors : {npc:1252} et le feu de camp d'Eric sont devant {area:2102}.\n{npc:1872} travaille à la forge à l'ouest de la distillerie.\nPuis entrez : {npc:6806}, l'aubergiste, {npc:1226} et {npc:1267}. La leçon de {skill:185} de {npc:1699} attend le retour avec les côtes, quand vous aurez les pièces de cuivre.",
	["Level 11.41"] = "Niveau 11,41",
	["If you skipped {quest:314}, grind here to level 11.41 to stay on the route's plan."] = "Si vous avez passé {quest:314}, montez ici jusqu'au niveau 11,41 pour rester dans le plan de la route.",
	["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, Tiza and Muiredon on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {area:1} drop it, and the Auction House sells it."] = "Suivez la route jusqu'à {zone:1455} et prenez {object:32362} : {npc:5149}, {npc:6179} et {npc:6178} sont dans {object:32386}, Tiza et Muiredon à son étage : l'escalier part juste au nord-est de {npc:5149}. {npc:6175}, un mendiant, erre dans la ville. Il demande dix {item:2589} : les troggs et les trolls de {area:1} en lâchent, et l'hôtel des ventes en vend.",
	["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {area:40}: fill {item:7207} at its base."] = "Quittez {zone:1453} par la grande porte. La cascade de {quest:1861} se trouve au sud-ouest des portes, sur le chemin de {area:40} à l'ouest : remplissez {item:7207} à son pied.",
	["{npc:247229}, in the library; inside"] = "{npc:247229}, dans la bibliothèque ; à l'intérieur",
	["{npc:911}, the warrior trainer; inside"] = "{npc:911}, le maître des guerriers ; à l'intérieur",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:248362} (élite de niveau 3) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 5.48"] = "Niveau 5,48",
	["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, montez ici jusqu'au niveau 5,48 pour rester dans le plan de la route.",
	["Level 5.77"] = "Niveau 5,77",
	["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Si vous avez passé {quest:91752}, montez ici jusqu'au niveau 5,77 pour rester dans le plan de la route.",
	["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Asseyez-vous (/assis) près de son feu de camp jusqu'à obtenir {spell:1229451}",
	["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306} : pour les dépeceurs seulement, les peaux se dépècent ; à l'intérieur",
	["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430} : Le camping pour les nuls vous demande de l'apprendre ; sous terre",
	["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "La ferme des Champierreux se trouve à l'ouest de la mine. M'man et « tante » Bernice se tiennent près de la maison.\nElle est assise dans la ferme.",
	["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "{object:694855} pousse dans les champs autour des vignes et de la ferme des Champierreux ; les sangliers Rochefendre alentour donnent le sang.\nLes sangliers Rochefendre broutent entre les vignes et la ferme.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {npc:248464} (élite de niveau 6) demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 8.39"] = "Niveau 8,39",
	["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Si vous avez passé {quest:91775}, montez ici jusqu'au niveau 8,39 pour rester dans le plan de la route.",
	["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} à {zone:1426} ; {area:87} n'a pas de maître des chamans",
	["{npc:270459} in {zone:1416}; {area:87} has no druid trainer"] = "{npc:270459} à {zone:1416} ; {area:87} n'a pas de maître des druides",
	["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. {npc:248278} roams the murloc shore along the river too: right-click the head it drops. {npc:248278} is elite: grouping up is advised."] = "{item:247813}, la hache et la boîte à outils gisent dans la rivière au sud du pont. {npc:330}, une grosse laie, fouille le sol dans {area:62} à l'ouest de la rivière avec ses {npc:390} : éloignez d'abord les marcassins. Tuez des rôdeurs et des jeunes ours des forêts en chemin. {npc:248278} parcourt aussi la rive des murlocs le long de la rivière : faites un clic droit sur la tête qu'il lâche. {npc:248278} est élite : un groupe est conseillé.",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "Ce sont des monstres élites : un groupe est conseillé, cherchez des joueurs avec qui la faire. {quest:91740} demande un groupe de 2. Passez-la si vous êtes seul : la route vous fait regagner l'expérience.",
	["Level 8.85"] = "Niveau 8,85",
	["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Si vous avez passé {quest:91740}, montez ici jusqu'au niveau 8,85 pour rester dans le plan de la route.",
	["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Suivez la route vers l'est après {area:91} jusqu'au pont. Finissez les rôdeurs et les jeunes ours des forêts autour de la rivière au sud.",
	["{npc:240}, while William brews"] = "{npc:240}, pendant que William fait son infusion",
	["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377} : {npc:376} à {zone:1453} prend les deux",
	["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Des avortons et des coursiers Rivepatte tiennent les collines au sud de la garnison, le long de la frontière de {zone:1436}.",
	["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, à côté d'elle : {spell:5149}",
	["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955} : il veut votre {item:247824} ; à l'intérieur",
	["{npc:1984} along the way to Back at {area:256}"] = "{npc:1984} en allant vers Retour à {area:256}",
	["{npc:3593}, the warrior trainer; inside"] = "{npc:3593}, le maître des guerriers ; à l'intérieur",
	["{npc:3595}, the priest trainer: in at the tree's front entrance and up the ramp"] = "{npc:3595}, la maîtresse des prêtres : entrez par l'entrée principale de l'arbre et montez la rampe",
	["{npc:3595}: in at the tree's front entrance and up the ramp; upstairs"] = "{npc:3595} : entrez par l'entrée principale de l'arbre et montez la rampe ; à l'étage",
	["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979} : lancez {spell:1259799} et Camouflage dans l'ombre, puis rendez-la à {npc:3595}",
	["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside."] = "Des sabres-de-nuit galeux et des sangliers des chardons parcourent le nord de {area:256}, sur le chemin de la grotte. {npc:1994} se tient tout au fond.",
	["{npc:8584} waits in the trees west of the cave mouth."] = "{npc:8584} attend dans les arbres à l'ouest de l'entrée de la grotte.",
	["Webwood Spiders; below ground"] = "Araignées Tisse-bois ; sous terre",
	["The moonwell sits north of {area:256}."] = "Le puits de lune se trouve au nord de {area:256}.",
	["{npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "{npc:8584} est un peu plus au nord-ouest. {quest:3522} dure cinq minutes : remplissez la fiole et allez directement le voir.",
	["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "/assis près du feu de camp de {npc:265811} jusqu'à obtenir {spell:1229451}",
	["{npc:6286}, south of the inn: Camping 101 asks you to learn it"] = "{npc:6286}, au sud de l'auberge : Le camping pour les nuls vous demande de l'apprendre",
	["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "Des sabres-de-nuit, des chouettes strigides et des rôdeuses Tisse-bois parcourent les environs de {area:186} et la route vers l'est ; les rôdeuses lâchent aussi les pattes d'araignée de la recette. Le puits de lune est au bord ouest de {area:260}.",
	["North from the lake to {npc:2150}, on the road back to {area:186}."] = "Au nord depuis le lac jusqu'à {npc:2150}, sur la route du retour vers {area:186}.",
	["{npc:2107} stands in the village, east of the moonwell. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} se tient dans le village, à l'est du puits de lune. {object:126158} est dans la maison sur la colline à l'extrémité est du village.",
	["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Au sud-ouest de Brise-étoile, au sud de {npc:2150}. {npc:2080} soigne ses jeunes arbres sur la rive ; des pousses de fouetteur et des sylvains errent autour de lui, et {quest:919} pousse parmi eux.",
	["{npc:7318}, in the den; walks around {area:736}: look inside the circle on the map"] = "{npc:7318}, dans la tanière ; se promène autour de {area:736} : cherchez dans le cercle sur la carte",
	["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Des pommes de gangrepin gisent sous les arbres tout autour de {area:186} et de {npc:2150} : ramassez-les sur la route de l'est et donnez-les à {npc:2150} en allant voir {npc:7234}.",
	["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Les mystiques Pin-tordu et {npc:7234} campent au nord-est de {area:260}. {npc:7234} lâche {item:8049} : ouvrez-le pour le joyau.\nAttention : {npc:7234} attend près du feu de camp, entouré de mystiques ; difficile de l'attirer sans renforts.",
	["The Bloodfeather harpies nest on the slopes west and north of the glade.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "Les harpies Plume-sanglante nichent sur les pentes à l'ouest et au nord de la clairière.\nAttention : les harpies sont serrées, d'autres rejoignent donc souvent le combat. Des lanceuses de sorts sont mêlées aux autres.",
	["Use the {item:18152} at the moonwell"] = "Utilisez {item:18152} au puits de lune",
	["the same {object:673378}: Fandral in {zone:1457} takes it"] = "le même {object:673378} : Fandral à {zone:1457} le prend",
	["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Descendez au sud par le côté ouest de l'île. Ursal rôde tout au sud, sous {area:478}.\nAttention : des Pin-tordu d'environ niveau 9-12 remplissent le camp, serrés les uns contre les autres ; il est facile d'en attirer plusieurs à la fois. Affrontez-les un par un avant d'engager Ursal.",
	["{npc:3598}, the warrior trainer: {quest:1684} in {zone:1457} takes it"] = "{npc:3598}, le maître des guerriers : {quest:1684} à {zone:1457} le prend",
	["{npc:3567}, back in {area:186}; upstairs"] = "{npc:3567}, de retour à {area:186} ; à l'étage",
	["{npc:6094} takes a {item:159} with the fronds and the vial: if you drank yours, buy another from {npc:6736} in this inn before you hand in."] = "{npc:6094} prend {item:159} avec les frondes et la fiole : si vous avez bu la vôtre, achetez-en une autre auprès de {npc:6736} dans cette auberge avant de rendre.",
	["{quest:1684} stands on the {area:1660}, just inside the city."] = "{quest:1684} se tient sur {area:1660}, juste à l'entrée de la ville.",
	["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Ressortez par la porte de la ville et prenez la route vers l'est : {quest:1683} se tient au sud, près de {area:736}. Rapportez son cor à {quest:1684}.",
	["{npc:4088}, on the {area:1660}: {spell:71}"] = "{npc:4088}, sur {area:1660} : {spell:71}",
	["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, à {area:1658} : {spell:5149}",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; l'arme de mêlée d'un chasseur vaut surtout par ses caractéristiques, et les armes à deux mains en portent le plus.",
	["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Tant que vous êtes ici : apprenez les bâtons auprès de {npc:11866} ({area:1660}, 10 pièces d'argent) ; un bâton porte plus de caractéristiques de sorts qu'une arme à une main pendant la montée en niveau.",
	["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Prenez le portail qui descend à {area:702}. {npc:10118} se tient sur le quai, {npc:3838} près des hippogriffes. Une fois {quest:6342} obtenue, reparlez à {npc:3838} et choisissez le vol vers {area:442} : il est gratuit et atterrit à côté de {npc:4200}. Si la carte des vols s'ouvre à la place, fermez-la et reparlez-lui en maintenant Maj.",
	["talk to {npc:3838} again: free with {quest:6342}"] = "reparlez à {npc:3838} : gratuit avec {quest:6342}",
	["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Apprenez la route aérienne auprès de {npc:3841} à l'atterrissage. L'étal de poissons de {npc:4200} est juste au nord d'elle, près des quais.\nLe bateau accoste à l'ouest du village. Le maître de vol se tient sur la colline au sud de l'auberge ; les donneurs de quêtes sont répartis le long de la rue principale.",
	["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442} for the boat."] = "Revenez en vol à {area:702} depuis {npc:3841}, donnez {item:16263} à {npc:10118} sur le quai, puis revolez jusqu'à {area:442} pour le bateau.",
	["Tide Crawlers scuttle along the shore below the village; {object:17182} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Des rampants des marées trottinent sur le rivage sous le village ; {object:17182} se dresse sur la plage juste au sud des quais. Des batteurs de Sombrivage nagent dans les hauts-fonds. {object:175207} se trouve sur le rivage juste au sud du village.",
	["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed."] = "Lancez {spell:18960}. {npc:11802} est à {area:2361} ; {quest:5929} se trouve dans les bois au nord-ouest. Puis {npc:11800}, à {area:2361}, emmène les druides directement à {area:702}, sans route aérienne.",
	["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "{npc:10118} se tient sur le quai de Rut'theran où vous atterrissez. Puis prenez le portail qui monte auprès de {npc:4217} à {area:1658}.",
	["Take the boat to {zone:1453} from {area:442}'s docks."] = "Prenez le bateau pour {zone:1453} depuis les quais de {area:442}.",
	["From {area:17203}, head through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "Depuis {area:17203}, passez les portes de la ville vers {zone:1429} et suivez la route vers l'ouest jusqu'à {zone:1436}.",
	["Rabid Thistle Bears roam the hills just east of {area:442}. Use {item:7586} on one and lead it back to him."] = "Des ours chardon enragés parcourent les collines juste à l'est de {area:442}. Utilisez {item:7586} sur l'un d'eux et ramenez-le-lui.",
	["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {object:17183} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Au nord par les collines. {npc:3650} attend dans les ruines de {quest:954} ; des grells sauvages et des esprits malfaisants les remplissent, des satyres Deth'ryll le bord est. {object:17183} se dresse près de la route à l'ouest des ruines ; {quest:4723} se trouve sur le rivage en allant le voir.",
	["Follow the road south. Onu is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "Suivez la route vers le sud. Onu est l'ancien du Bosquet ; {npc:270269} et {npc:11218} dorment à côté de lui.",
	["Follow the coast north-east to the {area:443}. Mathystra Relics lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Suivez la côte au nord-est jusqu'à {area:443}. Des reliques de Mathystra gisent parmi les ruines ; des myrmidons, des ensorceleuses et des guerriers Écaille-tempête les tiennent, et des maîtresses des bêtes Écaille-tempête arpentent le rivage.",
	["Hearthstone on cooldown? Follow the coast road back south."] = "Pierre de foyer pas encore prête ? Suivez la route côtière vers le sud.",
	["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} et {npc:263113} se tiennent au sommet de la tour de guet, à quelques pas au nord-est de {npc:251368}.",
	["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Sautez du haut de la tour de guet et utilisez {spell:1259416} pour descendre en planant jusqu'à {npc:251361}, à l'ouest de la tour.",
	["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} monte la garde à l'est du bosquet. {npc:251143} et les convertis d'Al'Aketh se rassemblent juste au nord d'elle ; {object:460002} s'élève plus au nord : lancez-y votre capacité raciale {spell:1259705}.",
	["Cast {spell:1259705} at the {object:460002}"] = "Lancez {spell:1259705} sur {object:460002}",
	["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle.\nCareful: {npc:256935} casts shocks; drag him clear of the other cultists before fighting so they don't join in."] = "{npc:252095} campe au sud de la tanière d'Ursera. Les brutes d'Al'Aketh tiennent le camp au sud-ouest d'elle ; {npc:256935} se tient au milieu.\nAttention : {npc:256935} lance des horions ; éloignez-le des autres cultistes avant de combattre pour qu'ils ne le rejoignent pas.",
	["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/assis près du feu de camp de {npc:263664} jusqu'à obtenir {spell:1229451}",
	["{npc:251905}: Camping 101 asks you to learn it"] = "{npc:251905} : Le camping pour les nuls vous demande de l'apprendre",
	["{npc:251918} along the way to Shen'dar turn-ins"] = "{npc:251918} en allant vers les rendus de Shen'dar",
	["\"Badwind\" Bennic, below ground"] = "« Malvent » Bennic, sous terre",
	["{npc:5148} in {zone:1455}; {area:16624} has no paladin trainer"] = "{npc:5148} à {zone:1455} ; {area:16624} n'a pas de maître des paladins",
	["Priest trainer"] = "Maître des prêtres",
	["Lariia in {zone:1438}; {area:16624} has no priest trainer"] = "Lariia à {zone:1438} ; {area:16624} n'a pas de maître des prêtres",
	["{npc:258098} in {zone:1455}; {area:16624} has no shaman trainer"] = "{npc:258098} à {zone:1455} ; {area:16624} n'a pas de maître des chamans",
	["Warlock trainer"] = "Maître des démonistes",
	["{item:2450} in {zone:1455}; {area:16624} has no warlock trainer"] = "{item:2450} à {zone:1455} ; {area:16624} n'a pas de maître des démonistes",
	["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} attend à l'entrée de {quest:92529}, au sud de Shen'dar. {spell:1254832} vous permet de marcher parmi les fidèles.",
	["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them.\nThe Novice Seers practise in the clearing west of Shen'dar."] = "Partez au nord-ouest jusqu'aux nids d'hippogriffes sur les falaises ouest. {item:263493} se trouve autour des nids ; la matriarche patrouille parmi eux.\nLes voyants novices s'entraînent dans la clairière à l'ouest de Shen'dar.",
	["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "{npc:257006} et {npc:252448} se tiennent du côté ouest de {area:16638}, à côté de l'auberge ; {npc:252377} et {npc:252389} s'entraînent juste à l'ouest de {npc:257006}. Des rampants Chant-du-vent bordent le rivage plus à l'ouest, vers 51,70.",
	["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "{npc:252377}, à côté de {npc:257006} : {npc:257196} tient le Rempart à {area:16629}",
	["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "{npc:252389}, à côté de {npc:257006} : le premier {item:15908}",
	["Innkeeper {npc:255940}, by the west gate"] = "L'aubergiste {npc:255940}, près de la porte ouest",
	["The {object:581822} lies by the path west of {area:16638}."] = "{object:581822} se trouve près du chemin à l'ouest de {area:16638}.",
	["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "{npc:254588}, parmi les crabes : apprivoisez-en un avec le premier {item:15908} de {npc:252389} tant que vous y êtes",
	["Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "Le camp de Fillion est au nord-ouest, et les matriarches criardes nichent juste à l'ouest du camp.",
	["{npc:252389} takes back the first {item:15908} and hands you two more, one at a time: Ornery Galestriders and Vuldren Alphas roam the fields just north of her. Tame each with its rod and bring the rod back to her. {npc:254411}, beside her, teaches {spell:5149}."] = "{npc:252389} reprend le premier {item:15908} et vous en donne deux autres, un par un : des coursiers du vent grincheux et des alphas vuldren parcourent les champs juste au nord d'elle. Apprivoisez chacun avec son bâtonnet et rapportez-lui le bâtonnet. {npc:254411}, à côté d'elle, enseigne {spell:5149}.",
	["{item:262668}: by the formations"] = "{item:262668} : près des formations",
	["{npc:252359}, the druid trainer, stands between the west gate and Valennia's house."] = "{npc:252359}, le maître des druides, se tient entre la porte ouest et la maison de Valennia.",
	["{npc:252359}: {quest:94006} (level 10)"] = "{npc:252359} : {quest:94006} (niveau 10)",
	["{npc:5148} in {zone:1455}; {area:16638} has no paladin trainer"] = "{npc:5148} à {zone:1455} ; {area:16638} n'a pas de maître des paladins",
	["{npc:5141} in {zone:1455}; {area:16638} has no priest trainer"] = "{npc:5141} à {zone:1455} ; {area:16638} n'a pas de maître des prêtres",
	["{npc:258098} in {zone:1455}; {area:16638} has no shaman trainer"] = "{npc:258098} à {zone:1455} ; {area:16638} n'a pas de maître des chamans",
	["{item:2450} in {zone:1455}; {area:16638} has no warlock trainer"] = "{item:2450} à {zone:1455} ; {area:16638} n'a pas de maître des démonistes",
	["Meet {npc:253844} at the gate"] = "Retrouvez {npc:253844} à la porte",
	["{npc:255853}, by the falls north-east of {area:16638}, on the way north: {spell:5487}"] = "{npc:255853}, près des chutes au nord-est de {area:16638}, sur le chemin du nord : {spell:5487}",
	["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:254151}, {npc:258130} et {npc:258134} sont au nord-est de {npc:257944} ; {npc:253622} se tient à leur est. Haalien lâche aussi {quest:94490}. Pour {quest:94489}, entrez dans la tanière des Croc-de-nuit, soignez 7 druides blessés et trouvez {npc:258130}.",
	["{item:263993}: {npc:257196} holds it, west of the shrine's approach; defeat him for it on the way in"] = "{item:263993} : {npc:257196} le détient, à l'ouest de l'accès au sanctuaire ; battez-le pour l'obtenir en entrant",
	["{npc:253590}, in the sanctum; upstairs"] = "{npc:253590}, dans le sanctuaire ; à l'étage",
	["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "Lorthuna attend en haut de {area:16630}, à l'est du sanctuaire : prenez le portail vers {area:16630} dans le sanctuaire intérieur, à côté de Valennia, et traversez les hauteurs vers l'est jusqu'à {npc:252475}. Quand elle tombe, {object:617084} à côté d'elle vous ramène en ville.",
	["{npc:252475} sends you on to {area:279}. Once you have trained, take the skycutter from the dock tower just south of {area:16638}: it lands by the Kirin Tor camp west of {area:279}, beside {npc:259084} and the Skyborne Portal."] = "{npc:252475} vous envoie à {area:279}. Une fois entraîné, prenez le coupe-ciel à la tour du quai juste au sud de {area:16638} : il atterrit près du camp du Kirin Tor à l'ouest de {area:279}, à côté de {npc:259084} et du portail céleste.",
	["Leave {zone:2521} to {zone:1416}"] = "Quitter {zone:2521} pour {zone:1416}",
	["{npc:259084} stands beside the Skyborne Portal, where the skycutter lands by the Kirin Tor camp west of {area:279}. The portal takes you to {zone:1453}."] = "{npc:259084} se tient à côté du portail céleste, là où le coupe-ciel atterrit près du camp du Kirin Tor à l'ouest de {area:279}. Le portail vous emmène à {zone:1453}.",
	["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {area:40}."] = "Bolvar Fordragon se tient dans la salle du trône de {object:2117}, à l'extrémité nord de la ville. Puis sortez par la grande porte vers {area:40}.",
	["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, le maître des druides de {zone:1453}, vous enseigne {spell:18960}. L'accueil de {npc:11802} attend votre voyage par {spell:499} à la fin de {zone:1439}.",
	["{npc:14725} takes cloth for {faction:69}; he stands in the {area:1659}, in the north-east of {faction:69}, by the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7801} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the {area:1662} is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1438} (levels 1-12), {zone:1439} (11-20) and {zone:1440} (18-30) while you level through them. After the donations come {quest:4183} in the {zone:1428} and {item:11040}, a second repeatable turn-in; then the optional hubs, best rate first: {area:188} (about 35 a minute at full value), {area:186} (28), {area:442} (23). Every {faction:69} gain also gives a quarter as much to {zone:1453}, {zone:1455} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14725} prend les tissus pour {faction:69} ; il se tient à {area:1659}, au nord-est de {faction:69}, près des tailleurs. Chaque premier don de 60 laine, soie, tisse-mage et {item:14047} rapporte 150 de réputation une seule fois ; après celui de {item:14047}, {quest:7801} rapporte 50 pour 20 {item:14047}, autant de fois que vous le voulez. L'hôtel des ventes de {area:1662} est le moyen le plus rapide de trouver du tissu. Dans Classic, les quêtes rapportent toute leur réputation tant qu'elles sont au plus 5 niveaux sous le vôtre : faites donc {zone:1438} (niveaux 1-12), {zone:1439} (11-20) et {zone:1440} (18-30) en montant de niveau. Après les dons viennent {quest:4183} dans {zone:1428} et {item:11040}, un second don répétable ; puis les zones facultatives, la plus rentable d'abord : {area:188} (environ 35 par minute à plein tarif), {area:186} (28), {area:442} (23). Chaque gain auprès de {faction:69} en donne aussi un quart à {zone:1453}, {zone:1455} et aux Exilés de Gnomeregan, sauf les quêtes des zones de départ de niveau 1-10. Diplomate d'héritage ajoute jusqu'à 10 % à chaque gain.",
	["{npc:9562} at {area:2418}, in the south-east of the {zone:1428}, starts {quest:4183}: 175 {faction:69} reputation for two quests (level 54: in Classic 140 at 60), and the chain goes on to {object:2117} for 175 {zone:1453}. The Black Broodlings and the {npc:7044} live on the slopes north of the Vigil; the {npc:7040} and {npc:7041} west of it, in the middle of the zone."] = "{npc:9562}, à {area:2418}, au sud-est de {zone:1428}, lance {quest:4183} : 175 de réputation auprès de {faction:69} pour deux quêtes (niveau 54 : dans Classic, 140 au niveau 60), et la suite mène à {object:2117} pour 175 auprès de {zone:1453}. Les dragonnets noirs et {npc:7044} vivent sur les pentes au nord du Guet ; {npc:7040} et {npc:7041} à l'ouest, au milieu de la zone.",
	["{npc:344} waits in the town hall of {area:69}; his next quest takes you to {object:2117} (the {zone:1453} guide follows it). Other {faction:69} quests at this level, for when you pass by: {npc:7916} in {area:702} has a wildkin chain into {zone:1452} (325 in all, with Ranshalla's escort), Arei's escort in {zone:1448} pays 150 after the {area:2479}'s chain, {npc:10739} at the {area:202} in the {zone:1422} 100 for the {item:12663}, and Put Her Down in Upper Blackrock Spire 100 with a group."] = "{npc:344} attend à l'hôtel de ville de {area:69} ; sa quête suivante vous mène à {object:2117} (le guide de {zone:1453} la suit). D'autres quêtes de {faction:69} à ce niveau, quand vous passez par là : {npc:7916} à {area:702} a une suite sur les sélénides qui mène à {zone:1452} (325 en tout, avec l'escorte de Ranshalla), l'escorte d'Arei à {zone:1448} rapporte 150 après la suite de {area:2479}, {npc:10739} à {area:202} dans {zone:1422} 100 pour {item:12663}, et Achevez-la dans le sommet du pic Rochenoire 100 en groupe.",
	["{quest:3803} takes 10 {item:11040} for 50, as often as you like, and pays in full at 60. The chain before it is level 50 (in Classic a fifth at 60): 220 at full. {npc:6735} sends you to {npc:3516} in the {area:1658}; he wants 20 {quest:3764}. (The innkeepers of {zone:1453} and {zone:1455} give the same start.)"] = "{quest:3803} prend 10 {item:11040} pour 50, autant de fois que vous le voulez, et paie en entier au niveau 60. La suite qui la précède est de niveau 50 (dans Classic, un cinquième au niveau 60) : 220 à plein tarif. {npc:6735} vous envoie voir {npc:3516} à {area:1658} ; il veut 20 {quest:3764}. (Les aubergistes de {zone:1453} et de {zone:1455} donnent le même départ.)",
	["{npc:9047}, beside Fandral in the {area:1658}, takes the soil. {npc:4217} sells the {item:11020} and Packets of Tharlendris Seeds. With a seed packet and 2 {quest:3764} in your bags, use the pouch to grow an {item:11024} and open it: about one casing in three holds {item:11040} (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things."] = "{npc:9047}, à côté de Fandral à {area:1658}, prend la terre. {npc:4217} vend {item:11020} et des sachets de graines de Tharlendris. Avec un sachet de graines et 2 {quest:3764} dans vos sacs, utilisez la bourse pour faire pousser une {item:11024}, puis ouvrez-la : environ une enveloppe sur trois contient {item:11040} (1 à 5), les autres d'autres herbes. La bourse ne sert qu'une fois toutes les 10 minutes : utilisez-la dès qu'elle est prête pendant que vous faites autre chose.",
	["Every 10 {item:11040}: 50 reputation at {npc:4217}. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 {quest:3764} and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the {item:14047}. {npc:7879} at {area:1116} in {zone:1444} takes {item:11040} at the same rate, 25 for 5, after his own quest."] = "Toutes les 10 {item:11040} : 50 de réputation auprès de {npc:4217}. Gardez la bourse et achetez des graines au fur et à mesure. C'est lent : environ 9 enveloppes, 90 minutes d'attente de la bourse, 18 {quest:3764} et 9 sachets de graines pour chaque don, soit un peu plus de 30 de réputation par heure : faites-le en parallèle de {item:14047}. {npc:7879}, à {area:1116} dans {zone:1444}, prend {item:11040} au même tarif, 25 pour 5, après sa propre quête.",
	["Optional: the Night Elf start glade in north-east {zone:1438}, about 1,050 reputation (210 at a fifth) in 30 minutes at 60. The givers stand around {area:256}, the great tree. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : la clairière de départ des Elfes de la nuit au nord-est de {zone:1438}, environ 1 050 de réputation (210 au cinquième) en 30 minutes au niveau 60. Les donneurs se tiennent autour de {area:256}, le grand arbre. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["{area:188}: the glade and the spider den"] = "{area:188} : la clairière et l'antre des araignées",
	["The nightsabers and boars roam the glade; the grells around {area:256} drop the {item:3297}; the totems stand in the furbolg camp north-west of the tree; the Webwood spiders live in the cave north of the glade. {npc:8584} waits outside that cave."] = "Les sabres-de-nuit et les sangliers parcourent la clairière ; les grells autour de {area:256} lâchent {item:3297} ; les totems sont dans le camp des furbolgs au nord-ouest de l'arbre ; les araignées Toilebois vivent dans la grotte au nord de la clairière. {npc:8584} attend devant cette grotte.",
	["{area:188}: first hand-in"] = "{area:188} : premier rendu",
	["{area:188}: the egg and the antidote"] = "{area:188} : l'œuf et l'antidote",
	["{area:186}: {npc:2080} and the lake"] = "{area:186} : {npc:2080} et le lac",
	["{npc:2080} tends his garden on the south-east shore of {area:259}; {npc:2107} stands upstairs in a house in {area:260}, east of {area:186}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2080} s'occupe de son jardin sur la rive sud-est de {area:259} ; {npc:2107} se tient à l'étage d'une maison de {area:260}, à l'est de {area:186} : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["{area:186}: the woods around the village"] = "{area:186} : les bois autour du village",
	["The timberlings by the lake drop seeds and sprouts; the Gnarlpine Ambushers lurk on the road west to {faction:69}; {npc:2038} waits deep in {area:258}, north-west of the village; the dreamcatcher lies in the furbolg camp east of the village, by {npc:2107}; the Nightsabers west of the village carry the pelts."] = "Les sylvains près du lac lâchent graines et pousses ; les embusqués Pin-Tordu guettent sur la route de {faction:69}, à l'ouest ; {npc:2038} attend au fond de {area:258}, au nord-ouest du village ; l'attrape-rêves est dans le camp des furbolgs à l'est du village, près de {npc:2107} ; les sabres-de-nuit à l'ouest du village portent les peaux.",
	["{area:186}: first hand-in"] = "{area:186} : premier rendu",
	["{area:186}: the relics and Ferocitas"] = "{area:186} : les reliques et Ferocitas",
	["The four relics of Wakening lie in the {area:262}, south-west of {area:186}; Ferocitas and the Gnarlpine Mystics camp east of the village."] = "Les quatre reliques de l'Éveil sont dans {area:262}, au sud-ouest de {area:186} ; Ferocitas et les mystiques Pin-Tordu campent à l'est du village.",
	["{quest:486}, a big bear, roams the {area:478} in south-west {zone:1438}."] = "{quest:486}, un gros ours, parcourt {area:478} au sud-ouest de {zone:1438}.",
	["Optional: {area:442} in {zone:1439}, a boat trip from {area:702}, about 1,400 reputation (280 at a fifth) in an hour at 60. The givers stand along the town's street and pier. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : {area:442} dans {zone:1439}, à un trajet en bateau de {area:702}, environ 1 400 de réputation (280 au cinquième) en une heure au niveau 60. Les donneurs se tiennent le long de la rue et de la jetée. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["{area:442}: the coast and the woods"] = "{area:442} : la côte et les bois",
	["The furbolg camp south of town counts for How Big a Threat; the Rabid Thistle Bears roam the woods south of town; the Highborne ghosts of the Ruins of Ameth'Aran, south-east of town, carry the relics, and Anaya's ghost walks there too; the bones lie on the beach south of town; the mushrooms grow in the {area:445} cave to the north-east."] = "Le camp des furbolgs au sud de la ville compte pour Une menace de quelle ampleur ; les ours chardons enragés parcourent les bois au sud de la ville ; les fantômes bien-nés des ruines d'Ameth'Aran, au sud-est de la ville, portent les reliques, et le fantôme d'Anaya s'y promène aussi ; les os sont sur la plage au sud de la ville ; les champignons poussent dans la grotte de {area:445}, au nord-est.",
	["{area:442}: first hand-in"] = "{area:442} : premier rendu",
	["{area:442}: the furbolgs, the bears and the grells"] = "{area:442} : les furbolgs, les ours et les grells",
	["{area:442}: second hand-in"] = "{area:442} : second rendu",
	["{area:442}: the seal, the {npc:6788} and the pelts"] = "{area:442} : le sceau, {npc:6788} et les peaux",
	["{quest:7801}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). {quest:4183} and the {item:11040} chain above take 8 turn-ins off, and every 10 {item:11040} you hand in counts as one more; each hub you did takes 20 to 28 more off if it paid in full. More quests pay {faction:69}, in full while they are no more than 5 levels below you: the rest of {zone:1439} (about 3,400 more), {area:415} in {zone:1440} (about 3,900) and Feathermoon in {zone:1444} (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7801} : 50 de réputation pour 20 {item:14047}, autant de fois que vous le voulez. Après les quatre premiers dons, un Humain, un Nain ou un Gnome est à Amical 700 sur 6 000 : Honoré est donc à 5 300, soit 106 rendus, 2 120 {item:14047} (les Elfes de la nuit partent 900 plus haut : 88 rendus ; les Célestes partent de Neutre 500, donc 7 900 : 158, deux de moins après Explorer l'Alliance). {quest:4183} et la suite de {item:11040} ci-dessus en retirent 8, et chaque lot de 10 {item:11040} rendu compte pour un de plus ; chaque zone faite en retire 20 à 28 de plus si elle a payé en entier. D'autres quêtes rapportent de la réputation auprès de {faction:69}, en entier tant qu'elles ne sont pas plus de 5 niveaux sous le vôtre : le reste de {zone:1439} (environ 3 400 de plus), {area:415} dans {zone:1440} (environ 3 900) et Pennelune dans {zone:1444} (environ 1 700). Chaque gain auprès d'une ville en donne aussi un quart aux trois autres villes de l'Alliance (non compté ici). Rendez tout votre {item:14047} d'un coup.",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, Lelanai at the {area:1658} in {faction:69} sells her nightsabers to other races in Classic; the Saber and Swift Saber guides cover them."] = "De Révéré à Exalté, il faut 21 000 de réputation : 420 rendus, 8 400 {item:14047}. À Exalté, Lelanai, à {area:1658} à {faction:69}, vend ses sabres-de-nuit aux autres races dans Classic ; les guides Sabre et Sabre rapide en parlent.",
	["{npc:14724} takes cloth for the {faction:54}; he stands in {object:171524} in {zone:1455}, by the tram. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7812} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12) and {npc:4077}'s quests in Stonetalon (20-25) while you level. After the donations come {npc:9616}'s ooze quests and {quest:4262} (400), then the optional {zone:1426} hubs, best rate first: {area:132} (about 38 a minute at full value), {area:131} (26), the quarry (17). Every {area:133} gain also gives a quarter as much to {zone:1453}, {zone:1455} and {zone:1457}, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14724} prend les tissus pour {faction:54} ; il se tient dans {object:171524} à {zone:1455}, près du tram. Chaque premier don de 60 laine, soie, tisse-mage et {item:14047} rapporte 150 de réputation une seule fois ; après celui de {item:14047}, {quest:7812} rapporte 50 pour 20 {item:14047}, autant de fois que vous le voulez. L'hôtel des ventes de la Halle est le moyen le plus rapide de trouver du tissu. Dans Classic, les quêtes rapportent toute leur réputation tant qu'elles sont au plus 5 niveaux sous le vôtre : faites donc {zone:1426} (niveaux 1-12) et les quêtes de {npc:4077} dans les Serres-Rocheuses (20-25) en montant de niveau. Après les dons viennent les quêtes de vase de {npc:9616} et {quest:4262} (400), puis les zones facultatives de {zone:1426}, la plus rentable d'abord : {area:132} (environ 38 par minute à plein tarif), {area:131} (26), la carrière (17). Chaque gain auprès de {area:133} en donne aussi un quart à {zone:1453}, {zone:1455} et {zone:1457}, sauf les quêtes des zones de départ de niveau 1-10. Diplomate d'héritage ajoute jusqu'à 10 % à chaque gain.",
	["{npc:9616} in {object:171524} wants ooze samples for her research: 150 {area:133} reputation for each of her two quests (level 52 and 54: in Classic 60 and 120 of it at 60). She hands you the empty jars."] = "{npc:9616}, dans {object:171524}, veut des échantillons de vase pour ses recherches : 150 de réputation auprès de {area:133} pour chacune de ses deux quêtes (niveau 52 et 54 : dans Classic, 60 et 120 au niveau 60). Elle vous donne les bocaux vides.",
	["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill one and use an empty jar on its remains."] = "Les vases maudites et souillées glissent dans les ruisseaux et les mares gangrenées autour de {area:1763} et {area:1765} : tuez-en une et utilisez un bocal vide sur ses restes.",
	["The Primal Oozes live in the pools around {area:537} in the middle of the crater; the Muculent and Glutinous Oozes fill the jars too. Kill one and use a jar on its remains."] = "Les vases primordiales vivent dans les mares autour de {area:537}, au milieu du cratère ; les vases mucilagineuses et gluantes remplissent aussi les bocaux. Tuez-en une et utilisez un bocal sur ses restes.",
	["{npc:9561} at {area:2418}, in the south-east of the {zone:1428}, wants {quest:4262} dead: 100 {area:133} reputation (level 52: in Classic 40 at 60). Her next quest, Incendius!, needs a {area:1584} group: 100 more, in full."] = "{npc:9561}, à {area:2418}, au sud-est de {zone:1428}, veut la mort de {quest:4262} : 100 de réputation auprès de {area:133} (niveau 52 : dans Classic, 40 au niveau 60). Sa quête suivante, Incendius !, demande un groupe pour {area:1584} : 100 de plus, en entier.",
	["{area:254} stands in the west of the {zone:1428}. {quest:4262}, a fire elemental, walks the lava paths inside it, near the door of {area:1584} but outside the dungeon: at 60 you take him alone."] = "{area:254} se dresse à l'ouest de {zone:1428}. {quest:4262}, un élémentaire de feu, arpente les chemins de lave à l'intérieur, près de la porte de {area:1584} mais hors du donjon : au niveau 60, vous le battez seul.",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,150 reputation (230 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : la vallée de départ des Nains et des Gnomes, au sud-ouest de {area:131}, environ 1 150 de réputation (230 au cinquième) en 30 minutes au niveau 60. {npc:658} et {npc:713} se tiennent à {area:77}. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["The wolves roam the valley floor; the troggs dig in the camps east of {area:77}; {npc:8416}'s box, chest and bucket lie in the trogg camps."] = "Les loups parcourent le fond de la vallée ; les troggs creusent dans les camps à l'est de {area:77} ; la boîte, le coffre et le seau de {npc:8416} sont dans les camps des troggs.",
	["Coldridge: {area:77} and {npc:714}"] = "Frigères : {area:77} et {npc:714}",
	["{npc:786} camps south of {area:77}, at the mouth of the troll cave; the journal lies at the back of the cave."] = "{npc:786} campe au sud de {area:77}, à l'entrée de la grotte des trolls ; le journal est au fond de la grotte.",
	["The Scalding Mornbrew cools in five minutes: run straight to {npc:836} at {area:77}."] = "La Bière du matin bouillante refroidit en cinq minutes : courez directement voir {npc:836} à {area:77}.",
	["Coldridge: on to {area:131}"] = "Frigères : en route pour {area:131}",
	["Optional: {area:131} and the Brewnall and {area:133} roads around it, about 1,300 reputation (260 at a fifth) in 50 minutes at 60. Most givers stand in and around the {area:2102} and at {area:189} east of it. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : {area:131} et les routes de Brassetout et de {area:133} autour, environ 1 300 de réputation (260 au cinquième) en 50 minutes au niveau 60. La plupart des donneurs se tiennent dans {area:2102} et autour, et à {area:189} à l'est. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["{area:131}: the hills and the depot"] = "{area:131} : les collines et le dépôt",
	["The boars and bears roam around {area:131}; the wendigos live in the {area:136} south-west of town; the leper gnomes at the {area:133} road carry the cogs and gears; Rumbleshot's ammo lies at his camp west of town."] = "Les sangliers et les ours parcourent les environs de {area:131} ; les wendigos vivent dans {area:136}, au sud-ouest de la ville ; les gnomes lépreux de la route de {area:133} portent les rouages et les engrenages ; les munitions de Tonneballe sont à son camp, à l'ouest de la ville.",
	["{area:131}: back in town"] = "{area:131} : retour en ville",
	["{area:131}: Brewnall and {quest:287}"] = "{area:131} : Brassetout et {quest:287}",
	["{npc:1374} stands by {area:137} on the lake north-west of {area:131}; {quest:287} is the troll cave west of it."] = "{npc:1374} se tient près de {area:137}, sur le lac au nord-ouest de {area:131} ; {quest:287} est la grotte des trolls à l'ouest.",
	["The quarry and {area:803}"] = "La carrière et {area:803}",
	["Optional: eastern {zone:1426}, from {npc:264936}'s camp to the {area:134} and {area:803}, about 500 reputation (100 at a fifth) in 30 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : l'est de {zone:1426}, du camp de {npc:264936} à {area:134} et {area:803}, environ 500 de réputation (100 au cinquième) en 30 minutes au niveau 60. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["The Dark Iron Spies lurk around Farsen's camp; the troggs dig in the {area:134}; {npc:1388}, a big snow leopard, prowls the hills above {area:803}."] = "Les espions Sombrefer rôdent autour du camp de Farsen ; les troggs creusent dans {area:134} ; {npc:1388}, un grand léopard des neiges, rôde dans les collines au-dessus de {area:803}.",
	["{quest:7812}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Night Elf stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Gnomes start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). {npc:9616}'s and {npc:9561}'s quests above take 8 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. Outside Dun Morogh Gnomeregan pays little: {npc:4077}'s quests in Stonetalon (about 500) and {object:171524}'s {area:133} dungeon quests. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7812} : 50 de réputation pour 20 {item:14047}, autant de fois que vous le voulez. Après les quatre premiers dons, un Humain, un Nain ou un Elfe de la nuit est à Amical 700 sur 6 000 : Honoré est donc à 5 300, soit 106 rendus, 2 120 {item:14047} (les Gnomes partent 900 plus haut : 88 rendus ; les Célestes partent de Neutre 2 000, donc 6 400 : 128, deux de moins après Explorer l'Alliance). Les quêtes de {npc:9616} et de {npc:9561} ci-dessus en retirent 8 ; chaque zone de {zone:1426} faite en retire 10 à 26 de plus si elle a payé en entier. Hors de Dun Morogh, Gnomeregan rapporte peu : les quêtes de {npc:4077} dans les Serres-Rocheuses (environ 500) et les quêtes de donjon de {area:133} de {object:171524}. Chaque gain auprès d'une ville en donne aussi un quart aux trois autres villes de l'Alliance (non compté ici). Rendez tout votre {item:14047} d'un coup.",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:7955} at {area:189} in {zone:1426} sells her mechanostriders to other races in Classic; the Mechanostrider and Swift Mechanostrider guides cover them."] = "De Révéré à Exalté, il faut 21 000 de réputation : 420 rendus, 8 400 {item:14047}. À Exalté, {npc:7955}, à {area:189} dans {zone:1426}, vend ses mécanotrotteurs aux autres races dans Classic ; les guides Mécanotrotteur et Mécanotrotteur rapide en parlent.",
	["Cloth, the {zone:1428} quests and the {zone:1426} hubs, which pay {area:133} too; {zone:1459} adds more."] = "Le tissu, les quêtes de {zone:1428} et les zones de {zone:1426}, qui rapportent aussi auprès de {area:133} ; {zone:1459} en ajoute.",
	["{npc:14723} takes cloth for {faction:47}; she stands outside the clothier on the north side of the {object:32372}, among the tailors. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7806} pays 50 for every 20 {item:14047}, as often as you like. The Auction House in the Commons is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do {zone:1426} (levels 1-12), {zone:1432} (10-20) and the {zone:1437} (20-30) while you level through them. After the donations come the level 52-59 quests of the {zone:1428} and {zone:1452} (about 600), then the optional {zone:1426} hubs, best rate first: {area:132} (about 37 a minute at full value), {area:131} (26), the quarry (17). Every {faction:47} gain also gives a quarter as much to {zone:1453}, {zone:1457} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14723} prend les tissus pour {faction:47} ; elle se tient devant le magasin de tissus, côté nord de {object:32372}, parmi les tailleurs. Chaque premier don de 60 laine, soie, tisse-mage et {item:14047} rapporte 150 de réputation une seule fois ; après celui de {item:14047}, {quest:7806} rapporte 50 pour 20 {item:14047}, autant de fois que vous le voulez. L'hôtel des ventes de la Halle est le moyen le plus rapide de trouver du tissu. Dans Classic, les quêtes rapportent toute leur réputation tant qu'elles sont au plus 5 niveaux sous le vôtre : faites donc {zone:1426} (niveaux 1-12), {zone:1432} (10-20) et {zone:1437} (20-30) en montant de niveau. Après les dons viennent les quêtes de niveau 52-59 de {zone:1428} et de {zone:1452} (environ 600), puis les zones facultatives de {zone:1426}, la plus rentable d'abord : {area:132} (environ 37 par minute à plein tarif), {area:131} (26), la carrière (17). Chaque gain auprès de {faction:47} en donne aussi un quart à {zone:1453}, {zone:1457} et aux Exilés de Gnomeregan, sauf les quêtes des zones de départ de niveau 1-10. Diplomate d'héritage ajoute jusqu'à 10 % à chaque gain.",
	["{area:2418} sits in the south-east of the {zone:1428}, at the top of the pass up from Redridge. {npc:9177} wants the Firegut ogres of {area:249}, north of the Vigil, thinned out; the Brutes keep to the rock's east side."] = "{area:2418} se trouve au sud-est de {zone:1428}, en haut du col qui monte des Carmines. {npc:9177} veut qu'on éclaircisse les ogres Tripe-de-feu de {area:249}, au nord du Guet ; les brutes restent côté est du rocher.",
	["Thaurissan and {area:252}"] = "Thaurissan et {area:252}",
	["The Thaurissan relics are the carved stones in the ruins around {area:251}, west along the road: click twelve of them. {npc:9176} and the Blackrock orcs and worgs hold the camps at the foot of {area:254}, further west; each may drop a {item:11467} (about one kill in three), and {npc:9177} wants fifty. The orcs are level 50 and up, so they drop {item:14047} too: keep it for {quest:7806}."] = "Les reliques de Thaurissan sont les pierres sculptées des ruines autour de {area:251}, à l'ouest par la route : cliquez-en douze. {npc:9176} et les orcs et worgs Rochenoire tiennent les camps au pied de {area:254}, plus à l'ouest ; chacun peut lâcher un {item:11467} (environ une fois sur trois), et {npc:9177} en veut cinquante. Les orcs sont de niveau 50 et plus : ils lâchent aussi du {item:14047}, gardez-le pour {quest:7806}.",
	["Plant {npc:9176}'s head on the soft dirt mound at the top of {area:249}."] = "Plantez la tête de {npc:9176} sur le monticule de terre meuble au sommet de {area:249}.",
	["With a group, {area:1584} pays more: Archesonus's chain goes on with {npc:9021} (100) and The Fate of the Kingdom (Emperor Thaurissan, 150), and {npc:9177} takes 20 Dark Iron Fanny Packs from the dwarves inside (The Good Stuff, 100). {zone:1459}, from level 51, pays {faction:47} too: its one-time quests about 1,900 as your Stormpike standing grows (the {zone:1459} guide walks them), and inside the battle 25 for every 10 Irondeep or {item:17542} and 50 for 5 Storm Crystals, as often as you like."] = "En groupe, {area:1584} rapporte davantage : la suite d'Archesonus continue avec {npc:9021} (100) et Le destin du royaume (l'empereur Thaurissan, 150), et {npc:9177} prend 20 sacoches Sombrefer sur les nains de l'intérieur (Les bonnes choses, 100). {zone:1459}, à partir du niveau 51, rapporte aussi auprès de {faction:47} : ses quêtes uniques environ 1 900 à mesure que votre réputation Foudrepique monte (le guide de {zone:1459} les détaille), et pendant la bataille 25 pour 10 Fondprofond ou {item:17542} et 50 pour 5 cristaux d'orage, autant de fois que vous le voulez.",
	["{npc:11755} in {area:2255} sends you west to {npc:10301} at {area:2253}. {npc:10301}'s damaged crate and wrecked wagon lie at {area:2245}, down the valley to the south-east; his supplies lie around the wagon and the owlbeasts nearby carry his amulet. The last quest is level 59: 100 {faction:47} in full."] = "{npc:11755}, à {area:2255}, vous envoie vers l'ouest voir {npc:10301} à {area:2253}. La caisse abîmée et le chariot détruit de {npc:10301} sont à {area:2245}, en descendant la vallée au sud-est ; ses provisions sont autour du chariot et les chouettards voisins portent son amulette. La dernière quête est de niveau 59 : 100 auprès de {faction:47} en entier.",
	["Optional: the Dwarf and Gnome start valley south-west of {area:131}, about 1,100 reputation (220 at a fifth) in 30 minutes at 60. {npc:658} and {npc:713} stand at {area:77}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : la vallée de départ des Nains et des Gnomes, au sud-ouest de {area:131}, environ 1 100 de réputation (220 au cinquième) en 30 minutes au niveau 60. {npc:658} et {npc:713} se tiennent à {area:77}. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["{quest:7806}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Night Elf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Dwarves start 900 higher: 88 turn-ins; Skyborne start at Neutral 2,000, so 6,400 away: 128, two fewer after Exploring the Alliance). The level 52-59 quests above take 12 turn-ins off; each {zone:1426} hub you did takes 10 to 26 more off if it paid in full. More hubs pay {faction:47}, in full while they are no more than 5 levels below you: {area:144} in {zone:1432} (about 3,500 in all) and {area:150} in the {zone:1437} (about 2,500). From level 51 {zone:1459}'s one-time quests add about 1,900. Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7806} : 50 de réputation pour 20 {item:14047}, autant de fois que vous le voulez. Après les quatre premiers dons, un Humain, un Elfe de la nuit ou un Gnome est à Amical 700 sur 6 000 : Honoré est donc à 5 300, soit 106 rendus, 2 120 {item:14047} (les Nains partent 900 plus haut : 88 rendus ; les Célestes partent de Neutre 2 000, donc 6 400 : 128, deux de moins après Explorer l'Alliance). Les quêtes de niveau 52-59 ci-dessus en retirent 12 ; chaque zone de {zone:1426} faite en retire 10 à 26 de plus si elle a payé en entier. D'autres zones rapportent de la réputation auprès de {faction:47}, en entier tant qu'elles ne sont pas plus de 5 niveaux sous le vôtre : {area:144} dans {zone:1432} (environ 3 500 en tout) et {area:150} dans {zone:1437} (environ 2 500). À partir du niveau 51, les quêtes uniques de {zone:1459} ajoutent environ 1 900. Chaque gain auprès d'une ville en donne aussi un quart aux trois autres villes de l'Alliance (non compté ici). Rendez tout votre {item:14047} d'un coup.",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:1261} at {area:803} in eastern {zone:1426} sells his rams to other races in Classic; the Ram and Swift Ram guides cover them."] = "De Révéré à Exalté, il faut 21 000 de réputation : 420 rendus, 8 400 {item:14047}. À Exalté, {npc:1261}, à {area:803} dans l'est de {zone:1426}, vend ses béliers aux autres races dans Classic ; les guides Bélier et Bélier rapide en parlent.",
	["New in Forever: {area:279}'s mages sell Azure armour recipes at Friendly and their tabard at Exalted."] = "Nouveauté de Forever : les mages de {area:279} vendent les patrons d'armure azur à Amical et leur tabard à Exalté.",
	["Alliance Skyborne start Friendly with the {faction:2740}, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so {npc:32287} sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}, past the Sky Enclave. Buy the ones for your profession."] = "Les Célestes de l'Alliance commencent à Amical auprès de {faction:2740}, et leurs quêtes d'arrivée, La cité magique de Dalaran et Explorer l'Alliance, rapportent 100 de plus chacune : {npc:32287} vous vend donc tout de suite les patrons azur (10 po chacun, compétence 175 requise). Il se tient à l'étage du bâtiment aux bannières de {faction:2740} à {area:279}, après l'Enclave céleste. Achetez ceux de votre métier.",
	["{npc:247264} of the {faction:2740} waits in {area:271}. He sends you to {npc:246748}'s image by the shore of {area:1338}, outside {area:279}'s walls. The {faction:2740} quests start at level 24 to 30 and pay full reputation while they are at most 5 levels below you; in Classic a quest 6+ levels below you pays less (a fifth at 60)."] = "{npc:247264}, de {faction:2740}, attend à {area:271}. Il vous envoie voir l'image de {npc:246748}, au bord de {area:1338}, hors des murs de {area:279}. Les quêtes de {faction:2740} commencent entre les niveaux 24 et 30 et rapportent toute leur réputation tant qu'elles sont au plus 5 niveaux sous le vôtre ; dans Classic, une quête 6 niveaux ou plus sous le vôtre rapporte moins (un cinquième au niveau 60).",
	["{npc:252085} waits in the Violet Citadel in {area:279}."] = "{npc:252085} attend dans la Citadelle pourpre à {area:279}.",
	["{npc:264265} in {area:279} wants a book back from {npc:6487}, the last boss of the {area:796}'s Library (levels 33 to 41), in {zone:1420}."] = "{npc:264265}, à {area:279}, veut récupérer un livre auprès de {npc:6487}, le dernier boss de la Bibliothèque de {area:796} (niveaux 33 à 41), dans {zone:1420}.",
	["The {area:796} stands in the north-east of {zone:1420}; Doan waits at the end of the Library wing. Group of five advised below level 40."] = "{area:796} se dresse au nord-est de {zone:1420} ; Doan attend au bout de l'aile de la Bibliothèque. Un groupe de cinq est conseillé sous le niveau 40.",
	["{npc:32287} sells the Azure helm and shoulder recipes at Friendly, 10g each (skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}. Buy the ones for your profession."] = "{npc:32287} vend les patrons de heaume et d'épaulières azur à Amical, 10 po chacun (compétence 175). Il se tient à l'étage du bâtiment aux bannières de {faction:2740} à {area:279}. Achetez ceux de votre métier.",
	["{npc:32287} and {npc:28776}, the tabard vendor in {area:279}, sell the {item:285327} at Exalted for 25g."] = "{npc:32287} et {npc:28776}, le vendeur de tabards de {area:279}, vendent {item:285327} à Exalté pour 25 po.",
	["{npc:14722} takes cloth for {faction:72}. The arrow leads to him; he stands upstairs inside his building. Each first donation of 60 Wool, Silk, Mageweave and {item:14047} pays 150 reputation once; after the {item:14047} one, {quest:7796} pays 50 for every 20 {item:14047}, as often as you like. The Auction House is the quickest source of cloth. In Classic, quests pay full reputation while they are at most 5 levels below you, so do Elwynn (levels 1-10), {zone:1436} (10-18), Redridge (15-25) and {zone:1431} (20-30) while you level through them. After the donations come the level 52-58 quests of the {zone:1422} and the {zone:1428} (about 1,150), then the optional low-level hubs, best rate first: Northshire and the city errands (about 40 a minute at full value), the {area:717} (30), Eastvale and {area:87} (25). Every {faction:72} gain also gives a quarter as much to {zone:1455}, {zone:1457} and the Gnomeregan Exiles, except quests in the level 1-10 start areas. Legacy Diplomat adds up to 10% to every gain."] = "{npc:14722} prend les tissus pour {faction:72}. La flèche mène à lui ; il se tient à l'étage de son bâtiment. Chaque premier don de 60 laine, soie, tisse-mage et {item:14047} rapporte 150 de réputation une seule fois ; après celui de {item:14047}, {quest:7796} rapporte 50 pour 20 {item:14047}, autant de fois que vous le voulez. L'hôtel des ventes est le moyen le plus rapide de trouver du tissu. Dans Classic, les quêtes rapportent toute leur réputation tant qu'elles sont au plus 5 niveaux sous le vôtre : faites donc Elwynn (niveaux 1-10), {zone:1436} (10-18), les Carmines (15-25) et {zone:1431} (20-30) en montant de niveau. Après les dons viennent les quêtes de niveau 52-58 de {zone:1422} et de {zone:1428} (environ 1 150), puis les zones facultatives de bas niveau, la plus rentable d'abord : Comté-du-Nord et les courses en ville (environ 40 par minute à plein tarif), {area:717} (30), le Val d'Est et {area:87} (25). Chaque gain auprès de {faction:72} en donne aussi un quart à {zone:1455}, {zone:1457} et aux Exilés de Gnomeregan, sauf les quêtes des zones de départ de niveau 1-10. Diplomate d'héritage ajoute jusqu'à 10 % à chaque gain.",
	["{item:4306} drops from humanoids level 23 to 40: Syndicate in Alterac and Arathi, the Defias of Duskwood's {area:94}, Stranglethorn's trolls."] = "{item:4306} tombe sur les humanoïdes de niveau 23 à 40 : le Syndicat dans Alterac et Arathi, les Défias de {area:94} au Bois de la Pénombre, les trolls de Strangleronce.",
	["These quests are level 52 to 58, so they pay in full at 60, or nearly. {npc:10838} and {npc:11053} at {area:3197}, in the south of the {zone:1422}, send you against the four Scourge cauldrons: 820 {faction:72} reputation in all and 600 {object:92525} on the side (in Classic about 690 {faction:72} at 60, as the first quests are level 52 and 53). The Skeletal Flayers and Slavering Ghouls roam the fields north of the camp."] = "Ces quêtes sont de niveau 52 à 58 : elles paient en entier, ou presque, au niveau 60. {npc:10838} et {npc:11053}, à {area:3197}, au sud de {zone:1422}, vous envoient contre les quatre chaudrons du Fléau : 820 de réputation auprès de {faction:72} en tout et 600 auprès de {object:92525} en plus (dans Classic, environ 690 auprès de {faction:72} au niveau 60, les premières quêtes étant de niveau 52 et 53). Les écorcheurs squelettes et les goules baveuses parcourent les champs au nord du camp.",
	["Andorhal and {area:199}"] = "Andorhal et {area:199}",
	["Mark the four watchtowers around Andorhal, north of the camp, with the {item:12815} at each door. {npc:11075} guards the cauldron at {area:199}, west of Andorhal; his key opens it. {npc:10778}'s ghost wanders by the Felstone farmhouse, and her parcel lies inside: it goes to {faction:72} for 150 more."] = "Marquez les quatre tours de guet autour d'Andorhal, au nord du camp, avec {item:12815} à chaque porte. {npc:11075} garde le chaudron de {area:199}, à l'ouest d'Andorhal ; sa clé l'ouvre. Le fantôme de {npc:10778} erre près de la ferme de Gangrepierre, et son colis est à l'intérieur : il va à {faction:72} pour 150 de plus.",
	["{npc:11077} guards the cauldron at {area:200}, north-east of {area:199}."] = "{npc:11077} garde le chaudron de {area:200}, au nord-est de {area:199}.",
	["{npc:11076} guards the cauldron at the {area:202}, the farm east of {area:200}."] = "{npc:11076} garde le chaudron de {area:202}, la ferme à l'est de {area:200}.",
	["{npc:11078} guards the cauldron at {area:201}, in the east of the zone."] = "{npc:11078} garde le chaudron de {area:201}, à l'est de la zone.",
	["{area:3197}: done"] = "{area:3197} : terminé",
	["{npc:11056} in the camp also ends The Key to {area:2057} (200), after a longer chain that needs a {area:2057} group."] = "{npc:11056}, au camp, termine aussi La clé de {area:2057} (200), après une suite plus longue qui demande un groupe pour {area:2057}.",
	["{npc:9562} at {area:2418}, in the south-east of the {zone:1428}, starts {quest:4183}: a chain to {area:69} and {object:2117}, 175 {faction:72} and 175 {zone:1457} reputation (level 54: in Classic four fifths of it at 60). The Black Broodlings and the {npc:7044} live on the slopes north of the Vigil; the {npc:7040} and {npc:7041} west of it, in the middle of the zone."] = "{npc:9562}, à {area:2418}, au sud-est de {zone:1428}, lance {quest:4183} : une suite vers {area:69} et {object:2117}, 175 de réputation auprès de {faction:72} et 175 auprès de {zone:1457} (niveau 54 : dans Classic, les quatre cinquièmes au niveau 60). Les dragonnets noirs et {npc:7044} vivent sur les pentes au nord du Guet ; {npc:7040} et {npc:7041} à l'ouest, au milieu de la zone.",
	["{npc:344} waits in the town hall of {area:69}."] = "{npc:344} attend à l'hôtel de ville de {area:69}.",
	["{area:69}: Solomon again"] = "{area:69} : de nouveau Solomon",
	["With a group the chain goes on into {area:1584}: {npc:9023}, Jail Break! and The Great Masquerade back in {faction:72} pay about 750 {faction:72} more, Maxwell's Mission (Lower {area:1583}) 250, Delivery to Ridgewell 135. Order Must Be Restored ({npc:11878} in the {zone:1423}) pays 200, The Key to {area:2057} 200; Onyxia's head 400 and Nefarian's 200 when the raids open."] = "En groupe, la suite continue dans {area:1584} : {npc:9023}, Évasion ! et La grande mascarade, de retour à {faction:72}, rapportent environ 750 de plus auprès de {faction:72}, La mission de Maxwell (partie inférieure de {area:1583}) 250, Livraison à Ridgewell 135. L'ordre doit être rétabli ({npc:11878} dans {zone:1423}) rapporte 200, La clé de {area:2057} 200 ; la tête d'Onyxia 400 et celle de Nefarian 200 quand les raids ouvriront.",
	["{area:717}: two quests"] = "{area:717} : deux quêtes",
	["Optional: the {area:717} is {faction:72}'s prison, a dungeon in the canals of the {object:2101}. At 60 you clear it alone in ten minutes: 300 reputation (60 at a fifth). {npc:1719} stands at the gate, {npc:1721} in {object:2100}. Two more {area:717} quests start outside the city, 100 each, if you pass by: What Comes Around... ({npc:1696}) from {npc:859} in {area:69} and Crime and Punishment ({npc:1663}) from {npc:270} in {area:42}. (The Stockade Riots, 100 more, needs the Unsent Letter from {npc:639} in the {area:1581} first.) In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : {area:717} est la prison de {faction:72}, un donjon dans les canaux de {object:2101}. Au niveau 60, vous le videz seul en dix minutes : 300 de réputation (60 au cinquième). {npc:1719} se tient à la porte, {npc:1721} dans {object:2100}. Deux autres quêtes de {area:717} commencent hors de la ville, 100 chacune, si vous passez par là : Retour à l'envoyeur ({npc:1696}) auprès de {npc:859} à {area:69} et Crime et châtiment ({npc:1663}) auprès de {npc:270} à {area:42}. (Les émeutes de la Prison, 100 de plus, demande d'abord la lettre non envoyée de {npc:639} dans {area:1581}.) Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["Inside the {area:717}"] = "Dans {area:717}",
	["Optional: the Human start valley north of {area:87}: about 1,600 reputation (320 at a fifth) in 40 minutes at 60, the best rate of the hubs. {npc:823} and {npc:197} stand at {area:24}. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : la vallée de départ des Humains au nord de {area:87} : environ 1 600 de réputation (320 au cinquième) en 40 minutes au niveau 60, le meilleur rendement des zones. {npc:823} et {npc:197} se tiennent à {area:24}. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["The Kobold Workers are in {area:34} north of the abbey; {npc:103} stands in the Defias camp east of the vineyard; {quest:3904} crates lie in the vineyard; the rats carrying the {object:83763} run about the abbey grounds."] = "Les ouvriers kobolds sont dans {area:34}, au nord de l'abbaye ; {npc:103} se tient dans le camp des Défias à l'est du vignoble ; les caisses de {quest:3904} sont dans le vignoble ; les rats qui portent {object:83763} courent autour de l'abbaye.",
	["{npc:80}, deep in {area:34}"] = "{npc:80}, au fond de {area:34}",
	["Northshire: the books end in {area:87}"] = "Comté-du-Nord : les livres se terminent à {area:87}",
	["{npc:240} stands in front of the Lion's Pride Inn in {area:87}. The Lost Books drop from the kobolds of {area:57} south of {area:87}; the picture book and the two rare books from the named kobolds there."] = "{npc:240} se tient devant l'auberge de la Fierté du lion à {area:87}. Les livres perdus tombent sur les kobolds de {area:57}, au sud de {area:87} ; le livre d'images et les deux livres rares sur les kobolds nommés qui s'y trouvent.",
	["Optional: {area:87}, Westbrook and the farms south of {area:87}: about 1,450 reputation (290 at a fifth) in an hour at 60. {npc:240}, {npc:241} and {npc:253} stand around the Lion's Pride Inn. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : {area:87}, Ruisseau-de-l'Ouest et les fermes au sud de {area:87} : environ 1 450 de réputation (290 au cinquième) en une heure au niveau 60. {npc:240}, {npc:241} et {npc:253} se tiennent autour de l'auberge de la Fierté du lion. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["{area:87}: the mines"] = "{area:87} : les mines",
	["{area:57} is south of {area:87}, {area:54} north-east of it. The kobolds in both drop the candles and the {item:773}; the wolves around {area:87} the pelts."] = "{area:57} est au sud de {area:87}, {area:54} au nord-est. Les kobolds des deux lâchent les bougies et {item:773} ; les loups autour de {area:87}, les peaux.",
	["{area:87}: back at the inn"] = "{area:87} : retour à l'auberge",
	["{area:87}: Westbrook and {npc:448}"] = "{area:87} : Ruisseau-de-l'Ouest et {npc:448}",
	["{npc:448} is an elite gnoll west of {area:120}; at 60 he is no trouble. The Wanted poster hangs on the garrison."] = "{npc:448} est un gnoll élite à l'ouest de {area:120} ; au niveau 60, il ne pose aucun problème. L'avis de recherche est affiché sur la caserne.",
	["The farms south of {area:87}"] = "Les fermes au sud de {area:87}",
	["The Stonefields' farm and the Maclures' farm lie on either side of the road south of {area:87}. {quest:87} guards the back of {area:57}; {npc:330} the boar roams the {area:62}."] = "La ferme des Champierreux et celle des Maclure sont de part et d'autre de la route, au sud de {area:87}. {quest:87} garde le fond de {area:57} ; {npc:330}, le sanglier, parcourt {area:62}.",
	["{item:1256}, from the murlocs of {area:18}"] = "{item:1256}, sur les murlocs de {area:18}",
	["Optional: eastern Elwynn, around {npc:261} on the bridge and the {area:91}, about 1,000 reputation (200 at a fifth) in 40 minutes at 60. In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. Skip this step to skip the hub."] = "Facultatif : l'est d'Elwynn, autour de {npc:261} sur le pont et de {area:91}, environ 1 000 de réputation (200 au cinquième) en 40 minutes au niveau 60. Dans Classic, les quêtes 6 niveaux ou plus sous le vôtre rapportent moins (un cinquième au niveau 60) ; un retour de la bêta de Forever dit qu'elles payaient en entier. Votre premier rendu vous le dira : s'il ne paie qu'un cinquième, passez ces zones. Passez cette étape pour sauter la zone.",
	["The murlocs along the river south of the bridge drop the fins; Prowlers and Young Forest Bears roam the woods; the Defias around the Brackwell farm and the {area:91} carry the bandanas; the enchanting supplies lie in their camps north of the tower; the Kobold Geomancers dig at {area:54}; the tools and the river finds lie along the river north of the logging camp."] = "Les murlocs le long de la rivière au sud du pont lâchent les nageoires ; rôdeurs et jeunes ours des forêts parcourent les bois ; les Défias autour de la ferme des Brackwell et de {area:91} portent les bandanas ; les fournitures d'enchantement sont dans leurs camps au nord de la tour ; les géomanciens kobolds creusent à {area:54} ; les outils et les trouvailles de la rivière sont le long de la rivière au nord du camp de bûcherons.",
	["{quest:7796}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a non-Human stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Humans start 900 higher: 88 turn-ins; a Skyborne's Exploring the Alliance paid 100, two fewer). The level 52-58 quests above take 23 turn-ins off; every Elwynn hub you did takes 20 to 30 more off if it paid in full. More quest hubs pay {faction:72}, in full while they are no more than 5 levels below you: {zone:1436} (about 2,500 in all), Redridge's {area:69} (about 3,000) and {zone:1431}'s {area:42} (about 2,900). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once."] = "{quest:7796} : 50 de réputation pour 20 {item:14047}, autant de fois que vous le voulez. Après les quatre premiers dons, un non-Humain est à Amical 700 sur 6 000 : Honoré est donc à 5 300, soit 106 rendus, 2 120 {item:14047} (les Humains partent 900 plus haut : 88 rendus ; Explorer l'Alliance d'un Céleste a rapporté 100, deux de moins). Les quêtes de niveau 52-58 ci-dessus en retirent 23 ; chaque zone d'Elwynn faite en retire 20 à 30 de plus si elle a payé en entier. D'autres zones de quêtes rapportent de la réputation auprès de {faction:72}, en entier tant qu'elles ne sont pas plus de 5 niveaux sous le vôtre : {zone:1436} (environ 2 500 en tout), {area:69} dans les Carmines (environ 3 000) et {area:42} dans {zone:1431} (environ 2 900). Chaque gain auprès d'une ville en donne aussi un quart aux trois autres villes de l'Alliance (non compté ici). Rendez tout votre {item:14047} d'un coup.",
	["Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:384} at {area:88} sells her horses to other races in Classic; the Horse and Swift Horse guides cover them."] = "De Révéré à Exalté, il faut 21 000 de réputation : 420 rendus, 8 400 {item:14047}. À Exalté, {npc:384}, à {area:88}, vend ses chevaux aux autres races dans Classic ; les guides Cheval et Cheval rapide en parlent.",
	["The {spell:17229}: 840 quest turn-ins in {zone:1452}, with Timbermaw reputation on the side."] = "{spell:17229} : 840 quêtes rendues dans {zone:1452}, avec de la réputation Brann-Bois en plus.",
	["{npc:10618} stands on top of {area:2241}, in the far north of {zone:1452}; the path winds up from the east side. Only the Alliance can earn the {faction:589}' favour, from Neutral, at level 58. All three of her quests pay 50 and repeat as often as you like: 840 turn-ins from Neutral to Exalted. The first one, {quest:4970}, is the only one open at the start."] = "{npc:10618} se tient au sommet de {area:2241}, à l'extrême nord de {zone:1452} ; le chemin monte en lacets par le côté est. Seule l'Alliance peut gagner la faveur de {faction:589}, à partir de Neutre, au niveau 58. Ses trois quêtes rapportent 50 chacune et se répètent autant de fois que vous le voulez : 840 rendus de Neutre à Exalté. La première, {quest:4970}, est la seule ouverte au début.",
	["The meat only drops while the quest is in your log, and a group shares no loot: farm it alone. The best droppers live right below the rock: {npc:7445} bears (about half the time) and Chillwind Ravagers (half the time) roam the snowfields east and south-east of it. Around {area:2255} the Chillwind Chimaeras drop it as often and the Shardtooth Bears a little less; the {npc:7446} by the giants' gorge in the south drop it most often (six in ten)."] = "La viande ne tombe que si la quête est dans votre journal, et un groupe ne partage pas le butin : faites-la seul. Les meilleurs à la lâcher vivent juste sous le rocher : les ours {npc:7445} (environ une fois sur deux) et les ravageurs Ventglacial (une fois sur deux) parcourent les champs de neige à l'est et au sud-est. Autour de {area:2255}, les chimères Ventglacial la lâchent aussi souvent et les ours Dent-d'éclat un peu moins ; {npc:7446}, près de la gorge des géants au sud, la lâchent le plus souvent (six fois sur dix).",
	["Repeat {quest:4970}: 30 turn-ins reach Neutral 1,500, and then {quest:5201} opens: 5 Winterfall Shamans and 5 Winterfall Ursas in {area:2244}, just east of {area:2255}. The village has only a few Shamans, but every furbolg there shares their spawn points: kill all of them, not just the ones you need, and more Shamans and Ursas appear; more Ursas walk the ridge just south-west of the village. Take both quests on every trip: kill the furbolgs, pick up meat on the way back. Neutral to Friendly is 60 turn-ins."] = "Répétez {quest:4970} : 30 rendus mènent à Neutre 1 500, puis {quest:5201} s'ouvre : 5 chamans Tombe-Hiver et 5 ursas Tombe-Hiver à {area:2244}, juste à l'est de {area:2255}. Le village n'a que quelques chamans, mais tous les furbolgs partagent leurs points d'apparition : tuez-les tous, pas seulement ceux qu'il vous faut, et d'autres chamans et ursas apparaissent ; d'autres ursas arpentent la crête juste au sud-ouest du village. Prenez les deux quêtes à chaque aller : tuez les furbolgs et ramassez la viande au retour. De Neutre à Amical, il faut 60 rendus.",
	["Friendly to Honored is 6,000: 120 turn-ins. {quest:5201} is the quickest; do {quest:4970} when the village is crowded or you pass the bears and chimaeras anyway. Every Winterfall furbolg you kill counts for {area:1769} too: 50 Timbermaw reputation per {quest:5201} up to the end of Honored with them, and about four {item:21383}. Take Salfa's Winterfall Activity (the Timbermaw guide) the first time you are in the village, and keep the beads until your Timbermaw kills stop counting: then each 5 pay 50. You will reach Exalted with the Timbermaw long before the {faction:589}."] = "D'Amical à Honoré, il faut 6 000 : 120 rendus. {quest:5201} est la plus rapide ; faites {quest:4970} quand le village est bondé ou que vous passez de toute façon près des ours et des chimères. Chaque furbolg Tombe-Hiver tué compte aussi pour {area:1769} : 50 de réputation Brann-Bois par {quest:5201} jusqu'à la fin d'Honoré auprès d'eux, et environ quatre {item:21383}. Prenez L'activité des Tombe-Hiver de Salfa (le guide Brann-Bois) la première fois que vous êtes au village, et gardez les perles jusqu'à ce que vos victoires ne comptent plus pour les Brann-Bois : chaque lot de 5 rapporte alors 50. Vous serez Exalté auprès des Brann-Bois bien avant {faction:589}.",
	["At Honored Rivern Frostwind adds {quest:5981}: 4 Frostmaul Giants and 4 Frostmaul Preservers, elite giants in {area:2249} in the south-east of {zone:1452}; the path down into the gorge starts at its north-west end. Take it on a trip south with a friend or two, or when {area:2244} is crowded; the {npc:7446} by the gorge drop {item:12622} most often. Honored to Exalted is 33,000: 660 turn-ins."] = "À Honoré, Rivern Frostwind ajoute {quest:5981} : 4 géants Cognegivre et 4 conservateurs Cognegivre, des géants élites à {area:2249}, au sud-est de {zone:1452} ; le chemin qui descend dans la gorge part de son extrémité nord-ouest. Faites-la lors d'un passage au sud avec un ou deux amis, ou quand {area:2244} est bondé ; {npc:7446} près de la gorge lâchent le plus souvent {item:12622}. D'Honoré à Exalté, il faut 33 000 : 660 rendus.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. Skyborne: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up."] = "{npc:4217} se tient à l'étage du bâtiment des druides de {area:1658}. Célestes : lancez {spell:18960} et prenez le vol de {npc:11800} au centre de {area:2361} (elle emmène les druides à {area:702}, sans trajet de vol requis), puis le portail pour monter.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:29} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Lancez {spell:18960} : {npc:11802} se tient à l'étage du bâtiment à côté de vous. {quest:29} a une limite de 30 minutes. Six récipients à babioles (des vases) reposent dans des creux étroits, au fond de {area:656} sous {area:2361}, souvent près des fissures bouillonnantes ({object:177524} au milieu du lac vous rend votre souffle) ; chacun revient trois minutes après avoir été ouvert, et d'autres druides les prennent aussi. Vérifiez que {item:15877} est dans vos sacs avant de remonter : il disparaît cinq minutes après avoir été ramassé. Nagez directement jusqu'à {area:2362} sur la rive nord-ouest, utilisez-le dans l'enceinte du sanctuaire et parlez à {npc:11799} près de l'arbre.",
	["Fly from {area:2361} to {area:442}. The {object:177792} lies far out on the sea floor off the north coast, between tall rocks west of where the {area:456} reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."] = "Volez de {area:2361} à {area:442}. {object:177792} repose loin au fond de la mer au large de la côte nord, entre de hauts rochers à l'ouest de l'endroit où {area:456} rejoint la mer : on ne le voit pas depuis le côté est des rochers. Surveillez votre souffle et les batteurs de Sombrivage ; combattez hors de l'eau.",
	["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Head west to the coast: the {object:177790} lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."] = "Prenez le bateau de {area:442} pour {zone:1453} et volez jusqu'à {area:108}. Partez vers l'ouest jusqu'à la côte : {object:177790} repose loin au fond de la mer à côté d'une fissure bouillonnante (de l'air), à l'ouest d'une ancre engloutie. Des requins rôdent ici ; ne nagez pas au-delà de l'épave qui suit, les eaux profondes provoquent la fatigue.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards {npc:11800}, in the middle of {area:2361}, flies druids straight to {area:702}."] = "Lancez {spell:18960}. Avec les deux moitiés dans vos sacs, placez-vous près de {area:2362} sur la rive nord-ouest et utilisez {item:15883} pour les assembler, puis relancez {spell:18960} (il fonctionne dans {zone:1450}) pour arriver près de {npc:11802}. Il se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages. Ensuite, {npc:11800}, au centre de {area:2361}, emmène les druides directement à {area:702}.",
	["Take the portal up to {npc:4217} in the {area:1658}. {quest:5061}: swim fast and breathe underwater."] = "Prenez le portail pour monter voir {npc:4217} à {area:1658}. {quest:5061} : nagez vite et respirez sous l'eau.",
	["{npc:3033} stands in the druids' hut on {area:1639}."] = "{npc:3033} se tient dans la hutte des druides sur {area:1639}.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. {quest:28} runs on a 30-minute timer. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of {area:656} below {area:2361}, often near the bubbling fissures (the {object:177524} in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the {item:15877} is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the {area:2362} on the north-west shore, use it inside the shrine grounds and speak to {npc:11799} by the tree."] = "Lancez {spell:18960} : {npc:11802} se tient à l'étage du bâtiment à côté de vous. {quest:28} a une limite de 30 minutes. Six récipients à babioles (des vases) reposent dans des creux étroits, au fond de {area:656} sous {area:2361}, souvent près des fissures bouillonnantes ({object:177524} au milieu du lac vous rend votre souffle) ; chacun revient trois minutes après avoir été ouvert, et d'autres druides les prennent aussi. Vérifiez que {item:15877} est dans vos sacs avant de remonter : il disparaît cinq minutes après avoir été ramassé. Nagez directement jusqu'à {area:2362} sur la rive nord-ouest, utilisez-le dans l'enceinte du sanctuaire et parlez à {npc:11799} près de l'arbre.",
	["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies at the bottom of very deep water off the coast north-west of the {area:228}, beside an air fissure where you can breathe: watch your breath on the way down."] = "Prenez le vol de {npc:11798} jusqu'à {zone:1456}, volez jusqu'à {zone:1454} et prenez le zeppelin pour {zone:1420} ; {zone:1421} est au sud de {zone:1458}. {object:177790} repose au fond d'eaux très profondes au large de la côte, au nord-ouest de {area:228}, à côté d'une fissure où vous pouvez respirer : surveillez votre souffle en descendant.",
	["The {object:177792} lies underwater in the {area:382} pond north of the Crossroads, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."] = "{object:177792} repose sous l'eau dans l'étang de {area:382}, au nord de la Croisée, devant un mur en bois. Les hommes de la KapitalRisk y rejoignent vite un combat : arrivez par l'ouest pour éviter la plupart d'entre eux.",
	["Cast {spell:18960}. With both halves in your bags, stand by the {area:2362} on the north-west shore and use the {item:15883} to join them, then cast {spell:18960} again (it works inside {zone:1450}) to land by {npc:11802}. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:11798} flies druids to {area:1638}."] = "Lancez {spell:18960}. Avec les deux moitiés dans vos sacs, placez-vous près de {area:2362} sur la rive nord-ouest et utilisez {item:15883} pour les assembler, puis relancez {spell:18960} (il fonctionne dans {zone:1450}) pour arriver près de {npc:11802}. Il se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages. {npc:11798} emmène les druides à {area:1638}.",
	["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Votre forme de tank : Forever n'enseigne plus {spell:5487}, ce sont ces quêtes qui la donnent. Elles ouvrent aussi {area:493}.",
	["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "Au niveau 10, l'appel d'un druide vous parvient : {npc:3602} à {area:186}, Denatharion à {zone:1457} ou Theridran à {zone:1453}. N'importe lequel vous envoie voir {npc:4217} dans l'enclave Cénarienne de Darnassus.",
	["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186} ; les lettres de Denatharion et de Theridran mènent au même endroit",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:4217} se tient à l'étage du bâtiment des druides de {area:1658}. Il vous apprend {spell:18960} avec la quête (il reste dans votre grimoire, onglet Équilibre).",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, past the armor vendor. The {quest:5929} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {area:493} flight path ({npc:10897}, south of the lake) for later, then take {npc:11800}'s flight from the middle of {area:2361}: she flies druids straight to {area:702}, no flight path needed. Take the portal up to {zone:1457}."] = "Lancez {spell:18960} : il vous dépose à côté du bâtiment où {npc:11802} se tient à l'étage, après le vendeur d'armures. {quest:5929} se trouve dans les bois au nord-ouest. Parlez-lui et passez par toutes ses répliques (ce qu'il représente, la force du corps, la force du cœur, puis demandez sa bénédiction) : c'est la conversation qui compte, il n'y a pas de combat. Il se fond dans le sol, n'a pas de marque de quête et dégage une faible lueur bleu-gris près d'un groupe de trois arbres : depuis {area:2361}, partez vers l'ouest au pied des montagnes du nord, par le passage entre les arbres et les collines. Si {npc:11802} n'est pas là à votre retour, sortez et relancez {spell:18960}. Apprenez le trajet de vol de {area:493} ({npc:10897}, au sud du lac) pour plus tard, puis prenez le vol de {npc:11800} au centre de {area:2361} : elle emmène les druides directement à {area:702}, sans trajet de vol requis. Prenez le portail pour monter à {zone:1457}.",
	["Fly from {area:702} to {area:442}. The {object:177525} stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the {area:442} road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the {item:15208} by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too."] = "Volez de {area:702} à {area:442}. {object:177525} se dresse dans la grotte de sélénides la plus proche à l'est du village : la plus au nord des deux petites grottes en tas de rochers, là où la route de {area:442} rejoint la grande route nord-sud. Des sélénides (niveau 11-13) se tiennent dehors, la grotte est vide : faufilez-vous. Utilisez {item:15208} près de la pierre : Griffelune (niveau 12-13) s'avance vers vous et reste trois minutes. Tuez-la, puis parlez à {npc:12144} qui apparaît et demandez la force de son corps et de son cœur : c'est la conversation qui valide. La Griffelune d'un autre druide vous donne aussi l'esprit.",
	["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Revolez à {area:702} et prenez le portail pour monter voir {npc:4217}.",
	["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "Au niveau 10, l'appel d'un druide vous parvient : {npc:3064} à {area:222} ou {npc:6746} à {zone:1456} (la lettre de {npc:6929} à {zone:1454} fonctionne aussi). N'importe lequel vous envoie voir {npc:3033} sur {area:1639} à {zone:1456}.",
	["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222} ; les lettres de Pala et de Gryshka mènent au même endroit",
	["{npc:3033} stands in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} se tient dans la hutte des druides sur {area:1639}, après les ponts de corde à l'est des ascenseurs. Il vous apprend {spell:18960} avec la quête (il reste dans votre grimoire, onglet Équilibre).",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs. The {quest:5930} sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from {area:2361} go west along the foot of the northern mountains, through the gap between the trees and the hills. If {npc:11802} is missing when you return, step outside and cast {spell:18960} again. Learn the {quest:5922} flight path (Faustron, south-west of the lake); {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Lancez {spell:18960} : il vous dépose à côté du bâtiment où {npc:11802} se tient à l'étage. {quest:5930} se trouve dans les bois au nord-ouest. Parlez-lui et passez par toutes ses répliques (ce qu'il représente, la force du corps, la force du cœur, puis demandez sa bénédiction) : c'est la conversation qui compte, il n'y a pas de combat. Il se fond dans le sol, n'a pas de marque de quête et dégage une faible lueur bleu-gris près d'un groupe de trois arbres : depuis {area:2361}, partez vers l'ouest au pied des montagnes du nord, par le passage entre les arbres et les collines. Si {npc:11802} n'est pas là à votre retour, sortez et relancez {spell:18960}. Apprenez le trajet de vol de {quest:5922} (Faustron, au sud-ouest du lac) ; {npc:11798}, à {area:2361}, emmène les druides à {area:1638}.",
	["The {object:177525} stands in the {zone:1413} just south-west of {area:378}, by the road out of {zone:1412}. Level 20 Thunderheads roam close by: clear the way first. Use the {item:15710} by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the {npc:12144} that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her."] = "{object:177525} se dresse dans {zone:1413}, juste au sud-ouest de {area:378}, près de la route qui sort de {zone:1412}. Des Tête-de-Tonnerre de niveau 20 rôdent tout près : dégagez d'abord le passage. Utilisez {item:15710} près de la pierre : Griffelune (niveau 12-13) apparaît pour trois minutes. Tuez-la, puis parlez à {npc:12144} qui apparaît et demandez la force de son corps et de son cœur : c'est la conversation qui valide. Mort pendant le combat ? Griffelune reste près de la pierre : revenez en courant et achevez-la.",
	["Back to {npc:3033} on {area:1639}."] = "Retour auprès de {npc:3033} sur {area:1639}.",
	["Skyboat from {area:279}"] = "Dirigeable depuis {area:279}",
	["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} s'apprend sur {zone:2521}. Passez cette étape si vous êtes encore sur l'île ; sinon, prenez le dirigeable au nord de {area:279}.",
	["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} s'apprend sur {zone:2521}. Passez cette étape si vous êtes encore sur l'île ; sinon, prenez le dirigeable depuis les falaises au sud de {area:17045}, au nord de {zone:1456}.",
	["{npc:252359} stands in {area:16638}."] = "{npc:252359} se tient à {area:16638}.",
	["{npc:255853} waits by the waterfall below the {area:16629}, north-east of {area:16638}. {npc:258443} (the bear you must defeat) lairs in an unmarked cave high on the cliff face west of him, where the {area:16623} meet the {area:16626}: take the path west out of {area:16638} (not north), cross the river on the log bridge and reach the cave from the cliff's upper, northern side. The cave at the foot of the cliffs and the foggy cave are the wrong ones."] = "{npc:255853} attend près de la cascade sous {area:16629}, au nord-est de {area:16638}. {npc:258443} (l'ours à vaincre) a son repaire dans une grotte non indiquée, haut sur la falaise à l'ouest de lui, là où {area:16623} rejoignent {area:16626} : prenez le chemin vers l'ouest depuis {area:16638} (pas vers le nord), traversez la rivière sur le pont de rondins et atteignez la grotte par le haut de la falaise, côté nord. La grotte au pied des falaises et la grotte embrumée ne sont pas les bonnes.",
	["{npc:3033} trains druids in the druids' hut on {area:1639}, over the rope bridges east of the lifts. He teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "{npc:3033} forme les druides dans la hutte des druides sur {area:1639}, après les ponts de corde à l'est des ascenseurs. Il vous apprend {spell:18960} avec la quête suivante (il reste dans votre grimoire, onglet Équilibre).",
	["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} se tient à côté de {npc:259084} et du portail des Célestes, à l'ouest de {area:279}, là où atterrit le fendeur de ciel venu de {zone:2521}. {npc:2543} propose la même quête.",
	["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer (the arrow points at him); he teaches you {spell:18960} with the next quest (it stays in your spellbook, Balance tab)."] = "Le portail des Célestes vous mène à {zone:1453}. {npc:5504} est le maître druide de la ville (la flèche le pointe) ; il vous apprend {spell:18960} avec la quête suivante (il reste dans votre grimoire, onglet Équilibre).",
	["Cast {spell:18960}: it lands you beside the building where {npc:11802} stands upstairs, in {area:2361}. Learn the {area:493} flight path while you are here (Faustron for the Horde, south-west of the lake; {npc:10897} for the Alliance, south of it)."] = "Lancez {spell:18960} : il vous dépose à côté du bâtiment où {npc:11802} se tient à l'étage, à {area:2361}. Apprenez le trajet de vol de {area:493} pendant que vous y êtes (Faustron pour la Horde, au sud-ouest du lac ; {npc:10897} pour l'Alliance, au sud).",
	["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer ({npc:3033}, {npc:4217} or Theridran in {zone:1453}) offers the same quest."] = "Lancez {spell:18960}. {npc:12042} se tient à {area:2361} ; votre maître de classe ({npc:3033}, {npc:4217} ou Theridran à {zone:1453}) propose la même quête.",
	["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Volez jusqu'à {area:976}, partez vers l'ouest jusqu'à la longue rampe qui descend dans {zone:1449} : {npc:9619} campe à son pied, dans le coin sud-est du cratère.",
	["Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the {area:540}, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' {spell:8137} makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around {area:541} and the western half): open them, about every other one gives a {item:22434}, back in three to five minutes."] = "Huit de chaque. Les guêpes et les dards Gorishi (niveau 51-52), dans {area:540} et autour, la ruche au sud-ouest du cratère, lâchent un dard environ une fois sur sept ; les guêpes partagent leurs points d'apparition avec les autres insectes : tuez tout ce qui est près de vous pour faire place à d'autres guêpes (réapparition en cinq minutes). {spell:8137} des insectes vous fait subir plus de dégâts physiques pendant 30 minutes ; les ouvrières appellent à l'aide quand elles sont blessées. Les pousses de pétale-de-sang poussent dans tout le cratère (autour de {area:541} et dans la moitié ouest) : ouvrez-les, environ une sur deux donne un {item:22434}, qui revient en trois à cinq minutes.",
	["Use the {item:22432} on a living {npc:6498} (an Ironhide or {npc:6500}, or {npc:6584}, counts too): they are elite (level 54-55), hit with {spell:14099} and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or {spell:339} it from range, stab it (the barb does not break {spell:2637}), then leave. The credit counts the moment the barb lands, even if you die after. The nearest roams south-west of {area:541}."] = "Utilisez {item:22432} sur un {npc:6498} vivant (un Peau-de-fer ou {npc:6500}, ou {npc:6584}, compte aussi) : ce sont des élites (niveau 54-55), qui frappent avec {spell:14099} et courent plus vite que la forme de voyage. Il vaut mieux être en groupe, mais un druide peut le faire seul : Hibernation ou {spell:339} à distance, plantez-lui l'aiguillon (il ne brise pas {spell:2637}), puis partez. La validation compte dès que l'aiguillon touche, même si vous mourez ensuite. Le plus proche rôde au sud-ouest de {area:541}.",
	["A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. {area:1477} stands in the middle of the {area:74} in the {zone:1435}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. {npc:8580} (level 50 elite, {spell:12887} and {spell:6524}) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The {item:22444} always drops."] = "Un donjon à cinq : il faut un groupe de cinq, vers le niveau 50-55. Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'à {area:1438} dans {zone:1419} et montez vers le nord. {area:1477} se dresse au milieu de {area:74} dans {zone:1435} : montez les escaliers du côté sud de la ruine, plongez dans la salle inondée, nagez vers le fond et suivez les escaliers et les couloirs jusqu'au portail. {npc:8580} (élite de niveau 50, {spell:12887} et {spell:6524}) n'apparaît que lorsque les six statues de serpent du balcon circulaire au-dessus de la fosse de l'autel sont cliquées dans l'ordre : sud, nord, sud-ouest, sud-est, nord-ouest, nord-est (chacune devient verte si c'est juste ; un mauvais ordre échoue). Nettoyez d'abord les monstres près de chaque statue et dans la fosse ; sauter dans l'eau est le chemin le plus rapide pour descendre, mais un repoussement près du bord peut être mortel. {item:22444} tombe à chaque fois.",
	["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:4217} se tient à {area:1658}. Célestes loin de {zone:1457} : lancez {spell:18960} et prenez le vol de {npc:11800} au centre de {area:2361} (elle emmène les druides à {area:702}, sans trajet de vol requis), puis le portail pour monter. Pas encore de forme aquatique ? Prenez aussi Une leçon à retenir auprès de lui : elle mène aussi à {npc:11802}, et son Épreuve du lac (le guide Forme aquatique) se passe au même {area:493}.",
	["{quest:98394} (Night Elves) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98394} (Elfes de la nuit) attend sur la colline au-dessus du pont au sud de {area:493} ; {npc:272054} (Célestes) se tient sur les hauteurs après les ponts jumeaux, au sud-ouest de {area:2361} : montez jusqu'à lui. Les reliques sont dans {area:2363}, à l'est du lac : quittez votre forme et cliquez sur la statue à l'entrée de la tanière pour un court camouflage (cinq minutes), puis allez au fond de la grotte et passez le pont. Des esprits enragés gardent les reliques et attaquent tout ce qu'ils voient : restez dans le camouflage de la statue et ne vous arrêtez pas. Chaque relique est un petit orbe à côté d'une statue de félin dans une alcôve : le Croc et la Griffe ont chacun un emplacement, l'Ombre silencieuse deux, et c'est celle que les joueurs campent. Une relique apparaît inutilisable pendant qu'un autre joueur la ramasse : attendez un instant et réessayez. Plus de camouflage ? Retournez à la statue de l'entrée.",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960} pour arriver près de {npc:11802} à {area:2361} (personne sur l'île de Zephras ne prend la quête des Célestes), puis prenez le vol de {npc:11800} jusqu'à {area:702} : elle se tient au centre de {area:2361} et y emmène les druides, sans trajet de vol requis. {npc:11802} se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "Prenez le portail pour monter voir {npc:4217}, à l'étage de {area:1658} : il vous apprend {spell:768}.",
	["{npc:3033} stands in the druids' hut on {area:1639}. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:3033} se tient dans la hutte des druides sur {area:1639}. Pas encore de forme aquatique ? Prenez aussi Une leçon à retenir auprès de lui : elle mène aussi à {npc:11802}, et son Épreuve du lac (le guide Forme aquatique) se passe au même {area:493}.",
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960}. {npc:11802} se tient à l'étage de son bâtiment à {area:2361} : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["{quest:98342} (Tauren) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98342} (Taurens) attend sur la colline au-dessus du pont au sud de {area:493} ; {npc:272054} (Célestes) se tient sur les hauteurs après les ponts jumeaux, au sud-ouest de {area:2361} : montez jusqu'à lui. Les reliques sont dans {area:2363}, à l'est du lac : quittez votre forme et cliquez sur la statue à l'entrée de la tanière pour un court camouflage (cinq minutes), puis allez au fond de la grotte et passez le pont. Des esprits enragés gardent les reliques et attaquent tout ce qu'ils voient : restez dans le camouflage de la statue et ne vous arrêtez pas. Chaque relique est un petit orbe à côté d'une statue de félin dans une alcôve : le Croc et la Griffe ont chacun un emplacement, l'Ombre silencieuse deux, et c'est celle que les joueurs campent. Une relique apparaît inutilisable pendant qu'un autre joueur la ramasse : attendez un instant et réessayez. Plus de camouflage ? Retournez à la statue de l'entrée.",
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960} pour arriver près de {npc:11802} à {area:2361} (personne sur l'île de Zephras ne prend la quête des Célestes), puis prenez le vol de {npc:11798} jusqu'à {area:1638}. {npc:11802} se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["{npc:3033} on {area:1639} teaches you {spell:768}."] = "{npc:3033}, sur {area:1639}, vous apprend {spell:768}.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} se tient à l'étage du bâtiment des druides de {area:1658}. Pas de {skill:182} ? Achetez d'abord cinq {item:2449} à l'hôtel des ventes : vous en aurez besoin plus tard.",
	["{npc:4217} stands upstairs in the druids' building of the {area:1658}; {npc:270459} by the Skyborne Portal does not give this quest. Cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No {skill:182}? Buy five {item:2449} on the Auction House first: you need them later."] = "{npc:4217} se tient à l'étage du bâtiment des druides de {area:1658} ; {npc:270459}, près du portail des Célestes, ne donne pas cette quête. Lancez {spell:18960} et prenez le vol de {npc:11800} au centre de {area:2361} (elle emmène les druides à {area:702}, sans trajet de vol requis), puis le portail pour monter. Pas de {skill:182} ? Achetez d'abord cinq {item:2449} à l'hôtel des ventes : vous en aurez besoin plus tard.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15844}. Then fly to {area:442} (learn the {zone:1450} flight path at Sindrayl first if you have not)."] = "Lancez {spell:18960} : {npc:11802} se tient à l'étage du bâtiment à côté de vous. Il vous remet {item:15844}. Volez ensuite jusqu'à {area:442} (apprenez d'abord le trajet de vol de {zone:1450} auprès de Sindrayl si ce n'est pas fait).",
	["Head north-east from {area:442} to {area:445}. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the {item:15844} (not the {item:12350} of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight."] = "Partez vers le nord-est depuis {area:442} jusqu'à {area:445}. Placez-vous à l'entrée de la grotte en haut de la cascade, pas dans la rivière en contrebas, et utilisez {item:15844} (pas {item:12350} d'une autre quête). Des nagas bordent la montée, un lanceur de sorts attend sur l'autre rive, et remplir l'échantillonneur en appelle deux autres (un chevaucheur de vagues et un toxicologue, niveau 15) : dégagez d'abord le passage et soyez prêt à combattre.",
	["Back in {area:442}, at the north end of the village."] = "De retour à {area:442}, au bout nord du village.",
	["The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of {area:442}; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No {skill:182} needed for the blooms. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it ({npc:1313} or {npc:1302} in {zone:1453}, or the Auction House)."] = "Les fleurs de champignon lunaire sont de minuscules champignons à points blancs sur le sol et les parois des petites grottes de sélénides, dans les collines juste à l'est et au sud-est de {area:442} ; chacune donne un ou deux champignons, et chaque grotte n'en a que quelques-unes : allez de grotte en grotte (elles repoussent en trois minutes). Les sélénides y sont irritables. Pas besoin de {skill:182} pour les fleurs. {item:2449} demande {skill:182} : les herboristes en cueillent dans tout {zone:1439}, les autres l'achètent ({npc:1313} ou {npc:1302} à {zone:1453}, ou à l'hôtel des ventes).",
	["Use the {item:15826} on living {npc:12298} (level 5, a green cloud over them): they roam {zone:1439} from the {area:456} to the {zone:1440} border, many around the Blackwood furbolg camp north-east of {area:442}. Druid trick: root a deer with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from {npc:3702} for a fresh salve."] = "Utilisez {item:15826} sur des {npc:12298} vivants (niveau 5, un nuage vert au-dessus d'eux) : ils parcourent {zone:1439} de {area:456} jusqu'à la limite de {zone:1440}, nombreux autour du camp des furbolgs Noirbois au nord-est de {area:442}. Astuce de druide : immobilisez un cerf avec {spell:339}, appliquez le baume avant que les racines ne frappent, et la mort par les racines compte une seconde fois. Une dose perdue sur un cerf qui n'a pas compté ? Abandonnez la quête et reprenez-la auprès de {npc:3702} pour un nouveau baume.",
	["Use the {item:15826} on {npc:12298}"] = "Utilisez {item:15826} sur {npc:12298}",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed) and the portal up to {zone:1457}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960} et voyez {npc:11802}, puis prenez le vol de {npc:11800} au centre de {area:2361} (elle emmène les druides à {area:702}, sans trajet de vol requis) et le portail pour monter à {zone:1457}. {npc:11802} se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["{npc:4217}, upstairs in the {area:1658}, teaches you {spell:8946}."] = "{npc:4217}, à l'étage de {area:1658}, vous apprend {spell:8946}.",
	["{npc:3033} stands in the druids' hut on {area:1639}; {npc:262560}, the Skyborne druid trainer where the airship from Zephras Isle lands in northern {zone:1412}, gives the same quest. No {skill:182}? {npc:3490} at the Crossroads sells {item:2449} later, or buy five on the Auction House now."] = "{npc:3033} se tient dans la hutte des druides sur {area:1639} ; {npc:262560}, le maître druide des Célestes, là où atterrit le dirigeable venu de l'île de Zephras au nord de {zone:1412}, donne la même quête. Pas de {skill:182} ? {npc:3490}, à la Croisée, vend {item:2449} plus tard, ou achetez-en cinq maintenant à l'hôtel des ventes.",
	["Cast {spell:18960}: {npc:11802} stands upstairs in the building beside you. He hands you the {item:15842}. {npc:11798} flies druids to {area:1638}; fly on to the Crossroads from there."] = "Lancez {spell:18960} : {npc:11802} se tient à l'étage du bâtiment à côté de vous. Il vous remet {item:15842}. {npc:11798} emmène les druides à {area:1638} ; de là, volez jusqu'à la Croisée.",
	["From the Crossroads head north to {area:384} and climb to the bubbling {object:19464} on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the {item:15842}: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run."] = "Depuis la Croisée, partez au nord jusqu'à {area:384} et montez jusqu'à {object:19464}, qui bouillonne au sommet. Des cultistes de la Lame ardente campent autour : attirez-les un ou deux à la fois. Placez-vous dans l'eau et utilisez {item:15842} : trois toxicologues de la Lame ardente (niveau 13-14, malédictions et sorts de démoniste) apparaissent et attaquent. Inutile de les tuer : une fois l'échantillonneur plein, fuyez.",
	["{npc:3448} stands in the Crossroads. No {skill:182}? {npc:3490}, a few steps away by the wind rider master, sells {item:2449} for 80 copper each, three at a time until he restocks."] = "{npc:3448} se tient à la Croisée. Pas de {skill:182} ? {npc:3490}, à quelques pas près du maître des coursiers du vent, vend {item:2449} 80 pc pièce, trois à la fois jusqu'à son réapprovisionnement.",
	["Every {npc:3234} (level 14-15) drops a horn, but they are few and wander: search the far north near the {area:382} and the oases, above all the {area:388} south-east of the Crossroads. They charge from range and stomp. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Chaque {npc:3234} (niveau 14-15) lâche une corne, mais ils sont rares et errent : cherchez à l'extrême nord près de {area:382} et des oasis, surtout {area:388} au sud-est de la Croisée. Ils chargent à distance et piétinent. Les herboristes trouvent {item:2449} dans tout le nord de {zone:1413}.",
	["Use the {item:15826} on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the {zone:1440} border, north-west of the Crossroads and west of {area:392}. Druid trick: root a gazelle with {spell:339}, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from {npc:3448} for a fresh salve."] = "Utilisez {item:15826} sur des gazelles maladives vivantes (niveau 3) : elles broutent des deux côtés de la route au nord de la Croisée jusqu'à la limite de {zone:1440}, au nord-ouest de la Croisée et à l'ouest de {area:392}. Astuce de druide : immobilisez une gazelle avec {spell:339}, appliquez le baume avant que les racines ne frappent, et la mort par les racines compte une seconde fois : cinq gazelles peuvent suffire. Une dose perdue ? Abandonnez la quête et reprenez-la auprès de {npc:3448} pour un nouveau baume.",
	["Use the {item:15826} on Sickly Gazelles"] = "Utilisez {item:15826} sur des gazelles maladives",
	["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lancez {spell:18960} et voyez {npc:11802}, puis prenez le vol de {npc:11798} jusqu'à {area:1638}. {npc:11802} se tient à l'étage de son bâtiment : montez à l'intérieur, la flèche ne distingue pas les étages.",
	["{npc:3033} on {area:1639} teaches you {spell:8946}."] = "{npc:3033}, sur {area:1639}, vous apprend {spell:8946}.",
	["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717} est un raid à 40 joueurs dans {area:254}. Quand {npc:12018} se rend, {object:179703} apparaît ; il contient {item:18703} environ une fois sur deux, une par victoire : il faudra peut-être plusieurs semaines de raids. Clic droit sur la feuille pour lancer la quête.",
	["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "Vartrus, Stoma et {npc:14526} sont des arbres pétrifiés sur un îlot d'un lac en anneau à {area:1767}, au nord de {zone:1448}. Leurs esprits n'apparaissent que lorsque quelqu'un portant la feuille monte la petite colline de l'île jusqu'à son bord est. Alliance : volez jusqu'à {area:1998} ; Horde : volez jusqu'à {area:1997}. Vartrus donne {quest:7636}, Stoma Une corde digne de ce nom, Hastat le carquois ; chacune peut se rendre séparément.",
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring an Elixir of Demonslaying ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "Les quatre démons sont des élites de niveau 60 déguisés en voyageurs amicaux ; parlez à l'un d'eux et dites-lui que vous savez ce qu'il est : il prend sa forme démoniaque. Combattez chacun seul : pas de familier (renvoyez-le), aucun soin, amélioration ou attaque d'un autre joueur une fois le combat lancé, sinon le démon vous traite de lâche et disparaît, avec 3 heures d'attente avant son retour (aussi après sa mort). Les améliorations et potions prises avant l'attaque sont permises, et un ami peut rester à côté pour tuer les monstres errants ou les joueurs ennemis, tant qu'il ne touche jamais au démon ni à vous. Apportez un élixir de tueur de démons ({skill:171} ou l'hôtel des ventes), des potions de mana majeures pour les longues poursuites, et une arme de mêlée avec l'enchantement Tueur de démons si possible. {spell:19878}, chez votre maître, montre les démons déguisés sur la minicarte. En groupe, réglez le butin sur « chacun pour soi » pour pouvoir ramasser la tête.",
	["Learn {spell:19878} and get demon-slaying potions"] = "Apprenez {spell:19878} et procurez-vous des potions de tueur de démons",
	["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}, une trolle accompagnée d'un loup, suit un long chemin qui part du lac à l'ouest d'Un'Goro et peut atteindre le sud du cratère ; utilisez {spell:19878}. Parlez-lui et elle devient {npc:14533}, et son loup Précieux un traqueur gangrené. La plus difficile des quatre : posez un piège givrant sur Précieux et éloignez bien Simone, ou entraînez Précieux à l'écart et tuez-le d'abord, laissez Simone se réinitialiser et revenez l'affronter seule. Son {spell:421} frappe fort : videz son mana avec {spell:3034} (15 secondes de recharge sur Forever) et occupez-la ; son {spell:23205} réduit votre puissance d'attaque à distance, alors achevez-la en mêlée. Ramassez sa tête avant que Précieux ne se libère.",
	["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529}, un humain, erre dans l'ouest de {zone:1428}, au sud de {area:254}. Parlez-lui et il devient {npc:14534}, le plus facile des quatre. Gardez {spell:3043} sur lui pendant tout le combat : tant qu'elle dure, il vous fait à peine mal. Quand il entre en {spell:23257}, dissipez-la avec {spell:19801} et ne restez jamais au corps à corps pendant ce temps ; entre deux frénésies, vous pouvez le combattre en mêlée avec {spell:2974} et {spell:2973}. Il ne peut pas quitter {zone:1428} : faites-le tourner autour des arbres si besoin.",
	["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {object:164639}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}, un gnome, marche autour des portes de {area:3428}, à l'extrême sud-ouest de {zone:1451}. Parlez-lui et il devient {npc:14530}. Il s'enrage avec {spell:23272} en se transformant : posez un {object:164639}, {spell:5384}, et il se réinitialise sans la rage. {spell:2974} l'immobilise longtemps ; immobilisé, il vous effraie et envoie des scarabées ({npc:14761}) : tuez-les vite avec des pièges et {spell:2643} avant qu'ils ne vous usent.",
	["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531}, un tauren, fait une boucle dans les rochers du nord de {zone:1452}, au nord de {area:2255}. Parlez-lui et il devient {npc:14535}. À moins de 30 mètres de lui, {spell:23298} frappe fort : gardez vos distances et faites-le courir pendant tout le combat, {spell:5118} activé, vers le sud par la route. {spell:1978} sur lui ajoute {spell:23299}, des dégâts de nature en plus : gardez-la active pendant que vous courez ; son {spell:23257} se dissipe avec {spell:19801}, mais la distance compte davantage. C'est un long combat : apportez des potions de mana et prévoyez votre trajet.",
	["Onyxia is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. She drops one {item:18705} in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first."] = "Onyxia est le boss du raid à 40 joueurs de {area:2159}, une grotte de {area:511} au sud de {zone:1445} ; elle revient une fois par semaine. Elle lâche un {item:18705} environ deux fois sur cinq, ramassable sans la quête : un seul chasseur l'obtient par victoire, décidez qui passe en premier.",
	["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "Le carquois d'Hastat demande {item:18704}. {npc:6109}, un boss mondial pour un raid, se tient au sud de {zone:1447}, ne revient que tous les deux à quatre jours et le lâche presque à chaque fois. Les draconiens élites de Cobalt dans {area:2245} et autour, la grotte au sud de {area:2255} dans {zone:1452}, le lâchent environ une fois sur 200 ; Griffe-de-mana un peu plus souvent. Passez le reste de ce guide si vous ne voulez pas le carquois.",
	["Experience at 50 through {zone:1447} and the {area:1417}; Classic's item choice may be gone on Forever."] = "De l'expérience au niveau 50 dans {zone:1447} et {area:1417} ; le choix d'objet de Classic a peut-être disparu sur Forever.",
	["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "Au niveau 50, tout maître chasseur de la Horde la propose : {npc:3352} dans {object:172958} de {zone:1454} ou {npc:3039} sur {area:1641} à {zone:1456}.",
	["{npc:8405} lives on a raised spot on the cliffs at the north-east rim of the {area:1221}, west-central {zone:1447}. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to {area:3137}; Horde: fly to {area:1237}, a short ride west of him."] = "{npc:8405} vit sur une avancée des falaises au bord nord-est de {area:1221}, dans le centre-ouest de {zone:1447}. Restez sur les crêtes hautes autour des ruines : la fosse en contrebas ne monte pas jusqu'à lui. Alliance : volez jusqu'à {area:3137} ; Horde : volez jusqu'à {area:1237}, à quelques minutes à l'ouest de lui.",
	["You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over {zone:1447} and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the {area:1220} in the north, and the hills north-east and south-east of {area:1237}; the {area:1234} area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes."] = "Il vous faut deux bois de coursier parfaits. Les coursiers Sabot-de-mousse (niveau 52-53, des cerfs) broutent dans tout {zone:1447} et en lâchent un environ une fois sur douze : comptez deux douzaines de victoires. Bons troupeaux : au nord de {area:1220}, au nord, et les collines au nord-est et au sud-est de {area:1237} ; le secteur de {area:1234} a aussi des géants et des draconiens élites. Ils s'enragent à 30 % de vie. Les coursiers partagent leurs points d'apparition avec les hippogriffes Tête-de-Tonnerre : s'il n'y en a pas, tuez les hippogriffes et des coursiers peuvent apparaître à leur place. Réapparition en cinq minutes et demie environ.",
	["You need six {item:20087}. Wavethrashers (three-headed sea beasts) live along {zone:1447}'s coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the {area:1229} about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. {spell:1494} does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water."] = "Il vous faut six {item:20087}. Les batteurs de vagues (des bêtes marines à trois têtes) vivent le long des côtes de {zone:1447}, surtout sous l'eau : les jeunes batteurs de vagues (niveau 51-52) de la rive nord-est lâchent une écaille environ une fois sur trois, les batteurs de vagues (52-53) de la côte est près de {area:1229} à peu près aussi souvent (quelques-uns marchent sur la plage), les grands batteurs de vagues (53-54) de la rive sud-est environ une fois sur sept. {spell:1494} ne les montre pas ; combattez-les là où vous pouvez respirer, et prévoyez de quoi respirer sous l'eau si possible. Des requins élites nagent en eaux profondes.",
	["Morphaz in the {area:1417}"] = "Morphaz dans {area:1417}",
	["Morphaz is an elite green drake (level 52) inside the {area:1417}, a five-player dungeon: needs a group of five. The temple stands in the {area:74} in eastern {zone:1435}: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} or {area:42} and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses {spell:12533} and {spell:11019}. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls."] = "Morphaz est un drake vert élite (niveau 52) dans {area:1417}, un donjon à cinq : il faut un groupe de cinq. Le temple se dresse dans {area:74}, à l'est de {zone:1435} : montez ses marches extérieures, plongez dans la salle inondée et suivez les escaliers jusqu'à l'entrée. Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'à {area:1438} ou {area:42} et continuez à monture. Il n'est pas là à votre arrivée : tuez d'abord les six gardiens trolls sur les plates-formes de l'anneau supérieur, ce qui ouvre le chemin vers {npc:5710} dans la fosse du sacrifice. La mort de Jammal'an fait sortir deux drakes, Tisserand et Faux-de-rêve (attirez-les un par un) ; une fois les deux morts, Morphaz et Hazzas apparaissent ensemble et ne peuvent être séparés. Nettoyez d'abord les draconiens autour de la fosse, car ils appellent à l'aide. Morphaz utilise {spell:12533} et {spell:11019}. La dent tombe à chaque fois. Les guerriers du groupe voudront peut-être le même passage pour les plumes vaudou des trolls du balcon.",
	["{item:20019}, inside the {area:1417}"] = "{item:20019}, dans {area:1417}",
	["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} de niveau 60, d'une bibliothèque de {area:2577} : de quoi boire pour vous et votre groupe.",
	["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a {item:18249} (it drops from the imp Pusillin in the East wing; a {item:18594} also opens them; Blink no longer gets past). Other mages in your group can take it too: share it."] = "Volez jusqu'à Pennelune (Alliance) ou {area:1099} (Horde) et rendez-vous à {area:2577}, au centre de {zone:1444}. {npc:14368} attend dans l'Athenaeum, la bibliothèque, par l'aile Ouest, ou par les portes de la cour de l'aile Nord avec une {item:18249} (elle tombe sur le diablotin Pusillin dans l'aile Est ; un {item:18594} les ouvre aussi ; Transfert ne passe plus). Les autres mages du groupe peuvent la prendre aussi : partagez-la.",
	["Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. {area:1758} hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets."] = "Hydrogénos, un élémentaire d'eau élite de niveau 57, vit dans le quartier de Crochebois (Haches-Tripes Est) : poursuivez le diablotin Pusillin jusqu'à ce qu'il se retourne pour combattre, nettoyez la salle des satyres, puis descendez la rampe en spirale jusqu'au bassin. Un groupe de cinq. Le givre ne lui fait rien : les mages givre passent au feu ou aux arcanes. {area:1758} touche tout le monde à moins de 10 mètres : les attaquants à distance restent en retrait ; à un quart de sa vie, il appelle des hydrotins. L'essence tombe à chaque fois ; il ne revient pas avant la réinitialisation de l'instance.",
	["The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in {area:2279}."] = "Le bâton légendaire du Gardien : quarante éclats de Naxxramas, deux boss de raid et un démon à {area:2279}.",
	["Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the {area:2277} in {zone:1423}: each of its twelve bosses before Sapphiron and {npc:15990}, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack."] = "Quarante éclats d'Atiesh tombent à Naxxramas, le raid à 40 joueurs dans la nécropole au-dessus de {area:2277}, à {zone:1423} : chacun de ses douze boss avant Saphiron et {npc:15990}, ainsi que le coffre des quatre cavaliers, en lâche un environ une fois sur trois, et le raid les répartit. Il faut de nombreuses semaines de passages. Gardez tous les éclats dans une seule pile.",
	["{spell:28324}: forty splinters become the {quest:9250}"] = "{spell:28324} : quarante éclats deviennent {quest:9250}",
	["Right-click the {quest:9250} to start the quest, then take it to {npc:15192}, the bronze dragon in elf form who stands outside the {area:2300} in eastern {zone:1446}. Fly to {area:976} and ride east."] = "Clic droit sur {quest:9250} pour lancer la quête, puis apportez-le à {npc:15192}, le dragon de bronze sous forme d'elfe qui se tient devant {area:2300}, à l'est de {zone:1446}. Volez jusqu'à {area:976} et partez vers l'est.",
	["Two more raid bosses, a full 40-player raid each, both pieces always drop: the {item:22733} from {npc:15990} on his throne at the top of Naxxramas, the {item:22734} from {npc:15727} at the bottom of the {area:16076}, behind the {area:3478} in southern {zone:1451}. Each boss comes back once a week."] = "Deux autres boss de raid, un raid complet à 40 joueurs chacun, les deux pièces tombent à chaque fois : {item:22733} sur {npc:15990}, sur son trône au sommet de Naxxramas, {item:22734} sur {npc:15727}, au fond de {area:16076}, derrière {area:3478} au sud de {zone:1451}. Chaque boss revient une fois par semaine.",
	["{item:22734}: {npc:15727}, {area:16076}, past the {object:176146}"] = "{item:22734} : {npc:15727}, {area:16076}, après {object:176146}",
	["Take the befouled staff to {area:2279}, the dungeon at the north end of {zone:1423}, through the main gate. On {object:175433} find the patch of {object:181206} with a small white flame on it, stand on it and use the staff: {npc:16387}, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his {spell:17466} hurts everyone and cannot be dispelled (shadow resistance helps), his {spell:28342} curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup."] = "Apportez le bâton souillé à {area:2279}, le donjon au nord de {zone:1423}, par la porte principale. Sur {object:175433}, trouvez la plaque de {object:181206} où brûle une petite flamme blanche, placez-vous dessus et utilisez le bâton : {npc:16387}, Main de Sargeras (boss de niveau 63), apparaît. Venez avec un groupe solide : son {spell:17466} blesse tout le monde et ne se dissipe pas (la résistance à l'ombre aide), sa malédiction {spell:28342} doit être retirée aussitôt, et le Désarmement d'un guerrier lui fait lâcher son épée, qu'un joueur de mêlée peut ramasser et utiliser contre lui. Il reste jusqu'à deux heures et demie : vous pouvez vous regrouper.",
	["the befouled staff, on the {object:181206} inside {area:2279}"] = "le bâton souillé, sur {object:181206} dans {area:2279}",
	["Back to {npc:15192} at the {area:2300}."] = "Retour auprès de {npc:15192} à {area:2300}.",
	["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}; come in from the west road, the elites roam its east side."] = "La chaumière de {npc:6546} est au fond du marais à l'ouest de Theramore, juste au nord de {area:508} ; arrivez par la route de l'ouest, les élites rôdent du côté est.",
	["The Burning Blade Summoners (level 38-39, not elite) work the {area:602} in southern {zone:1443}, east of {area:2408}, and every one carries an {item:7291}. They cast {spell:686} from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western {zone:1412}, south-west of {zone:1456}."] = "Les invocateurs de la Lame ardente (niveau 38-39, non élites) occupent {area:602}, au sud de {zone:1443}, à l'est de {area:2408}, et chacun porte un {item:7291}. Ils lancent {spell:686} à 40 mètres, gardent un diablotin à leurs côtés et fuient chercher de l'aide quand ils sont presque morts ; des vierges du Néant patrouillent la ruine à colonnes à côté : attirez-les avec prudence. Mages de la Horde : un autre invocateur se tient seul à l'ouest de {zone:1412}, au sud-ouest de {zone:1456}.",
	["{area:1517} is a dungeon in the northern {zone:1418}: a group of five. Go in by the rear entrance, a cave in {area:1898} south-east of the main entrance (elite dragons fly nearby): the {npc:7023} (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an {npc:7209}, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back."] = "{area:1517} est un donjon au nord de {zone:1418} : un groupe de cinq. Entrez par l'entrée arrière, une grotte à {area:1898} au sud-est de l'entrée principale (des dragons élites volent à proximité) : {npc:7023} (élite de niveau 42) se tient juste après la première porte. À 80, 60, 40 et 20 %, il détache un {npc:7209}, élite lui aussi ; tant qu'un éclat vit, tous deux renvoient les sorts ciblés : utilisez des sorts de zone et votre baguette. Astuce en solo : franchissez la limite de zone toute proche chaque fois qu'un éclat apparaît ; la Sentinelle se soigne mais rapetisse sans cesse. Elle lâche toujours la source d'énergie, et met 2 heures à revenir.",
	["Back to {npc:6546}. Accepting {quest:1957} opens a rift beside her cottage and starts a 10 minute timer: twelve {quest:1957} (level 40, Shock and {spell:403}) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out."] = "Retour auprès de {npc:6546}. Accepter {quest:1957} ouvre une faille à côté de sa chaumière et lance un compte à rebours de 10 minutes : douze {quest:1957} (niveau 40, Électrocution et {spell:403}) en sortent environ quatre à la fois. En attaquer un n'attire pas les autres. Se tenir au bord du champ les attire tous ; l'arbre au sud-ouest est hors de leur portée mais à portée de vos sorts. Tuez-en douze et rendez la quête avant la fin du compte à rebours.",
	["At 40 the mage trainers who send you to {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) also have {quest:2861}, a quest any class can do. {npc:6546} then wants the {quest:2846} from {npc:7795}, a level 46 elite naga in {area:978}, the troll dungeon in north-western {zone:1446}: a group of five, level 44-54. She is one of the bosses by the sacred pool, and the tiara always drops. The reward window shows the {item:9527} and the {item:9531}."] = "Au niveau 40, les maîtres mages qui vous envoient voir {npc:6546} ({npc:5497}, Bink, {npc:4568}, {npc:5885}) ont aussi {quest:2861}, une quête accessible à toutes les classes. {npc:6546} veut ensuite {quest:2846} de {npc:7795}, une naga élite de niveau 46 à {area:978}, le donjon troll au nord-ouest de {zone:1446} : un groupe de cinq, niveau 44-54. C'est l'un des boss près du bassin sacré, et le diadème tombe à chaque fois. La fenêtre de récompense montre {item:9527} et {item:9531}.",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to {npc:8379} at the top of the tower; an attendant at the top sends you back down, as often as you like."] = "Volez jusqu'à {area:3137} (Alliance) ou {area:1237} (Horde). {npc:8395} campe sous la tour de son maître, à peu de distance à l'est de {area:1237} : depuis l'embranchement de la route principale de {zone:1447} à {area:1221}, allez tout droit vers le nord jusqu'aux falaises. Descendez de monture avant qu'il ne vous téléporte en haut, sinon la téléportation risque d'échouer. Un sentier sans ennemis monte jusqu'à {npc:8379} au sommet de la tour ; un serviteur en haut vous redescend, autant de fois que vous le voulez.",
	["The blood elves hold the {area:1220} on the hills of north-eastern {zone:1447}. Blood Elf Surveyors (51-52, {spell:8349} up close) and Reclaimers (52-53, {spell:133}, and they heal and {spell:139} each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes."] = "Les elfes de sang tiennent {area:1220} sur les collines au nord-est de {zone:1447}. Les arpenteurs elfes de sang (51-52, {spell:8349} au corps à corps) et les récupérateurs (52-53, {spell:133}, ils se soignent et se lancent {spell:139}) lâchent chacun la poussière environ une fois sur quatre ; ils vous repèrent de loin : attirez-les par les bords. Ils reviennent au bout de 5 minutes et demie.",
	["The Spitelash Sirens (level 50-52) walk the ruins and beaches around the {area:1221} and the bay east of {area:1237}, often three together, and a few stand inside the {area:1223}; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. {npc:7864} ghosts wander the ruins: watch your back."] = "Les sirènes Fouette-bile (niveau 50-52) parcourent les ruines et les plages autour de {area:1221} et la baie à l'est de {area:1237}, souvent par trois, et quelques-unes se tiennent dans {area:1223} ; chacune lâche un corail environ une fois sur quatre. Les hurleuses Fouette-bile se ressemblent presque mais ne le lâchent jamais. Tuer les autres nagas fait apparaître plus de sirènes à leur place. Des fantômes {npc:7864} errent dans les ruines : surveillez vos arrières.",
	["{area:1477}, the {area:1417}, lies in the {area:74}: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to {npc:5710} and {npc:5711} in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, {spell:12533} and {spell:11019}) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear."] = "{area:1477}, {area:1417}, se trouve dans {area:74} : montez les marches du bâtiment englouti, nagez vers le fond et suivez le passage jusqu'au portail. Un groupe de cinq, niveau 50-54. Morphaz ne vous attend pas à l'arrivée. Tuez d'abord les six gardiens trolls (élites de 50-52) sur les plates-formes de l'anneau supérieur ; cela ouvre le chemin (la rampe de gauche depuis l'entrée) vers {npc:5710} et {npc:5711} dans la fosse du sacrifice. Une fois Jammal'an mort, deux drakes verts, Tisserand et Faux-de-rêve, sortent et patrouillent la fosse : attirez-les un par un. Une fois les deux morts, Morphaz (élite de niveau 52, {spell:12533} et {spell:11019}) et Hazzas apparaissent ensemble et ne peuvent être séparés : combattez les deux. L'éclat tombe à chaque fois. Les chasseurs, prêtres et voleurs de niveau 50 ont aussi besoin de Morphaz : un groupe d'entre eux se partage un seul passage.",
	["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the {zone:1413}. Her cottage is no refuge: mobs follow you inside. Take both her quests."] = "{npc:6546}, une ermite, vit dans une chaumière au fond du marais à l'ouest de Theramore, juste au nord de {area:508}. Des élites de niveau 38-41 rôdent à l'est de sa ferme, et à la nage on croise des carapaces de vase de niveau 42 : arrivez par l'ouest, par la route venant de {zone:1413}. Sa chaumière n'est pas un refuge : les monstres vous suivent à l'intérieur. Prenez ses deux quêtes.",
	["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548} passe ses journées au circuit de course de {area:439}, au sud-est de {zone:1441}.",
	["The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of {area:321}; every kind of them drops a {item:7273} about two times in five: you need ten. Then go to the {area:336} (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the {item:7272} forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more."] = "Les trolls Fânécorce (niveau 30-36) tiennent les villages du sud-est d'Arathi et au sud de {area:321} ; chacun d'eux lâche un {item:7273} environ deux fois sur cinq : il vous en faut dix. Allez ensuite à {area:336} (le cercle extérieur, pas le cercle intérieur). Trois élémentaires (niveau 33-39) entourent sa pierre centrale : attirez-les un par un et éliminez-les d'abord. Placez-vous à la pierre centrale et utilisez un bâton totem ; une dizaine de secondes plus tard, {item:7272} se forme sur la pierre : cliquez dessus. Si vous mourez avant de le ramasser, la ronce et les bâtons sont perdus et il en faut dix autres.",
	["at the middle stone of the {area:336}"] = "à la pierre centrale de {area:336}",
	["{npc:6546} also wants one {item:1529}, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of {area:271} drop one about every fifth kill. Do not sell it to a vendor by mistake."] = "{npc:6546} veut aussi un {item:1529}, une gemme verte. Les mineurs en trouvent parfois dans les filons ; l'hôtel des ventes en vend ; les coureurs des côtes Aileron-Déchiré, sur la côte au sud-ouest de {area:271}, en lâchent un environ une fois sur cinq. Ne le vendez pas à un marchand par erreur.",
	["Tirth sold the book to the Scarlet Crusade. The {area:796} stands in north-eastern {zone:1420}; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in {npc:6487}'s round room: on the left-hand shelf as you face his room, next to the {item:5535}. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read."] = "Tirth a vendu le livre à la Croisade écarlate. {area:796} se dresse au nord-est de {zone:1420} ; faites l'aile de la Bibliothèque avec un groupe de cinq. Le livre est dans le dernier long couloir, celui qui mène à la salle ronde de {npc:6487} : sur l'étagère de gauche quand vous faites face à sa salle, à côté de {item:5535}. Prenez le gros livre bleu en surbrillance qui dépasse de l'étagère ; un curseur en forme de loupe indique un livre que l'on peut seulement lire.",
	["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Une nouvelle apparence pour {spell:118} : la cible devient un cochon au lieu d'un mouton.",
	["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower, a short way east of {area:1237}: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower."] = "Volez jusqu'à {area:3137} (Alliance) ou {area:1237} (Horde). {npc:8395} campe sous la tour de {npc:8379}, à peu de distance à l'est de {area:1237} : depuis l'embranchement de la route principale de {zone:1447} à {area:1221}, allez tout droit vers le nord jusqu'aux falaises. Descendez de monture et il vous téléporte en haut ; un sentier monte jusqu'à l'archimage au sommet de la tour.",
	["{npc:8408} (level 55, not elite, Strike and {spell:99}) hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He always drops the {item:23250} and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine."] = "{npc:8408} (niveau 55, non élite, Frappe et {spell:99}) se cache derrière ses gardes Fouette-bile dans {area:1223}, le plus grand bâtiment au milieu de {area:1221}. Il lâche toujours {item:23250} et revient 5 minutes et demie après avoir été tué. Quittez d'abord tout groupe de raid : un raid ne valide rien, un groupe si.",
	["Back to the {area:1221}, full of Spitelash naga. Cast your sheep {spell:118} (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with {spell:122} and {spell:1449}. Fifty clones are needed, so it takes a while; not in a raid group."] = "Retour à {area:1221}, plein de nagas Fouette-bile. Lancez votre {spell:118} mouton (celui en tortue ne fait rien) sur un naga et attendez quelques secondes : il se divise en deux à six clones de métamorphose d'environ 150 points de vie qui s'enfuient vite. Placez-vous à côté du mouton et frappez-les dès qu'ils apparaissent avec {spell:122} et {spell:1449}. Il faut cinquante clones, cela prend du temps ; pas en groupe de raid.",
	["{npc:8379}: {spell:118} (pig)"] = "{npc:8379} : {spell:118} (cochon)",
	["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "Le bâton épique du prêtre : {spell:23101} de {area:2717}, le sauvetage des paysans de {npc:14494}, puis l'Œil de l'ombre.",
	["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "{item:18646} vient de {object:179703}, le coffre qui apparaît quand {npc:12018} se rend dans {area:2717}, un raid à 40 joueurs (il est dans la cache environ une fois sur deux). Le portail de {area:2717} est au fond de {area:1584} ; une fois l'Harmonisation avec le Cœur faite (un {item:18412} pris à côté de ce portail), {npc:14387}, dans {area:254}, vous y téléporte directement. Rien dans cette suite ne commence sans l'Œil : {npc:14494} est invisible tant que vous ne l'avez pas équipé.",
	["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387} : l'accès à {area:2717} une fois harmonisé",
	["{item:18646}: {area:2717}, through {area:254}"] = "{item:18646} : {area:2717}, par {area:254}",
	["Equip {item:18646}, then find {npc:14494}, a ghost on the hillside in the north-west of the {zone:1423}, west of {area:2279}'s gate (if she does not show, take the Eye off and put it back on). {quest:7621} is only talk; {quest:7622} starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or {item:13931}, and a stack of {item:8956} or {item:13180} for the skeletons."] = "Équipez {item:18646}, puis trouvez {npc:14494}, un fantôme sur le flanc de colline au nord-ouest de {zone:1423}, à l'ouest de la porte de {area:2279} (si elle n'apparaît pas, retirez l'Œil et remettez-le). {quest:7621} n'est qu'une conversation ; {quest:7622} commence dès que vous l'acceptez : préparez-vous d'abord : mana plein, potions de mana majeures, runes démoniaques ou sombres, nourriture de mana ou {item:13931}, et une pile de {item:8956} ou de {item:13180} pour les squelettes.",
	["Save 50 peasants before 15 die (the {object:179694} by the path counts the dead). They walk from the cave towards {npc:14494} in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first ({spell:552}), keep {spell:139} on the hurt ones, {spell:2061} the nearly dead, and kill skeletons as they spawn: one {spell:15237} of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and {npc:14494} is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back."] = "Sauvez 50 paysans avant que 15 ne meurent ({object:179694} au bord du chemin compte les morts). Ils marchent par vagues depuis la grotte vers {npc:14494}, attrapent des maladies et attirent squelettes et archers squelettes. Guérissez d'abord les maladies à lueur violette ({spell:552}), gardez {spell:139} sur les blessés, {spell:2061} sur ceux qui sont presque morts, et tuez les squelettes dès qu'ils apparaissent : un {spell:15237} de rang 3 ou plus les tue, l'huile demande deux impulsions pendant qu'ils vous frappent. Protégez-vous au début de chaque vague ; les barres de noms amicales permettent de repérer facilement les paysans blessés. Des amis peuvent vous améliorer avant que vous n'acceptiez et peuvent soigner ou guérir les paysans, mais ils ne doivent pas vous soigner ni vous améliorer, attaquer un squelette ou amener un familier une fois l'épreuve commencée, sinon un démon apparaît et tue tout le monde. En cas d'échec, {npc:14494} disparaît un moment (de 15 minutes à deux heures selon les joueurs) ; reparlez-lui à son retour.",
	["17,060 XP and 1g55s at 50: {zone:1447}, then Morphaz in the {area:1417} (group of 5). The item choice may be gone."] = "17 060 points d'expérience et 1 po 55 pa au niveau 50 : {zone:1447}, puis Morphaz dans {area:1417} (groupe de 5). Le choix d'objet a peut-être disparu.",
	["{npc:8405}, a furbolg, lives on the clifftop north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up."] = "{npc:8405}, un furbolg, vit au sommet de la falaise au nord-est de {area:1221}. Alliance : volez jusqu'à {area:3137} ; Horde : volez jusqu'à {area:1237}. Partez vers l'est et quittez la route à l'embranchement avant les ruines, puis suivez le bord nord de la falaise vers l'est jusqu'à lui : les ruines nagas et la plage en contrebas sont enfermées par des falaises sans chemin pour monter.",
	["Carrying an {item:7972} already? It counts at once. Otherwise any undead may drop one, rarely: the {npc:7864} (level 48) in the {area:1221} below {npc:8405}'s cliff drop it about one kill in ten, the highborne ghosts on {zone:1447}'s border with {zone:1440} (level 45-46) a little less, the Anguished and {npc:7523} in {zone:1452} (54-55) about one in eight. The Auction House is usually quicker."] = "Vous portez déjà un {item:7972} ? Il compte tout de suite. Sinon, n'importe quel mort-vivant peut en lâcher un, rarement : {npc:7864} (niveau 48) à {area:1221}, sous la falaise de {npc:8405}, en lâchent un environ une fois sur dix, les fantômes bien-nés à la limite de {zone:1447} et de {zone:1440} (niveau 45-46) un peu moins, les angoissés et {npc:7523} à {zone:1452} (54-55) environ une fois sur huit. L'hôtel des ventes est généralement plus rapide.",
	["Morphaz is a level 52 elite green dragon inside the {area:1417}, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to {area:75}; Alliance: fly to {area:1438} in the {zone:1419} and ride north. The temple stands in the middle of the {area:74}: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then {npc:5710} below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops."] = "Morphaz est un dragon vert élite de niveau 52 dans {area:1417}, un donjon à cinq : venez avec un groupe de cinq (un groupe de niveau 60 le fait sans peine). Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'à {area:1438} dans {zone:1419} et montez vers le nord. Le temple se dresse au milieu de {area:74} : montez les marches du côté sud, nagez vers le fond de la salle inondée et prenez les escaliers jusqu'au portail. À l'intérieur, Morphaz n'apparaît que tard : tuez les six mini-boss trolls des balcons supérieurs, puis {npc:5710} en dessous ; cela réveille les drakes Tisserand et Faux-de-rêve dans la fosse du sacrifice, et tuer les deux fait venir Morphaz et Hazzas. Le duo patrouille ensemble et ne peut être séparé : attirez-les dans un couloir et faites-les tourner dos au groupe par le tank (souffle et repoussement). Ramassez son butin en groupe, pas en raid : le sang tombe à chaque fois.",
	["{quest:8257}: the {area:1417} entrance"] = "{quest:8257} : l'entrée de {area:1417}",
	["{npc:10922} is at the {area:2479} in southern {zone:1448}. Horde: fly to {area:1997} and ride south-east; Alliance: fly to {area:415} in {zone:1440} and ride north into {zone:1448}. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick {item:19990}, {item:20006} or Woestave, and Forever's notes say that choice may be gone."] = "{npc:10922} est à {area:2479}, au sud de {zone:1448}. Horde : volez jusqu'à {area:1997} et partez vers le sud-est ; Alliance : volez jusqu'à {area:415} dans {zone:1440} et montez vers le nord jusqu'à {zone:1448}. Elle prend le sang contre de l'expérience et de l'or. Regardez la fenêtre de récompense avant de rendre la quête : Classic laissait choisir {item:19990}, {item:20006} ou Bâton du malheur, et les notes de Forever disent que ce choix a peut-être disparu.",
	["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Ouvre {area:3486}, le repaire caché des voleurs dans les collines d'Alterac, et les missions de {npc:13085} contre le Syndicat.",
	["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "Au niveau 24, le maître voleur de n'importe quelle capitale ({npc:332} ou {npc:918} à {zone:1453}, Gest ou Ormok à {zone:1454}, et les autres) a pour vous une {item:17126} de {npc:13936} : demandez-la dans sa fenêtre de dialogue. Ouvrez-la : la quête vous donne {item:17125} pour {npc:6707}. Apprenez d'abord {spell:1846} auprès de votre maître si ce n'est pas fait ; l'entrée en est l'épreuve.",
	["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "La Horde vole jusqu'à {area:272}, l'Alliance jusqu'à {area:271}. Le sentier du manoir est difficile à voir : il commence derrière le plateau au nord de {area:275}, à l'est de {area:272}, monte dans les collines et tourne deux fois jusqu'à un petit tunnel. Un coffre se trouve dans le tunnel : ne l'ouvrez pas. Lancez {spell:1846} près de lui et approchez-vous ; c'est le Rite de la ruse (il revient au bout de 5 minutes). Ouvrir le coffre fait venir Milton, un voleur élite d'environ niveau 32. Au bout du tunnel se trouve {area:3486} : {npc:6707} est à l'étage, à l'intérieur. N'attaquez personne au manoir : cela coûte de la réputation auprès de {npc:13936}.",
	["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "Rite de la ruse : {spell:1846} à côté du coffre du tunnel",
	["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} est dans {area:275}, la forteresse du Syndicat au sud du manoir ; il peut se tenir à quinze endroits différents dans le donjon : cherchez bien. Vite et sans bruit, dit {npc:13085}. Faites les poches des voleurs, mages de l'ombre et veilleurs du Syndicat de niveau 20-21 en chemin : ils portent {quest:6701} pour la quête de réputation répétable des gardes.",
	["Pick Pocket Syndicate members for {quest:6701}"] = "Faites les poches des membres du Syndicat pour {quest:6701}",
	["In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "Vers le milieu de la trentaine, {npc:13085} a deux autres missions ; prenez les deux. Barton mène une troupe d'éclaireurs du Syndicat à {area:280}, à l'est de {zone:1416}, dans l'une des maisons, entouré de membres du Syndicat camouflés. Faites-lui les poches pour le rapport et ne le tuez pas : il ne le lâche pas. Si votre niveau est inférieur au sien, il voit à travers le camouflage ; Maître de la tromperie aide, ou Distraction, Disparition et revenez par derrière. {spell:921} peut rater plusieurs fois de suite.",
	["Pick Pocket Barton for {item:275482}"] = "Faites les poches de Barton pour {item:275482}",
	["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "Retour auprès de {npc:13085} ; le rapport vous lance sur les traces des reliques des Perenolde. Deux tours se dressent parmi {area:281}, au milieu de {zone:1416}, tenues par des ogres : le bouclier est dans la tour nord, l'épée dans la tour sud, entourée d'ogres élites qui voient de loin. Restez camouflé ; rien ne garde les reliques à l'intérieur.",
	["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "{area:324}, à l'ouest d'Arathi, est une place forte du Syndicat ; pour y entrer, il vous faut un uniforme. {area:313}, au nord-ouest d'Arathi, est tenu par des bandits de grand chemin, des traqueurs et des mercenaires du Syndicat (niveau 30-32) : trouvez-y {object:656157} et prenez l'uniforme ; cela termine {quest:96783}.",
	["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Les hommes de Falconcrest font l'échange à l'extrémité sud de {area:1057}, le vieux mur entre Arathi et {area:287}. Tuez les deux qui gardent la boîte et prenez {item:275882}. Gardez {item:275706} : {npc:13085} le veut en retour avec la livraison.",
	["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486} se cache dans les collines à l'est de {area:272}. La Horde vole jusqu'à {area:272}, l'Alliance jusqu'à {area:271}. Le sentier commence derrière le plateau au nord de {area:275}, monte dans les collines et passe par un petit tunnel jusqu'à {zone:1416} ; le seigneur Jorach est dans le manoir. N'attaquez personne au manoir : une réputation perdue auprès de Ravenholdt le pousse à refuser de vous parler.",
	["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "L'Alliance vole jusqu'à {area:3137}, la Horde jusqu'à {area:1237}. Seuls les chamans Brann-Bois de niveau 50-51, dans les collines des furbolgs au nord de {zone:1447}, portent le sac (les furbolgs de niveau 47-49 plus au sud non) : environ une fois sur trente. Faites-leur plutôt {spell:921} et vous ne perdez aucune réputation Brann-Bois ; si vous êtes Inamical ou mieux auprès de {area:1769}, marquez-les d'abord « En guerre » dans votre panneau de réputation. Ils lancent {spell:403} et {spell:6535}, se soignent entre eux et fuient quand ils sont presque morts.",
	["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395}, qui campe sous les falaises juste à l'est de {area:1237}, vous téléporte en haut (descendez d'abord de monture) ; un sentier mène à la tour de Xylem.",
	["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "Les vases sylvestres (niveau 52-53, {spell:6907} au corps à corps) lâchent un fragment quatre fois sur cinq : le plus grand groupe, sept d'entre elles, est dans les collines de {area:2497} au nord-est de {zone:1447}, quatre autres au sud-est de {area:1237}. Faites-leur les poches avant de les tuer pour un ou deux fragments de plus. Tuer les ravageurs Aile-de-brume et les hippogriffes qui partagent leurs emplacements fait apparaître plus de vases.",
	["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, un drake vert élite de niveau 52, vit au fond de {area:1417} : un groupe de cinq, niveau 50-54. Le temple se dresse dans {area:74} ; montez dans le bâtiment englouti, nagez vers le fond et suivez le passage jusqu'au portail. Horde : volez jusqu'à {area:75} ; Alliance : volez jusqu'à {area:1438} et continuez à monture. Il n'est pas là à votre arrivée : tuez d'abord les six gardiens trolls (élites de 50-52) sur les plates-formes de l'anneau supérieur, ce qui ouvre le chemin (la rampe de gauche depuis l'entrée) vers {npc:5710} dans la fosse du sacrifice. La mort de Jammal'an fait sortir deux drakes, Tisserand et Faux-de-rêve ; une fois les deux morts, Morphaz et Hazzas apparaissent ensemble et combattent en duo. Leur {spell:12533} inflige des dégâts de nature : les potions de protection contre la nature aident ; les poisons et {spell:2094} ne fonctionnent pas sur eux. La clé tombe à chaque fois. Les chasseurs, prêtres et mages de niveau 50 ont aussi besoin de Morphaz : un seul passage sert à tous.",
	["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "{item:277246}, la paie de C pour une mission en solo dans {area:796}.",
	["C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "La mission suivante de C arrive par lettre : une fois au niveau 30 et la mission du cor faite, passez dans n'importe quelle capitale et la lettre de C arrive dans la boîte aux lettres ; c'est seulement alors que {object:410369}, près de {area:204}, au sud de Pins-Argentés juste au sud de {area:236}, la propose. Les données de la quête indiquent un minimum de 25, mais les joueurs reçoivent la lettre, et la mission, au niveau 30.",
	["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "Le monastère se dresse à l'extrême nord-est de {zone:1420}. Entrez seul, hors de tout groupe. Avant d'entrer, prenez {spell:427592} dans le casier à fournitures des écuries derrière le monastère et portez-le ; le camouflage et les actions suspectes le retirent : remettez-le après chaque changement d'aile. Dans le Cimetière, dans la chambre d'Expiation (la première grande salle), faites {spell:921} sur un {npc:4293} ou un crieur écarlate pour {item:210963}. Dans la Bibliothèque, ouvrez avec elle la boîte aux lettres personnelle de l'Athenaeum et lisez le message confidentiel. Il vous renvoie vous asseoir sur les deux bancs entre les deux statues du Cimetière. Guettez les messages du mécanisme, puis prenez {item:210968} dans le coffre de pierre : un élite se tient près du coffre avec une patrouille derrière, mais depuis le côté du mausolée nord, vous pouvez tourner la caméra jusqu'à voir la boîte et cliquer dessus à travers le mur (une touche d'interaction marche aussi). Un fantôme élite marche près du mausolée ; le morceau brisé sur son bord vous tient hors de son chemin. Retournez ensuite à la Bibliothèque pour le reliquaire verrouillé et l'œil. Évitez de vous battre dans l'instance.",
	["The {item:277210}, C's payment for a solo job inside {area:236}."] = "{item:277210}, la paie de C pour une mission en solo dans {area:236}.",
	["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} est un coffre dans une maison juste à l'extérieur de {area:204}, au sud de Pins-Argentés, au sud de {area:236}. Ouvrez-le et lisez le mot de C : la mission doit se faire seul, hors de tout groupe.",
	["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}, un gobelin amical envers les deux factions, se tient parmi la KapitalRisk à {area:461}, à l'est des Serres-Rocheuses, un peu au nord-est de {area:460}. La Horde vole jusqu'à {area:460} ; l'Alliance jusqu'à {area:467}. Il veut un {item:210187} avant de livrer des explosifs : les bûcherons de la KapitalRisk (niveau 18) qui travaillent autour de lui en ont dans leurs poches. Approchez-vous camouflé derrière l'un d'eux et faites {spell:921} ; les tuer ne le donne pas.",
	["{spell:921} a {npc:3989} for a {item:210187}"] = "{spell:921} sur un {npc:3989} pour un {item:210187}",
	["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:461}, dans {object:2164} de {object:2101}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord un {item:5770} et un {item:3577} (étapes suivantes) pour éviter un voyage.",
	["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:5172}, à {zone:1455}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord un {item:5770} et un {item:3577} (étapes suivantes) pour éviter un voyage.",
	["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:3326}, dans {object:172960}, vous envoie voir {npc:6266} à {area:392}. Achetez d'abord un {item:5770} et un {item:3577} (étapes suivantes) pour éviter un voyage.",
	["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "Au niveau 31, {npc:4563}, dans {object:36082}, vous envoie voir {npc:6266} à {area:392} ; le zeppelin de {zone:1420} va à {zone:1411}. Achetez d'abord un {item:5770} et un {item:3577} (étapes suivantes) pour éviter un voyage.",
	["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} se tient près de la tour de {npc:6251}, sur la colline au-dessus de {area:392}, derrière la cabane des ingénieurs. Elle prend la robe, puis envoie le lingot d'or à {npc:2670} à {area:35}.",
	["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "Le bateau de {area:392} va à {area:35}. {npc:2670} tient {object:59851} à un étage supérieur de la ville. Donnez-lui {item:3577} ; il filera le fil plus tard.",
	["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25. The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south, drop the stone half the time; they resist fire, so use {spell:686} and Corruption."] = "Les satyres Haine-furie (niveau 31-32) tiennent {area:603} à l'extrême nord-est de {zone:1443}, après {area:608} : deux victoires sur cinq donnent une fiole, comptez donc environ 25. Les infernaux inférieurs (36-37) et les gardiens de portail démoniaque (38) de {area:602}, au sud, lâchent la pierre une fois sur deux ; ils résistent au feu : utilisez {spell:686} et Corruption.",
	["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "Retour auprès de {npc:2670} à {area:35} : il propose {quest:4785}, une quête que vous lui rendez aussitôt. Il n'affiche peut-être pas de marque de quête ; parlez-lui quand même.",
	["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. They resist fire: {spell:686} and Corruption. Below 38 they hit hard; the Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Les exilés ardents (niveau 38-39), des élémentaires de feu à {area:334}, à l'ouest de {zone:1417}, lâchent le charbon environ une fois sur trois. Ils résistent au feu : {spell:686} et Corruption. Sous le niveau 38, ils frappent fort ; les charmes de crête des exilés des crêtes près de {area:321} achèvent un exilé déjà blessé. Faites un {item:6265} avec {spell:1120} en chemin.",
	["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265} : {spell:1120} sur un exilé pendant qu'il meurt",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} attend à côté de {npc:14469} sur une butte juste au nord-est de {area:1997} : en venant du nord par le pont de {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques vases. Remettez-lui {quest:8419} du maître avec le tissu. Il veut ensuite dix {item:20613} et quatre {item:20614}.",
	["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} attend à côté de {npc:14469} sur une butte juste au nord-est de {area:1997} : en venant du nord par le pont de {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques vases. Prenez sa propre {quest:8420} et remettez-lui aussitôt le tissu. Il veut ensuite dix {item:20613} et quatre {item:20614}.",
	["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "Les tréants Ferarbre (niveau 52) de {area:1767}, au nord de {zone:1448}, à l'ouest de {area:1998}, lâchent {item:20613} une fois sur quatre ; le grand {npc:7149} (55) en lâche souvent trois d'un coup mais frappe fort et étourdit. Les vases souillées (51) autour de {npc:14470} et le long du Sang-venin lâchent l'essence une fois sur cinq.",
	["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} veut maintenant six {item:20609} de {area:1417} : un passage en donjon.",
	["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "{area:1417} ({area:1477}, niveau 50-56, un groupe de cinq) se dresse au milieu de {area:74} : nagez vers le temple englouti et prenez les escaliers jusqu'à l'entrée. Les six gardiens trolls (niveau 51-52, élites) se tiennent sur les balcons autour de la fosse centrale, chacun avec des renforts ; chacun lâche sa plume à chaque fois : Taillade et {npc:5716} l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte. Impossible en solo au niveau 52.",
	["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:461}, dans {object:2164} de {object:2101}, vous envoie voir {npc:6266} à {area:392}.",
	["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:5172}, à {zone:1455}, vous envoie voir {npc:6266} à {area:392}.",
	["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "Au niveau 35, {npc:3326}, dans {object:172960}, vous envoie voir {npc:6266} à {area:392}.",
	["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "Au niveau 35, {npc:4563}, dans {object:36082}, vous envoie voir {npc:6266} à {area:392}. Le zeppelin de {zone:1420} va à {zone:1411}.",
	["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} et ses deux acolytes se tiennent dans la tour de {npc:6251}, sur la colline au-dessus de {area:392}.",
	["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} occupe le centre-sud de {zone:1443}, à l'est de {area:2408}. Les invocateurs de la Lame ardente (niveau 38-39, des démonistes avec diablotins) portent {item:7291} à chaque fois. Pour l'esprit, amenez votre démon à peu de vie avec vos dégâts sur la durée, puis canalisez le rubis ou l'émeraude sur lui et continuez pendant qu'il meurt, comme avec {spell:1120} : la gemme n'inflige aucun dégât. Le rubis fonctionne sur les chiens gangrenés du cercle : les deux dévoreurs de mana (37-38) au nord, et les chasseurs de mages (38) et chasseurs telluriques (39) plus au sud. L'émeraude fonctionne sur les infernaux inférieurs (36-37, seize d'entre eux, résistants au feu).",
	["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "Retour auprès de {npc:6266}, dans la tour au-dessus de {area:392}, avec l'esprit et la gemme d'abord : son orbe en découle.",
	["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Before you accept Cleansing, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 35-38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} vit dans sa ferme au milieu de {zone:1445}, au sud de la route venant de {zone:1413} et au sud-ouest de Theramore ; un esprit guérisseur se tient à côté. Mortefange, un crocilisque de niveau 45, patrouille les ruisseaux juste au nord-est. Avant d'accepter Purification, éliminez les araignées et les crocilisques autour de son enclos. Accepter lance un compte à rebours de 3 minutes : elle marche jusqu'à l'enclos et libère {npc:6549}. Il est élite (niveau 40) : mieux vaut être en groupe ; un démoniste d'environ 40 peut le faire seul avec Peur ou {spell:710} et des dégâts sur la durée, un démoniste de niveau 35-38 vient avec un ami. Le compte à rebours continue après la victoire : rendez la quête aussitôt. Si le temps est écoulé, abandonnez la quête et reprenez-la auprès de {npc:6546}.",
	["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "Retour auprès de {npc:6266}, dans la tour au-dessus de {area:392}, avec l'orbe purifié. Sur la voie du chien gangrené, acceptez sa dernière quête et attendez à côté d'elle qu'elle achève {item:15108} (ne l'attaquez pas : le journal de quêtes parle de la tuer), puis reparlez-lui et choisissez l'orbe de main gauche ou le bâton.",
	["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247} campe à côté de {npc:6244}, sous une tente juste au nord-est de {area:378}, au sud de {zone:1413}. Les démonistes de l'Alliance le rejoignent depuis {area:392} ou Theramore ; ceux de la Horde descendent vers le sud depuis la Croisée. Il veut des fragments de deux donjons : prenez la quête avant vos passages à {area:2797} et à {area:236}.",
	["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (niveau 24-32, un groupe de cinq) s'ouvre dans les ruines de la côte nord-ouest de {zone:1440}, sous l'eau à {area:414}. Les acolytes du Crépuscule (niveau 24-25, élites, soigneurs) se tiennent dans les dernières salles, autour de {npc:4832} et de l'autel avant {npc:4829} ; chacun lâche un fragment, mais seuls trois apparaissent par passage et ils ne reviennent pas avant deux heures : un passage sert donc un seul démoniste. Tuez-les en premier, avant qu'ils ne soignent les autres.",
	["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236} (niveau 22-30, un groupe de cinq) se dresse sur la colline au sud de {area:228}. Libérez le prisonnier des cellules à droite de l'entrée et il ouvre le chemin vers la cour. Les âmes noires d'Ombrecroc (niveau 20-21, élites) ne sont pas dans la cour : elles parcourent les salles au-delà, en haut de la rampe qui tourne à gauche et dans le bâtiment qui suit. Il y en a environ douze par passage et une sur cinq lâche le grand fragment : éliminez-les toutes et refaites un passage s'il ne tombe pas.",
	["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "Au niveau 50, {npc:14469} et son diablotin {npc:14470} attendent sur une butte au centre de {zone:1448}, juste au nord-est de {area:1997} : en venant du nord par le pont de {area:1765}, ils se tiennent à l'écart de la route, à l'est, après quelques vases. {npc:14469} vous envoie voir {npc:14470}, à côté de lui, qui veut trois essences gangrenées parfaites de trois endroits.",
	["{area:1763} lies just south of {area:1997}, west of the road. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} se trouve juste au sud de {area:1997}, à l'ouest de la route. De ses deux grottes, {area:1770} est celle du nord, plus haut sur la colline ; l'autre n'a pas de légionnaires. Les tunnels de {area:1770} filent vers le nord sous les collines, et les légionnaires de Jaedenar (niveau 55) se tiennent dans les salles les plus profondes, des premières rampes jusqu'à la salle de {npc:9516} ; ils assènent un uppercut à quiconque est au corps à corps. Trois victoires sur quatre donnent l'essence, mais seuls onze environ apparaissent : frayez-vous un chemin et attendez une réapparition de cinq minutes s'il le faut. Les cultistes de {area:1763} et de {area:1770} sont tous hostiles.",
	["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "Les sentinelles gangregardes (niveau 54) patrouillent autour de {area:72}, au sud de {zone:1419}, chacune avec un chasseur corrompu. Laissez tranquilles les serviteurs de Razelikh de niveau 57 : on ne peut pas les tuer sans leur propre quête.",
	["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Les restes de {npc:14467} reposent à {area:1766}, le cratère brûlé au nord de {npc:14469} : suivez la route vers le nord depuis son camp ; les restes sont un peu à l'est. Utilisez {item:18626} à côté d'eux et attendez qu'il se relève. {npc:14467} est élite (niveau 55) : mieux vaut être en groupe ; un démoniste de niveau 55 ou plus peut le faire seul avec Peur et des dégâts sur la durée, ou avec Asservir démon, mais les sorts de feu ne lui font rien et il vous repousse. Si vous mourez, il se soigne entièrement ; il se relève trois minutes après sa mort. Un infernal élite patrouille le bassin au sud des restes : éloignez {npc:14467} de lui. Il lâche toujours son cœur. Vous avez perdu {item:18626} ? Abandonnez la quête et reprenez-la auprès de {npc:14470}.",
	["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "Au niveau 60, {npc:14463} attend à {area:73}, le creux rempli de démons à l'ouest de {zone:1419}. La Balafre est pleine d'élites qui frappent fort : posez-vous d'abord une pierre d'âme, puis longez le mur de droite en entrant, ou traversez à monture. {npc:14463} vous confie deux missions à la fois.",
	["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "Les satyres Sauvengeance (niveau 55-57, élites) remplissent le quartier de Crochebois, l'aile est de {area:2577} : venez avec un groupe de cinq. Quatre sur cinq lâchent un sang, mais ils ne reviennent pas avant deux heures et un passage complet peut ne pas suffire pour quinze ; réinitialisez et recommencez. La porte de derrière à {area:2518} demande {item:18249}, qui tombe dans cette aile ; tant que personne ne l'a, entrez par la porte principale de {area:2577}, au centre de {zone:1444}.",
	["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Les démons Hederine (niveau 57-60, élites) tiennent {area:2256}, à l'extrême sud de {zone:1452} : mieux vaut être en groupe. Deux tueurs gardent la gorge après le pont ; le tunnel ouest mène à d'autres initiés, les plus faciles (attention à leur {spell:7645}). Un démoniste peut les tuer seul un par un avec Peur ou {spell:710} et des dégâts sur la durée, mais lentement. N'importe lequel peut lâcher les larmes, quatre fois sur cinq.",
	["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Rendez les deux à {npc:14463} et prenez {item:18601}. Trouvez un {npc:12396} (niveau 61, élite) seul à {area:73}, ouvrez à environ 30 mètres avec votre marcheur du Vide sur lui, et canalisez la prison sur lui pendant environ 20 secondes : il vous attaque pour se libérer, et son {spell:45} peut interrompre la canalisation : sacrifiez le marcheur du Vide pour son bouclier s'il le faut. Mieux vaut être en groupe : un second joueur pour encaisser rend la chose facile. Quand la canalisation se termine, il devient {item:18605} : cliquez dessus. Si la canalisation est interrompue, tuez-le ou fuyez, et essayez sur un autre.",
	["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Une épée de tank au niveau 60 : un livre de {area:2577}, puis le souffle de {npc:10184} trempe la lame (l'épée n'est pas encore dans les objets de Forever).",
	["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "Le livre est un butin rare et aléatoire des boss des trois ailes de {area:2577} (Alzzin, Hydrogénos et le reste de l'Est, Tendris, Illyanna, Kalendris, {npc:11496} et l'Ouest, {npc:11501} et les gardes du Nord) et très rarement du coffre du tribut ; il s'échange : l'hôtel des ventes en a peut-être un. {area:2577} est un donjon à cinq dans les ruines du centre de {zone:1444} : il faut un groupe de cinq. Clic droit sur le livre pour lancer la quête ; il reste dans vos sacs.",
	["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} est le boss du raid à 40 joueurs de {area:2159}, une grotte de {area:511} au sud de {zone:1445} ; elle revient une fois par semaine. Prévenez d'abord le raid. Tard dans le combat (vers 10-15 % de vie, une fois qu'elle s'est reposée au sol), utilisez {item:18489} pour la planter sur le passage de son souffle de feu, en général aux pieds du tank principal. Une fois chauffée par son souffle, cliquez sur {object:179562} pour prendre {item:18488} : vous avez alors 20 minutes. Son souffle peut vous tuer pendant que vous plantez ou ramassez la lame ; si vous mourez et que personne ne vous ressuscite avant sa mort, attendez la semaine suivante. Plantée au mauvais endroit ? Abandonnez la quête, reprenez-la auprès de Lydros pour une nouvelle lame.",
	["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "De l'expérience au niveau 50, avec {area:1417} pour finir ; le choix d'objet de Classic a peut-être disparu sur Forever.",
	["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "{npc:7572}, un fantôme, se tient au sud-ouest de {zone:1435}, au col qui mène à {zone:1419}, à peu de distance au sud-ouest de {area:75}. Horde : volez jusqu'à {area:75}. Alliance : volez jusqu'à {area:1438} dans {zone:1419} et montez vers le nord par le col. Des bêtes de haut niveau rôdent en chemin.",
	["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "Sept sangliers infernaux (niveau 52-53, non élites) parcourent le nord-ouest de {zone:1419}, au sud-ouest de {area:1438} ; certains se tiennent près des ogres sur le flanc de la montagne, au bord de la route. Ils chargent à 25 mètres et lancent {spell:8349}. Ils partagent leurs points d'apparition avec les gangrebêtes et les scorpides : s'il n'y a pas de sangliers, tuez ceux-là et des sangliers peuvent apparaître à leur place. Retour en 5 minutes.",
	["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "Les Ombrejures campent autour de l'entrée de la grotte de {area:1440}, au sud de {area:1438} sur la route de {area:72}. Il vous faut 20 adeptes (niveau 52-53, ils drainent le sang et soignent les alliés blessés : tuez-les en premier), 10 cultistes (51-52, ils lancent à distance : rapprochez-vous) et 20 voyous (52-53, Rossée et {spell:1766}). Les voyous peuvent manquer avant les autres : tuez chaque Ombrejure que vous croisez.",
	["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "Il vous faut deux plumes de chaque couleur des six gardiens trolls Atal'ai (niveau 51-52, élites) du balcon de {area:1417}, qui maintiennent la barrière devant {npc:5710} : Taillade et {npc:5716} lâchent l'ambre, Hukku et Mijan la bleue, Zolo et Loro la verte, à chaque fois ; chaque joueur ayant la quête ramasse son propre lot. {area:1417} est un donjon à cinq : il faut un groupe de cinq. Il se trouve dans {area:74}, à l'est de {zone:1435} : montez les marches extérieures du temple, plongez dans la salle inondée et suivez les escaliers jusqu'à l'entrée. À l'intérieur, rejoignez le balcon par les escaliers ou le chemin de droite, pas par l'escalier en spirale. Hukku appelle des gardiens et lance {spell:9081} et {spell:8282} ; Mijan soigne les autres ({spell:139}, une {npc:3560}, {spell:331} sous la moitié de sa vie) : tuez-la vite, ou sa garde ; {npc:5716} frappe en arc.",
	["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} au niveau 30 et une hache, une épée ou un marteau de guerre {spell:1680} au niveau 40.",
	["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5479}, à côté de {npc:5480} dans le bâtiment des maîtres guerriers de {object:2100}, vous envoie voir {npc:6236} sur {area:720} dans {zone:1413}.",
	["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:5113}, le maître guerrier de {zone:1455}, vous envoie voir {npc:6236} sur {area:720} dans {zone:1413}.",
	["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3354}, dans {object:172958}, vous envoie voir {npc:6236} sur {area:720} dans {zone:1413}.",
	["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:3041}, le maître guerrier de {zone:1456}, vous envoie voir {npc:6236} sur {area:720} dans {zone:1413}.",
	["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "Au niveau 30, {npc:4595}, un maître guerrier de {zone:1458}, vous envoie voir {npc:6236} sur {area:720} dans {zone:1413}.",
	["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Volez jusqu'à {area:392} et partez vers le sud le long de {area:391}. {area:720} est au large, au sud-est : traversez à pied par le banc de sable peu profond ; à côté, l'eau est profonde et la fatigue arrive. {npc:6236} se tient près de l'arène.",
	["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "Vous avez 10 minutes. Mangez et buvez à fond, puis montez sur la grille au milieu de la foule : {npc:6248} annonce les adversaires (niveau 26-27), qui arrivent un par un, à 15-20 secondes d'intervalle, et seulement tant que vous restez près de la grille. Après chaque victoire, quittez la grille pour manger ou vous bander ; remontez quand vous êtes prêt pour le suivant. Six adversaires, puis {npc:6238} (niveau 33, non élite) s'avance ; il reste neutre jusqu'à ce que vous l'attaquiez : bandez-vous ou mangez d'abord. N'utilisez pas {spell:1160} : cela fait fuir les adversaires et d'autres arrivent en même temps. Si rien ne commence, descendez de la grille et remontez-y, ou abandonnez la quête et reprenez-la.",
	["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {quest:1714} from his cauldron. Click the cauldron for that quest."] = "{npc:6176} campe près de ruines sur la rive est de la rivière qui passe près de {area:272}, à quelques pas au nord-est de la ville, juste de l'autre côté de la limite de {zone:1416} ; son chaudron est à côté de lui. Horde : volez jusqu'à {area:272}. Alliance : volez jusqu'à {area:271} et remontez la rivière vers le nord ; les gardes de {area:272} sont des élites de niveau 42 : restez loin de la ville. Accepter {quest:1712} vous donne {item:6929}, la liste de ce qu'il lui faut : 8 {item:3357}, 30 défenses de Scalpessang et {quest:1714} de son chaudron. Cliquez sur le chaudron pour cette quête.",
	["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite, and hit hard at 30-33: bring a friend or come at 35 or more. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "Le chaudron veut 8 charmes de chaque sorte, 24 en tout, et chaque exilé lâche son charme environ une fois sur trois : comptez quelque 70 victoires. Tous sont de niveau 38-39, non élites, et frappent fort aux niveaux 30-33 : venez avec un ami ou au niveau 35 ou plus. Les exilés ardents (feu) près de {area:334} au nord-ouest, au nord-ouest de {area:320} ; les exilés tonnants (air) près de {area:336}, au sud-est de {area:320}, qui lancent {spell:403} à 40 mètres ; les exilés des crêtes (eau) près de {area:333}, au nord-ouest de {area:321}, avec {spell:122}. Une douzaine de chaque, de retour en moins de 7 minutes. Les charmes s'échangent et se vendent à l'hôtel des ventes ; en utiliser un bannit pour un moment une autre sorte d'exilé (ardent sur tonnant, tonnant sur crête, crête sur ardent).",
	["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "Il vous faut 8 {item:3357}. Les herboristes en cueillent au bord des rivières et des lacs de {zone:1437}, {zone:1417} et {zone:1434} ; sinon, l'hôtel des ventes. Les vendeurs d'herbes n'en ont qu'un à la fois et se réapprovisionnent toutes les deux heures : {npc:1302} et {npc:1313} à {zone:1453}, {npc:844} sur la route à l'est d'Elwynn, Jeeda à {area:460} dans les Serres-Rocheuses, Montarr à {zone:1441}. Les sorciers-docteurs Kurzen du nord de Strangleronce en lâchent un environ une fois sur douze.",
	["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "Il vous faut 30 défenses. Chaque troll Scalpessang (niveau 33-37) du nord-ouest de Strangleronce en lâche une environ une fois sur trois : comptez quelque 80 victoires. Les camps et ruines au nord et au nord-ouest de {area:117} et autour de {area:123} sur la côte. Ils s'enragent sous 30 % de vie et les guerriers désarment ; retour en 5 minutes.",
	["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "Retour auprès de {npc:6176}. Accepter {quest:1713} lance son rituel, et {quest:1712} apparaît juste au nord de son camp. {quest:1712} est élite (niveau 40) : mieux vaut être en groupe ; il faut un groupe de deux ou trois vers le niveau 40. Il inflige des dégâts de nature (un {item:6052} les absorbe), tourbillonne, et {spell:10101} vous projette au loin pendant qu'il se soigne le temps que vous reveniez : combattez dos à une pente ou à un rocher. {item:6894} tombe à chaque fois. Si le combat échoue, {npc:6176} ne répond plus : abandonnez {quest:1713} et reprenez-la pour une nouvelle invocation ; les objets précédents ne sont plus nécessaires.",
	["{quest:7562} and his goblin {npc:14437} camp on the hill across the road from the {area:255}, in the far north-west of the {zone:1428}, west of {area:254}. The chain is long: about 420 gold in {npc:14437}'s and {npc:14522}'s goods, a pile of crafted materials, the {area:2057} and {area:2577}. Start buying or gathering the materials of the next steps now."] = "{quest:7562} et son gobelin {npc:14437} campent sur la colline de l'autre côté de la route de {area:255}, à l'extrême nord-ouest de {zone:1428}, à l'ouest de {area:254}. La suite est longue : environ 420 po de marchandises chez {npc:14437} et {npc:14522}, une pile de matériaux fabriqués, {area:2057} et {area:2577}. Commencez dès maintenant à acheter ou récolter les matériaux des étapes suivantes.",
	["Every owlbeast of {zone:1452} (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. {area:2250}, in the north-east, and the {area:2242}'s surroundings are packed with them, and they respawn in five and a half minutes."] = "Chaque chouettard de {zone:1452} (niveau 53-58, aucun élite) lâche le sang environ une fois sur trois : environ quatre-vingt-dix victoires pour trente. {area:2250}, au nord-est, et les environs de {area:2242} en sont remplis, et ils réapparaissent en cinq minutes et demie.",
	["Back to {npc:14436}: he gives you the {item:18591} for {npc:14437} beside him. Then {npc:14436} asks for the bell, the wheel and the candle, and {npc:14437} sends you to {quest:7623} in {area:1763}: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after {npc:14523}, and a spare in case one runs out) and bring 150 gold for the stardust."] = "Retour auprès de {npc:14436} : il vous donne {item:18591} pour {npc:14437}, à côté de lui. Puis {npc:14436} demande la cloche, la roue et la bougie, et {npc:14437} vous envoie voir {quest:7623} à {area:1763} : achetez-lui trois potions d'ombre pour ce voyage (6 po chacune : une pour entrer, une après {npc:14523}, et une de réserve au cas où l'effet s'arrête) et apportez 150 po pour la poussière d'étoile.",
	["{npc:14437} wants 10 Elixirs of Shadow Power ({skill:171}: 3 Ghost Mushrooms and a {item:8925} each), 6 Large Brilliant Shards ({skill:333}: disenchant level 51+ blue items), 25 {item:11370} ({skill:186} 230: the Dark Iron Deposits of the {zone:1428} and {area:1584}) and 35 Black Dragonscales ({skill:393}: the black dragonkin of the {zone:1428}, a few percent a kill, best from the {npc:7043}). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales."] = "{npc:14437} veut 10 élixirs de puissance de l'ombre ({skill:171} : 3 champignons fantômes et une {item:8925} chacun), 6 grands éclats brillants ({skill:333} : désenchantez des objets bleus de niveau 51 et plus), 25 {item:11370} ({skill:186} 230 : les gisements de sombrefer de {zone:1428} et de {area:1584}) et 35 écailles de dragon noir ({skill:393} : les draconiens noirs de {zone:1428}, quelques pour cent par victoire, surtout {npc:7043}). Fabriquez ou récoltez ce que vos métiers permettent et achetez le reste à l'hôtel des ventes ; trouver 35 écailles peut prendre du temps.",
	["{area:1763} lies just south of {area:1997} in western {zone:1448}, west of the road; of its two caves, {area:1770} is the northern one, further up the hill. Drink a {item:18802} at its mouth: for 20 minutes the Shadow Council there treat you as one of their own ({spell:23179}). The oozes in the red pool and the succubus Rakaiah beyond them still attack: hug the wall past them. Go down past the second, red pool, up the ramp and across two bridges to {quest:7623}, a great winged dreadlord at the back. He talks to you only while the potion lasts."] = "{area:1763} se trouve juste au sud de {area:1997}, à l'ouest de {zone:1448}, à l'ouest de la route ; de ses deux grottes, {area:1770} est celle du nord, plus haut sur la colline. Buvez une {item:18802} à son entrée : pendant 20 minutes, le Conseil des ombres vous traite comme l'un des siens ({spell:23179}). Les vases du bassin rouge et la succube Rakaiah au-delà attaquent quand même : longez le mur pour les dépasser. Descendez après le second bassin, le rouge, montez la rampe et passez deux ponts jusqu'à {quest:7623}, un grand seigneur de l'effroi ailé au fond. Il ne vous parle que tant que la potion agit.",
	["{npc:14523} waits in a small side room up a bridge you passed on the way down. Speak to him and he and four guards attack (all level 57, none elite): let your voidwalker hold the guards and burn {npc:14523}, sacrificing it if you must. Or click off your {spell:23179} aura to start the fight, kill {npc:14523}, then drink another potion: the guards stop at once. Take his heart back to {npc:9516} with a potion active."] = "{npc:14523} attend dans une petite salle latérale, en haut d'un pont que vous avez passé en descendant. Parlez-lui et lui et quatre gardes attaquent (tous de niveau 57, aucun élite) : laissez votre marcheur du Vide retenir les gardes et concentrez-vous sur {npc:14523}, en sacrifiant le marcheur s'il le faut. Ou retirez votre aura {spell:23179} pour lancer le combat, tuez {npc:14523}, puis buvez une autre potion : les gardes s'arrêtent aussitôt. Rapportez son cœur à {npc:9516} avec une potion active.",
	["Back to {npc:14437} with the stardust; with the {quest:7630} also done he gives you the {item:18688} for the {area:2057}. Put a group of five together now: a party, not a raid group."] = "Retour auprès de {npc:14437} avec la poussière d'étoile ; avec {quest:7630} faite aussi, il vous donne {item:18688} pour {area:2057}. Formez maintenant un groupe de cinq : un groupe, pas un raid.",
	["The {area:2057} (level 58-60, a group of five) lies under {area:2298}, the island town in the south-east of the {zone:1422}: someone needs the {item:13704} or a rogue to open the door. Fight down to {npc:10508}'s room and use the {item:18688} at the alchemy lab tables to the right: {npc:14500} makes the parchment. You need not kill Ras, but it only counts at this lab and only in a party."] = "{area:2057} (niveau 58-60, un groupe de cinq) se trouve sous {area:2298}, la ville insulaire au sud-est de {zone:1422} : il faut {item:13704} ou un voleur pour ouvrir la porte. Frayez-vous un chemin jusqu'à la salle de {npc:10508} et utilisez {item:18688} aux tables du laboratoire d'alchimie, à droite : {npc:14500} fabrique le parchemin. Inutile de tuer Ras, mais cela ne compte qu'à ce laboratoire et qu'en groupe.",
	["{area:2577} stands in the ruins of central {zone:1444}: from the gate at the foot of the ruins, walk up through the outer courtyards to the west wing's door at the north end. That door and an inner door need the {item:18249} (it drops from Pusillin in Dire Maul East) or a rogue with 300 Lockpicking. Bring a party of five. Lower {npc:11496}'s shield by killing the guardians of the five pylons (two stand in his own room), then kill {npc:11496}: his dais is the summoning circle. Rest and rebuff before you start."] = "{area:2577} se dresse dans les ruines du centre de {zone:1444} : depuis la porte au pied des ruines, montez par les cours extérieures jusqu'à la porte de l'aile ouest, au bout nord. Cette porte et une porte intérieure demandent {item:18249} (elle tombe sur Pusillin à Haches-Tripes Est) ou un voleur avec 300 en crochetage. Venez avec un groupe de cinq. Faites tomber le bouclier de {npc:11496} en tuant les gardiens des cinq pylônes (deux se tiennent dans sa propre salle), puis tuez {npc:11496} : son estrade est le cercle d'invocation. Reposez-vous et relancez vos améliorations avant de commencer.",
	["At 40 {npc:461}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Au niveau 40, {npc:461}, dans la cave de {object:2164} de {object:2101}, vous envoie voir {npc:6251} à {area:392}. Aucune quête proposée ? Terminez d'abord la suite du chasseur corrompu : d'après les joueurs, la monture vient après.",
	["At 40 {npc:5172}, by the warlock trainers in {zone:1455}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Au niveau 40, {npc:5172}, près des maîtres démonistes de {zone:1455}, vous envoie voir {npc:6251} à {area:392}. Aucune quête proposée ? Terminez d'abord la suite du chasseur corrompu : d'après les joueurs, la monture vient après.",
	["At 40 {npc:3326}, in the {object:172960}, sends you to {npc:6251} in {area:392}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Au niveau 40, {npc:3326}, dans {object:172960}, vous envoie voir {npc:6251} à {area:392}. Aucune quête proposée ? Terminez d'abord la suite du chasseur corrompu : d'après les joueurs, la monture vient après.",
	["At 40 {npc:4563}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}; {area:392} is a short flight from {zone:1454}. No quest offered? Finish the felhunter chain first: players report the mount comes after it."] = "Au niveau 40, {npc:4563}, dans {object:36082}, vous envoie voir {npc:6251} à {area:392}. Le zeppelin de {zone:1420} va à {zone:1411} ; {area:392} est à un court vol de {zone:1454}. Aucune quête proposée ? Terminez d'abord la suite du chasseur corrompu : d'après les joueurs, la monture vient après.",
	["{area:392} is the goblin port on the {zone:1413} coast, east of the Crossroads; from the Alliance side take the boat from {area:35}. {npc:6251} stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own {quest:3631} and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing."] = "{area:392} est le port gobelin sur la côte de {zone:1413}, à l'est de la Croisée ; côté Alliance, prenez le bateau depuis {area:35}. {npc:6251} se tient près de sa petite tour sur la colline au-dessus de la ville, pas en bas sur les quais. Rendez la quête, puis prenez sa propre {quest:3631} et rendez-la aussitôt : elle vous apprend la monture. Pas de combat, et les quêtes ne demandent rien.",
	["{area:2279} is a group of five, level 58-60. The {object:175461} at {object:175440}, in north-western {zone:1423}, leads to the undead side; {npc:10440} waits in the Slaughter House at its end. Our data gives the reins a 0.02% drop chance (pfQuest, Era): one in about five thousand kills. Nothing shows Forever changing it."] = "{area:2279} est un donjon à cinq, niveau 58-60. {object:175461} à {object:175440}, au nord-ouest de {zone:1423}, mène au côté mort-vivant ; {npc:10440} attend dans l'abattoir, tout au bout. Nos données donnent aux rênes 0,02 % de chances (pfQuest, Era) : une fois sur cinq mille victoires environ. Rien n'indique que Forever l'ait changé.",
	["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521} est l'île de départ des Célestes ; tout le monde peut s'y rendre. Un dirigeable part du nord de {area:279} toutes les cinq minutes environ (un autre décolle au nord de {zone:1456} ; chaque faction peut prendre l'un ou l'autre). Passez cette étape si vous êtes déjà sur l'île.",
	["{zone:2521} is the Skyborne starting island; anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either). Skip this if you are already on the island."] = "{zone:2521} est l'île de départ des Célestes ; tout le monde peut s'y rendre. Un dirigeable part des falaises au sud de {area:17045}, au nord de {zone:1456}, toutes les cinq minutes environ (un autre décolle de {area:279} ; chaque faction peut prendre l'un ou l'autre). Passez cette étape si vous êtes déjà sur l'île.",
	["Skyborne learn {skill:762} from {npc:265756} himself for 100g, and it comes with a Galestrider. He stands at the {area:17684} in {area:16638}, near the skyboat docks."] = "Les Célestes apprennent {skill:762} auprès de {npc:265756} lui-même pour 100 po, avec un trotte-vent offert. Il se tient à {area:17684} à {area:16638}, près des quais des dirigeables.",
	["Any race can buy Galestriders, but riding one also takes {spell:1285849}, which only the Skyborne get with {skill:762}. Other races can learn it too, but how is not known yet: in Classic another race's riding needed Exalted with its home faction, here the High Order (Alliance) or the Windshapers (Horde). Ask {npc:265756} before you buy."] = "Toutes les races peuvent acheter des trotte-vent, mais en monter un demande aussi {spell:1285849}, que seuls les Célestes obtiennent avec {skill:762}. Les autres races peuvent l'apprendre aussi, mais on ne sait pas encore comment : dans Classic, la monte d'une autre race demandait d'être Exalté auprès de sa faction d'origine, ici le Haut Ordre (Alliance) ou les Façonne-vent (Horde). Demandez à {npc:265756} avant d'acheter.",
	["{npc:265756} is at the {area:17684} in {area:16638}, the island's harbour town, near the skyboat docks. The Forever client lists each Galestrider at 20g; choose one."] = "{npc:265756} est à {area:17684} à {area:16638}, la ville portuaire de l'île, près des quais des dirigeables. Le client Forever affiche chaque trotte-vent à 20 po ; choisissez-en un.",
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, professions, PvP, exploring) is worth one, and every point the account earns counts here, spent or not. The Legacy Challenges guide plans them. The Progress Track gives the {item:281060} at 15, the {npc:268840} at 25, the {item:277717} at 40 and the reins at 55. Claim each one from {npc:6791} at the inn in {area:392}, on the {zone:1413} coast: he offers a \"Legacy Reward\" quest once you have the points."] = "Les points d'héritage sont communs au compte : chaque défi d'héritage (une classe aux niveaux 25, 45 et 60, les métiers, le JcJ, l'exploration) en vaut un, et chaque point gagné par le compte compte ici, dépensé ou non. Le guide des défis d'héritage les planifie. La piste de progression donne {item:281060} à 15, {npc:268840} à 25, {item:277717} à 40 et les rênes à 55. Réclamez chaque récompense auprès de {npc:6791}, à l'auberge de {area:392}, sur la côte de {zone:1413} : il propose une quête « Récompense d'héritage » une fois les points atteints.",
	["Skyborne train Journeyman {skill:762} with {npc:265756} himself for 1,000g; Blizzard says it comes with a mount. He stands at the {area:17684} in {area:16638}, near the skyboat docks."] = "Les Célestes apprennent {skill:762} Compagnon auprès de {npc:265756} lui-même pour 1 000 po ; selon Blizzard, une monture est offerte. Il se tient à {area:17684} à {area:16638}, près des quais des dirigeables.",
	["{npc:265756} is at the {area:17684} in {area:16638}, the island's harbour town, near the skyboat docks. The Forever client lists each Swift Galestrider at 200g; choose one."] = "{npc:265756} est à {area:17684} à {area:16638}, la ville portuaire de l'île, près des quais des dirigeables. Le client Forever affiche chaque trotte-vent rapide à 200 po ; choisissez-en un.",
	["The {item:276275} costs one {item:274026}, the prize for winning the Stranglethorn Fishing Extravaganza. The contest runs on Sundays from 2 to 4 pm server time: be on the {area:35} docks when it starts and take {quest:8193} from {npc:15077}. Bring your best {skill:356} skill and lures so no fish gets away, a mount and empty bags, and bind your hearthstone in {area:35}."] = "{item:276275} coûte une {item:274026}, le prix du vainqueur du Concours de pêche de Strangleronce. Le concours a lieu le dimanche de 14 h à 16 h, heure du serveur : soyez sur les quais de {area:35} au début et prenez {quest:8193} auprès de {npc:15077}. Apportez votre meilleur niveau en {skill:356} et des appâts pour ne laisser filer aucun poisson, une monture et des sacs vides, et liez votre pierre de foyer à {area:35}.",
	["While the contest runs, schools of {item:19807} appear along the Stranglethorn coast, none inside {area:35}. Fish 40 {item:19807} from them; each school lasts only a few casts, so ride on to the next as soon as one is gone. The arrow takes you up the west coast north of {area:35}; more schools lie further north and just south of {area:35}."] = "Pendant le concours, des bancs de {item:19807} apparaissent le long de la côte de Strangleronce, aucun à l'intérieur de {area:35}. Pêchez-y 40 {item:19807} ; chaque banc ne dure que quelques lancers, alors filez au suivant dès qu'il disparaît. La flèche vous fait remonter la côte ouest au nord de {area:35} ; d'autres bancs se trouvent plus au nord et juste au sud de {area:35}.",
	["{npc:15078}, {npc:15077}'s apprentice, stands beside him on the {area:35} docks and trades the {item:276275} for the coin."] = "{npc:15078}, l'apprenti de {npc:15077}, se tient à côté de lui sur les quais de {area:35} et échange {item:276275} contre la pièce.",
	["The Searing Whelps of the {area:511} in southern {zone:1445} (level 42-43) and the Scalding Whelps of eastern {zone:1418} (level 41-43) drop it about once in 900 kills. The waypoint is the {area:511}, where the whelps stand thickest; the {zone:1418} whelps are the same grind. The whelpling can be traded, so the Auction House may be quicker."] = "Les jeunes dragons brûlants de {area:511}, au sud de {zone:1445} (niveau 42-43), et les jeunes dragons ébouillantés de l'est de {zone:1418} (niveau 41-43) le lâchent environ une fois sur 900. Le point de passage est {area:511}, où les jeunes dragons sont les plus nombreux ; ceux de {zone:1418} demandent le même effort. Le dragonnet s'échange : l'hôtel des ventes peut être plus rapide.",
	["{npc:14860} sells two frogs (1g each) while the Darkmoon Faire is in town; Forever has not shown the Faire yet. In Classic it sets up south of {area:87} in {zone:1429} one month and near {zone:1456} in {zone:1412} the next; go to whichever is up. {npc:14860} runs all over the Faire grounds, so look around for him. He carries only one {item:11027} at a time and restocks it about every 30 minutes: if he has none, someone just bought it. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:14860} vend deux grenouilles (1 po chacune) pendant la foire de Sombrelune ; Forever ne l'a pas encore montrée. Dans Classic, elle s'installe un mois au sud de {area:87} dans {zone:1429}, le mois suivant près de {zone:1456} dans {zone:1412} ; allez à celle qui est ouverte. {npc:14860} court partout sur le terrain de la foire : cherchez-le bien. Il n'a qu'un seul {item:11027} à la fois et en reprend un toutes les 30 minutes environ : s'il n'en a plus, quelqu'un vient de l'acheter. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; les objectifs restent cochés ensuite.",
	["{area:1581}: Defias Pirates"] = "{area:1581} : pirates défias",
	["{area:1581} is a group of five at level 17-26, under {area:20}: go in at the {area:20} mine and follow the tunnel down to the instance portal. The Defias Pirates (elite, level 19-20) on and around the ship at the far end drop the macaw about once in 30 kills, so plan on several runs; a character well past the dungeon's level clears it alone. The cage can be traded: look at the Auction House too."] = "{area:1581} est un donjon à cinq de niveau 17-26, sous {area:20} : entrez par la mine de {area:20} et suivez le tunnel jusqu'au portail de l'instance. Les pirates défias (élites, niveau 19-20), sur le navire au fond et autour, lâchent l'ara environ une fois sur 30 : prévoyez plusieurs passages ; un personnage d'un niveau bien supérieur au donjon le fait seul. La cage s'échange : regardez aussi à l'hôtel des ventes.",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}, dans la mine de {area:20}",
	["{area:1581} portal, at the bottom of the mine"] = "Portail de {area:1581}, au fond de la mine",
	["Every Bloodsail pirate on the Stranglethorn coast (level 39-45) can drop it, but only about once in 5,000 kills; the Swabbies on the ships off the southern tip, about once in 2,500. That is a grind of many hours, so most players kill pirates while doing something else there, or buy the cage on the Auction House. The waypoint is the Swashbucklers' and Warlocks' camp on the {area:43}, south of {area:35}. Every pirate kill also lowers your Bloodsail Buccaneers standing."] = "Tous les pirates de la Voile sanglante de la côte de Strangleronce (niveau 39-45) peuvent le lâcher, mais seulement une fois sur 5 000 environ ; les mousses des navires au large de la pointe sud, une fois sur 2 500 environ. Cela représente de nombreuses heures : la plupart des joueurs tuent des pirates en faisant autre chose sur place, ou achètent la cage à l'hôtel des ventes. Le point de passage est le camp des bretteurs et des démonistes sur {area:43}, au sud de {area:35}. Chaque pirate tué fait aussi baisser votre réputation auprès des Flibustiers de la Voile sanglante.",
	["Bloodsail camp, the {area:43}"] = "Camp de la Voile sanglante, {area:43}",
	["Horde players buy the {npc:7386} (60s) from {npc:262471}, a trader new in Forever, at {area:2539}, the Darkspear camp at the southern tip of {zone:1442}, on the way up from the {zone:1413}. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "Les joueurs de la Horde achètent {npc:7386} (60 pa) auprès de {npc:262471}, un marchand ajouté par Forever, à {area:2539}, le camp des Sombrelances à la pointe sud de {zone:1442}, en montant depuis {zone:1413}. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; l'objectif reste coché ensuite.",
	["{npc:6548} at the {area:2240}, the goblin and gnome racetrack in the {area:439} of south-eastern {zone:1441}, sells the {item:11023} (1g) to both sides. The nearest flight paths are {area:484} (Horde) and {area:976} in {zone:1446} (both sides); from {area:976}, ride north into the {area:439}. Each pet item teaches its companion when you use it; the goal stays ticked afterwards."] = "{npc:6548}, à {area:2240}, le circuit de course des gobelins et des gnomes dans {area:439}, au sud-est de {zone:1441}, vend {item:11023} (1 po) aux deux camps. Les trajets de vol les plus proches sont {area:484} (Horde) et {area:976} dans {zone:1446} (les deux camps) ; depuis {area:976}, montez vers le nord jusqu'à {area:439}. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; l'objectif reste coché ensuite.",
	["Each robot starts with a distress beacon that mobs in its zone drop, about one kill in 40 to 100 in Classic's data. In {zone:1444} the best are the Coast Crawl Snapclaws and Deepseers (levels 43-45) on the {area:1108} and the Sprite Dragons (47-48), about 2.5%; ogres, harpies, naga and Grimtotems drop it about 1%. You can loot it from level 40."] = "Chaque robot commence par une balise de détresse que lâchent les monstres de sa zone, environ une fois sur 40 à 100 d'après les données de Classic. À {zone:1444}, les meilleurs sont les pinces-tranchantes et les voyants des profondeurs de la Côte rampante (niveau 43-45) sur {area:1108} et les dragons féériques (47-48), environ 2,5 % ; les ogres, harpies, nagas et Totems-Sinistres la lâchent environ 1 % du temps. Vous pouvez la ramasser dès le niveau 40.",
	["Right-click the beacon. OOX-22/FE sits in a cave near {area:1105}, among yetis and apes. Its escort runs west along the road to the dock on the {area:1108} with three ambushes: three yetis, then three gorillas, then four or five gnolls with a caster. Bring a friend if you are under 47. The robot keeps walking unless it is hit, so stay close; if it will not move, another player has it: wait for it to come back. Its turn-in is in {area:35}; keep the quest for later."] = "Clic droit sur la balise. OOX-22/FE se trouve dans une grotte près de {area:1105}, parmi les yétis et les singes. Son escorte part vers l'ouest par la route jusqu'au quai de {area:1108}, avec trois embuscades : trois yétis, puis trois gorilles, puis quatre ou cinq gnolls avec un lanceur de sorts. Venez avec un ami si vous êtes en dessous du niveau 47. Le robot continue d'avancer tant qu'on ne le frappe pas : restez près de lui ; s'il ne bouge pas, un autre joueur l'escorte : attendez qu'il revienne. Sa quête se rend à {area:35} ; gardez-la pour plus tard.",
	["OOX-17/TN stands in the hills near the {area:981} in south-east {zone:1446}. Its escort to {area:977} has two ambushes: three scorpids near the start, three Wastewander bandits near the end. The robot has about 3,000 health and stops to fight what you attack, so it can tank for a moment while you recover. Its turn-in is in {area:35} too."] = "OOX-17/TN se trouve dans les collines près de {area:981}, au sud-est de {zone:1446}. Son escorte jusqu'à {area:977} compte deux embuscades : trois scorpides près du départ, trois bandits Bat-le-désert près de l'arrivée. Le robot a environ 3 000 points de vie et s'arrête pour combattre ce que vous attaquez : il peut encaisser un moment pendant que vous récupérez. Sa quête se rend aussi à {area:35}.",
	["OOX-09/HL waits on the largest island of the lake west of {area:351}. Its escort to the shore beyond Overlook Cliff has two ambushes of three: Marauding Owlbeasts, then Vilebranch Ambushers; the robot warns you just before each."] = "OOX-09/HL attend sur la plus grande île du lac à l'ouest de {area:351}. Son escorte jusqu'au rivage au-delà de la falaise du Belvédère compte deux embuscades de trois : des chouettards maraudeurs, puis des embusqués Vilebranch ; le robot vous prévient juste avant chacune.",
	["{npc:7406} is in {area:35}, upstairs in the building north of the inn, above {npc:2490}. Hand in all three rescues; at level 45 he then offers {quest:3721}, which you turn straight back in for the {item:10398}."] = "{npc:7406} est à {area:35}, à l'étage du bâtiment au nord de l'auberge, au-dessus de {npc:2490}. Rendez les trois sauvetages ; au niveau 45, il propose alors {quest:3721}, que vous lui rendez aussitôt pour {item:10398}.",
	["The Alliance camp is at {area:1002} in western {zone:1433}. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to {npc:214101}, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with the Azeroth Commerce Authority. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there."] = "Le camp de l'Alliance est à {area:1002}, dans l'ouest de {zone:1433}. Les faveurs de marchand viennent des caisses égarées que lâchent les monstres dès le niveau 10 : remplissez-en une avec un lot qu'elle indique et remettez-la à {npc:214101}, pour 5 à 30 faveurs par caisse. La friandise coûte 1 500 faveurs et, d'après les listes du vendeur en bêta, demande Révéré auprès de l'Autorité commerciale d'Azeroth. Les caisses ne rapportent pas de réputation : elle vient des commandes d'artisan, 21 000 de Neutre à Révéré. Le guide de réputation des factions de ravitaillement vous y mène.",
	["The Horde camp is just outside the west gate of the Crossroads. Merchant's Favor comes from Waylaid Crates that mobs drop from level 10: fill one with a bundle it lists and hand it to Dokimi, for 5 to 30 Favor a crate. The treat costs 1,500 Favor and, by beta vendor lists, needs Revered with Durotar Supply and Logistics. Crates pay no standing: that comes from the Craftsman's Writs, 21,000 from Neutral to Revered. The Supply Factions Reputation guide takes you there. (Another {npc:256384} stands in the {zone:1458}; this is the one at the camp.)"] = "Le camp de la Horde est juste devant la porte ouest de la Croisée. Les faveurs de marchand viennent des caisses égarées que lâchent les monstres dès le niveau 10 : remplissez-en une avec un lot qu'elle indique et remettez-la à Dokimi, pour 5 à 30 faveurs par caisse. La friandise coûte 1 500 faveurs et, d'après les listes du vendeur en bêta, demande Révéré auprès de Ravitaillement et logistique de Durotar. Les caisses ne rapportent pas de réputation : elle vient des commandes d'artisan, 21 000 de Neutre à Révéré. Le guide de réputation des factions de ravitaillement vous y mène. (Un autre {npc:256384} se tient à {zone:1458} ; il s'agit ici de celui du camp.)",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the north side of {area:279} about every five minutes (another flies from north of {zone:1456}; either faction may take either)."] = "{zone:2521} est l'île de départ des Célestes ; d'après les retours de la bêta, tout le monde peut s'y rendre. Un dirigeable part du nord de {area:279} toutes les cinq minutes environ (un autre décolle au nord de {zone:1456} ; chaque faction peut prendre l'un ou l'autre).",
	["{zone:2521} is the Skyborne starting island; by beta reports anyone may visit. A skyboat leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes (another flies from {area:279}; either faction may take either)."] = "{zone:2521} est l'île de départ des Célestes ; d'après les retours de la bêta, tout le monde peut s'y rendre. Un dirigeable part des falaises au sud de {area:17045}, au nord de {zone:1456}, toutes les cinq minutes environ (un autre décolle de {area:279} ; chaque faction peut prendre l'un ou l'autre).",
	["From {area:16635} follow the road south, then cut across the field to the top of the waterfall: five frogs sit together on a rock there, by a log. Mobs patrol nearby, so a level 1 character should watch its back. Stand by the rock, target a frog and type /sing. The frogs sing back, the group disappears and one frog hops onto the log beside you: click it to take the {item:268109}, then use it to learn the pet. The item is not bound until you use it, so a friend on the island can sing again and trade you one."] = "Depuis {area:16635}, suivez la route vers le sud, puis coupez à travers champ jusqu'en haut de la cascade : cinq grenouilles sont assises ensemble sur un rocher, près d'un tronc. Des monstres patrouillent à côté : un personnage de niveau 1 doit surveiller ses arrières. Placez-vous près du rocher, ciblez une grenouille et tapez /chanter. Les grenouilles vous répondent en chantant, le groupe disparaît et une grenouille saute sur le tronc à côté de vous : cliquez dessus pour prendre {item:268109}, puis utilisez-le pour apprendre la mascotte. L'objet n'est lié qu'une fois utilisé : un ami sur l'île peut chanter à son tour et vous en échanger un.",
	["{npc:2663}, the pirate supplier in {area:35}, sells two parrots (40s each), with no stock limit. He stands next to {npc:2664}, the cook. {area:35} is neutral: the boat from {area:392} and the Stranglethorn road both arrive there. Each pet item teaches its companion when you use it; the goals stay ticked afterwards."] = "{npc:2663}, le fournisseur des pirates à {area:35}, vend deux perroquets (40 pa chacun), sans limite de stock. Il se tient à côté de {npc:2664}, le cuisinier. {area:35} est neutre : le bateau de {area:392} et la route de Strangleronce y arrivent tous les deux. Chaque objet de mascotte vous apprend son compagnon quand vous l'utilisez ; les objectifs restent cochés ensuite.",
	["{npc:254151}, the druids' quartermaster, waits inside their den in the {area:16631}, the cave just north-east of {npc:257944}'s camp. He sells the squirrel (50s) once you are Revered with the {faction:2758}. Get there young: the Shadowgale storyline and {npc:254151}'s first ear quest take you to Friendly, and his repeatable pays 1000 for five Al'Aketh Cultist's Ears up to level 18 but, by Classic's rules, only 200 from level 22. From Friendly to Revered that is about 80 ears at level 18 and about 400 at 22 or above. The Nightclaw Druids Reputation guide walks you through it."] = "{npc:254151}, l'intendant des druides, attend dans leur repaire de {area:16631}, la grotte juste au nord-est du camp de {npc:257944}. Il vend l'écureuil (50 pa) une fois Révéré auprès de {faction:2758}. Allez-y jeune : l'histoire de Sombre-rafale et la première quête d'oreilles de {npc:254151} vous mènent à Amical, et sa quête répétable rapporte 1000 pour cinq oreilles de cultiste d'Al'Aketh jusqu'au niveau 18, mais, selon les règles de Classic, seulement 200 à partir du niveau 22. D'Amical à Révéré, cela fait environ 80 oreilles au niveau 18 et environ 400 au niveau 22 ou plus. Le guide de réputation des Druides de la Griffe nocturne vous accompagne.",
	["{area:1581}: Cookie"] = "{area:1581} : Cookie",
	["{area:1581} is a group of five under {area:20}: the mine mouth is in {area:20}, the instance portal deep inside the mine. Cookie, the murloc cook, waits on a small island under the pirate ship at the far end, an optional boss; his cooking heals him, so interrupt it. He drops the Siamese about 15% of the time in Classic's data: expect several runs. The carrier can be traded, so check the Auction House too."] = "{area:1581} est un donjon à cinq sous {area:20} : l'entrée de la mine est à {area:20}, le portail de l'instance tout au fond de la mine. Cookie, le cuisinier murloc, attend sur un îlot sous le navire pirate au fond, un boss facultatif ; sa cuisine le soigne, alors interrompez-la. Il lâche le siamois environ 15 % du temps d'après les données de Classic : prévoyez plusieurs passages. Le panier s'échange : regardez aussi à l'hôtel des ventes.",
	["{area:1581} portal, inside the {area:20} mine"] = "Portail de {area:1581}, dans la mine de {area:20}",
	["{npc:10260} at {area:251}"] = "{npc:10260} à {area:251}",
	["{npc:10260} stands inside the cave at {area:251}, the camp in northern {zone:1428} east of {area:254}. He also gives {npc:10260}'s Exotic Pets (the {item:12264}): take both, they are done in the same run."] = "{npc:10260} se tient dans la grotte de {area:251}, le camp au nord de {zone:1428}, à l'est de {area:254}. Il donne aussi Les animaux exotiques de {npc:10260} ({item:12264}) : prenez les deux, elles se font dans le même passage.",
	["Lower {area:1583}"] = "Partie inférieure de {area:1583}",
	["Lower {area:1583} is a group of five, level 55-60, inside {area:254}. The Spire Spider Eggs lie around {npc:10596}'s nest in the Skitterweb Tunnels, the spider halls: click them until you have 15 (each gives one to three). Hard-hitting spiderlings can hatch as you loot. By player reports the eggs cannot be looted in a raid group, so keep the party at five or fewer."] = "La partie inférieure de {area:1583} est un donjon à cinq, niveau 55-60, dans {area:254}. Les œufs d'araignée du pic gisent autour du nid de {npc:10596} dans les tunnels de Grouilletoile, les salles des araignées : cliquez dessus jusqu'à en avoir 15 (chacun en donne un à trois). Des bébés araignées qui frappent fort peuvent éclore pendant la fouille. D'après les joueurs, les œufs ne se ramassent pas en groupe de raid : restez à cinq au maximum.",
	["Legacy Points are account-wide: each Legacy Challenge (a class reaching 25, 45 and 60, a crafting profession at 150, 225 and 300, PvP ranks and battleground reputations, exploring, dungeons and raids) is worth one, and the track counts points earned, not spent. It gives the {item:281060} at 15, the {item:277714} at 25, the {item:277717} at 40 and the {item:277718} at 55. The rewards are claimed as quests from {npc:6791} in the inn at {area:392}, the goblin port on the {zone:1413} coast (Alliance players come by the boat from {area:35}): with 25 points he offers {quest:96383}; hand it straight back for the cub."] = "Les points d'héritage sont communs au compte : chaque défi d'héritage (une classe aux niveaux 25, 45 et 60, un métier d'artisanat à 150, 225 et 300, les rangs JcJ et les réputations de champ de bataille, l'exploration, les donjons et les raids) en vaut un, et la piste compte les points gagnés, pas dépensés. Elle donne {item:281060} à 15, {item:277714} à 25, {item:277717} à 40 et {item:277718} à 55. Les récompenses se réclament par des quêtes auprès de {npc:6791}, à l'auberge de {area:392}, le port gobelin sur la côte de {zone:1413} (les joueurs de l'Alliance viennent par le bateau de {area:35}) : à 25 points, il propose {quest:96383} ; rendez-la aussitôt pour le petit.",
	["The {npc:2172} is a rare level 20 tallstrider in southern {zone:1439}, near the {area:449}. Kill counts so far give her about 0.6% per kill, roughly one in 170, and in Classic she comes back only every few hours: check her spot whenever you pass, rather than camping. The hatchling binds when you loot it, so it never reaches the Auction House."] = "{npc:2172} est un haut-trotteur rare de niveau 20 au sud de {zone:1439}, près de {area:449}. Les décomptes connus lui donnent environ 0,6 % par victoire, soit une fois sur 170, et dans Classic elle ne réapparaît que toutes les quelques heures : passez voir son emplacement à chaque passage plutôt que de camper. Le bébé se lie quand vous le ramassez : il n'arrive jamais à l'hôtel des ventes.",
	["The red whelps live in the hills of the eastern {zone:1437}, towards {area:1037}: about 50 of them, back about five minutes after a kill in Classic's data. Red Whelps (levels 23-24) and Crimson Whelps (25-26) drop the whelpling about once in 650 kills, the Flamesnorting Whelps (26-27) mixed in with them only once in 1,600, so expect a long farm. It can be traded, so the Auction House may be quicker."] = "Les jeunes dragons rouges vivent dans les collines de l'est de {zone:1437}, vers {area:1037} : une cinquantaine, qui reviennent environ cinq minutes après avoir été tués d'après les données de Classic. Les jeunes dragons rouges (niveau 23-24) et cramoisis (25-26) lâchent le dragonnet environ une fois sur 650, les jeunes dragons crache-flammes (26-27) mêlés à eux une fois sur 1 600 seulement : attendez-vous à une longue chasse. Il s'échange : l'hôtel des ventes peut être plus rapide.",
	["The Flesh Pickers feed in the {area:596} in the middle of southern {zone:1443}. Use the kit's tool on one."] = "Les charognards se nourrissent à {area:596}, au milieu du sud de {zone:1443}. Utilisez sur l'un d'eux l'outil du nécessaire.",
	["{npc:10260} stands inside the cave at {area:251}, the camp in northern {zone:1428} east of {area:254}. He gives you an {item:12262}. He also gives En-Ay-Es-Tee-Why (the {item:12529}): take both, they are done in the same run."] = "{npc:10260} se tient dans la grotte de {area:251}, le camp au nord de {zone:1428}, à l'est de {area:254}. Il vous donne {item:12262}. Il donne aussi En-Ay-Es-Tee-Why ({item:12529}) : prenez les deux, elles se font dans le même passage.",
	["Lower {area:1583}: Halycon's pups"] = "Partie inférieure de {area:1583} : les chiots de Halycon",
	["{area:9} opens onto {zone:1429}; {area:87} is south down the road."] = "{area:9} débouche sur {zone:1429} ; {area:87} est au sud, en suivant la route.",
	["Take the {area:2257} from {zone:1453}'s {object:28027} to {zone:1455}, then leave the city through its gates."] = "Prenez {area:2257} depuis {object:28027} de {zone:1453} jusqu'à {zone:1455}, puis sortez de la ville par ses portes.",
	["Leave {zone:1426} east through the South Gate tunnel; it opens into {zone:1432} by the dwarf king statues of the {area:924}."] = "Quittez {zone:1426} vers l'est par le tunnel de la porte Sud ; il débouche dans {zone:1432} près des statues des rois nains de {area:924}.",
	["Flight path here: {area:144} ({npc:1572})."] = "Trajet de vol ici : {area:144} ({npc:1572}).",
	["Fly from {area:144} to {zone:1453} if you have its flight path; otherwise ride back to {zone:1455} and take the {area:2257}. Walk west out of {zone:1429} past the {area:120} into {zone:1436}."] = "Volez de {area:144} à {zone:1453} si vous avez ce trajet ; sinon, revenez à {zone:1455} et prenez {area:2257}. Sortez de {zone:1429} vers l'ouest après {area:120} pour entrer dans {zone:1436}.",
	["Flight path here: {area:108} (Thor)."] = "Trajet de vol ici : {area:108} (Thor).",
