	["Flight path here: {area:69} ({npc:931})."] = "Trajet de vol ici : {area:69} ({npc:931}).",
	["From {area:1002} take the road south into {zone:1431}; {area:42} is east along its main road. Most of Duskwood is level 24-30: come with Redridge behind you."] = "Depuis {area:1002}, prenez la route vers le sud jusqu'à {zone:1431} ; {area:42} est à l'est sur la route principale. La plus grande partie du Bois de la Pénombre est de niveau 24-30 : venez après les Carmines.",
	["Flight path here: {area:42} ({npc:2409})."] = "Trajet de vol ici : {area:42} ({npc:2409}).",
	["Fly from {area:42} to {area:144} in {zone:1432} and ride north through the {area:836} pass into the {zone:1437}."] = "Volez de {area:42} à {area:144} dans {zone:1432}, puis montez vers le nord par le col de {area:836} jusqu'à {zone:1437}.",
	["Flight path here: {area:150} ({npc:1571})."] = "Trajet de vol ici : {area:150} ({npc:1571}).",
	["the discovery triggers at the {area:1038}: do not go into {area:1037} itself"] = "la découverte se déclenche à {area:1038} : n'entrez pas dans {area:1037} lui-même",
