	["Flight path here: {area:251} (Vahgruk)."] = "Trajet de vol ici : {area:251} (Vahgruk).",
	["Take the pass south from the {zone:1428} into the {zone:1433}, follow the road south-west through {area:1002} into {zone:1431} and east past {area:42} into {zone:1430}."] = "Prenez le col vers le sud depuis {zone:1428} jusqu'à {zone:1433}, suivez la route vers le sud-ouest par {area:1002} jusqu'à {zone:1431}, puis vers l'est après {area:42} jusqu'à {zone:1430}.",
	["Ride east out of {zone:1430} into the {zone:1435} and take the road south into the {zone:1419}; {area:1438} (Alliance) stands just inside."] = "Sortez de {zone:1430} vers l'est jusqu'à {zone:1435} et prenez la route vers le sud jusqu'à {zone:1419} ; {area:1438} (Alliance) se trouve juste à l'entrée.",
	["Flight path here: {area:1438} ({npc:8609})."] = "Trajet de vol ici : {area:1438} ({npc:8609}).",
